INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (3, 'AAXJ', 'ETF', 'usa', NULL, 'American Century One Choice Blend+ 2015 Portfolio Investor Class', 'DOLLAR', 'Blend', 'Large', 'American Century Investments', 'NGM', 'Pacific/Asia ex-Japan Stk', 5574671872, 0.011, '2008-08-13', 0.23, 'The investment seeks the highest total return consistent with its asset mix. The fund is a "fund of funds," meaning that it seeks to achieve its objective by investing in other mutual funds and exchange-traded funds (ETFs) advised by American Century (collectively, the underlying funds) that represent a variety of asset classes and investment styles. The underlying stock funds draw on growth, value and quantitative investment techniques and diversify investments among small, medium and large U.S. and foreign companies.', 0.007, 0.0054, 1036417, 1.2876e+06, 86.132, 90.435, NULL, NULL, 2.03, 11.7, 18, 1.42, NULL, NULL, '{"Cap_Size": "Large", "Quote_Mode": "ETF", "Currency_Base": "DOLLAR", "GeoZone_Class": "usa", "Strategy_Type": "Blend"}', '{"Net_Worth": 5574671872, "Yield_Rate": 0.011, "Expense_Net": 0.007, "Benchmark_Exp": 0.0054, "Turnover_Ratio": 0.23}', '{"volume_metrics": {"Vol_3M": 1036417, "Vol_Recent": 1287600}, "moving_averages": {"MA_50": 86.132, "MA_200": 90.435}}', '{"asset_allocation": {"Bond_Weight": null, "Equity_Weight": null}, "bond_characteristics": {"Avg_Maturity": null, "Duration_Yrs": null}}', '{"valuation_metrics": {"PB_Ratio": 2.03, "PE_Ratio": 18, "PS_Ratio": 1.42, "PCF_Ratio": 11.7}}');
INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (648, 'FLCO', 'ETF', 'usa', 'Alger Health Sciences Fund Clas', 'Alger Health Sciences Fund Class A', 'USD', NULL, NULL, 'Alger', 'PCX', 'Corporate Bond', 1070205824, 0.0287, '2016-10-03', 0.5332, 'The investment seeks long-term capital appreciation. The fund invests at least 80% of its net assets, plus any borrowings for investment purposes, in equity securities of companies of any market capitalization that are engaged in the health sciences sector. It can invest in foreign securities.', 0.0035, 0.0017, 55270, 12470, 25.949, 26.007, NULL, NULL, NULL, NULL, NULL, NULL, 11.79, 8.43, '{"Cap_Size": null, "Quote_Mode": "ETF", "Currency_Base": "USD", "GeoZone_Class": "usa", "Strategy_Type": null}', '{"Net_Worth": 1070205824, "Yield_Rate": 0.0287, "Expense_Net": 0.0035, "Benchmark_Exp": 0.0017, "Turnover_Ratio": 0.5332}', '{"volume_metrics": {"Vol_3M": 55270, "Vol_Recent": 12470}, "moving_averages": {"MA_50": 25.949, "MA_200": 26.007}}', '{"asset_allocation": {"Bond_Weight": null, "Equity_Weight": null}, "bond_characteristics": {"Avg_Maturity": 11.79, "Duration_Yrs": 8.43}}', '{"valuation_metrics": {"PB_Ratio": null, "PE_Ratio": null, "PS_Ratio": null, "PCF_Ratio": null}}');
INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (649, 'FLDR', 'ETF', 'U.S.', 'Alger Health Sciences Fund Clas', 'Alger Health Sciences Fund Class Z', 'usd', NULL, NULL, 'Alger', 'BTS', 'Ultrashort Bond', 236389056, 0.0058, '2018-06-12', 0.43, 'The investment seeks long-term capital appreciation. The fund invests at least 80% of its net assets, plus any borrowings for investment purposes, in equity securities of companies of any market capitalization that are engaged in the health sciences sector. It can invest in foreign securities.', 0.0015, 0.0022, 23538, 21830, 50.782, 50.824, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0.9, '{"Cap_Size": null, "Quote_Mode": "ETF", "Currency_Base": "usd", "GeoZone_Class": "U.S.", "Strategy_Type": null}', '{"Net_Worth": 236389056, "Yield_Rate": 0.0058, "Expense_Net": 0.0015, "Benchmark_Exp": 0.0022, "Turnover_Ratio": 0.43}', '{"volume_metrics": {"Vol_3M": 23538, "Vol_Recent": 21830}, "moving_averages": {"MA_50": 50.782, "MA_200": 50.824}}', '{"asset_allocation": {"Bond_Weight": null, "Equity_Weight": null}, "bond_characteristics": {"Avg_Maturity": null, "Duration_Yrs": 0.9}}', '{"valuation_metrics": {"PB_Ratio": null, "PE_Ratio": null, "PS_Ratio": null, "PCF_Ratio": null}}');
INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (568, 'FATT', 'ETF', 'UNITED_STATES', 'Focused Global Growth Fund Clas', 'American Century Focused Global Growth Fund R5 Class', 'DOLLAR', NULL, NULL, 'American Century Investments', 'PCX', NULL, NULL, NULL, '2021-05-24', NULL, 'The investment seeks capital growth. The fund invests primarily in companies located in developed countries world-wide (including the United States). Under normal market conditions, the fund''s portfolio managers seek securities of companies whose earnings, revenues or key business fundamentals are not only growing, but growing at an accelerating pace.', 0.0115, NULL, 2075, 750, 24.057, 24.524, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '{"Cap_Size": null, "Quote_Mode": "ETF", "Currency_Base": "DOLLAR", "GeoZone_Class": "UNITED_STATES", "Strategy_Type": null}', '{"Net_Worth": null, "Yield_Rate": null, "Expense_Net": 0.0115, "Benchmark_Exp": null, "Turnover_Ratio": null}', '{"volume_metrics": {"Vol_3M": 2075, "Vol_Recent": 750}, "moving_averages": {"MA_50": 24.057, "MA_200": 24.524}}', '{"asset_allocation": {"Bond_Weight": null, "Equity_Weight": null}, "bond_characteristics": {"Avg_Maturity": null, "Duration_Yrs": null}}', '{"valuation_metrics": {"PB_Ratio": null, "PE_Ratio": null, "PS_Ratio": null, "PCF_Ratio": null}}');
INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (323, 'DBO', 'ETF', 'usa', 'American Century Short Duration', 'American Century Short Duration Fund Investor Class', 'US$', NULL, NULL, 'American Century Investments', 'PCX', NULL, 516884832, NULL, '2007-01-05', NULL, 'The investment seeks to maximize total return; as a secondary objective, the fund seeks a high level of income. The fund invests at least 65% of its assets in investment-grade, non-money market debt securities. No more than 10% of the fund''s assets may be invested in non-dollar denominated debt securities. The weighted average duration of the fund''s portfolio must be three years or shorter.', 0.0075, NULL, 1427811, 2.93463e+06, 14.396, 12.52, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '{"Cap_Size": null, "Quote_Mode": "ETF", "Currency_Base": "US$", "GeoZone_Class": "usa", "Strategy_Type": null}', '{"Net_Worth": 516884832, "Yield_Rate": null, "Expense_Net": 0.0075, "Benchmark_Exp": null, "Turnover_Ratio": null}', '{"volume_metrics": {"Vol_3M": 1427811, "Vol_Recent": 2934630}, "moving_averages": {"MA_50": 14.396, "MA_200": 12.52}}', '{"asset_allocation": {"Bond_Weight": null, "Equity_Weight": null}, "bond_characteristics": {"Avg_Maturity": null, "Duration_Yrs": null}}', '{"valuation_metrics": {"PB_Ratio": null, "PE_Ratio": null, "PS_Ratio": null, "PCF_Ratio": null}}');
INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (1, 'AAAU', 'ETF', 'UNITED_STATES', 'DWS RREEF Real Assets Fund - Cl', 'DWS RREEF Real Assets Fund - Class A', 'US$', NULL, NULL, 'DWS', 'PCX', NULL, 384448608, NULL, '2018-07-24', NULL, 'The investment seeks total return in excess of inflation through capital growth and current income. The fund will invest at least 80% of its net assets, plus the amount of any borrowings for investment purposes, in a combination of investments that the Advisor believes offer exposure to "real assets." It generally invests between 25% and 75% of fund assets in securities of foreign issuers, including up to 10% of fund assets in issuers located in countries with new or emerging markets.', 0.0018, NULL, 239238, 255410, 17.807, 17.818, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '{"Cap_Size": null, "Quote_Mode": "ETF", "Currency_Base": "US$", "GeoZone_Class": "UNITED_STATES", "Strategy_Type": null}', '{"Net_Worth": 384448608, "Yield_Rate": null, "Expense_Net": 0.0018, "Benchmark_Exp": null, "Turnover_Ratio": null}', '{"volume_metrics": {"Vol_3M": 239238, "Vol_Recent": 255410}, "moving_averages": {"MA_50": 17.807, "MA_200": 17.818}}', '{"asset_allocation": {"Bond_Weight": null, "Equity_Weight": null}, "bond_characteristics": {"Avg_Maturity": null, "Duration_Yrs": null}}', '{"valuation_metrics": {"PB_Ratio": null, "PE_Ratio": null, "PS_Ratio": null, "PCF_Ratio": null}}');
INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (2, 'AADR', 'ETF', 'US', 'AllianzGI Health Sciences Fund ', 'Virtus AllianzGI Health Sciences Fund Class P', 'DOLLAR', 'Blend', 'Large', 'Virtus', 'NGM', 'Foreign Large Growth', 88836160, 0.0031, '2010-07-20', NULL, 'The investment seeks long-term capital appreciation. The fund seeks to achieve its objective by normally investing at least 80% of its net assets (plus borrowings made for investment purposes) in health sciences-related companies. The portfolio manager considers health sciences-related companies to include companies that design, manufacture or sell products or services used for or in connection with healthcare, medicine or life sciences. The fund will invest primarily in common stocks and other equity securities.', 0.011, 0.0066, 2596, 3170, 64.555, 65.297, NULL, NULL, 1.71, 7.46, 13.34, 1.2, NULL, NULL, '{"Cap_Size": "Large", "Quote_Mode": "ETF", "Currency_Base": "DOLLAR", "GeoZone_Class": "US", "Strategy_Type": "Blend"}', '{"Net_Worth": 88836160, "Yield_Rate": 0.0031, "Expense_Net": 0.011, "Benchmark_Exp": 0.0066, "Turnover_Ratio": null}', '{"volume_metrics": {"Vol_3M": 2596, "Vol_Recent": 3170}, "moving_averages": {"MA_50": 64.555, "MA_200": 65.297}}', '{"asset_allocation": {"Bond_Weight": null, "Equity_Weight": null}, "bond_characteristics": {"Avg_Maturity": null, "Duration_Yrs": null}}', '{"valuation_metrics": {"PB_Ratio": 1.71, "PE_Ratio": 13.34, "PS_Ratio": 1.2, "PCF_Ratio": 7.46}}');
INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (4, 'ABEQ', 'ETF', 'us', 'Thrivent Large Cap Growth Fund ', 'Thrivent Large Cap Growth Fund Class A', 'USD', 'Value', 'Large', 'Thrivent Funds', 'PCX', 'Large Value', 49694168, 0.0049, '2020-01-21', 0.36, 'The investment seeks long-term capital appreciation. The fund invests at least 80% of its net assets (plus the amount of any borrowing for investment purposes) in equity securities of large companies. The Adviser focuses mainly on the equity securities of large domestic and international companies which have market capitalizations equivalent to those included in widely known indices such as the Russell 1000 Growth Index, S&P 500 Index, or the large company market capitalization classifications published by Lipper, Inc. These companies typically have a market capitalization of approximately $8 billion or more. The fund is non-diversified.', 0.0088, 0.0034, 4280, 8540, 27.639, 27.389, NULL, NULL, 1.79, 12.48, 16.71, 1.91, NULL, NULL, '{"Cap_Size": "Large", "Quote_Mode": "ETF", "Currency_Base": "USD", "GeoZone_Class": "us", "Strategy_Type": "Value"}', '{"Net_Worth": 49694168, "Yield_Rate": 0.0049, "Expense_Net": 0.0088, "Benchmark_Exp": 0.0034, "Turnover_Ratio": 0.36}', '{"volume_metrics": {"Vol_3M": 4280, "Vol_Recent": 8540}, "moving_averages": {"MA_50": 27.639, "MA_200": 27.389}}', '{"asset_allocation": {"Bond_Weight": null, "Equity_Weight": null}, "bond_characteristics": {"Avg_Maturity": null, "Duration_Yrs": null}}', '{"valuation_metrics": {"PB_Ratio": 1.79, "PE_Ratio": 16.71, "PS_Ratio": 1.91, "PCF_Ratio": 12.48}}');
INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (5, 'ACES', 'ETF', 'US', NULL, 'American Century One Choice Blend+ 2015 Portfolio I Class', 'USD', 'Growth', 'Medium', 'American Century Investments', 'PCX', 'Miscellaneous Sector', 1007483264, 0.0053, '2018-06-27', NULL, 'The investment seeks the highest total return consistent with its asset mix. The fund is a "fund of funds," meaning that it seeks to achieve its objective by investing in other mutual funds and exchange-traded funds (ETFs) advised by American Century (collectively, the underlying funds) that represent a variety of asset classes and investment styles. The underlying stock funds draw on growth, value and quantitative investment techniques and diversify investments among small, medium and large U.S. and foreign companies.', 0.0055, 0.0067, 106048, 51400, 73.532, 72.601, 0.9992, 0, 3.62, 15.08, 31.27, 4.09, NULL, NULL, '{"Cap_Size": "Medium", "Quote_Mode": "ETF", "Currency_Base": "USD", "GeoZone_Class": "US", "Strategy_Type": "Growth"}', '{"Net_Worth": 1007483264, "Yield_Rate": 0.0053, "Expense_Net": 0.0055, "Benchmark_Exp": 0.0067, "Turnover_Ratio": null}', '{"volume_metrics": {"Vol_3M": 106048, "Vol_Recent": 51400}, "moving_averages": {"MA_50": 73.532, "MA_200": 72.601}}', '{"asset_allocation": {"Bond_Weight": 0, "Equity_Weight": 0.9992}, "bond_characteristics": {"Avg_Maturity": null, "Duration_Yrs": null}}', '{"valuation_metrics": {"PB_Ratio": 3.62, "PE_Ratio": 31.27, "PS_Ratio": 4.09, "PCF_Ratio": 15.08}}');
