INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (13, 'ADIV', 'ETF', 'UNITED_STATES', 'DWS RREEF Real Assets Fund - Cl', 'DWS RREEF Real Assets Fund - Class C', 'Dollar', 'Value', 'Large', 'DWS', 'PCX', 'Pacific/Asia ex-Japan Stk', 4788004, 0.0278, '2021-03-29', NULL, 'The investment seeks total return in excess of inflation through capital growth and current income. The fund will invest at least 80% of its net assets, plus the amount of any borrowings for investment purposes, in a combination of investments that the Advisor believes offer exposure to "real assets." It generally invests between 25% and 75% of fund assets in securities of foreign issuers, including up to 10% of fund assets in issuers located in countries with new or emerging markets.', 0.0078, 0.0054, 430, 410, 17.443, 18.162, 0.997, 0, 1.67, 13.73, 13.41, 1.23, NULL, NULL, '{"Cap_Size": "Large", "Quote_Mode": "ETF", "Currency_Base": "Dollar", "GeoZone_Class": "UNITED_STATES", "Strategy_Type": "Value"}', '{"Net_Worth": 4788004, "Yield_Rate": 0.0278, "Expense_Net": 0.0078, "Benchmark_Exp": 0.0054, "Turnover_Ratio": null}', '{"volume_metrics": {"Vol_3M": 430, "Vol_Recent": 410}, "moving_averages": {"MA_50": 17.443, "MA_200": 18.162}}', '{"asset_allocation": {"Bond_Weight": 0, "Equity_Weight": 0.997}, "bond_characteristics": {"Avg_Maturity": null, "Duration_Yrs": null}}', '{"valuation_metrics": {"PB_Ratio": 1.67, "PE_Ratio": 13.41, "PS_Ratio": 1.23, "PCF_Ratio": 13.73}}');
