INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (60, 'ARKW', 'ETF', 'UNITED_STATES', 'Invesco Select Risk: Growth Inv', 'Invesco Select Risk: Growth Investor Fund Class A', 'usd', 'Growth', 'Large', 'Invesco', 'PCX', 'Technology', 6354094080, NULL, '2014-09-30', NULL, 'The investment seeks long-term growth of capital consistent with a higher level of risk relative to the broad stock market. The fund is a "fund of funds," and invests its assets in other underlying mutual funds advised by the Adviser and ETFs and other pooled investment vehicles. Its target allocation is to invest approximately 70%-85% of its total assets in underlying funds that invest primarily in equity securities, approximately 5%-30% of its total assets in underlying funds that invest primarily in fixed-income securities and approximately 5%-20% of its total assets in alternative asset classes.', 0.0079, 0.0053, 753130, 1.12133e+06, 148.852, 147.908, 0.9995, 0, 8.55, 32.1, 50.48, 5.97, NULL, NULL, '{"Cap_Size": "Large", "Quote_Mode": "ETF", "Currency_Base": "usd", "GeoZone_Class": "UNITED_STATES", "Strategy_Type": "Growth"}', '{"Net_Worth": 6354094080, "Yield_Rate": null, "Expense_Net": 0.0079, "Benchmark_Exp": 0.0053, "Turnover_Ratio": null}', '{"volume_metrics": {"Vol_3M": 753130, "Vol_Recent": 1121330}, "moving_averages": {"MA_50": 148.852, "MA_200": 147.908}}', '{"asset_allocation": {"Bond_Weight": 0, "Equity_Weight": 0.9995}, "bond_characteristics": {"Avg_Maturity": null, "Duration_Yrs": null}}', '{"valuation_metrics": {"PB_Ratio": 8.55, "PE_Ratio": 50.48, "PS_Ratio": 5.97, "PCF_Ratio": 32.1}}');
INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (61, 'ARKX', 'ETF', 'usa', 'American Beacon Balanced Fund I', 'American Beacon Balanced Fund R5 Class', 'Usd', 'Growth', 'Large', 'American Beacon', 'BTS', NULL, 669418624, NULL, '2021-03-30', NULL, 'The investment seeks income and capital appreciation. Under normal circumstances, between 50% and 70% of the fund''s total assets are invested in equity securities and between 30% and 50% of the fund''s total assets are invested in debt securities. The fund''s equity investments may include common stocks, convertible securities, real estate investment trusts ("REITs"), American Depositary Receipts ("ADRs") and U.S. dollar-denominated foreign stocks traded on U.S. exchanges (collectively referred to as "stocks"). It may invest in companies of all market capitalizations.', 0.0075, NULL, 274227, 294090, 20.102, 20.393, 0.9976, 0, 4.86, 20.85, 33.93, 2.84, NULL, NULL, '{"Cap_Size": "Large", "Quote_Mode": "ETF", "Currency_Base": "Usd", "GeoZone_Class": "usa", "Strategy_Type": "Growth"}', '{"Net_Worth": 669418624, "Yield_Rate": null, "Expense_Net": 0.0075, "Benchmark_Exp": null, "Turnover_Ratio": null}', '{"volume_metrics": {"Vol_3M": 274227, "Vol_Recent": 294090}, "moving_averages": {"MA_50": 20.102, "MA_200": 20.393}}', '{"asset_allocation": {"Bond_Weight": 0, "Equity_Weight": 0.9976}, "bond_characteristics": {"Avg_Maturity": null, "Duration_Yrs": null}}', '{"valuation_metrics": {"PB_Ratio": 4.86, "PE_Ratio": 33.93, "PS_Ratio": 2.84, "PCF_Ratio": 20.85}}');
