INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (64, 'ASET', 'ETF', 'UNITED_STATES', 'Aasgard Small & Mid-Cap Fund', 'Aasgard Small & Mid-Cap Fund No Load Class', 'DOLLAR', 'Value', 'Large', 'Aasgard', 'NGM', NULL, 30690664, 0.0162, '2015-11-23', 0.14, 'The investment seeks a combination of dividend income and capital appreciation, with a secondary focus on lower than market volatility. The fund will invest at least 80% of its net assets (plus any borrowings for investment purposes) in dividend-paying common stocks of small- and medium-sized companies. It invests primarily in the common stocks of domestic small- and medium-sized companies with market capitalizations under $15 billion that the Advisor believes have strong growth potential and attractive dividend and yield opportunities. The fund may also invest up to 15% of its net assets in real estate investment trusts ("REITs").', 0.0057, NULL, 1825, 1930, 33.382, 33.045, NULL, NULL, 2, 9.63, 19.43, 1.92, NULL, NULL, '{"Cap_Size": "Large", "Quote_Mode": "ETF", "Currency_Base": "DOLLAR", "GeoZone_Class": "UNITED_STATES", "Strategy_Type": "Value"}', '{"Net_Worth": 30690664, "Yield_Rate": 0.0162, "Expense_Net": 0.0057, "Benchmark_Exp": null, "Turnover_Ratio": 0.14}', '{"volume_metrics": {"Vol_3M": 1825, "Vol_Recent": 1930}, "moving_averages": {"MA_50": 33.382, "MA_200": 33.045}}', '{"asset_allocation": {"Bond_Weight": null, "Equity_Weight": null}, "bond_characteristics": {"Avg_Maturity": null, "Duration_Yrs": null}}', '{"valuation_metrics": {"PB_Ratio": 2, "PE_Ratio": 19.43, "PS_Ratio": 1.92, "PCF_Ratio": 9.63}}');
INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (65, 'ASHR', 'ETF', 'United States', NULL, 'American Century One Choice Blend+ 2045 Portfolio Investor Class', 'US_DOLLAR', 'Blend', 'Large', 'American Century Investments', 'PCX', 'China Region', 2773868032, 0.008, '2013-11-06', 1.15, 'The investment seeks the highest total return consistent with its asset mix. The fund is a "fund of funds," meaning that it seeks to achieve its objective by investing in other mutual funds and exchange-traded funds (ETFs) advised by American Century (collectively, the underlying funds) that represent a variety of asset classes and investment styles. The underlying stock funds draw on growth, value and quantitative investment techniques and diversify investments among small, medium and large U.S. and foreign companies.', 0.0065, 0.0068, 3171712, 2.07671e+06, 38.482, 39.203, 0.9914, 0, 2.29, 14.84, 18.01, 1.91, NULL, NULL, '{"Cap_Size": "Large", "Quote_Mode": "ETF", "Currency_Base": "US_DOLLAR", "GeoZone_Class": "United States", "Strategy_Type": "Blend"}', '{"Net_Worth": 2773868032, "Yield_Rate": 0.008, "Expense_Net": 0.0065, "Benchmark_Exp": 0.0068, "Turnover_Ratio": 1.15}', '{"volume_metrics": {"Vol_3M": 3171712, "Vol_Recent": 2076710}, "moving_averages": {"MA_50": 38.482, "MA_200": 39.203}}', '{"asset_allocation": {"Bond_Weight": 0, "Equity_Weight": 0.9914}, "bond_characteristics": {"Avg_Maturity": null, "Duration_Yrs": null}}', '{"valuation_metrics": {"PB_Ratio": 2.29, "PE_Ratio": 18.01, "PS_Ratio": 1.91, "PCF_Ratio": 14.84}}');
INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (66, 'ASHS', 'ETF', 'United States', 'Invesco Select Risk: Growth Inv', 'Invesco Select Risk: Growth Investor Fund Class R5', 'US_DOLLAR', 'Blend', 'Medium', 'Invesco', 'PCX', 'China Region', 40269792, 0.004, '2014-05-21', 0.48, 'The investment seeks long-term growth of capital consistent with a higher level of risk relative to the broad stock market. The fund is a "fund of funds," and invests its assets in other underlying mutual funds advised by the Adviser and ETFs and other pooled investment vehicles. Its target allocation is to invest approximately 70%-85% of its total assets in underlying funds that invest primarily in equity securities, approximately 5%-30% of its total assets in underlying funds that invest primarily in fixed-income securities and approximately 5%-20% of its total assets in alternative asset classes.', 0.0065, 0.0068, 10946, 14890, 40.414, 38.425, 0.9953, 0, 1.98, 10.31, 19.45, 1.07, NULL, NULL, '{"Cap_Size": "Medium", "Quote_Mode": "ETF", "Currency_Base": "US_DOLLAR", "GeoZone_Class": "United States", "Strategy_Type": "Blend"}', '{"Net_Worth": 40269792, "Yield_Rate": 0.004, "Expense_Net": 0.0065, "Benchmark_Exp": 0.0068, "Turnover_Ratio": 0.48}', '{"volume_metrics": {"Vol_3M": 10946, "Vol_Recent": 14890}, "moving_averages": {"MA_50": 40.414, "MA_200": 38.425}}', '{"asset_allocation": {"Bond_Weight": 0, "Equity_Weight": 0.9953}, "bond_characteristics": {"Avg_Maturity": null, "Duration_Yrs": null}}', '{"valuation_metrics": {"PB_Ratio": 1.98, "PE_Ratio": 19.45, "PS_Ratio": 1.07, "PCF_Ratio": 10.31}}');
