INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (87, 'AZAL', 'ETF', 'usa', 'American Beacon International E', 'American Beacon International Equity Fund Class R6', 'Dollar', 'Blend', 'Large', 'American Beacon', 'PCX', 'Large Blend', 30547872, NULL, '2020-06-30', NULL, 'The investment seeks long-term capital appreciation. The fund normally invests at least 80% of its net assets (plus the amount of any borrowings for investment purposes) in common stocks and securities convertible into common stocks (collectively, "stocks") of issuers based in at least three different countries located outside the United States. It primarily invests in countries comprising the MSCI EAFE Index©. The MSCI EAFE Index is designed to represent the performance of large- and mid-capitalization securities across 21 developed markets countries, including countries in Europe, Australasia and the Far East, and excluding the U.S. and Canada.', 0.0074, 0.0036, 3411, 2820, 28.633, 27.997, 0.9976, 0, 4.28, 17.34, 26.06, 2.89, NULL, NULL, '{"Cap_Size": "Large", "Quote_Mode": "ETF", "Currency_Base": "Dollar", "GeoZone_Class": "usa", "Strategy_Type": "Blend"}', '{"Net_Worth": 30547872, "Yield_Rate": null, "Expense_Net": 0.0074, "Benchmark_Exp": 0.0036, "Turnover_Ratio": null}', '{"volume_metrics": {"Vol_3M": 3411, "Vol_Recent": 2820}, "moving_averages": {"MA_50": 28.633, "MA_200": 27.997}}', '{"asset_allocation": {"Bond_Weight": 0, "Equity_Weight": 0.9976}, "bond_characteristics": {"Avg_Maturity": null, "Duration_Yrs": null}}', '{"valuation_metrics": {"PB_Ratio": 4.28, "PE_Ratio": 26.06, "PS_Ratio": 2.89, "PCF_Ratio": 17.34}}');
INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (88, 'AZAO', 'ETF', 'United States', 'Invesco Select Risk: Growth Inv', 'Invesco Select Risk: Growth Investor Fund Class R6', 'Usd', 'Blend', 'Large', 'Invesco', 'PCX', 'Large Blend', 33549998, NULL, '2020-09-30', NULL, 'The investment seeks long-term growth of capital consistent with a higher level of risk relative to the broad stock market. The fund is a "fund of funds," and invests its assets in other underlying mutual funds advised by the Adviser and ETFs and other pooled investment vehicles. Its target allocation is to invest approximately 70%-85% of its total assets in underlying funds that invest primarily in equity securities, approximately 5%-30% of its total assets in underlying funds that invest primarily in fixed-income securities and approximately 5%-20% of its total assets in alternative asset classes.', 0.0074, 0.0036, 14720, 3410, 29.625, 28.562, 1, 0, 4.26, 17.31, 25.99, 2.88, NULL, NULL, '{"Cap_Size": "Large", "Quote_Mode": "ETF", "Currency_Base": "Usd", "GeoZone_Class": "United States", "Strategy_Type": "Blend"}', '{"Net_Worth": 33549998, "Yield_Rate": null, "Expense_Net": 0.0074, "Benchmark_Exp": 0.0036, "Turnover_Ratio": null}', '{"volume_metrics": {"Vol_3M": 14720, "Vol_Recent": 3410}, "moving_averages": {"MA_50": 29.625, "MA_200": 28.562}}', '{"asset_allocation": {"Bond_Weight": 0, "Equity_Weight": 1}, "bond_characteristics": {"Avg_Maturity": null, "Duration_Yrs": null}}', '{"valuation_metrics": {"PB_Ratio": 4.26, "PE_Ratio": 25.99, "PS_Ratio": 2.88, "PCF_Ratio": 17.31}}');
INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (89, 'AZBA', 'ETF', 'US', 'American Fds 2030 Target Date R', 'American Funds 2030 Target Date Retirement Fund Class A', 'Dollar', 'Blend', 'Large', 'American Funds', 'PCX', 'Large Blend', 24564352, NULL, '2020-05-28', NULL, 'The investment seeks growth, income and conservation of capital. The fund normally invests a greater portion of its assets in fixed income, equity-income and balanced funds as it approaches and passes its target date. The advisor attempts to achieve its investment objectives by investing in a mix of American Funds in different combinations and weightings. The underlying American Funds represent a variety of fund categories, including growth funds, growth-and-income funds, equity-income funds, balanced funds and fixed income funds. The fund categories represent differing investment objectives.', 0.0074, 0.0036, 1961, 1910, 26.784, 26.379, 0.9987, 0, 4.27, 17.32, 26.01, 2.89, NULL, NULL, '{"Cap_Size": "Large", "Quote_Mode": "ETF", "Currency_Base": "Dollar", "GeoZone_Class": "US", "Strategy_Type": "Blend"}', '{"Net_Worth": 24564352, "Yield_Rate": null, "Expense_Net": 0.0074, "Benchmark_Exp": 0.0036, "Turnover_Ratio": null}', '{"volume_metrics": {"Vol_3M": 1961, "Vol_Recent": 1910}, "moving_averages": {"MA_50": 26.784, "MA_200": 26.379}}', '{"asset_allocation": {"Bond_Weight": 0, "Equity_Weight": 0.9987}, "bond_characteristics": {"Avg_Maturity": null, "Duration_Yrs": null}}', '{"valuation_metrics": {"PB_Ratio": 4.27, "PE_Ratio": 26.01, "PS_Ratio": 2.89, "PCF_Ratio": 17.32}}');
