INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (94, 'BAL', 'ETF', 'U.S.A.', 'Alger Portfolios - Alger Growth', 'Alger Large Cap Growth Portfolio Class I-2', 'Usd', NULL, NULL, 'Alger', 'PCX', NULL, 12809062, NULL, '2018-01-17', NULL, 'The investment seeks long-term capital appreciation. The advisor focuses on growing companies that generally have broad product lines, markets, financial resources and depth of management. It normally invests at least 80% of its net assets in equity securities of companies that, at the time of purchase of the securities, have a market capitalization equal to or greater than the market capitalization of companies included in the Russell 1000 Growth Index, updated quarterly as reported as of the most recent quarter-end. This index is designed to track the performance of large-capitalization growth stocks.', 0.0045, NULL, 11325, 7430, 61.356, 51.984, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '{"Cap_Size": null, "Quote_Mode": "ETF", "Currency_Base": "Usd", "GeoZone_Class": "U.S.A.", "Strategy_Type": null}', '{"Net_Worth": 12809062, "Yield_Rate": null, "Expense_Net": 0.0045, "Benchmark_Exp": null, "Turnover_Ratio": null}', '{"volume_metrics": {"Vol_3M": 11325, "Vol_Recent": 7430}, "moving_averages": {"MA_50": 61.356, "MA_200": 51.984}}', '{"asset_allocation": {"Bond_Weight": null, "Equity_Weight": null}, "bond_characteristics": {"Avg_Maturity": null, "Duration_Yrs": null}}', '{"valuation_metrics": {"PB_Ratio": null, "PE_Ratio": null, "PS_Ratio": null, "PCF_Ratio": null}}');
INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (95, 'BALT', 'ETF', 'UNITED_STATES', 'American Beacon Large Cap Value', 'American Beacon Large Cap Value Fund Investor Class', 'DOLLAR', NULL, NULL, 'American Beacon', 'BTS', NULL, 25, NULL, '2021-06-30', NULL, 'The investment seeks long-term capital appreciation and current income. Under normal circumstances, at least 80% of the fund''s net assets (plus the amount of any borrowings for investment purposes) are invested in equity securities of large market capitalization U.S. companies. These companies have market capitalizations within the market capitalization range of the companies in the Russell 1000© Index at the time of investment.', 0.0069, NULL, 23172, 12180, 25.842, 25.802, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '{"Cap_Size": null, "Quote_Mode": "ETF", "Currency_Base": "DOLLAR", "GeoZone_Class": "UNITED_STATES", "Strategy_Type": null}', '{"Net_Worth": 25, "Yield_Rate": null, "Expense_Net": 0.0069, "Benchmark_Exp": null, "Turnover_Ratio": null}', '{"volume_metrics": {"Vol_3M": 23172, "Vol_Recent": 12180}, "moving_averages": {"MA_50": 25.842, "MA_200": 25.802}}', '{"asset_allocation": {"Bond_Weight": null, "Equity_Weight": null}, "bond_characteristics": {"Avg_Maturity": null, "Duration_Yrs": null}}', '{"valuation_metrics": {"PB_Ratio": null, "PE_Ratio": null, "PS_Ratio": null, "PCF_Ratio": null}}');
