INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (96, 'BAPR', 'ETF', 'United States', 'Aberdeen Short Duration High Yi', 'Aberdeen Short Duration High Yield Municipal Fund Class A', 'Usd', 'Blend', 'Large', 'Aberdeen', 'BTS', NULL, 129622496, NULL, '2019-03-29', NULL, 'The investment seeks a high level of current income exempt from federal income tax. Under normal circumstances, the fund invests at least 80% of its net assets in municipal obligations that are exempt from federal income tax (including securities subject to the federal alternative minimum tax ("AMT")). It invests at least 50% of its assets in municipal bonds rated BBB or lower by S&P Global Ratings or Baa or lower by Moody''s Investors Service, Inc., at the time of investment, or the equivalent by another independent rating agency or the unrated equivalent as determined by the Adviser.', 0.0079, NULL, 10135, 6410, 32.615, 31.589, 0.9905, 0, 4.42, 17.56, 26.45, 2.96, NULL, NULL, '{"Cap_Size": "Large", "Quote_Mode": "ETF", "Currency_Base": "Usd", "GeoZone_Class": "United States", "Strategy_Type": "Blend"}', '{"Net_Worth": 129622496, "Yield_Rate": null, "Expense_Net": 0.0079, "Benchmark_Exp": null, "Turnover_Ratio": null}', '{"volume_metrics": {"Vol_3M": 10135, "Vol_Recent": 6410}, "moving_averages": {"MA_50": 32.615, "MA_200": 31.589}}', '{"asset_allocation": {"Bond_Weight": 0, "Equity_Weight": 0.9905}, "bond_characteristics": {"Avg_Maturity": null, "Duration_Yrs": null}}', '{"valuation_metrics": {"PB_Ratio": 4.42, "PE_Ratio": 26.45, "PS_Ratio": 2.96, "PCF_Ratio": 17.56}}');
INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (182, 'BSCU', 'ETF', 'America', 'AB Bond Fund, Inc. - AB Total R', 'AB Total Return Bond Portfolio Class C', 'US$', NULL, NULL, 'AllianceBernstein', 'NGM', NULL, 26519706, NULL, '2020-09-16', NULL, 'The investment seeks to maximize long-term total return. The fund invests at least 80% of its net assets in fixed-income securities. It invests in readily marketable fixed-income securities with a range of maturities from short- to long-term and relatively attractive yields that do not involve undue risk of loss of capital. It may invest up to 25% of its net assets in below investment grade bonds. The fund may use leverage for investment purposes.', 0.001, NULL, 8135, 5930, 19.418, 19.479, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '{"Cap_Size": null, "Quote_Mode": "ETF", "Currency_Base": "US$", "GeoZone_Class": "America", "Strategy_Type": null}', '{"Net_Worth": 26519706, "Yield_Rate": null, "Expense_Net": 0.001, "Benchmark_Exp": null, "Turnover_Ratio": null}', '{"volume_metrics": {"Vol_3M": 8135, "Vol_Recent": 5930}, "moving_averages": {"MA_50": 19.418, "MA_200": 19.479}}', '{"asset_allocation": {"Bond_Weight": null, "Equity_Weight": null}, "bond_characteristics": {"Avg_Maturity": null, "Duration_Yrs": null}}', '{"valuation_metrics": {"PB_Ratio": null, "PE_Ratio": null, "PS_Ratio": null, "PCF_Ratio": null}}');
