INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (98, 'BATT', 'ETF', 'United States', 'Cavanal Hill Moderate Duration ', 'Cavanal Hill Moderate Duration Fund Class A', 'Dollar', 'Growth', 'Large', 'Cavanal Hill funds', 'PCX', NULL, 173481360, 0.0021, '2018-06-04', 1.31, 'The investment seeks total return. The fund invests primarily in debt obligations such as bonds, notes and debentures, and bills issued by U.S. corporations or the U.S. government, its agencies, or instrumentalities, municipal securities, mortgage-backed securities, asset-backed securities, collateralized mortgage obligations and fixed income ETFs. It invests at least 80% of its net assets in bonds and maintains an average portfolio duration between three and five years.', 0.0059, NULL, 209588, 217210, 18.891, 17.328, 0.9985, 0, 3.84, 14.1, 34.14, 1.72, NULL, NULL, '{"Cap_Size": "Large", "Quote_Mode": "ETF", "Currency_Base": "Dollar", "GeoZone_Class": "United States", "Strategy_Type": "Growth"}', '{"Net_Worth": 173481360, "Yield_Rate": 0.0021, "Expense_Net": 0.0059, "Benchmark_Exp": null, "Turnover_Ratio": 1.31}', '{"volume_metrics": {"Vol_3M": 209588, "Vol_Recent": 217210}, "moving_averages": {"MA_50": 18.891, "MA_200": 17.328}}', '{"asset_allocation": {"Bond_Weight": 0, "Equity_Weight": 0.9985}, "bond_characteristics": {"Avg_Maturity": null, "Duration_Yrs": null}}', '{"valuation_metrics": {"PB_Ratio": 3.84, "PE_Ratio": 34.14, "PS_Ratio": 1.72, "PCF_Ratio": 14.1}}');
INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (99, 'BAUG', 'ETF', 'United States', 'American Beacon Intl Equity Fun', 'American Beacon International Equity Fund R5 Class', 'US Dollar', 'Blend', 'Large', 'American Beacon', 'BTS', NULL, 29997818, NULL, '2019-07-31', NULL, 'The investment seeks long-term capital appreciation. The fund normally invests at least 80% of its net assets (plus the amount of any borrowings for investment purposes) in common stocks and securities convertible into common stocks (collectively, "stocks") of issuers based in at least three different countries located outside the United States. It primarily invests in countries comprising the MSCI EAFE Index©. The MSCI EAFE Index is designed to represent the performance of large- and mid-capitalization securities across 21 developed markets countries, including countries in Europe, Australasia and the Far East, and excluding the U.S. and Canada.', 0.0079, NULL, 12895, 2250, 32.367, 31.579, 1, 0, 4.42, 17.56, 26.46, 2.96, NULL, NULL, '{"Cap_Size": "Large", "Quote_Mode": "ETF", "Currency_Base": "US Dollar", "GeoZone_Class": "United States", "Strategy_Type": "Blend"}', '{"Net_Worth": 29997818, "Yield_Rate": null, "Expense_Net": 0.0079, "Benchmark_Exp": null, "Turnover_Ratio": null}', '{"volume_metrics": {"Vol_3M": 12895, "Vol_Recent": 2250}, "moving_averages": {"MA_50": 32.367, "MA_200": 31.579}}', '{"asset_allocation": {"Bond_Weight": 0, "Equity_Weight": 1}, "bond_characteristics": {"Avg_Maturity": null, "Duration_Yrs": null}}', '{"valuation_metrics": {"PB_Ratio": 4.42, "PE_Ratio": 26.46, "PS_Ratio": 2.96, "PCF_Ratio": 17.56}}');
INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (100, 'BBAX', 'ETF', 'United States', 'Ancora Income Fund Class I', 'Ancora Income Fund Class I', 'US_DOLLAR', 'Blend', 'Large', 'Ancora', 'BTS', NULL, 3723602944, 0.0249, '2018-08-07', NULL, 'The investment seeks a high level of income with a secondary objective of capital appreciation. The fund pursues its income objective by investing primarily in income-producing securities (such as debt securities, preferred stocks, high dividend-bearing common shares, common and preferred shares of closed-end investment companies). It will invest in shares of closed-end funds and convertible securities of large, small and mid-sized companies. The fund will invest only in securities of companies with market capitalizations of more than $500 million, except that the fund may invest in closed-end funds with market capitalizations of less than that amount.', 0.0019, NULL, 129808, 167210, 55.814, 57.739, 0.9934, 0, 1.78, 10.83, 22.61, 2.72, NULL, NULL, '{"Cap_Size": "Large", "Quote_Mode": "ETF", "Currency_Base": "US_DOLLAR", "GeoZone_Class": "United States", "Strategy_Type": "Blend"}', '{"Net_Worth": 3723602944, "Yield_Rate": 0.0249, "Expense_Net": 0.0019, "Benchmark_Exp": null, "Turnover_Ratio": null}', '{"volume_metrics": {"Vol_3M": 129808, "Vol_Recent": 167210}, "moving_averages": {"MA_50": 55.814, "MA_200": 57.739}}', '{"asset_allocation": {"Bond_Weight": 0, "Equity_Weight": 0.9934}, "bond_characteristics": {"Avg_Maturity": null, "Duration_Yrs": null}}', '{"valuation_metrics": {"PB_Ratio": 1.78, "PE_Ratio": 22.61, "PS_Ratio": 2.72, "PCF_Ratio": 10.83}}');
