INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (492, 'EMNT', 'ETF', 'usa', 'Alger International Focus Fund ', 'Alger International Focus Fund Class B', 'US$', NULL, NULL, 'Alger', 'PCX', 'Ultrashort Bond', 152999856, 0.0097, '2019-12-10', 1.02, 'The investment seeks long-term capital appreciation. Under normal circumstances, the fund invests at least 80% of its net assets in equity securities, including common stocks, American Depositary Receipts and Global Depositary Receipts, of foreign companies. It generally invests in at least three foreign countries, and, at times, may invest a substantial portion of its assets in a single foreign country.', 0.0024, 0.0022, 9703, 20800, 100.543, 100.637, NULL, NULL, NULL, NULL, NULL, NULL, 0.7, 0.59, '{"Cap_Size": null, "Quote_Mode": "ETF", "Currency_Base": "US$", "GeoZone_Class": "usa", "Strategy_Type": null}', '{"Net_Worth": 152999856, "Yield_Rate": 0.0097, "Expense_Net": 0.0024, "Benchmark_Exp": 0.0022, "Turnover_Ratio": 1.02}', '{"volume_metrics": {"Vol_3M": 9703, "Vol_Recent": 20800}, "moving_averages": {"MA_50": 100.543, "MA_200": 100.637}}', '{"asset_allocation": {"Bond_Weight": null, "Equity_Weight": null}, "bond_characteristics": {"Avg_Maturity": 0.7, "Duration_Yrs": 0.59}}', '{"valuation_metrics": {"PB_Ratio": null, "PE_Ratio": null, "PS_Ratio": null, "PCF_Ratio": null}}');
