INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (119, 'BFEB', 'ETF', 'United States', 'American Beacon Small Cap Value', 'American Beacon Small Cap Value Fund R6 Class', 'US_DOLLAR', 'Blend', 'Large', 'American Beacon', 'BTS', NULL, 84867440, NULL, '2020-01-31', NULL, 'The investment seeks long-term capital appreciation and current income. Under normal circumstances, at least 80% of the fund''s net assets (plus the amount of any borrowings for investment purposes) are invested in equity securities of small market capitalization U.S. companies. These companies have market capitalizations of $5 billion or less at the time of investment. The fund''s investments may include common stocks, preferred stocks, real estate investment trusts ("REITs"), American Depositary Receipts ("ADRs"), master limited partnerships ("MLPs"), and U.S. dollar-denominated foreign stocks traded on U.S. exchanges (collectively, "stocks").', 0.0079, NULL, 14043, 43400, 31.463, 30.445, 0.9923, 0, 4.42, 17.56, 26.45, 2.96, NULL, NULL, '{"Cap_Size": "Large", "Quote_Mode": "ETF", "Currency_Base": "US_DOLLAR", "GeoZone_Class": "United States", "Strategy_Type": "Blend"}', '{"Net_Worth": 84867440, "Yield_Rate": null, "Expense_Net": 0.0079, "Benchmark_Exp": null, "Turnover_Ratio": null}', '{"volume_metrics": {"Vol_3M": 14043, "Vol_Recent": 43400}, "moving_averages": {"MA_50": 31.463, "MA_200": 30.445}}', '{"asset_allocation": {"Bond_Weight": 0, "Equity_Weight": 0.9923}, "bond_characteristics": {"Avg_Maturity": null, "Duration_Yrs": null}}', '{"valuation_metrics": {"PB_Ratio": 4.42, "PE_Ratio": 26.45, "PS_Ratio": 2.96, "PCF_Ratio": 17.56}}');
