INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (124, 'BIB', 'ETF', 'U.S.A.', 'Ultra Short Tax-Free Income Fun', 'Cavanal Hill Ultra Short Tax-Free Income Fund Class A', 'US_DOLLAR', 'Growth', 'Medium', 'Cavanal Hill funds', 'NGM', 'Trading--Leveraged Equity', 270422208, NULL, '2010-04-06', 0.37, 'The investment seeks to generate current income exempt from federal income taxes consistent with the preservation of capital. The fund invests in a diversified portfolio of municipal bonds and debentures. As a matter of fundamental policy, it invests, under normal circumstances, at least 80% of its net assets in municipal securities, the income from which is both exempt from federal income tax and not subject to federal alternative minimum tax for individuals. The fund invests at least 80% of its net assets in tax-free bonds and maintains a dollar-weighted average maturity between 1 day to 1 year.', 0.0095, 0.009, 60682, 51860, 89.285, 91.997, NULL, NULL, NULL, NULL, NULL, 3.4, NULL, NULL, '{"Cap_Size": "Medium", "Quote_Mode": "ETF", "Currency_Base": "US_DOLLAR", "GeoZone_Class": "U.S.A.", "Strategy_Type": "Growth"}', '{"Net_Worth": 270422208, "Yield_Rate": null, "Expense_Net": 0.0095, "Benchmark_Exp": 0.009, "Turnover_Ratio": 0.37}', '{"volume_metrics": {"Vol_3M": 60682, "Vol_Recent": 51860}, "moving_averages": {"MA_50": 89.285, "MA_200": 91.997}}', '{"asset_allocation": {"Bond_Weight": null, "Equity_Weight": null}, "bond_characteristics": {"Avg_Maturity": null, "Duration_Yrs": null}}', '{"valuation_metrics": {"PB_Ratio": null, "PE_Ratio": null, "PS_Ratio": 3.4, "PCF