INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (126, 'BICK', 'ETF', 'United States', 'Cavanal Hill World Energy Fund ', 'Cavanal Hill World Energy Fund A', 'US$', 'Blend', 'Large', 'Cavanal Hill funds', 'NGM', 'Diversified Emerging Mkts', 93996840, 0.0039, '2010-04-12', 0.58, 'The investment seeks growth and income. The fund invests at least 80% of its net assets in a wide range of energy-related financial instruments issued in the U.S. and markets around the world. Investments typically include a combination of common stock, bonds, exchange traded funds ("ETFs") and exchange traded notes ("ETNs") but may also include other asset types that are related to energy industry activities. It will invest at least 40%, but may invest up to 100%, of its net assets in the securities of issuers organized or having their principal place of business outside the U.S. or doing a substantial amount of business outside the U.S.', 0.0064, 0.0056, 33709, 2860, 34.35, 37.238, 0.9973, 0, 2.33, 10.23, 18.42, 1.12, NULL, NULL, '{"Cap_Size": "Large", "Quote_Mode": "ETF", "Currency_Base": "US$", "GeoZone_Class": "United States", "Strategy_Type": "Blend"}', '{"Net_Worth": 93996840, "Yield_Rate": 0.0039, "Expense_Net": 0.0064, "Benchmark_Exp": 0.0056, "Turnover_Ratio": 0.58}', '{"volume_metrics": {"Vol_3M": 33709, "Vol_Recent": 2860}, "moving_averages": {"MA_50": 34.35, "MA_200": 37.238}}', '{"asset_allocation": {"Bond_Weight": 0, "Equity_Weight": 0.9973}, "bond_characteristics": {"Avg_Maturity": null, "Duration_Yrs": null}}', '{"valuation_metrics": {"PB_Ratio": 2.33, "PE_Ratio": 18.42, "PS_Ratio": 1.12, "PCF_Ratio": 10.23}}');
