INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (128, 'BILS', 'ETF', 'UNITED_STATES', 'AB Municipal Income Fund II - A', 'AB Municipal Income Fund II Arizona Portfolio Class A', 'USD', NULL, NULL, 'AllianceBernstein', 'PCX', NULL, 10007506, NULL, '2020-09-24', NULL, 'The investment seeks to earn the highest level of current income exempt from both federal income tax and State of Arizona personal income tax that is available without assuming what the Adviser considers to be undue risk. The fund principally invests in high-yielding, predominantly investment grade municipal securities. It invests at least 80% of its net assets in municipal securities that pay interest that is exempt from federal income tax.', 0.00136, NULL, 1495, 5420, 100.028, 100.056, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '{"Cap_Size": null, "Quote_Mode": "ETF", "Currency_Base": "USD", "GeoZone_Class": "UNITED_STATES", "Strategy_Type": null}', '{"Net_Worth": 10007506, "Yield_Rate": null, "Expense_Net": 0.00136, "Benchmark_Exp": null, "Turnover_Ratio": null}', '{"volume_metrics": {"Vol_3M": 1495, "Vol_Recent": 5420}, "moving_averages": {"MA_50": 100.028, "MA_200": 100.056}}', '{"asset_allocation": {"Bond_Weight": null, "Equity_Weight": null}, "bond_characteristics": {"Avg_Maturity": null, "Duration_Yrs": null}}', '{"valuation_metrics": {"PB_Ratio": null, "PE_Ratio": null, "PS_Ratio": null, "PCF_Ratio": null}}');
