INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (135, 'BJUL', 'ETF', 'United States', 'American Beacon Balanced Fund C', 'American Beacon Balanced Fund C Class', 'US Dollar', 'Blend', 'Large', 'American Beacon', 'BTS', NULL, 48600056, NULL, '2018-08-28', 0.04, 'The investment seeks income and capital appreciation. Under normal circumstances, between 50% and 70% of the fund''s total assets are invested in equity securities and between 30% and 50% of the fund''s total assets are invested in debt securities. The fund''s equity investments may include common stocks, convertible securities, real estate investment trusts ("REITs"), American Depositary Receipts ("ADRs") and U.S. dollar-denominated foreign stocks traded on U.S. exchanges (collectively referred to as "stocks"). It may invest in companies of all market capitalizations.', 0.0079, NULL, 52683, 8150, 32.469, 31.65, 1, 0, 4.42, 17.56, 26.46, 2.96, NULL, NULL, '{"Cap_Size": "Large", "Quote_Mode": "ETF", "Currency_Base": "US Dollar", "GeoZone_Class": "United States", "Strategy_Type": "Blend"}', '{"Net_Worth": 48600056, "Yield_Rate": null, "Expense_Net": 0.0079, "Benchmark_Exp": null, "Turnover_Ratio": 0.04}', '{"volume_metrics": {"Vol_3M": 52683, "Vol_Recent": 8150}, "moving_averages": {"MA_50": 32.469, "MA_200": 31.65}}', '{"asset_allocation": {"Bond_Weight": 0, "Equity_Weight": 1}, "bond_characteristics": {"Avg_Maturity": null, "Duration_Yrs": null}}', '{"valuation_metrics": {"PB_Ratio": 4.42, "PE_Ratio": 26.46, "PS_Ratio": 2.96, "PCF_Ratio": 17.56}}');
INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (136, 'BJUN', 'ETF', 'US', 'AB Cap Fund, Inc. - AB Emerging', 'AB Emerging Markets Multi-Asset Portfolio Class C', 'US Dollar', 'Blend', 'Large', 'AllianceBernstein', 'BTS', NULL, 87169936, NULL, '2019-05-31', NULL, 'The investment seeks to maximize total return. The fund invests at least 80% of its net assets under normal circumstances in securities of emerging market issuers and/or the currencies of emerging market countries. It will invest between 30% and 95% of its net assets in equity securities, and between 0% and 65% of its net assets in debt securities, with any remainder held in cash (including foreign currency). The fund is not constrained based on the country, region, market capitalization, credit quality or duration of its investments and its assets may at times be concentrated in a particular country or region.', 0.0079, NULL, 16477, 46360, 33.678, 32.748, NULL, NULL, 4.42, 17.56, 26.45, 2.96, NULL, NULL, '{"Cap_Size": "Large", "Quote_Mode": "ETF", "Currency_Base": "US Dollar", "GeoZone_Class": "US", "Strategy_Type": "Blend"}', '{"Net_Worth": 87169936, "Yield_Rate": null, "Expense_Net": 0.0079, "Benchmark_Exp": null, "Turnover_Ratio": null}', '{"volume_metrics": {"Vol_3M": 16477, "Vol_Recent": 46360}, "moving_averages": {"MA_50": 33.678, "MA_200": 32.748}}', '{"asset_allocation": {"Bond_Weight": null, "Equity_Weight": null}, "bond_characteristics": {"Avg_Maturity": null, "Duration_Yrs": null}}', '{"valuation_metrics": {"PB_Ratio": 4.42, "PE_Ratio": 26.45, "PS_Ratio": 2.96, "PCF_Ratio": 17.56}}');
