INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (156, 'BND', 'ETF', 'U.S.A.', 'AB Cap Fund, Inc. - AB Emerging', 'AB Emerging Markets Multi-Asset Portfolio Class I', 'Usd', NULL, NULL, 'AllianceBernstein', 'NGM', 'Intermediate-Term Bond', 312150884352, 0.0202, '2007-04-03', 0.79, 'The investment seeks to maximize total return. The fund invests at least 80% of its net assets under normal circumstances in securities of emerging market issuers and/or the currencies of emerging market countries. It will invest between 30% and 95% of its net assets in equity securities, and between 0% and 65% of its net assets in debt securities, with any remainder held in cash (including foreign currency). The fund is not constrained based on the country, region, market capitalization, credit quality or duration of its investments and its assets may at times be concentrated in a particular country or region.', 0.00035, 0.0023, 5682791, 6.71921e+06, 85.263, 85.58, 0, 0.9902, NULL, NULL, NULL, NULL, 8.6, 6.79, '{"Cap_Size": null, "Quote_Mode": "ETF", "Currency_Base": "Usd", "GeoZone_Class": "U.S.A.", "Strategy_Type": null}', '{"Net_Worth": 312150884352, "Yield_Rate": 0.0202, "Expense_Net": 0.00035, "Benchmark_Exp": 0.0023, "Turnover_Ratio": 0.79}', '{"volume_metrics": {"Vol_3M": 5682791, "Vol_Recent": 6719210}, "moving_averages": {"MA_50": 85.263, "MA_200": 85.58}}', '{"asset_allocation": {"Bond_Weight": 0.9902, "Equity_Weight": 0}, "bond_characteristics": {"Avg_Maturity": 8.6, "Duration_Yrs": 6.79}}', '{"valuation_metrics": {"PB_Ratio": null, "PE_Ratio": null, "PS_Ratio": null, "PCF_Ratio": null}}');
INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (157, 'BNDC', 'ETF', 'United States', 'AB Corporate Shares - AB Impact', 'AB Impact Municipal Income Shares', 'Dollar', NULL, NULL, 'AllianceBernstein', 'PCX', 'Intermediate-Term Bond', 119968144, 0.0214, '2016-11-18', 0.91, 'The investment seeks to earn the highest level of current income, exempt from federal taxation, that is available consistent with what the Adviser considers to be an appropriate level of risk. The fund pursues its objective by investing principally in high-yielding municipal securities of any credit quality that (i) score highly on the Adviser''s environmental, social and governance ("ESG") criteria and (ii) are deemed by the Adviser to have an environmental or social impact in underserved or low socio-economic communities. The fund invests at least 80% of its net assets in municipal securities that pay interest that is exempt from federal income tax.', 0.0035, 0.0023, 9370, 10260, 26.197, 26.261, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 7.07, '{"Cap_Size": null, "Quote_Mode": "ETF", "Currency_Base": "Dollar", "GeoZone_Class": "United States", "Strategy_Type": null}', '{"Net_Worth": 119968144, "Yield_Rate": 0.0214, "Expense_Net": 0.0035, "Benchmark_Exp": 0.0023, "Turnover_Ratio": 0.91}', '{"volume_metrics": {"Vol_3M": 9370, "Vol_Recent": 10260}, "moving_averages": {"MA_50": 26.197, "MA_200": 26.261}}', '{"asset_allocation": {"Bond_Weight": null, "Equity_Weight": null}, "bond_characteristics": {"Avg_Maturity": null, "Duration_Yrs": 7.07}}', '{"valuation_metrics": {"PB_Ratio": null, "PE_Ratio": null, "PS_Ratio": null, "PCF_Ratio": null}}');
INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (158, 'BNDX', 'ETF', 'US', 'American Century Balanced Fund ', 'American Century Balanced Fund I Class', 'Usd', NULL, NULL, 'American Century Investments', 'NGM', NULL, 116407050240, 0.0094, '2013-05-31', 0.31, 'The investment seeks long-term capital growth and current income. For the equity portion of the fund, the portfolio managers select stocks using quantitative management techniques in a multi-step process. For the fixed-income portion of the fund, the portfolio managers invest in a diversified portfolio of high- and medium-grade non-money market debt securities. These securities, which may be payable in U.S. or foreign currencies, may include corporate bonds and notes, government securities, bank loans, securities backed by mortgages or other assets and collateralized debt obligations.', 0.0008, NULL, 2296838, 2.27619e+06, 56.911, 57.209, NULL, NULL, NULL, NULL, NULL, NULL, 9.7, 8.38, '{"Cap_Size": null, "Quote_Mode": "ETF", "Currency_Base": "Usd", "GeoZone_Class": "US", "Strategy_Type": null}', '{"Net_Worth": 116407050240, "Yield_Rate": 0.0094, "Expense_Net": 0.0008, "Benchmark_Exp": null, "Turnover_Ratio": 0.31}', '{"volume_metrics": {"Vol_3M": 2296838, "Vol_Recent": 2276190}, "moving_averages": {"MA_50": 56.911, "MA_200": 57.209}}', '{"asset_allocation": {"Bond_Weight": null, "Equity_Weight": null}, "bond_characteristics": {"Avg_Maturity": 9.7, "Duration_Yrs": 8.38}}', '{"valuation_metrics": {"PB_Ratio": null, "PE_Ratio": null, "PS_Ratio": null, "PCF_Ratio": null}}');
INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (159, 'BNE', 'ETF', 'UNITED_STATES', 'AB Trust - AB International Val', 'AB International Value Fund Advisor Class', 'USD', 'Growth', 'Medium', 'AllianceBernstein', 'PCX', NULL, 7013170, NULL, '2020-12-08', NULL, 'The investment seeks long-term growth of capital. The fund invests primarily in a diversified portfolio of equity securities of established companies selected from more than 40 industries and more than 40 developed and emerging market countries. These countries currently include the developed nations in Europe and the Far East, Canada, Australia and emerging market countries worldwide. The fund invests significantly (at least 40%--unless market conditions are not deemed favorable by the Adviser) in securities of non-U.S. companies. In addition, it invests, under normal circumstances, in the equity securities of companies located in at least three countries.', 0.0087, NULL, 12719, 790, 29.75, 28.653, 0.9961, 0, 3.21, 14.09, 30.16, 1.53, NULL, NULL, '{"Cap_Size": "Medium", "Quote_Mode": "ETF", "Currency_Base": "USD", "GeoZone_Class": "UNITED_STATES", "Strategy_Type": "Growth"}', '{"Net_Worth": 7013170, "Yield_Rate": null, "Expense_Net": 0.0087, "Benchmark_Exp": null, "Turnover_Ratio": null}', '{"volume_metrics": {"Vol_3M": 12719, "Vol_Recent": 790}, "moving_averages": {"MA_50": 29.75, "MA_200": 28.653}}', '{"asset_allocation": {"Bond_Weight": 0, "Equity_Weight": 0.9961}, "bond_characteristics": {"Avg_Maturity": null, "Duration_Yrs": null}}', '{"valuation_metrics": {"PB_Ratio": 3.21, "PE_Ratio": 30.16, "PS_Ratio": 1.53, "PCF_Ratio": 14.09}}');
INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (161, 'BOB', 'ETF', 'US', 'AB Cap Fund, Inc. - AB Emerging', 'AB Emerging Markets Multi-Asset Portfolio Class K', 'Usd', 'Value', 'Medium', 'AllianceBernstein', 'BTS', 'Large Blend', 14130040, NULL, '2021-01-12', NULL, 'The investment seeks to maximize total return. The fund invests at least 80% of its net assets under normal circumstances in securities of emerging market issuers and/or the currencies of emerging market countries. It will invest between 30% and 95% of its net assets in equity securities, and between 0% and 65% of its net assets in debt securities, with any remainder held in cash (including foreign currency). The fund is not constrained based on the country, region, market capitalization, credit quality or duration of its investments and its assets may at times be concentrated in a particular country or region.', 0.0085, 0.0036, 1793, 2680, 26.901, 25.988, 0.9904, 0, 1.85, NULL, 15.28, 1.62, NULL, NULL, '{"Cap_Size": "Medium", "Quote_Mode": "ETF", "Currency_Base": "Usd", "GeoZone_Class": "US", "Strategy_Type": "Value"}', '{"Net_Worth": 14130040, "Yield_Rate": null, "Expense_Net": 0.0085, "Benchmark_Exp": 0.0036, "Turnover_Ratio": null}', '{"volume_metrics": {"Vol_3M": 1793, "Vol_Recent": 2680}, "moving_averages": {"MA_50": 26.901, "MA_200": 25.988}}', '{"asset_allocation": {"Bond_Weight": 0, "Equity_Weight": 0.9904}, "bond_characteristics": {"Avg_Maturity": null, "Duration_Yrs": null}}', '{"valuation_metrics": {"PB_Ratio": 1.85, "PE_Ratio": 15.28, "PS_Ratio": 1.62, "PCF_Ratio": null}}');
INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (162, 'BOCT', 'ETF', 'U.S.', 'Alger Portfolios - Alger Balanc', 'Alger Balanced Portfolio Class I-2', 'US_DOLLAR', 'Blend', 'Large', 'Alger', 'BTS', NULL, 81503288, NULL, '2018-09-28', NULL, 'The investment seeks current income and long-term capital appreciation. The manager focuses on stocks of companies that the advisor believes demonstrate growth potential and on fixed-income securities, with emphasis on income-producing securities that appear to have potential for capital appreciation. It normally will invest at least 25% of its net assets in fixed-income securities and at least 25% of its net assets in equity securities. The fund also may invest up to 10% of its net assets in lower-rated securities, rated "B" (or the equivalent) or better by any one of those rating agencies.', 0.008, NULL, 26601, 5040, 33.621, 32.311, 1, 0, 4.42, 17.56, 26.46, 2.96, NULL, NULL, '{"Cap_Size": "Large", "Quote_Mode": "ETF", "Currency_Base": "US_DOLLAR", "GeoZone_Class": "U.S.", "Strategy_Type": "Blend"}', '{"Net_Worth": 81503288, "Yield_Rate": null, "Expense_Net": 0.008, "Benchmark_Exp": null, "Turnover_Ratio": null}', '{"volume_metrics": {"Vol_3M": 26601, "Vol_Recent": 5040}, "moving_averages": {"MA_50": 33.621, "MA_200": 32.311}}', '{"asset_allocation": {"Bond_Weight": 0, "Equity_Weight": 1}, "bond_characteristics": {"Avg_Maturity": null, "Duration_Yrs": null}}', '{"valuation_metrics": {"PB_Ratio": 4.42, "PE_Ratio": 26.46, "PS_Ratio": 2.96, "PCF_Ratio": 17.56}}');
INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (163, 'BOIL', 'ETF', 'us', 'American Beacon Balanced Fund A', 'American Beacon Balanced Fund Advisor Class', 'USD', NULL, NULL, 'American Beacon', 'PCX', 'Trading--Leveraged Commodities', 70214528, NULL, '2011-10-04', NULL, 'The investment seeks income and capital appreciation. Under normal circumstances, between 50% and 70% of the fund''s total assets are invested in equity securities and between 30% and 50% of the fund''s total assets are invested in debt securities. The fund''s equity investments may include common stocks, convertible securities, real estate investment trusts ("REITs"), American Depositary Receipts ("ADRs") and U.S. dollar-denominated foreign stocks traded on U.S. exchanges (collectively referred to as "stocks"). It may invest in companies of all market capitalizations.', 0.0131, 0.009, 1827085, 2.5572e+06, 64.969, 41.076, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '{"Cap_Size": null, "Quote_Mode": "ETF", "Currency_Base": "USD", "GeoZone_Class": "us", "Strategy_Type": null}', '{"Net_Worth": 70214528, "Yield_Rate": null, "Expense_Net": 0.0131, "Benchmark_Exp": 0.009, "Turnover_Ratio": null}', '{"volume_metrics": {"Vol_3M": 1827085, "Vol_Recent": 2557200}, "moving_averages": {"MA_50": 64.969, "MA_200": 41.076}}', '{"asset_allocation": {"Bond_Weight": null, "Equity_Weight": null}, "bond_characteristics": {"Avg_Maturity": null, "Duration_Yrs": null}}', '{"valuation_metrics": {"PB_Ratio": null, "PE_Ratio": null, "PS_Ratio": null, "PCF_Ratio": null}}');
INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (166, 'BOTZ', 'ETF', 'UNITED_STATES', 'AMG Managers Fairpointe Mid Cap', 'AMG River Road Mid Cap Value Fund - Class I', 'Usd', 'Growth', 'Large', 'AMG Funds', 'NGM', 'Miscellaneous Sector', 2581059840, 0.0017, '2016-09-12', NULL, 'The investment seeks long-term total return through capital appreciation. Under normal circumstances, the fund invests at least 80% of its net assets, plus the amount of any borrowings for investment purposes, in securities of mid-capitalization companies. The adviser currently considers mid-cap companies to be those with market capitalizations at the time of acquisition within the capitalization range of the Russell Midcap© Index.', 0.0068, 0.0067, 635325, 572480, 37.321, 35.321, 0.9995, 0, 4.14, 23.35, 47.48, 3.63, NULL, NULL, '{"Cap_Size": "Large", "Quote_Mode": "ETF", "Currency_Base": "Usd", "GeoZone_Class": "UNITED_STATES", "Strategy_Type": "Growth"}', '{"Net_Worth": 2581059840, "Yield_Rate": 0.0017, "Expense_Net": 0.0068, "Benchmark_Exp": 0.0067, "Turnover_Ratio": null}', '{"volume_metrics": {"Vol_3M": 635325, "Vol_Recent": 572480}, "moving_averages": {"MA_50": 37.321, "MA_200": 35.321}}', '{"asset_allocation": {"Bond_Weight": 0, "Equity_Weight": 0.9995}, "bond_characteristics": {"Avg_Maturity": null, "Duration_Yrs": null}}', '{"valuation_metrics": {"PB_Ratio": 4.14, "PE_Ratio": 47.48, "PS_Ratio": 3.63, "PCF_Ratio": 23.35}}');
INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (167, 'BOUT', 'ETF', 'U.S.A.', 'AB Bond Fund, Inc. - AB Bond In', 'AB Bond Inflation Strategy Class A', 'US Dollar', 'Blend', 'Medium', 'AllianceBernstein', 'PCX', NULL, 19716544, NULL, '2018-09-12', 16.37, 'The investment seeks to maximize real return without assuming what the Adviser considers to be undue risk. The fund pursues its objective by investing principally in inflation-indexed securities (such as Treasury Inflation-Protected Securities ("TIPS") or inflation-indexed securities from issuers other than the U.S. Treasury) or by gaining inflation protection through derivatives transactions, such as inflation (CPI) swaps or total return swaps linked to TIPS. Under normal circumstances, it invests at least 80% of its net assets in fixed-income securities.', 0.008, NULL, 13388, 12350, 36.444, 34.604, 0.9912, 0, 2.43, 13.34, 19.72, 3.52, NULL, NULL, '{"Cap_Size": "Medium", "Quote_Mode": "ETF", "Currency_Base": "US Dollar", "GeoZone_Class": "U.S.A.", "Strategy_Type": "Blend"}', '{"Net_Worth": 19716544, "Yield_Rate": null, "Expense_Net": 0.008, "Benchmark_Exp": null, "Turnover_Ratio": 16.37}', '{"volume_metrics": {"Vol_3M": 13388, "Vol_Recent": 12350}, "moving_averages": {"MA_50": 36.444, "MA_200": 34.604}}', '{"asset_allocation": {"Bond_Weight": 0, "Equity_Weight": 0.9912}, "bond_characteristics": {"Avg_Maturity": null, "Duration_Yrs": null}}', '{"valuation_metrics": {"PB_Ratio": 2.43, "PE_Ratio": 19.72, "PS_Ratio": 3.52, "PCF_Ratio": 13.34}}');
