INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (186, 'BSJM', 'ETF', 'U.S.', 'AB Bond Fund, Inc. - AB Total R', 'AB Total Return Bond Portfolio Class A', 'AmericanDollar', NULL, NULL, 'AllianceBernstein', 'NGM', 'High Yield Bond', 887304320, 0.0378, '2014-09-17', 0.63, 'The investment seeks to maximize long-term total return. The fund invests at least 80% of its net assets in fixed-income securities. It invests in readily marketable fixed-income securities with a range of maturities from short- to long-term and relatively attractive yields that do not involve undue risk of loss of capital. It may invest up to 25% of its net assets in below investment grade bonds. The fund may use leverage for investment purposes.', 0.0042, 0.0047, 283564, 356790, 23.204, 23.279, 0, 1, NULL, NULL, NULL, NULL, 3.52, 1.33, '{"Cap_Size": null, "Quote_Mode": "ETF", "Currency_Base": "AmericanDollar", "GeoZone_Class": "U.S.", "Strategy_Type": null}', '{"Net_Worth": 887304320, "Yield_Rate": 0.0378, "Expense_Net": 0.0042, "Benchmark_Exp": 0.0047, "Turnover_Ratio": 0.63}', '{"volume_metrics": {"Vol_3M": 283564, "Vol_Recent": 356790}, "moving_averages": {"MA_50": 23.204, "MA_200": 23.279}}', '{"asset_allocation": {"Bond_Weight": 1, "Equity_Weight": 0}, "bond_characteristics": {"Avg_Maturity": 3.52, "Duration_Yrs": 1.33}}', '{"valuation_metrics": {"PB_Ratio": null, "PE_Ratio": null, "PS_Ratio": null, "PCF_Ratio": null}}');
INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (239, 'CHAD', 'ETF', 'United States', 'American Century Diversified Bo', 'American Century Diversified Bond Fund I Class', 'Dollar', NULL, NULL, 'American Century Investments', 'PCX', 'Trading--Inverse Equity', 125670120, NULL, '2015-06-17', NULL, 'The investment seeks a high level of income by investing in non-money market debt securities. Under normal market conditions, the fund invests at least 80% of its net assets in high- and medium-grade, non-money market debt securities. It invests most of its assets in investment-grade securities. The weighted average maturity of the fund''s portfolio must be three and one-half years or longer.', 0.0085, 0.0092, 16774, 10310, 16.876, 17.052, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '{"Cap_Size": null, "Quote_Mode": "ETF", "Currency_Base": "Dollar", "GeoZone_Class": "United States", "Strategy_Type": null}', '{"Net_Worth": 125670120, "Yield_Rate": null, "Expense_Net": 0.0085, "Benchmark_Exp": 0.0092, "Turnover_Ratio": null}', '{"volume_metrics": {"Vol_3M": 16774, "Vol_Recent": 10310}, "moving_averages": {"MA_50": 16.876, "MA_200": 17.052}}', '{"asset_allocation": {"Bond_Weight": null, "Equity_Weight": null}, "bond_characteristics": {"Avg_Maturity": null, "Duration_Yrs": null}}', '{"valuation_metrics": {"PB_Ratio": null, "PE_Ratio": null, "PS_Ratio": null, "PCF_Ratio": null}}');
INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (189, 'BSJP', 'ETF', 'USA', 'Invesco Balanced-Risk Allocatio', 'Invesco Balanced-Risk Allocation Fund Class C', 'USD', NULL, NULL, 'Invesco', 'NGM', 'High Yield Bond', 271814528, 0.0459, '2017-09-26', 0.26, 'The investment seeks to provide total return with a low to moderate correlation to traditional financial market indices. The fund''s investment strategy is designed to provide capital loss protection during down markets by investing in multiple asset classes. Its exposure to these three asset classes will be achieved primarily through investments in derivative instruments (generally having aggregate notional exposure exceeding 65% of the fund''s net assets), including but not limited to futures, options, currency forward contracts and swap agreements.', 0.0042, 0.0047, 105835, 155510, 24.495, 24.581, NULL, NULL, NULL, NULL, NULL, NULL, 4.29, 2.25, '{"Cap_Size": null, "Quote_Mode": "ETF", "Currency_Base": "USD", "GeoZone_Class": "USA", "Strategy_Type": null}', '{"Net_Worth": 271814528, "Yield_Rate": 0.0459, "Expense_Net": 0.0042, "Benchmark_Exp": 0.0047, "Turnover_Ratio": 0.26}', '{"volume_metrics": {"Vol_3M": 105835, "Vol_Recent": 155510}, "moving_averages": {"MA_50": 24.495, "MA_200": 24.581}}', '{"asset_allocation": {"Bond_Weight": null, "Equity_Weight": null}, "bond_characteristics": {"Avg_Maturity": 4.29, "Duration_Yrs": 2.25}}', '{"valuation_metrics": {"PB_Ratio": null, "PE_Ratio": null, "PS_Ratio": null, "PCF_Ratio": null}}');
INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (190, 'BSJQ', 'ETF', 'us', 'AB Cap Fund, Inc. - AB Emerging', 'AB Emerging Markets Multi-Asset Portfolio Class R', 'US_DOLLAR', NULL, NULL, 'AllianceBernstein', 'NGM', 'High Yield Bond', 98031888, 0.0438, '2018-08-09', 0.35, 'The investment seeks to maximize total return. The fund invests at least 80% of its net assets under normal circumstances in securities of emerging market issuers and/or the currencies of emerging market countries. It will invest between 30% and 95% of its net assets in equity securities, and between 0% and 65% of its net assets in debt securities, with any remainder held in cash (including foreign currency). The fund is not constrained based on the country, region, market capitalization, credit quality or duration of its investments and its assets may at times be concentrated in a particular country or region.', 0.0042, 0.0047, 72295, 131530, 25.59, 25.658, NULL, NULL, NULL, NULL, NULL, NULL, 4.93, 2.43, '{"Cap_Size": null, "Quote_Mode": "ETF", "Currency_Base": "US_DOLLAR", "GeoZone_Class": "us", "Strategy_Type": null}', '{"Net_Worth": 98031888, "Yield_Rate": 0.0438, "Expense_Net": 0.0042, "Benchmark_Exp": 0.0047, "Turnover_Ratio": 0.35}', '{"volume_metrics": {"Vol_3M": 72295, "Vol_Recent": 131530}, "moving_averages": {"MA_50": 25.59, "MA_200": 25.658}}', '{"asset_allocation": {"Bond_Weight": null, "Equity_Weight": null}, "bond_characteristics": {"Avg_Maturity": 4.93, "Duration_Yrs": 2.43}}', '{"valuation_metrics": {"PB_Ratio": null, "PE_Ratio": null, "PS_Ratio": null, "PCF_Ratio": null}}');
INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (191, 'BSJR', 'ETF', 'U.S.A.', 'AmericaFirst Monthly Risk-On Ri', 'AmericaFirst Monthly Risk-On Risk-Off Fund Class A', 'usd', NULL, NULL, 'AmericaFirst Funds', 'NGM', 'High Yield Bond', 41023856, 0.0437, '2019-09-12', 0.56, 'The investment seeks to achieve capital appreciation with a focus on producing positive returns regardless of the direction of the financial markets. The fund seeks to achieve its investment objective through long positions in global equity markets and U.S. interest rate markets. It will invest in equity securities regardless of market capitalization and regardless of industry sector. With regard to fixed income securities, the fund invests primarily in U.S. Treasury bonds with a mid-term maturity.', 0.0042, 0.0047, 15235, 24080, 25.438, 25.486, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '{"Cap_Size": null, "Quote_Mode": "ETF", "Currency_Base": "usd", "GeoZone_Class": "U.S.A.", "Strategy_Type": null}', '{"Net_Worth": 41023856, "Yield_Rate": 0.0437, "Expense_Net": 0.0042, "Benchmark_Exp": 0.0047, "Turnover_Ratio": 0.56}', '{"volume_metrics": {"Vol_3M": 15235, "Vol_Recent": 24080}, "moving_averages": {"MA_50": 25.438, "MA_200": 25.486}}', '{"asset_allocation": {"Bond_Weight": null, "Equity_Weight": null}, "bond_characteristics": {"Avg_Maturity": null, "Duration_Yrs": null}}', '{"valuation_metrics": {"PB_Ratio": null, "PE_Ratio": null, "PS_Ratio": null, "PCF_Ratio": null}}');
