INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (201, 'BSMT', 'ETF', 'US', 'Invesco Balanced-Risk Allocatio', 'Invesco Balanced-Risk Allocation Fund Class A', 'Usd', NULL, NULL, 'Invesco', 'NGM', NULL, 10365555, 0.0168, '2019-09-25', NULL, 'The investment seeks to provide total return with a low to moderate correlation to traditional financial market indices. The fund''s investment strategy is designed to provide capital loss protection during down markets by investing in multiple asset classes. Its exposure to these three asset classes will be achieved primarily through investments in derivative instruments (generally having aggregate notional exposure exceeding 65% of the fund''s net assets), including but not limited to futures, options, currency forward contracts and swap agreements.', 0.0018, NULL, 2022, 3730, 25.945, 26.05, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '{"Cap_Size": null, "Quote_Mode": "ETF", "Currency_Base": "Usd", "GeoZone_Class": "US", "Strategy_Type": null}', '{"Net_Worth": 10365555, "Yield_Rate": 0.0168, "Expense_Net": 0.0018, "Benchmark_Exp": null, "Turnover_Ratio": null}', '{"volume_metrics": {"Vol_3M": 2022, "Vol_Recent": 3730}, "moving_averages": {"MA_50": 25.945, "MA_200": 26.05}}', '{"asset_allocation": {"Bond_Weight": null, "Equity_Weight": null}, "bond_characteristics": {"Avg_Maturity": null, "Duration_Yrs": null}}', '{"valuation_metrics": {"PB_Ratio": null, "PE_Ratio": null, "PS_Ratio": null, "PCF_Ratio": null}}');
INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (202, 'BSMU', 'ETF', 'U.S.', 'American Beacon Small Cap Value', 'American Beacon Small Cap Value Fund Class A', 'Usd', NULL, NULL, 'American Beacon', 'NGM', NULL, 7676980, NULL, '2020-09-16', NULL, 'The investment seeks long-term capital appreciation and current income. Under normal circumstances, at least 80% of the fund''s net assets (plus the amount of any borrowings for investment purposes) are invested in equity securities of small market capitalization U.S. companies. These companies have market capitalizations of $5 billion or less at the time of investment. The fund''s investments may include common stocks, preferred stocks, real estate investment trusts ("REITs"), American Depositary Receipts ("ADRs"), master limited partnerships ("MLPs"), and U.S. dollar-denominated foreign stocks traded on U.S. exchanges (collectively, "stocks").', 0.0018, NULL, 1475, 1830, 25.351, 25.5, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '{"Cap_Size": null, "Quote_Mode": "ETF", "Currency_Base": "Usd", "GeoZone_Class": "U.S.", "Strategy_Type": null}', '{"Net_Worth": 7676980, "Yield_Rate": null, "Expense_Net": 0.0018, "Benchmark_Exp": null, "Turnover_Ratio": null}', '{"volume_metrics": {"Vol_3M": 1475, "Vol_Recent": 1830}, "moving_averages": {"MA_50": 25.351, "MA_200": 25.5}}', '{"asset_allocation": {"Bond_Weight": null, "Equity_Weight": null}, "bond_characteristics": {"Avg_Maturity": null, "Duration_Yrs": null}}', '{"valuation_metrics": {"PB_Ratio": null, "PE_Ratio": null, "PS_Ratio": null, "PCF_Ratio": null}}');
INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (203, 'BSV', 'ETF', 'America', 'AB Trust - AB Discovery Value F', 'AB Discovery Value Fund Class I', 'US$', NULL, NULL, 'AllianceBernstein', 'PCX', 'Short-Term Bond', 67711201280, 0.0148, '2007-04-03', 0.49, 'The investment seeks long-term growth of capital. The fund invests primarily in a diversified portfolio of equity securities of small- to mid-capitalization U.S. companies. Under normal circumstances, it invests at least 80% of its net assets in securities of small- to mid-capitalization companies. For purposes of this policy, small- to mid-capitalization companies are those that, at the time of investment, fall within the capitalization range between the smallest company in the Russell 2500© Value Index and the greater of $5 billion or the market capitalization of the largest company in the Russell 2500© Value Index.', 0.0005, 0.0026, 2677877, 3.62508e+06, 81.529, 82.07, NULL, NULL, NULL, NULL, NULL, NULL, 2.9, 2.78, '{"Cap_Size": null, "Quote_Mode": "ETF", "Currency_Base": "US$", "GeoZone_Class": "America", "Strategy_Type": null}', '{"Net_Worth": 67711201280, "Yield_Rate": 0.0148, "Expense_Net": 0.0005, "Benchmark_Exp": 0.0026, "Turnover_Ratio": 0.49}', '{"volume_metrics": {"Vol_3M": 2677877, "Vol_Recent": 3625080}, "moving_averages": {"MA_50": 81.529, "MA_200": 82.07}}', '{"asset_allocation": {"Bond_Weight": null, "Equity_Weight": null}, "bond_characteristics": {"Avg_Maturity": 2.9, "Duration_Yrs": 2.78}}', '{"valuation_metrics": {"PB_Ratio": null, "PE_Ratio": null, "PS_Ratio": null, "PCF_Ratio": null}}');
