INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (230, 'CDL', 'ETF', 'usa', 'AB Trust - AB Discovery Value F', 'AB Discovery Value Fund Advisor Class', 'Dollar', 'Value', 'Large', 'AllianceBernstein', 'NGM', 'Large Value', 221055552, 0.0245, '2015-07-07', NULL, 'The investment seeks long-term growth of capital. The fund invests primarily in a diversified portfolio of equity securities of small- to mid-capitalization U.S. companies. Under normal circumstances, it invests at least 80% of its net assets in securities of small- to mid-capitalization companies. For purposes of this policy, small- to mid-capitalization companies are those that, at the time of investment, fall within the capitalization range between the smallest company in the Russell 2500© Value Index and the greater of $5 billion or the market capitalization of the largest company in the Russell 2500© Value Index.', 0.0035, 0.0034, 6345, 7730, 58.45, 56.927, 0.9993, 0, 2.48, 10.79, 17.61, 1.5, NULL, NULL, '{"Cap_Size": "Large", "Quote_Mode": "ETF", "Currency_Base": "Dollar", "GeoZone_Class": "usa", "Strategy_Type": "Value"}', '{"Net_Worth": 221055552, "Yield_Rate": 0.0245, "Expense_Net": 0.0035, "Benchmark_Exp": 0.0034, "Turnover_Ratio": null}', '{"volume_metrics": {"Vol_3M": 6345, "Vol_Recent": 7730}, "moving_averages": {"MA_50": 58.45, "MA_200": 56.927}}', '{"asset_allocation": {"Bond_Weight": 0, "Equity_Weight": 0.9993}, "bond_characteristics": {"Avg_Maturity": null, "Duration_Yrs": null}}', '{"valuation_metrics": {"PB_Ratio": 2.48, "PE_Ratio": 17.61, "PS_Ratio": 1.5, "PCF_Ratio": 10.79}}');
INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (231, 'CEFA', 'ETF', 'USA', 'AB Cap Fund, Inc. - AB Emerging', 'AB Emerging Markets Multi-Asset Portfolio Class Z', 'DOLLAR', 'Blend', 'Large', 'AllianceBernstein', 'NGM', 'Foreign Large Blend', 3208577, 0.0185, '2020-06-22', NULL, 'The investment seeks to maximize total return. The fund invests at least 80% of its net assets under normal circumstances in securities of emerging market issuers and/or the currencies of emerging market countries. It will invest between 30% and 95% of its net assets in equity securities, and between 0% and 65% of its net assets in debt securities, with any remainder held in cash (including foreign currency). The fund is not constrained based on the country, region, market capitalization, credit quality or duration of its investments and its assets may at times be concentrated in a particular country or region.', 0.0035, 0.0037, 1109, 1800, 32.577, 32.3, 0.9991, 0, 1.86, 11.11, 20.38, 1.6, NULL, NULL, '{"Cap_Size": "Large", "Quote_Mode": "ETF", "Currency_Base": "DOLLAR", "GeoZone_Class": "USA", "Strategy_Type": "Blend"}', '{"Net_Worth": 3208577, "Yield_Rate": 0.0185, "Expense_Net": 0.0035, "Benchmark_Exp": 0.0037, "Turnover_Ratio": null}', '{"volume_metrics": {"Vol_3M": 1109, "Vol_Recent": 1800}, "moving_averages": {"MA_50": 32.577, "MA_200": 32.3}}', '{"asset_allocation": {"Bond_Weight": 0, "Equity_Weight": 0.9991}, "bond_characteristics": {"Avg_Maturity": null, "Duration_Yrs": null}}', '{"valuation_metrics": {"PB_Ratio": 1.86, "PE_Ratio": 20.38, "PS_Ratio": 1.6, "PCF_Ratio": 11.11}}');
INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (232, 'CEFS', 'ETF', 'America', 'Alger Capital Appreciation Fund', 'Alger Capital Appreciation Fund Class A', 'US_DOLLAR', 'Value', 'Large', 'Alger', 'BTS', 'Tactical Allocation', 74306464, 0.0792, '2017-03-20', NULL, 'The investment seeks long-term capital appreciation. The fund invests at least 85% of its net assets, plus any borrowings for investment purposes, in equity securities of companies of any market capitalization that the Manager believes demonstrate promising growth potential. It may invest a significant portion of its assets in securities of companies conducting business within a single sector, including the information technology, healthcare and consumer discretionary sectors.', 0.038, 0.0112, 17601, 24820, 21.617, 21.17, NULL, NULL, 2.11, 11.96, 16.95, 2.12, 7.97, 6.17, '{"Cap_Size": "Large", "Quote_Mode": "ETF", "Currency_Base": "US_DOLLAR", "GeoZone_Class": "America", "Strategy_Type": "Value"}', '{"Net_Worth": 74306464, "Yield_Rate": 0.0792, "Expense_Net": 0.038, "Benchmark_Exp": 0.0112, "Turnover_Ratio": null}', '{"volume_metrics": {"Vol_3M": 17601, "Vol_Recent": 24820}, "moving_averages": {"MA_50": 21.617, "MA_200": 21.17}}', '{"asset_allocation": {"Bond_Weight": null, "Equity_Weight": null}, "bond_characteristics": {"Avg_Maturity": 7.97, "Duration_Yrs": 6.17}}', '{"valuation_metrics": {"PB_Ratio": 2.11, "PE_Ratio": 16.95, "PS_Ratio": 2.12, "PCF_Ratio": 11.96}}');
INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (233, 'CEW', 'ETF', 'usa', 'AB Municipal Income Fund, Inc. ', 'AB Municipal Income Fund California Portfolio Class C', 'USD', NULL, NULL, 'AllianceBernstein', 'PCX', 'Emerging-Markets Local-Currency Bond', 16386980, 0.0065, '2009-05-06', NULL, 'The investment seeks to earn the highest level of current income, exempt from federal income tax and California personal income tax, which is available without assuming what the Adviser considers to be undue risk to income or principal. The fund invests principally in high-yielding, predominantly investment grade municipal securities. It invests at least 80% of its net assets in municipal securities that pay interest that is exempt from federal income tax. These securities may pay interest that is subject to the federal alternative minimum tax ("AMT") for certain taxpayers.', 0.0055, 0.0055, 5641, 1970, 17.694, 18.009, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '{"Cap_Size": null, "Quote_Mode": "ETF", "Currency_Base": "USD", "GeoZone_Class": "usa", "Strategy_Type": null}', '{"Net_Worth": 16386980, "Yield_Rate": 0.0065, "Expense_Net": 0.0055, "Benchmark_Exp": 0.0055, "Turnover_Ratio": null}', '{"volume_metrics": {"Vol_3M": 5641, "Vol_Recent": 1970}, "moving_averages": {"MA_50": 17.694, "MA_200": 18.009}}', '{"asset_allocation": {"Bond_Weight": null, "Equity_Weight": null}, "bond_characteristics": {"Avg_Maturity": null, "Duration_Yrs": null}}', '{"valuation_metrics": {"PB_Ratio": null, "PE_Ratio": null, "PS_Ratio": null, "PCF_Ratio": null}}');
