INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (260, 'CLDL', 'ETF', 'U.S.A.', 'Invesco Exchange Fund Shs', 'Invesco Exchange Fund', 'DOLLAR', 'Growth', 'Large', 'Invesco', 'PCX', 'Trading--Leveraged Equity', 27698024, NULL, '2021-01-08', NULL, 'The investment seeks long-term growth of capital; current income is a secondary consideration. The fund accepts, in exchange for fund shares, large blocks of individual securities with large unrealized appreciation. This exchange is a non-taxable event. The fund invests primarily in common stocks and convertible securities. It may not invest in other investment companies.', 0.0107, 0.009, 7193, 17530, 29.789, 26.557, NULL, NULL, 13.11, 31.63, 40.31, 11.05, NULL, NULL, '{"Cap_Size": "Large", "Quote_Mode": "ETF", "Currency_Base": "DOLLAR", "GeoZone_Class": "U.S.A.", "Strategy_Type": "Growth"}', '{"Net_Worth": 27698024, "Yield_Rate": null, "Expense_Net": 0.0107, "Benchmark_Exp": 0.009, "Turnover_Ratio": null}', '{"volume_metrics": {"Vol_3M": 7193, "Vol_Recent": 17530}, "moving_averages": {"MA_50": 29.789, "MA_200": 26.557}}', '{"asset_allocation": {"Bond_Weight": null, "Equity_Weight": null}, "bond_characteristics": {"Avg_Maturity": null, "Duration_Yrs": null}}', '{"valuation_metrics": {"PB_Ratio": 13.11, "PE_Ratio": 40.31, "PS_Ratio": 11.05, "PCF_Ratio": 31.63}}');
