INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (279, 'CORN', 'ETF', 'usa', 'Invesco Growth & Income Fund Cl', 'Invesco Growth and Income Fund Class A', 'usd', NULL, NULL, 'Invesco', 'PCX', NULL, 176720000, NULL, '2010-06-09', NULL, 'The investment seeks total return through growth of capital and current income. Under normal market conditions, the fund''s investment adviser seeks to achieve the fund''s investment objective by investing primarily in income-producing equity securities, which include common stocks and convertible securities. It may invest in securities of issuers of all capitalization sizes; however, a substantial number of the issuers in which the fund invests are large-capitalization issuers. The fund may invest up to 25% of its net assets in securities of foreign issuers, which may include depositary receipts.', 0.0111, NULL, 174932, 181230, 20.769, 19.873, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '{"Cap_Size": null, "Quote_Mode": "ETF", "Currency_Base": "usd", "GeoZone_Class": "usa", "Strategy_Type": null}', '{"Net_Worth": 176720000, "Yield_Rate": null, "Expense_Net": 0.0111, "Benchmark_Exp": null, "Turnover_Ratio": null}', '{"volume_metrics": {"Vol_3M": 174932, "Vol_Recent": 181230}, "moving_averages": {"MA_50": 20.769, "MA_200": 19.873}}', '{"asset_allocation": {"Bond_Weight": null, "Equity_Weight": null}, "bond_characteristics": {"Avg_Maturity": null, "Duration_Yrs": null}}', '{"valuation_metrics": {"PB_Ratio": null, "PE_Ratio": null, "PS_Ratio": null, "PCF_Ratio": null}}');
