INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (286, 'CRUZ', 'ETF', 'America', 'American Century Equity Income ', 'American Century Equity Income Fund I Class', 'usd', 'Value', 'Medium', 'American Century Investments', 'PCX', 'Consumer Cyclical', 2260941, NULL, '2021-06-03', NULL, 'The investment seeks current income; capital appreciation is a secondary objective. The portfolio managers look for equity securities of companies with a favorable income-paying history that have prospects for income payments to continue or increase. The portfolio managers also look for equity securities of companies that they believe are undervalued and have the potential for an increase in price. The fund may invest a portion of its assets in foreign securities when these securities meet the portfolio managers'' standards of selection.', 0.0045, 0.0045, 28630, 68240, 22.312, 22.267, 0.9951, 0, 2.69, NULL, NULL, 5.05, NULL, NULL, '{"Cap_Size": "Medium", "Quote_Mode": "ETF", "Currency_Base": "usd", "GeoZone_Class": "America", "Strategy_Type": "Value"}', '{"Net_Worth": 2260941, "Yield_Rate": null, "Expense_Net": 0.0045, "Benchmark_Exp": 0.0045, "Turnover_Ratio": null}', '{"volume_metrics": {"Vol_3M": 28630, "Vol_Recent": 68240}, "moving_averages": {"MA_50": 22.312, "MA_200": 22.267}}', '{"asset_allocation": {"Bond_Weight": 0, "Equity_Weight": 0.9951}, "bond_characteristics": {"Avg_Maturity": null, "Duration_Yrs": null}}', '{"valuation_metrics": {"PB_Ratio": 2.69, "PE_Ratio": null, "PS_Ratio": 5.05, "PCF_Ratio": null}}');
