INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (301, 'CYB', 'ETF', 'US', 'American Century Inv, NT Intern', 'American Century NT International Growth Fund G Class', 'US Dollar', NULL, NULL, 'American Century Investments', 'PCX', 'Single Currency', 52705336, 0.004, '2008-05-14', NULL, 'The investment seeks capital growth. The fund invests primarily in securities of companies located in at least three developed countries world-wide (excluding the United States). It may also invest in emerging market countries. The portfolio managers look for stocks of companies they believe will increase in value over time, using an investment strategy developed by the fund''s investment advisor.', 0.0045, 0.0043, 10717, 6620, 28.143, 27.769, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '{"Cap_Size": null, "Quote_Mode": "ETF", "Currency_Base": "US Dollar", "GeoZone_Class": "US", "Strategy_Type": null}', '{"Net_Worth": 52705336, "Yield_Rate": 0.004, "Expense_Net": 0.0045, "Benchmark_Exp": 0.0043, "Turnover_Ratio": null}', '{"volume_metrics": {"Vol_3M": 10717, "Vol_Recent": 6620}, "moving_averages": {"MA_50": 28.143, "MA_200": 27.769}}', '{"asset_allocation": {"Bond_Weight": null, "Equity_Weight": null}, "bond_characteristics": {"Avg_Maturity": null, "Duration_Yrs": null}}', '{"valuation_metrics": {"PB_Ratio": null, "PE_Ratio": null, "PS_Ratio": null, "PCF_Ratio": null}}');
INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (302, 'CZA', 'ETF', 'UNITED_STATES', 'American Century Inv, NT Growth', 'American Century NT Growth Fund G Class', 'AmericanDollar', 'Blend', 'Medium', 'American Century Investments', 'PCX', 'Mid-Cap Blend', 223769872, 0.0121, '2007-04-02', 1.62, 'The investment seeks long-term capital growth. The fund normally invests in stocks of companies that the adviser believes will increase in value over time. The portfolio managers use a variety of analytical research tools and techniques to identify the stocks of larger-sized companies that meet their investment criteria. Under normal market conditions, the fund''s portfolio will primarily consist of securities of companies demonstrating business improvement. The fund is not permitted to invest in securities issued by companies assigned the Global Industry Classification Standard (GICS) for the tobacco industry.', 0.0069, 0.0047, 3393, 3610, 93.166, 89.971, 0.9991, 0, 3.28, 14.28, 21.66, 1.47, NULL, NULL, '{"Cap_Size": "Medium", "Quote_Mode": "ETF", "Currency_Base": "AmericanDollar", "GeoZone_Class": "UNITED_STATES", "Strategy_Type": "Blend"}', '{"Net_Worth": 223769872, "Yield_Rate": 0.0121, "Expense_Net": 0.0069, "Benchmark_Exp": 0.0047, "Turnover_Ratio": 1.62}', '{"volume_metrics": {"Vol_3M": 3393, "Vol_Recent": 3610}, "moving_averages": {"MA_50": 93.166, "MA_200": 89.971}}', '{"asset_allocation": {"Bond_Weight": 0, "Equity_Weight": 0.9991}, "bond_characteristics": {"Avg_Maturity": null, "Duration_Yrs": null}}', '{"valuation_metrics": {"PB_Ratio": 3.28, "PE_Ratio": 21.66, "PS_Ratio": 1.47, "PCF_Ratio": 14.28}}');
INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (303, 'DALI', 'ETF', 'UNITED_STATES', 'American Century NT Heritage Fu', 'American Century NT Heritage Fund G Class', 'US$', 'Growth', 'Medium', 'American Century Investments', 'NGM', 'Tactical Allocation', 111817024, 0.0047, '2018-05-14', NULL, 'The investment seeks long-term capital growth. The fund normally invests in stocks of medium-sized companies that the adviser believes will increase in value over time, using an investment strategy developed by the fund''s investment advisor. In implementing this strategy, the portfolio managers make their investment decisions based primarily on their analysis of individual companies, rather than on broad economic forecasts.', 0.0081, 0.0112, 12954, 40880, 26.35, 25.122, 0.9988, 0, 4.71, 13.64, 24.25, 1.74, NULL, NULL, '{"Cap_Size": "Medium", "Quote_Mode": "ETF", "Currency_Base": "US$", "GeoZone_Class": "UNITED_STATES", "Strategy_Type": "Growth"}', '{"Net_Worth": 111817024, "Yield_Rate": 0.0047, "Expense_Net": 0.0081, "Benchmark_Exp": 0.0112, "Turnover_Ratio": null}', '{"volume_metrics": {"Vol_3M": 12954, "Vol_Recent": 40880}, "moving_averages": {"MA_50": 26.35, "MA_200": 25.122}}', '{"asset_allocation": {"Bond_Weight": 0, "Equity_Weight": 0.9988}, "bond_characteristics": {"Avg_Maturity": null, "Duration_Yrs": null}}', '{"valuation_metrics": {"PB_Ratio": 4.71, "PE_Ratio": 24.25, "PS_Ratio": 1.74, "PCF_Ratio": 13.64}}');
INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (304, 'DALT', 'ETF', 'us', 'Absolute Capital Defender Fund ', 'Absolute Capital Defender Fund Class A', 'USD', 'Growth', 'Large', 'Absolute Capital', 'BTS', 'World Allocation', 68700976, 0.0142, '2017-09-29', 0.44, 'The investment seeks long term capital appreciation. The fund seeks to achieve its investment objective by investing directly or indirectly through other investment companies, including mutual funds, exchange traded funds ("ETFs") and closed-end funds (collectively, "underlying funds") in domestic and foreign (including emerging markets) (i) fixed income securities of any maturity or credit quality (including "junk bonds"); (ii) equity securities of any market capitalization; (iii) cash and cash equivalents; and (iv) exchange traded notes ("ETNs").', 0.0383, 0.0058, 8724, 10550, 10.587, 10.399, NULL, NULL, 4.36, 17.85, 22.19, 2.43, NULL, NULL, '{"Cap_Size": "Large", "Quote_Mode": "ETF", "Currency_Base": "USD", "GeoZone_Class": "us", "Strategy_Type": "Growth"}', '{"Net_Worth": 68700976, "Yield_Rate": 0.0142, "Expense_Net": 0.0383, "Benchmark_Exp": 0.0058, "Turnover_Ratio": 0.44}', '{"volume_metrics": {"Vol_3M": 8724, "Vol_Recent": 10550}, "moving_averages": {"MA_50": 10.587, "MA_200": 10.399}}', '{"asset_allocation": {"Bond_Weight": null, "Equity_Weight": null}, "bond_characteristics": {"Avg_Maturity": null, "Duration_Yrs": null}}', '{"valuation_metrics": {"PB_Ratio": 4.36, "PE_Ratio": 22.19, "PS_Ratio": 2.43, "PCF_Ratio": 17.85}}');
INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (305, 'DAPP', 'ETF', 'U.S.', 'Sanford C. Bernstein Fund, Inc.', 'AB Intermediate California Municipal Portfolio Class C', 'Usd', 'Growth', 'Medium', 'AllianceBernstein', 'NGM', NULL, 25247644, NULL, '2021-04-12', NULL, 'The investment seeks to provide safety of principal and maximize total return after taking account of federal and state taxes for California residents. The fund invests at least 80% of its net assets in a portfolio of municipal securities issued by the State of California or its political subdivisions, or otherwise exempt from California state income tax. It seeks to maintain an effective duration of three and one-half years to seven years. The fund may invest up to 20% of its total assets in fixed-income securities rated BB or B by national rating agencies, which are not investment-grade (commonly known as "junk bonds"). It is non-diversified.', 0.0065, NULL, 53133, 66300, 28.302, 26.724, NULL, NULL, 13.61, NULL, 42.96, 17.07, NULL, NULL, '{"Cap_Size": "Medium", "Quote_Mode": "ETF", "Currency_Base": "Usd", "GeoZone_Class": "U.S.", "Strategy_Type": "Growth"}', '{"Net_Worth": 25247644, "Yield_Rate": null, "Expense_Net": 0.0065, "Benchmark_Exp": null, "Turnover_Ratio": null}', '{"volume_metrics": {"Vol_3M": 53133, "Vol_Recent": 66300}, "moving_averages": {"MA_50": 28.302, "MA_200": 26.724}}', '{"asset_allocation": {"Bond_Weight": null, "Equity_Weight": null}, "bond_characteristics": {"Avg_Maturity": null, "Duration_Yrs": null}}', '{"valuation_metrics": {"PB_Ratio": 13.61, "PE_Ratio": 42.96, "PS_Ratio": 17.07, "PCF_Ratio": null}}');
