INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (313, 'DBEF', 'ETF', 'UNITED_STATES', 'AllianzGI Core Plus Bond Fund C', 'Virtus AllianzGI Core Plus Bond Fund Class R6', 'Usd', 'Blend', 'Large', 'Virtus', 'PCX', 'Foreign Large Blend', 3970983936, 0.0293, '2011-06-09', 0.09, 'The investment seeks total return, consisting of current income and capital appreciation. The fund seeks to achieve its objective by normally investing at least 80% of its net assets (plus borrowings made for investment purposes) in bonds, notes and other debt instruments, including derivatives that provide exposure to such investments. It may invest up to 35% of its net assets in debt instruments that, at the time of purchase, are rated below investment grade, or if unrated, determined by the manager to be of comparable quality.', 0.0036, 0.0037, 489767, 655140, 38.714, 37.679, NULL, NULL, 1.85, 10.91, 20.28, 1.58, NULL, NULL, '{"Cap_Size": "Large", "Quote_Mode": "ETF", "Currency_Base": "Usd", "GeoZone_Class": "UNITED_STATES", "Strategy_Type": "Blend"}', '{"Net_Worth": 3970983936, "Yield_Rate": 0.0293, "Expense_Net": 0.0036, "Benchmark_Exp": 0.0037, "Turnover_Ratio": 0.09}', '{"volume_metrics": {"Vol_3M": 489767, "Vol_Recent": 655140}, "moving_averages": {"MA_50": 38.714, "MA_200": 37.679}}', '{"asset_allocation": {"Bond_Weight": null, "Equity_Weight": null}, "bond_characteristics": {"Avg_Maturity": null, "Duration_Yrs": null}}', '{"valuation_metrics": {"PB_Ratio": 1.85, "PE_Ratio": 20.28, "PS_Ratio": 1.58, "PCF_Ratio": 10.91}}');
