INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (315, 'DBEM', 'ETF', 'USA', 'Horizon Active Risk Assist Fund', 'Horizon Active Risk Assist Fund Class I', 'Dollar', 'Blend', 'Large', 'Horizon Investments', 'PCX', 'Diversified Emerging Mkts', 117476512, 0.0206, '2011-06-09', 0.2, 'The investment seeks to capture the majority of the returns associated with equity market investments, while mitigating downside risk through use of a risk overlay strategy. The fund seeks to achieve its objective by using a multi-discipline active asset allocation investment approach. The adviser executes its global securities allocation strategy by allocating assets across various sectors of the global securities markets. Normally the fund invests a majority of its assets in ETFs that invest primarily in equity securities; however, certain ETFs in which the fund may invest primarily in fixed income securities.', 0.0066, 0.0056, 11348, 8210, 27.395, 28.271, NULL, NULL, 2.08, 10.68, 16.89, 1.4, NULL, NULL, '{"Cap_Size": "Large", "Quote_Mode": "ETF", "Currency_Base": "Dollar", "GeoZone_Class": "USA", "Strategy_Type": "Blend"}', '{"Net_Worth": 117476512, "Yield_Rate": 0.0206, "Expense_Net": 0.0066, "Benchmark_Exp": 0.0056, "Turnover_Ratio": 0.2}', '{"volume_metrics": {"Vol_3M": 11348, "Vol_Recent": 8210}, "moving_averages": {"MA_50": 27.395, "MA_200": 28.271}}', '{"asset_allocation": {"Bond_Weight": null, "Equity_Weight": null}, "bond_characteristics": {"Avg_Maturity": null, "Duration_Yrs": null}}', '{"valuation_metrics": {"PB_Ratio": 2.08, "PE_Ratio": 16.89, "PS_Ratio": 1.4, "PCF_Ratio": 10.68}}');
INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (316, 'DBEU', 'ETF', 'U.S.', 'Columbia Acorn Fund Class I', 'Columbia Acorn Fund Institutional Class', 'Usd', 'Blend', 'Large', 'Columbia Threadneedle', 'PCX', 'Europe Stock', 562835072, 0.0266, '2013-10-01', 0.13, 'The investment seeks long-term capital appreciation. The fund invests a majority of its net assets in the common stock of small- and mid-sized companies with market capitalizations generally in the range of market capitalizations in the Russell 2500 Growth Index, the fund''s benchmark, (the Index) at the time of purchase. It invests the majority of its assets in U.S. companies, but also may invest up to 33% of its total assets in foreign companies in developed markets (for example, Japan, Canada and the United Kingdom) and in emerging markets.', 0.0046, 0.0044, 140811, 245760, 35.339, 34.195, NULL, NULL, 2.04, 11.15, 21.31, 1.64, NULL, NULL, '{"Cap_Size": "Large", "Quote_Mode": "ETF", "Currency_Base": "Usd", "GeoZone_Class": "U.S.", "Strategy_Type": "Blend"}', '{"Net_Worth": 562835072, "Yield_Rate": 0.0266, "Expense_Net": 0.0046, "Benchmark_Exp": 0.0044, "Turnover_Ratio": 0.13}', '{"volume_metrics": {"Vol_3M": 140811, "Vol_Recent": 245760}, "moving_averages": {"MA_50": 35.339, "MA_200": 34.195}}', '{"asset_allocation": {"Bond_Weight": null, "Equity_Weight": null}, "bond_characteristics": {"Avg_Maturity": null, "Duration_Yrs": null}}', '{"valuation_metrics": {"PB_Ratio": 2.04, "PE_Ratio": 21.31, "PS_Ratio": 1.64, "PCF_Ratio": 11.15}}');
INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (2275, 'REML', 'ETF', 'USA', 'Boston Trust Equity Fund', 'Boston Trust Equity Fund', 'Dollar', NULL, NULL, 'Boston Trust Walden Funds', 'PCX', NULL, 234940576, 0.1157, '2016-07-13', NULL, 'The investment seeks long-term capital growth through an actively managed portfolio of stocks. The fund invests, under normal circumstances, at least 80% of its assets in a diversified portfolio of domestic equity securities, such as common stock. The fund may invest in companies of any size, but generally focuses on large capitalization companies. "Assets" means net assets, plus the amount of borrowing for investment purposes.', 0.005, NULL, 423814, 593840, 7.084, 7.021, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '{"Cap_Size": null, "Quote_Mode": "ETF", "Currency_Base": "Dollar", "GeoZone_Class": "USA", "Strategy_Type": null}', '{"Net_Worth": 234940576, "Yield_Rate": 0.1157, "Expense_Net": 0.005, "Benchmark_Exp": null, "Turnover_Ratio": null}', '{"volume_metrics": {"Vol_3M": 423814, "Vol_Recent": 593840}, "moving_averages": {"MA_50": 7.084, "MA_200": 7.021}}', '{"asset_allocation": {"Bond_Weight": null, "Equity_Weight": null}, "bond_characteristics": {"Avg_Maturity": null, "Duration_Yrs": null}}', '{"valuation_metrics": {"PB_Ratio": null, "PE_Ratio": null, "PS_Ratio": null, "PCF_Ratio": null}}');
INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (318, 'DBGR', 'ETF', 'America', 'Invesco Comstock Fund Class Y', 'Invesco Comstock Fund Class Y', 'US_DOLLAR', 'Value', 'Large', 'Invesco', 'PCX', 'Miscellaneous Region', 14560880, 0.0322, '2011-06-09', 0.14, 'The investment seeks total return through growth of capital and current income. The fund invests, under normal circumstances, at least 80% of its net assets (plus any borrowings for investment purposes) in common stocks, and in derivatives and other instruments that have economic characteristics similar to such securities. It may invest in securities of issuers of any market capitalization; and, a substantial number of the issuers in which the fund invests are large-capitalization issuers. The fund may invest up to 10% of its net assets in real estate investment trusts (REITs).', 0.0045, 0.0053, 496, 1470, 32.333, 32.183, NULL, NULL, 1.76, 7.81, 18.2, 1.14, NULL, NULL, '{"Cap_Size": "Large", "Quote_Mode": "ETF", "Currency_Base": "US_DOLLAR", "GeoZone_Class": "America", "Strategy_Type": "Value"}', '{"Net_Worth": 14560880, "Yield_Rate": 0.0322, "Expense_Net": 0.0045, "Benchmark_Exp": 0.0053, "Turnover_Ratio": 0.14}', '{"volume_metrics": {"Vol_3M": 496, "Vol_Recent": 1470}, "moving_averages": {"MA_50": 32.333, "MA_200": 32.183}}', '{"asset_allocation": {"Bond_Weight": null, "Equity_Weight": null}, "bond_characteristics": {"Avg_Maturity": null, "Duration_Yrs": null}}', '{"valuation_metrics": {"PB_Ratio": 1.76, "PE_Ratio": 18.2, "PS_Ratio": 1.14, "PCF_Ratio": 7.81}}');
