INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (336, 'DEEF', 'ETF', 'us', 'American Century Investment, Ze', 'American Century Zero Coupon 2025 Fund Advisor Class', 'AmericanDollar', 'Blend', 'Large', 'American Century Investments', 'PCX', 'Foreign Large Blend', 70757744, 0.0358, '2015-11-24', 0.43, 'The investment seeks the highest return consistent with investment in U.S. Treasury securities. The fund invests at least 80% of the value of its net assets in zero-coupon securities. It invests primarily in zero-coupon U.S. Treasury securities and their equivalents (including certain zero-coupon U.S. government agency securities), and may invest up to 20% of its assets in other zero-coupon U.S. government agency securities that are AAA-rated. Zero-coupon securities make no periodic interest or principal payments. The fund is managed to mature in the year 2025 and will be liquidated near the end of its target maturity year.', 0.0024, 0.0037, 6670, 3280, 31.699, 32.066, NULL, NULL, 1.59, 8.34, 15.68, 0.89, NULL, NULL, '{"Cap_Size": "Large", "Quote_Mode": "ETF", "Currency_Base": "AmericanDollar", "GeoZone_Class": "us", "Strategy_Type": "Blend"}', '{"Net_Worth": 70757744, "Yield_Rate": 0.0358, "Expense_Net": 0.0024, "Benchmark_Exp": 0.0037, "Turnover_Ratio": 0.43}', '{"volume_metrics": {"Vol_3M": 6670, "Vol_Recent": 3280}, "moving_averages": {"MA_50": 31.699, "MA_200": 32.066}}', '{"asset_allocation": {"Bond_Weight": null, "Equity_Weight": null}, "bond_characteristics": {"Avg_Maturity": null, "Duration_Yrs": null}}', '{"valuation_metrics": {"PB_Ratio": 1.59, "PE_Ratio": 15.68, "PS_Ratio": 0.89, "PCF_Ratio": 8.34}}');
INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (337, 'DEEP', 'ETF', 'U.S.', 'Columbia Dividend Opportunity F', 'Columbia Dividend Opportunity Fund Class C', 'usd', 'Value', 'Small', 'Columbia Threadneedle', 'PCX', 'Small Value', 50408648, 0.0112, '2014-09-22', 1.43, 'The investment seeks a high level of current income with a secondary objective of growth of income and capital. The fund''s assets primarily are invested in equity securities. Under normal market conditions, it will invest at least 80% of its net assets (including the amount of any borrowings for investment purposes) in dividend-paying common and preferred stocks. The fund may invest in companies that have market capitalizations of any size. It may invest up to 25% of its net assets in foreign investments.', 0.008, 0.0035, 11445, 30710, 36.784, 35.219, 0.9999, 0, 1.55, 5.8, 9.37, 0.77, NULL, NULL, '{"Cap_Size": "Small", "Quote_Mode": "ETF", "Currency_Base": "usd", "GeoZone_Class": "U.S.", "Strategy_Type": "Value"}', '{"Net_Worth": 50408648, "Yield_Rate": 0.0112, "Expense_Net": 0.008, "Benchmark_Exp": 0.0035, "Turnover_Ratio": 1.43}', '{"volume_metrics": {"Vol_3M": 11445, "Vol_Recent": 30710}, "moving_averages": {"MA_50": 36.784, "MA_200": 35.219}}', '{"asset_allocation": {"Bond_Weight": 0, "Equity_Weight": 0.9999}, "bond_characteristics": {"Avg_Maturity": null, "Duration_Yrs": null}}', '{"valuation_metrics": {"PB_Ratio": 1.55, "PE_Ratio": 9.37, "PS_Ratio": 0.77, "PCF_Ratio": 5.8}}');
INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (338, 'DEF', 'ETF', 'United States', NULL, 'Advisors Capital US Dividend Fund', 'USD', 'Blend', 'Large', 'Advisors Capital', 'PCX', 'Large Blend', 253653840, 0.0121, '2006-12-15', 1.36, 'The investment seeks long-term capital appreciation. Under normal circumstances, the fund invests at least 80% of its assets (defined as net assets plus borrowing for investment purposes) in dividend-paying common stock of U.S. companies. It invests in companies of any capitalization. The fund is typically structured with 30 to 50 stocks spread across seven to ten sectors. The Sub-Advisor expects the fund to have a better-than-market dividend yield with lower downside risk when compared to the S&P 500 Index.', 0.0053, 0.0036, 25706, 23310, 68.815, 65.882, 0.9995, 0, 4.12, 14.75, 23.71, 1.48, NULL, NULL, '{"Cap_Size": "Large", "Quote_Mode": "ETF", "Currency_Base": "USD", "GeoZone_Class": "United States", "Strategy_Type": "Blend"}', '{"Net_Worth": 253653840, "Yield_Rate": 0.0121, "Expense_Net": 0.0053, "Benchmark_Exp": 0.0036, "Turnover_Ratio": 1.36}', '{"volume_metrics": {"Vol_3M": 25706, "Vol_Recent": 23310}, "moving_averages": {"MA_50": 68.815, "MA_200": 65.882}}', '{"asset_allocation": {"Bond_Weight": 0, "Equity_Weight": 0.9995}, "bond_characteristics": {"Avg_Maturity": null, "Duration_Yrs": null}}', '{"valuation_metrics": {"PB_Ratio": 4.12, "PE_Ratio": 23.71, "PS_Ratio": 1.48, "PCF_Ratio": 14.75}}');
INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (339, 'DEFN', 'ETF', 'UNITED_STATES', 'American Century Strategic Allo', 'American Century Strategic Allocation: Aggressive Fund A Class', 'DOLLAR', 'Blend', 'Large', 'American Century Investments', 'BTS', NULL, 7482987, NULL, '2020-11-24', NULL, 'The investment seeks the highest level of total return consistent with its asset mix. The fund''s asset allocation strategy diversifies investments among equity securities, bonds and money market instruments. It usually invests 79% of its assets in stocks, 20% of its assets in bonds, and 1% of its assets in cash equivalents. The fund also invests in a variety of debt securities payable in U.S. and foreign currencies. It may invest in any type of U.S. or foreign equity security that meets certain fundamental and technical standards. The fund may invest up to 10% of its assets in below investment-grade securities.', 0.0055, NULL, 1467, NULL, 24.474, 24.409, NULL, NULL, 6.88, 16.61, 27.15, 3.59, NULL, NULL, '{"Cap_Size": "Large", "Quote_Mode": "ETF", "Currency_Base": "DOLLAR", "GeoZone_Class": "UNITED_STATES", "Strategy_Type": "Blend"}', '{"Net_Worth": 7482987, "Yield_Rate": null, "Expense_Net": 0.0055, "Benchmark_Exp": null, "Turnover_Ratio": null}', '{"volume_metrics": {"Vol_3M": 1467, "Vol_Recent": null}, "moving_averages": {"MA_50": 24.474, "MA_200": 24.409}}', '{"asset_allocation": {"Bond_Weight": null, "Equity_Weight": null}, "bond_characteristics": {"Avg_Maturity": null, "Duration_Yrs": null}}', '{"valuation_metrics": {"PB_Ratio": 6.88, "PE_Ratio": 27.15, "PS_Ratio": 3.59, "PCF_Ratio": 16.61}}');
INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (340, 'DEM', 'ETF', 'U.S.A.', 'American Century International ', 'American Century International Value Fund R6 Class', 'DOLLAR', 'Value', 'Large', 'American Century Investments', 'PCX', 'Diversified Emerging Mkts', 2011405312, 0.0448, '2007-07-13', 0.62, 'The investment seeks long-term capital growth. In selecting stocks for the fund, the portfolio managers will normally invest at least 65% of net assets in securities of issuers from a minimum of three countries outside the United States. The portfolio managers generally look for securities from issuers that have characteristics similar to those of the companies that comprise the MSCI EAFE© Value Index. Characteristics the portfolio managers may consider include industry sector and geographic location, among others. The portfolio managers will normally invest at least 80% of the value of the fund''s net assets in equity securities.', 0.0063, 0.0056, 202991, 211400, 43.664, 44.714, 0.9938, 0, 1.19, 5.98, 8.95, 0.79, NULL, NULL, '{"Cap_Size": "Large", "Quote_Mode": "ETF", "Currency_Base": "DOLLAR", "GeoZone_Class": "U.S.A.", "Strategy_Type": "Value"}', '{"Net_Worth": 2011405312, "Yield_Rate": 0.0448, "Expense_Net": 0.0063, "Benchmark_Exp": 0.0056, "Turnover_Ratio": 0.62}', '{"volume_metrics": {"Vol_3M": 202991, "Vol_Recent": 211400}, "moving_averages": {"MA_50": 43.664, "MA_200": 44.714}}', '{"asset_allocation": {"Bond_Weight": 0, "Equity_Weight": 0.9938}, "bond_characteristics": {"Avg_Maturity": null, "Duration_Yrs": null}}', '{"valuation_metrics": {"PB_Ratio": 1.19, "PE_Ratio": 8.95, "PS_Ratio": 0.79, "PCF_Ratio": 5.98}}');
