INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (349, 'DFEB', 'ETF', 'U.S.', 'AMG Managers LMCG Small Cap Gro', 'AMG GW&K Small/Mid Cap Growth Fund – N', 'US$', 'Blend', 'Large', 'AMG Funds', 'BTS', NULL, 293499840, NULL, '2020-02-21', NULL, 'The investment seeks to provide long-term capital appreciation. Under normal circumstances, the fund invests at least 80% of its net assets, plus the amount of any borrowings for investment purposes, in securities of small- and mid-capitalization companies. The manager currently defines small- and mid-capitalization companies to be those with market capitalizations at the time of purchase within the range of capitalizations of companies in the Russell 2500© Growth Index. The subadviser seeks to identify quality companies with growth oriented characteristics.', 0.0085, NULL, 35548, 40470, 34.8, 34.113, NULL, NULL, 4.43, 17.58, 26.49, 2.96, NULL, NULL, '{"Cap_Size": "Large", "Quote_Mode": "ETF", "Currency_Base": "US$", "GeoZone_Class": "U.S.", "Strategy_Type": "Blend"}', '{"Net_Worth": 293499840, "Yield_Rate": null, "Expense_Net": 0.0085, "Benchmark_Exp": null, "Turnover_Ratio": null}', '{"volume_metrics": {"Vol_3M": 35548, "Vol_Recent": 40470}, "moving_averages": {"MA_50": 34.8, "MA_200": 34.113}}', '{"asset_allocation": {"Bond_Weight": null, "Equity_Weight": null}, "bond_characteristics": {"Avg_Maturity": null, "Duration_Yrs": null}}', '{"valuation_metrics": {"PB_Ratio": 4.43, "PE_Ratio": 26.49, "PS_Ratio": 2.96, "PCF_Ratio": 17.58}}');
INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (350, 'DFEN', 'ETF', 'America', 'Cavanal Hill World Energy Fund ', 'Cavanal Hill World Energy Fund C', 'USD', 'Value', 'Large', 'Cavanal Hill funds', 'PCX', 'Trading--Leveraged Equity', 366816352, 0.0006, '2017-05-03', 1.59, 'The investment seeks growth and income. The fund invests at least 80% of its net assets in a wide range of energy-related financial instruments issued in the U.S. and markets around the world. Investments typically include a combination of common stock, bonds, exchange traded funds ("ETFs") and exchange traded notes ("ETNs") but may also include other asset types that are related to energy industry activities. It will invest at least 40%, but may invest up to 100%, of its net assets in the securities of issuers organized or having their principal place of business outside the U.S. or doing a substantial amount of business outside the U.S.', 0.0101, 0.009, 1114982, 1.76981e+06, 21.34, 21.974, NULL, NULL, 3.2, 19.16, NULL, 2.32, NULL, NULL, '{"Cap_Size": "Large", "Quote_Mode": "ETF", "Currency_Base": "USD", "GeoZone_Class": "America", "Strategy_Type": "Value"}', '{"Net_Worth": 366816352, "Yield_Rate": 0.0006, "Expense_Net": 0.0101, "Benchmark_Exp": 0.009, "Turnover_Ratio": 1.59}', '{"volume_metrics": {"Vol_3M": 1114982, "Vol_Recent": 1769810}, "moving_averages": {"MA_50": 21.34, "MA_200": 21.974}}', '{"asset_allocation": {"Bond_Weight": null, "Equity_Weight": null}, "bond_characteristics": {"Avg_Maturity": null, "Duration_Yrs": null}}', '{"valuation_metrics": {"PB_Ratio": 3.2, "PE_Ratio": null, "PS_Ratio": 2.32, "PCF_Ratio": 19.16}}');
