INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (355, 'DFUS', 'ETF', 'USA', 'American Century California Hig', 'American Century California High Yield Municipal Fund Y Class', 'DOLLAR', 'Blend', 'Large', 'American Century Investments', 'PCX', 'Large Blend', 5584181248, 0.0112, '2001-09-25', NULL, 'The investment seeks high current income that is exempt from federal and California income taxes. The fund invests at least 80% of its net assets in municipal securities with income payments exempt from federal and California income taxes. It invests in California municipal and other debt securities with an emphasis on high-yield securities. A high-yield security is one that has been rated below investment-grade, or determined by the investment advisor to be of similar quality. The portfolio managers also may buy unrated securities if they determine such securities meet the investment objectives of the fund.', 0.0011, 0.0036, 96059, 121220, 49.723, 48.765, 1, 0, 4.38, 17.2, 25.55, 2.73, NULL, NULL, '{"Cap_Size": "Large", "Quote_Mode": "ETF", "Currency_Base": "DOLLAR", "GeoZone_Class": "USA", "Strategy_Type": "Blend"}', '{"Net_Worth": 5584181248, "Yield_Rate": 0.0112, "Expense_Net": 0.0011, "Benchmark_Exp": 0.0036, "Turnover_Ratio": null}', '{"volume_metrics": {"Vol_3M": 96059, "Vol_Recent": 121220}, "moving_averages": {"MA_50": 49.723, "MA_200": 48.765}}', '{"asset_allocation": {"Bond_Weight": 0, "Equity_Weight": 1}, "bond_characteristics": {"Avg_Maturity": null, "Duration_Yrs": null}}', '{"valuation_metrics": {"PB_Ratio": 4.38, "PE_Ratio": 25.55, "PS_Ratio": 2.73, "PCF_Ratio": 17.2}}');
INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (356, 'DGL', 'ETF', 'U.S.A.', 'American Century California Int', 'American Century California Intermediate-Term Tax-Free Bond Fund Y Class', 'AmericanDollar', NULL, NULL, 'American Century Investments', 'PCX', NULL, 96963440, NULL, '2007-01-05', NULL, 'The investment seeks safety of principal and high current income that is exempt from federal and California income taxes. The fund primarily invests in investment-grade debt securities and, under normal market conditions, will invest at least 80% of its net assets in debt securities that have interest payments exempt from federal and California income taxes. Cities, counties and other municipalities in California and U.S. territories, such as Puerto Rico, issue these securities. The fund''s weighted average maturity will be not less than three years nor more than ten years. However, there is no maturity limit on individual securities.', 0.0075, NULL, 21579, 15010, 51.366, 51.565, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '{"Cap_Size": null, "Quote_Mode": "ETF", "Currency_Base": "AmericanDollar", "GeoZone_Class": "U.S.A.", "Strategy_Type": null}', '{"Net_Worth": 96963440, "Yield_Rate": null, "Expense_Net": 0.0075, "Benchmark_Exp": null, "Turnover_Ratio": null}', '{"volume_metrics": {"Vol_3M": 21579, "Vol_Recent": 15010}, "moving_averages": {"MA_50": 51.366, "MA_200": 51.565}}', '{"asset_allocation": {"Bond_Weight": null, "Equity_Weight": null}, "bond_characteristics": {"Avg_Maturity": null, "Duration_Yrs": null}}', '{"valuation_metrics": {"PB_Ratio": null, "PE_Ratio": null, "PS_Ratio": null, "PCF_Ratio": null}}');
