INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (371, 'DIVZ', 'ETF', 'United States', 'AB Core Opportunities Fund, Inc', 'AB Core Opportunities Fund Class C', 'US Dollar', 'Value', 'Large', 'AllianceBernstein', 'PCX', NULL, 28672800, NULL, '2021-01-27', NULL, 'The investment seeks long-term growth of capital. The fund invests primarily in the equity securities of U.S. companies that the Adviser believes are attractively valued. The Adviser relies primarily upon the fundamental analysis and research of its dedicated investment team for the fund in conducting research and making investment decisions. The team initially screens a primary research universe of largely U.S. companies for attractive security valuation and business models. Once appropriate candidates have been identified for further analysis, the team conducts fundamental research to better understand the economics of the company''s business model.', 0.0065, NULL, 5253, 6740, 28.673, 28.305, NULL, NULL, 2.13, 10.2, 17.61, 1.65, NULL, NULL, '{"Cap_Size": "Large", "Quote_Mode": "ETF", "Currency_Base": "US Dollar", "GeoZone_Class": "United States", "Strategy_Type": "Value"}', '{"Net_Worth": 28672800, "Yield_Rate": null, "Expense_Net": 0.0065, "Benchmark_Exp": null, "Turnover_Ratio": null}', '{"volume_metrics": {"Vol_3M": 5253, "Vol_Recent": 6740}, "moving_averages": {"MA_50": 28.673, "MA_200": 28.305}}', '{"asset_allocation": {"Bond_Weight": null, "Equity_Weight": null}, "bond_characteristics": {"Avg_Maturity": null, "Duration_Yrs": null}}', '{"valuation_metrics": {"PB_Ratio": 2.13, "PE_Ratio": 17.61, "PS_Ratio": 1.65, "PCF_Ratio": 10.2}}');
