INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (382, 'DMRE', 'ETF', 'United States', 'Adler Value Fund Institutional ', 'Adler Value Fund Institutional Class', 'usd', 'Blend', 'Large', 'Adler', 'PCX', 'Diversified Emerging Mkts', 54995444, 0.0119, '2019-03-19', 6.47, 'The investment seeks to achieve long-term growth of capital. The fund seeks to achieve its investment objective by investing principally in equity securities of U.S. and non-U.S. issuers, including common stocks, depositary receipts evidencing ownership of common stocks issued by a foreign issuer ("ADRs"), preferred stocks, securities convertible into common stocks, and securities that carry the right to buy common stocks (e.g., rights, warrants, and options) of companies the Adviser believes are undervalued by the equity market based on the Adviser''s assessment of the company. The fund is non-diversified.', 0.006, 0.0056, 162, 90, 54.205, 57.48, 0.9943, 0, 1.97, 11.91, 16.23, 1.22, NULL, NULL, '{"Cap_Size": "Large", "Quote_Mode": "ETF", "Currency_Base": "usd", "GeoZone_Class": "United States", "Strategy_Type": "Blend"}', '{"Net_Worth": 54995444, "Yield_Rate": 0.0119, "Expense_Net": 0.006, "Benchmark_Exp": 0.0056, "Turnover_Ratio": 6.47}', '{"volume_metrics": {"Vol_3M": 162, "Vol_Recent": 90}, "moving_averages": {"MA_50": 54.205, "MA_200": 57.48}}', '{"asset_allocation": {"Bond_Weight": 0, "Equity_Weight": 0.9943}, "bond_characteristics": {"Avg_Maturity": null, "Duration_Yrs": null}}', '{"valuation_metrics": {"PB_Ratio": 1.97, "PE_Ratio": 16.23, "PS_Ratio": 1.22, "PCF_Ratio": 11.91}}');
INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (383, 'DMRI', 'ETF', 'usa', '361 Domestic Long/Short Equity ', '361 Domestic Long/Short Equity Fund Investor Class', 'usd', 'Blend', 'Large', '361 Funds', 'PCX', 'Foreign Large Blend', 186709472, 0.0155, '2017-07-31', 6.9, 'The investment seeks to achieve long-term capital appreciation; the fund also seeks to preserve capital in down markets. In pursuing its investment objectives, the fund seeks to invest at least 80% of the value of its net assets (which include borrowings for investment purposes) in equity securities such as common stocks, warrants and rights of issuers that are organized in the United States and the securities of which are principally traded on a major U.S. exchange. It employs a strategy of taking long and short positions in equity securities publicly traded in the U.S.', 0.005, 0.0037, 567, 1480, 52.857, 52.721, 0.994, 0, 1.84, 10.88, 19.99, 1.53, NULL, NULL, '{"Cap_Size": "Large", "Quote_Mode": "ETF", "Currency_Base": "usd", "GeoZone_Class": "usa", "Strategy_Type": "Blend"}', '{"Net_Worth": 186709472, "Yield_Rate": 0.0155, "Expense_Net": 0.005, "Benchmark_Exp": 0.0037, "Turnover_Ratio": 6.9}', '{"volume_metrics": {"Vol_3M": 567, "Vol_Recent": 1480}, "moving_averages": {"MA_50": 52.857, "MA_200": 52.721}}', '{"asset_allocation": {"Bond_Weight": 0, "Equity_Weight": 0.994}, "bond_characteristics": {"Avg_Maturity": null, "Duration_Yrs": null}}', '{"valuation_metrics": {"PB_Ratio": 1.84, "PE_Ratio": 19.99, "PS_Ratio": 1.53, "PCF_Ratio": 10.88}}');
