INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (418, 'DWAW', 'ETF', 'United States', 'Invesco European Growth Fund Cl', 'Invesco European Growth Fund Class A', 'USD', 'Growth', 'Medium', 'Invesco', 'NGM', NULL, 166637552, 0.0016, '2019-12-26', NULL, 'The investment seeks long-term growth of capital. The fund invests at least 80% of its net assets (plus any borrowings for investment purposes) in securities of European issuers, and in derivatives and other instruments that have economic characteristics similar to such securities. It invests primarily in equity securities and depositary receipts. The fund may invest in the securities of issuers of all capitalization sizes and may invest a significant amount of its net assets in the securities of small- and mid-capitalization issuers.', 0.0124, NULL, 6454, 7760, 37.672, 37.213, 0.997, 0, 4.93, 20.79, 30.39, 3.32, NULL, NULL, '{"Cap_Size": "Medium", "Quote_Mode": "ETF", "Currency_Base": "USD", "GeoZone_Class": "United States", "Strategy_Type": "Growth"}', '{"Net_Worth": 166637552, "Yield_Rate": 0.0016, "Expense_Net": 0.0124, "Benchmark_Exp": null, "Turnover_Ratio": null}', '{"volume_metrics": {"Vol_3M": 6454, "Vol_Recent": 7760}, "moving_averages": {"MA_50": 37.672, "MA_200": 37.213}}', '{"asset_allocation": {"Bond_Weight": 0, "Equity_Weight": 0.997}, "bond_characteristics": {"Avg_Maturity": null, "Duration_Yrs": null}}', '{"valuation_metrics": {"PB_Ratio": 4.93, "PE_Ratio": 30.39, "PS_Ratio": 3.32, "PCF_Ratio": 20.79}}');
