INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (420, 'DWEQ', 'ETF', 'usa', 'Water Island Diversified Event-', 'Water Island Event-Driven Fund ClassR', 'Dollar', 'Blend', 'Medium', 'Arbitrage Fund', 'NGM', NULL, 81534184, 0.0002, '2019-12-26', NULL, 'The investment seeks to achieve capital growth. The fund invests in equity and debt and debt-like instruments (including high yield bonds commonly known as "junk bonds") of companies whose prices the fund''s investment adviser believes are or will be impacted by a corporate event. Specifically, the fund employs investment strategies designed to capture price movements generated by corporate events such as mergers, acquisitions, asset sales, restructurings, refinancings, recapitalizations, reorganizations or other special situations (referred to as "event-driven opportunities"). It is non-diversified.', 0.0103, NULL, 2990, 2910, 28.608, 27.867, 0.9973, 0, 4.01, 13.13, 32.18, 2.51, NULL, NULL, '{"Cap_Size": "Medium", "Quote_Mode": "ETF", "Currency_Base": "Dollar", "GeoZone_Class": "usa", "Strategy_Type": "Blend"}', '{"Net_Worth": 81534184, "Yield_Rate": 0.0002, "Expense_Net": 0.0103, "Benchmark_Exp": null, "Turnover_Ratio": null}', '{"volume_metrics": {"Vol_3M": 2990, "Vol_Recent": 2910}, "moving_averages": {"MA_50": 28.608, "MA_200": 27.867}}', '{"asset_allocation": {"Bond_Weight": 0, "Equity_Weight": 0.9973}, "bond_characteristics": {"Avg_Maturity": null, "Duration_Yrs": null}}', '{"valuation_metrics": {"PB_Ratio": 4.01, "PE_Ratio": 32.18, "PS_Ratio": 2.51, "PCF_Ratio": 13.13}}');
INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (421, 'DWLD', 'ETF', 'United States', 'Emerging Markets Debt Fund - G ', 'American Century Emerging Markets Debt Fund G CLASS', 'DOLLAR', 'Blend', 'Large', 'American Century Investments', 'BTS', NULL, 422648736, 0.0022, '2017-01-11', 0.28, 'The investment seeks total return. Under normal market conditions, the fund invests at least 80% of its net assets in fixed income instruments of issuers that are economically tied to emerging markets. It will invest in debt instruments issued by foreign governments and corporations. The fund may invest without limitation in both investment grade and high-yield ("junk bonds") debt securities. It also invests in derivative instruments. The fund may use foreign currency exchange contracts to shift its investment exposure from one currency into another, for hedging purposes or to enhance returns.', 0.0063, NULL, 22643, 34440, 30.716, 32.644, 1, 0, 1.84, 15.65, 16.76, 1.13, NULL, NULL, '{"Cap_Size": "Large", "Quote_Mode": "ETF", "Currency_Base": "DOLLAR", "GeoZone_Class": "United States", "Strategy_Type": "Blend"}', '{"Net_Worth": 422648736, "Yield_Rate": 0.0022, "Expense_Net": 0.0063, "Benchmark_Exp": null, "Turnover_Ratio": 0.28}', '{"volume_metrics": {"Vol_3M": 22643, "Vol_Recent": 34440}, "moving_averages": {"MA_50": 30.716, "MA_200": 32.644}}', '{"asset_allocation": {"Bond_Weight": 0, "Equity_Weight": 1}, "bond_characteristics": {"Avg_Maturity": null, "Duration_Yrs": null}}', '{"valuation_metrics": {"PB_Ratio": 1.84, "PE_Ratio": 16.76, "PS_Ratio": 1.13, "PCF_Ratio": 15.65}}');
