INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (426, 'DWX', 'ETF', 'U.S.A.', 'Emerging Markets Debt Fund - A', 'American Century Emerging Markets Debt Fund A Class', 'Dollar', 'Value', 'Large', 'American Century Investments', 'PCX', 'Foreign Large Value', 653997440, 0.0347, '2008-02-12', 0.65, 'The investment seeks total return. Under normal market conditions, the fund invests at least 80% of its net assets in fixed income instruments of issuers that are economically tied to emerging markets. It will invest in debt instruments issued by foreign governments and corporations. The fund may invest without limitation in both investment grade and high-yield ("junk bonds") debt securities. It also invests in derivative instruments. The fund may use foreign currency exchange contracts to shift its investment exposure from one currency into another, for hedging purposes or to enhance returns.', 0.0045, 0.0046, 46720, 56560, 38.636, 39.243, NULL, NULL, 1.46, 8.52, 15.37, 1.77, NULL, NULL, '{"Cap_Size": "Large", "Quote_Mode": "ETF", "Currency_Base": "Dollar", "GeoZone_Class": "U.S.A.", "Strategy_Type": "Value"}', '{"Net_Worth": 653997440, "Yield_Rate": 0.0347, "Expense_Net": 0.0045, "Benchmark_Exp": 0.0046, "Turnover_Ratio": 0.65}', '{"volume_metrics": {"Vol_3M": 46720, "Vol_Recent": 56560}, "moving_averages": {"MA_50": 38.636, "MA_200": 39.243}}', '{"asset_allocation": {"Bond_Weight": null, "Equity_Weight": null}, "bond_characteristics": {"Avg_Maturity": null, "Duration_Yrs": null}}', '{"valuation_metrics": {"PB_Ratio": 1.46, "PE_Ratio": 15.37, "PS_Ratio": 1.77, "PCF_Ratio": 8.52}}');
INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (427, 'DXD', 'ETF', 'US', 'Invesco European Growth Fund Cl', 'Invesco European Growth Fund Class R', 'Dollar', NULL, NULL, 'Invesco', 'PCX', 'Trading--Inverse Equity', 100060792, NULL, '2006-07-11', NULL, 'The investment seeks long-term growth of capital. The fund invests at least 80% of its net assets (plus any borrowings for investment purposes) in securities of European issuers, and in derivatives and other instruments that have economic characteristics similar to such securities. It invests primarily in equity securities and depositary receipts. The fund may invest in the securities of issuers of all capitalization sizes and may invest a significant amount of its net assets in the securities of small- and mid-capitalization issuers.', 0.0095, 0.0092, 1674537, 1.7881e+06, 8.752, 9.476, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '{"Cap_Size": null, "Quote_Mode": "ETF", "Currency_Base": "Dollar", "GeoZone_Class": "US", "Strategy_Type": null}', '{"Net_Worth": 100060792, "Yield_Rate": null, "Expense_Net": 0.0095, "Benchmark_Exp": 0.0092, "Turnover_Ratio": null}', '{"volume_metrics": {"Vol_3M": 1674537, "Vol_Recent": 1788100}, "moving_averages": {"MA_50": 8.752, "MA_200": 9.476}}', '{"asset_allocation": {"Bond_Weight": null, "Equity_Weight": null}, "bond_characteristics": {"Avg_Maturity": null, "Duration_Yrs": null}}', '{"valuation_metrics": {"PB_Ratio": null, "PE_Ratio": null, "PS_Ratio": null, "PCF_Ratio": null}}');
