INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (437, 'EAOR', 'ETF', 'us', 'Equity Income Fund Class G', 'American Century Equity Income Fund G Class', 'DOLLAR', 'Blend', 'Large', 'American Century Investments', 'BTS', NULL, 7702439, NULL, '2020-06-12', NULL, 'The investment seeks current income; capital appreciation is a secondary objective. The portfolio managers look for equity securities of companies with a favorable income-paying history that have prospects for income payments to continue or increase. The portfolio managers also look for equity securities of companies that they believe are undervalued and have the potential for an increase in price. The fund may invest a portion of its assets in foreign securities when these securities meet the portfolio managers'' standards of selection.', 0.0018, NULL, 1508, 860, 31.491, 30.93, NULL, NULL, 2.86, 14.58, 24.46, 2.09, 7.97, 6.34, '{"Cap_Size": "Large", "Quote_Mode": "ETF", "Currency_Base": "DOLLAR", "GeoZone_Class": "us", "Strategy_Type": "Blend"}', '{"Net_Worth": 7702439, "Yield_Rate": null, "Expense_Net": 0.0018, "Benchmark_Exp": null, "Turnover_Ratio": null}', '{"volume_metrics": {"Vol_3M": 1508, "Vol_Recent": 860}, "moving_averages": {"MA_50": 31.491, "MA_200": 30.93}}', '{"asset_allocation": {"Bond_Weight": null, "Equity_Weight": null}, "bond_characteristics": {"Avg_Maturity": 7.97, "Duration_Yrs": 6.34}}', '{"valuation_metrics": {"PB_Ratio": 2.86, "PE_Ratio": 24.46, "PS_Ratio": 2.09, "PCF_Ratio": 14.58}}');
