INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (446, 'ECOW', 'ETF', 'US', 'Aberdeen Emerging Markets Fund,', 'Aberdeen Emerging Markets Fund Institutional Service Class', 'US$', 'Value', 'Large', 'Aberdeen', 'NGM', 'Diversified Emerging Mkts', 9258468, 0.0293, '2019-05-02', 1.09, 'The investment seeks long-term capital appreciation. The fund invests primarily in common stocks, but may also invest in other types of equity securities, including, but not limited to, preferred stock and depositary receipts. It invests at least 80% of the value of its net assets, plus any borrowings for investment purposes, in equity securities of emerging market companies. The fund may invest in securities denominated in U.S. Dollars and currencies of emerging market countries in which it is permitted to invest. It may invest in securities of any market capitalization, including small and mid-cap securities.', 0.0074, 0.0056, 2643, 9940, 24.341, 25.656, 0.9958, 0, 1.39, 3.64, 9.33, 0.66, NULL, NULL, '{"Cap_Size": "Large", "Quote_Mode": "ETF", "Currency_Base": "US$", "GeoZone_Class": "US", "Strategy_Type": "Value"}', '{"Net_Worth": 9258468, "Yield_Rate": 0.0293, "Expense_Net": 0.0074, "Benchmark_Exp": 0.0056, "Turnover_Ratio": 1.09}', '{"volume_metrics": {"Vol_3M": 2643, "Vol_Recent": 9940}, "moving_averages": {"MA_50": 24.341, "MA_200": 25.656}}', '{"asset_allocation": {"Bond_Weight": 0, "Equity_Weight": 0.9958}, "bond_characteristics": {"Avg_Maturity": null, "Duration_Yrs": null}}', '{"valuation_metrics": {"PB_Ratio": 1.39, "PE_Ratio": 9.33, "PS_Ratio": 0.66, "PCF_Ratio": 3.64}}');
