INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (455, 'EDZ', 'ETF', 'United States', 'Emerging Markets Debt Fund - R', 'American Century Emerging Markets Debt Fund R6 Class', 'usd', NULL, NULL, 'American Century Investments', 'PCX', 'Trading--Inverse Equity', 23357212, NULL, '2008-12-17', NULL, 'The investment seeks total return. Under normal market conditions, the fund invests at least 80% of its net assets in fixed income instruments of issuers that are economically tied to emerging markets. It will invest in debt instruments issued by foreign governments and corporations. The fund may invest without limitation in both investment grade and high-yield ("junk bonds") debt securities. It also invests in derivative instruments. The fund may use foreign currency exchange contracts to shift its investment exposure from one currency into another, for hedging purposes or to enhance returns.', 0.011, 0.0092, 228053, 283300, 9.047, 8.595, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '{"Cap_Size": null, "Quote_Mode": "ETF", "Currency_Base": "usd", "GeoZone_Class": "United States", "Strategy_Type": null}', '{"Net_Worth": 23357212, "Yield_Rate": null, "Expense_Net": 0.011, "Benchmark_Exp": 0.0092, "Turnover_Ratio": null}', '{"volume_metrics": {"Vol_3M": 228053, "Vol_Recent": 283300}, "moving_averages": {"MA_50": 9.047, "MA_200": 8.595}}', '{"asset_allocation": {"Bond_Weight": null, "Equity_Weight": null}, "bond_characteristics": {"Avg_Maturity": null, "Duration_Yrs": null}}', '{"valuation_metrics": {"PB_Ratio": null, "PE_Ratio": null, "PS_Ratio": null, "PCF_Ratio": null}}');
INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (456, 'EEH', 'ETF', 'us', 'American Century Equity Growth ', 'American Century Equity Growth Fund C Class', 'US Dollar', NULL, NULL, 'American Century Investments', 'PCX', 'Large Blend', 1417347, NULL, '2007-08-01', NULL, 'The investment seeks long-term capital growth by investing in common stocks. The fund invests at least 80% of its net assets in equity securities. In selecting stocks for the fund, the portfolio managers use quantitative and qualitative management techniques in a multi-step process. First, the managers rank stocks, primarily large capitalization, publicly traded U.S. companies from most attractive to least attractive based on an objective set of measures. Second, the portfolio managers use a quantitative model to build a portfolio of stocks from the ranking that they believe will provide the optimal balance between risk and expected return.', 0.0075, 0.0036, 19, 20, 32.887, 30.935, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '{"Cap_Size": null, "Quote_Mode": "ETF", "Currency_Base": "US Dollar", "GeoZone_Class": "us", "Strategy_Type": null}', '{"Net_Worth": 1417347, "Yield_Rate": null, "Expense_Net": 0.0075, "Benchmark_Exp": 0.0036, "Turnover_Ratio": null}', '{"volume_metrics": {"Vol_3M": 19, "Vol_Recent": 20}, "moving_averages": {"MA_50": 32.887, "MA_200": 30.935}}', '{"asset_allocation": {"Bond_Weight": null, "Equity_Weight": null}, "bond_characteristics": {"Avg_Maturity": null, "Duration_Yrs": null}}', '{"valuation_metrics": {"PB_Ratio": null, "PE_Ratio": null, "PS_Ratio": null, "PCF_Ratio": null}}');
INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (484, 'EMBH', 'ETF', 'USA', 'Sustainable Equity Fund Class G', 'American Century Sustainable Equity Fund G Class', 'Dollar', NULL, NULL, 'American Century Investments', 'PCX', 'Emerging Markets Bond', 7190984, 0.0252, '2015-07-22', 0.04, 'The investment seeks long-term capital growth; income is a secondary objective. The fund will generally invest in large capitalization companies the advisor believes show sustainable business improvement using a proprietary multi-factor model that combines fundamental measures of a stock''s value and growth potential with ESG metrics. The model assigns each security a financial metrics score and an ESG score that are combined to create an overall score. To measure growth, the managers may use the rate of growth of a company''s earnings and cash flow and changes in its earnings estimates.', 0.0047, 0.0046, 1158, 700, 23.569, 23.799, NULL, NULL, NULL, NULL, NULL, NULL, 13.54, 0.24, '{"Cap_Size": null, "Quote_Mode": "ETF", "Currency_Base": "Dollar", "GeoZone_Class": "USA", "Strategy_Type": null}', '{"Net_Worth": 7190984, "Yield_Rate": 0.0252, "Expense_Net": 0.0047, "Benchmark_Exp": 0.0046, "Turnover_Ratio": 0.04}', '{"volume_metrics": {"Vol_3M": 1158, "Vol_Recent": 700}, "moving_averages": {"MA_50": 23.569, "MA_200": 23.799}}', '{"asset_allocation": {"Bond_Weight": null, "Equity_Weight": null}, "bond_characteristics": {"Avg_Maturity": 13.54, "Duration_Yrs": 0.24}}', '{"valuation_metrics": {"PB_Ratio": null, "PE_Ratio": null, "PS_Ratio": null, "PCF_Ratio": null}}');
