INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (459, 'EEMD', 'ETF', 'usa', 'American Century Equity Income ', 'American Century Equity Income Fund C Class', 'USD', 'Value', 'Medium', 'American Century Investments', 'PCX', 'Diversified Emerging Mkts', 7474248, 0.0438, '2017-11-28', 1.21, 'The investment seeks current income; capital appreciation is a secondary objective. The portfolio managers look for equity securities of companies with a favorable income-paying history that have prospects for income payments to continue or increase. The portfolio managers also look for equity securities of companies that they believe are undervalued and have the potential for an increase in price. The fund may invest a portion of its assets in foreign securities when these securities meet the portfolio managers'' standards of selection.', 0.005, 0.0056, 1290, 1490, 22.442, 22.946, 0.9916, 0, 0.79, 3.17, 7.37, 0.44, NULL, NULL, '{"Cap_Size": "Medium", "Quote_Mode": "ETF", "Currency_Base": "USD", "GeoZone_Class": "usa", "Strategy_Type": "Value"}', '{"Net_Worth": 7474248, "Yield_Rate": 0.0438, "Expense_Net": 0.005, "Benchmark_Exp": 0.0056, "Turnover_Ratio": 1.21}', '{"volume_metrics": {"Vol_3M": 1290, "Vol_Recent": 1490}, "moving_averages": {"MA_50": 22.442, "MA_200": 22.946}}', '{"asset_allocation": {"Bond_Weight": 0, "Equity_Weight": 0.9916}, "bond_characteristics": {"Avg_Maturity": null, "Duration_Yrs": null}}', '{"valuation_metrics": {"PB_Ratio": 0.79, "PE_Ratio": 7.37, "PS_Ratio": 0.44, "PCF_Ratio": 3.17}}');
