INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (466, 'EFAD', 'ETF', 'U.S.A.', 'Access Flex Bear High Yield Fun', 'Access Flex Bear High Yield ProFund Investor Class', 'USD', 'Blend', 'Large', 'ProFunds', 'BTS', 'Foreign Large Growth', 138085568, 0.0168, '2014-08-19', NULL, 'The investment seeks to provide investment results that correspond generally to the inverse of the total return of the high yield market consistent with maintaining reasonable liquidity. The fund invests primarily in financial instruments that ProFund Advisors believes, in combination, should provide investment results that correspond generally to the inverse of the high yield market. It seeks to maintain inverse exposure to the high yield market regardless of market conditions and without taking defensive positions in cash or other instruments in anticipation of periods favorable for the high yield market. The fund is non-diversified.', 0.0051, 0.0066, 6532, 9800, 46.825, 46.224, 0.9911, 0, 2.89, 14.65, 24.53, 2.21, NULL, NULL, '{"Cap_Size": "Large", "Quote_Mode": "ETF", "Currency_Base": "USD", "GeoZone_Class": "U.S.A.", "Strategy_Type": "Blend"}', '{"Net_Worth": 138085568, "Yield_Rate": 0.0168, "Expense_Net": 0.0051, "Benchmark_Exp": 0.0066, "Turnover_Ratio": null}', '{"volume_metrics": {"Vol_3M": 6532, "Vol_Recent": 9800}, "moving_averages": {"MA_50": 46.825, "MA_200": 46.224}}', '{"asset_allocation": {"Bond_Weight": 0, "Equity_Weight": 0.9911}, "bond_characteristics": {"Avg_Maturity": null, "Duration_Yrs": null}}', '{"valuation_metrics": {"PB_Ratio": 2.89, "PE_Ratio": 24.53, "PS_Ratio":