INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (494, 'EMSH', 'ETF', 'U.S.', 'Fundamental Investors, Class C ', 'American Funds Fundamental Investors Class C', 'US_DOLLAR', NULL, NULL, 'American Funds', 'BTS', 'Emerging Markets Bond', 7337642, 0.0282, '2013-11-19', NULL, 'The investment seeks long-term growth of capital and income. The fund invests primarily in common stocks of companies that appear to offer superior opportunities for capital growth and most of which have a history of paying dividends. It may invest significantly in securities of issuers domiciled outside the United States. The investment adviser uses a system of multiple portfolio managers in managing the fund''s assets.', 0.005, 0.0046, 1095, 1700, 72.511, 73.148, 0, 0.9966, NULL, NULL, NULL, NULL, NULL, NULL, '{"Cap_Size": null, "Quote_Mode": "ETF", "Currency_Base": "US_DOLLAR", "GeoZone_Class": "U.S.", "Strategy_Type": null}', '{"Net_Worth": 7337642, "Yield_Rate": 0.0282, "Expense_Net": 0.005, "Benchmark_Exp": 0.0046, "Turnover_Ratio": null}', '{"volume_metrics": {"Vol_3M": 1095, "Vol_Recent": 1700}, "moving_averages": {"MA_50": 72.511, "MA_200": 73.148}}', '{"asset_allocation": {"Bond_Weight": 0.9966, "Equity_Weight": 0}, "bond_characteristics": {"Avg_Maturity": null, "Duration_Yrs": null}}', '{"valuation_metrics": {"PB_Ratio": null, "PE_Ratio": null, "PS_Ratio": null, "PCF_Ratio": null}}');
INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (497, 'EMXC', 'ETF', 'USA', 'AllianzGI International Value F', 'Virtus NFJ International Value Fund Class C', 'US_DOLLAR', 'Blend', 'Large', 'Virtus', 'NGM', 'Diversified Emerging Mkts', 835443904, 0.0137, '2017-07-18', 0.18, 'The investment seeks long-term growth of capital and income. The fund normally invests at least 65% of its net assets (plus borrowings made for investment purposes) in common stocks and other equity securities (such as preferred stocks, convertible securities and warrants) of non-U.S. companies with market capitalizations greater than $1 billion. It normally invests significantly in securities that the portfolio managers expect will generate income (for example, by paying dividends).', 0.0025, 0.0056, 400225, 270440, 61.143, 61.071, NULL, NULL, 1.98, 9.21, 17.83, 1.62, NULL, NULL, '{"Cap_Size": "Large", "Quote_Mode": "ETF", "Currency_Base": "US_DOLLAR", "GeoZone_Class": "USA", "Strategy_Type": "Blend"}', '{"Net_Worth": 835443904, "Yield_Rate": 0.0137, "Expense_Net": 0.0025, "Benchmark_Exp": 0.0056, "Turnover_Ratio": 0.18}', '{"volume_metrics": {"Vol_3M": 400225, "Vol_Recent": 270440}, "moving_averages": {"MA_50": 61.143, "MA_200": 61.071}}', '{"asset_allocation": {"Bond_Weight": null, "Equity_Weight": null}, "bond_characteristics": {"Avg_Maturity": null, "Duration_Yrs": null}}', '{"valuation_metrics": {"PB_Ratio": 1.98, "PE_Ratio": 17.83, "PS_Ratio": 1.62, "PCF_Ratio": 9.21}}');
