INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (502, 'EOPS', 'ETF', 'UNITED_STATES', 'American Balanced Fund - Class ', 'American Funds American Balanced Fund Class F-3', 'US_DOLLAR', NULL, NULL, 'American Funds', 'BTS', NULL, NULL, NULL, '2021-06-09', NULL, 'The investment seeks conservation of capital, current income and long-term growth of capital and income. The fund uses a balanced approach to invest in a broad range of securities, including common stocks and investment-grade bonds. It also invests in securities issued and guaranteed by the U.S. government and by federal agencies and instrumentalities. In addition, the fund may invest a portion of its assets in common stocks, most of which have a history of paying dividends, bonds and other securities of issuers domiciled outside the United States.', 0.0195, NULL, 2850, 1220, 27.184, 26.474, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '{"Cap_Size": null, "Quote_Mode": "ETF", "Currency_Base": "US_DOLLAR", "GeoZone_Class": "UNITED_STATES", "Strategy_Type": null}', '{"Net_Worth": null, "Yield_Rate": null, "Expense_Net": 0.0195, "Benchmark_Exp": null, "Turnover_Ratio": null}', '{"volume_metrics": {"Vol_3M": 2850, "Vol_Recent": 1220}, "moving_averages": {"MA_50": 27.184, "MA_200": 26.474}}', '{"asset_allocation": {"Bond_Weight": null, "Equity_Weight": null}, "bond_characteristics": {"Avg_Maturity": null, "Duration_Yrs": null}}', '{"valuation_metrics": {"PB_Ratio": null, "PE_Ratio": null, "PS_Ratio": null, "PCF_Ratio": null}}');
INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (577, 'FCAL', 'ETF', 'US', 'American Century Global Gold Fu', 'American Century Global Gold Fund I Class', 'US$', NULL, NULL, 'American Century Investments', 'NGM', 'Muni California Long', 101695144, 0.0207, '2017-06-21', 0.81, 'The investment seeks to realize a total return (capital growth and dividends) consistent with investment in securities of companies that are engaged in mining, processing, fabricating or distributing gold or other precious metals throughout the world. The fund invests at least 80% of its net assets in companies that are engaged in mining, processing, fabricating, distributing, exploring for or otherwise dealing in gold. It is non-diversified.', 0.005, 0.0028, 9219, 7410, 54.538, 54.704, NULL, NULL, NULL, NULL, NULL, NULL, 14.35, NULL, '{"Cap_Size": null, "Quote_Mode": "ETF", "Currency_Base": "US$", "GeoZone_Class": "US", "Strategy_Type": null}', '{"Net_Worth": 101695144, "Yield_Rate": 0.0207, "Expense_Net": 0.005, "Benchmark_Exp": 0.0028, "Turnover_Ratio": 0.81}', '{"volume_metrics": {"Vol_3M": 9219, "Vol_Recent": 7410}, "moving_averages": {"MA_50": 54.538, "MA_200": 54.704}}', '{"asset_allocation": {"Bond_Weight": null, "Equity_Weight": null}, "bond_characteristics": {"Avg_Maturity": 14.35, "Duration_Yrs": null}}', '{"valuation_metrics": {"PB_Ratio": null, "PE_Ratio": null, "PS_Ratio": null, "PCF_Ratio": null}}');
INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (509, 'EQOP', 'ETF', 'us', 'Aperture International Equity F', 'Aperture International Equity Fund Class X Shares', 'usd', 'Blend', 'Large', 'Aperture Investors', 'PCX', NULL, 13995050, NULL, '2020-09-16', 0.06, 'The investment seeks a return in excess of the MSCI ACWI ex-US Index (the "index"). Under normal circumstances, the fund invests at least 80% of its net assets, plus any borrowings for investment purposes, in equity securities. It will invest primarily in securities economically tied to non-U.S. countries, including emerging market countries. The fund seeks to achieve its objective primarily by taking long and short positions in equity securities. It is non-diversified.', 0.009, NULL, 29085, 90, 35.781, 34.081, NULL, NULL, 2.81, 16.56, 27.05, 2.55, NULL, NULL, '{"Cap_Size": "Large", "Quote_Mode": "ETF", "Currency_Base": "usd", "GeoZone_Class": "us", "Strategy_Type": "Blend"}', '{"Net_Worth": 13995050, "Yield_Rate": null, "Expense_Net": 0.009, "Benchmark_Exp": null, "Turnover_Ratio": 0.06}', '{"volume_metrics": {"Vol_3M": 29085, "Vol_Recent": 90}, "moving_averages": {"MA_50": 35.781, "MA_200": 34.081}}', '{"asset_allocation": {"Bond_Weight": null, "Equity_Weight": null}, "bond_characteristics": {"Avg_Maturity": null, "Duration_Yrs": null}}', '{"valuation_metrics": {"PB_Ratio": 2.81, "PE_Ratio": 27.05, "PS_Ratio": 2.55, "PCF_Ratio": 16.56}}');
INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (503, 'EPI', 'ETF', 'U.S.A.', 'Acuitas US Microcap Fund - Inst', 'Acuitas US Microcap Fund Institutional Shares', 'US$', 'Blend', 'Large', 'Acuitas Investments', 'PCX', 'India Equity', 852500672, 0.0072, '2008-02-22', 0.23, 'The investment seeks capital appreciation. The fund normally invests at least 80% of its net assets (plus borrowings for investment purposes) in the equity securities of microcap companies. It will pursue its investment objective using a "multi-manager" process, allocating assets among a carefully chosen group of asset managers (the "Subadvisers"). The Adviser will select the fund''s Subadvisers using its manager research and selection process which seeks to identify investment managers that are likely to achieve out performance over a long time horizon.', 0.0084, 0.0084, 535267, 614140, 37.898, 34.603, 1, 0, 2.35, 9.72, 17.95, 1.82, NULL, NULL, '{"Cap_Size": "Large", "Quote_Mode": "ETF", "Currency_Base": "US$", "GeoZone_Class": "U.S.A.", "Strategy_Type": "Blend"}', '{"Net_Worth": 852500672, "Yield_Rate": 0.0072, "Expense_Net": 0.0084, "Benchmark_Exp": 0.0084, "Turnover_Ratio": 0.23}', '{"volume_metrics": {"Vol_3M": 535267, "Vol_Recent": 614140}, "moving_averages": {"MA_50": 37.898, "MA_200": 34.603}}', '{"asset_allocation": {"Bond_Weight": 0, "Equity_Weight": 1}, "bond_characteristics": {"Avg_Maturity": null, "Duration_Yrs": null}}', '{"valuation_metrics": {"PB_Ratio": 2.35, "PE_Ratio": 17.95, "PS_Ratio": 1.82, "PCF_Ratio": 9.72}}');
INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (504, 'EPRF', 'ETF', 'US', 'American Mutual Fund - Class F-', 'American Funds American Mutual Fund Class F-3', 'Usd', NULL, NULL, 'American Funds', 'BTS', NULL, 184549376, 0.0514, '2016-05-23', 0.58, 'The investment seeks current income, growth of capital and conservation of principal. The fund invests primarily in common stocks of companies that are likely to participate in the growth of the American economy and whose dividends appear to be sustainable. It invests primarily in securities of issuers domiciled in the United States and Canada. The fund may also invest in bonds and other debt securities, including those issued by the U.S. government and by federal agencies and instrumentalities.', 0.0047, NULL, 40451, 34070, 24.013, 24.22, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '{"Cap_Size": null, "Quote_Mode": "ETF", "Currency_Base": "Usd", "GeoZone_Class": "US", "Strategy_Type": null}', '{"Net_Worth": 184549376, "Yield_Rate": 0.0514, "Expense_Net": 0.0047, "Benchmark_Exp": null, "Turnover_Ratio": 0.58}', '{"volume_metrics": {"Vol_3M": 40451, "Vol_Recent": 34070}, "moving_averages": {"MA_50": 24.013, "MA_200": 24.22}}', '{"asset_allocation": {"Bond_Weight": null, "Equity_Weight": null}, "bond_characteristics": {"Avg_Maturity": null, "Duration_Yrs": null}}', '{"valuation_metrics": {"PB_Ratio": null, "PE_Ratio": null, "PS_Ratio": null, "PCF_Ratio": null}}');
INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (505, 'EPS', 'ETF', 'United States', 'Yorktown Short Term Bond Fund C', 'Yorktown Short Term Bond Fund Class L', 'Usd', 'Blend', 'Large', 'Yorktown Funds', 'PCX', 'Large Blend', 579606272, 0.0158, '2007-02-23', 0.21, 'The investment seeks income consistent with the preservation of capital. Under normal circumstances, the fund invests at least 80% of its assets in fixed income securities that, in the Adviser''s opinion, offer the opportunity for income consistent with preservation of capital. Its portfolio will have an average aggregate maturity of not more than three years. The fund seeks to provide diversification by allocating its investments among various areas of the fixed income markets. It primarily invests in the investment grade debt securities of various types.', 0.0008, 0.0036, 29953, 17840, 48.147, 46.271, 1, 0, 3.74, 14.18, 21.17, 2.16, NULL, NULL, '{"Cap_Size": "Large", "Quote_Mode": "ETF", "Currency_Base": "Usd", "GeoZone_Class": "United States", "Strategy_Type": "Blend"}', '{"Net_Worth": 579606272, "Yield_Rate": 0.0158, "Expense_Net": 0.0008, "Benchmark_Exp": 0.0036, "Turnover_Ratio": 0.21}', '{"volume_metrics": {"Vol_3M": 29953, "Vol_Recent": 17840}, "moving_averages": {"MA_50": 48.147, "MA_200": 46.271}}', '{"asset_allocation": {"Bond_Weight": 0, "Equity_Weight": 1}, "bond_characteristics": {"Avg_Maturity": null, "Duration_Yrs": null}}', '{"valuation_metrics": {"PB_Ratio": 3.74, "PE_Ratio": 21.17, "PS_Ratio": 2.16, "PCF_Ratio": 14.18}}');
INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (506, 'EPV', 'ETF', 'America', 'AAM/Bahl & Gaynor Income Growth', 'AAM/Bahl & Gaynor Income Growth Fund Class A', 'usd', NULL, NULL, 'AAM', 'PCX', 'Trading--Inverse Equity', 7464526, NULL, '2009-06-16', NULL, 'The investment seeks current and growing income, secondarily downside protection and thirdly long-term capital appreciation. Under normal market conditions, the fund invests at least 80% of its assets plus borrowings for investment purposes in equity securities, primarily common stock, of companies that have historically paid dividends and have strong dividend policies. Although the fund may invest in any size companies, it primarily invests in large capitalization companies. Under normal market conditions, it typically invests in a diversified portfolio of 35 to 50 securities spread across a variety of economic sectors.', 0.0095, 0.0092, 23962, 61720, 11.614, 12.352, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '{"Cap_Size": null, "Quote_Mode": "ETF", "Currency_Base": "usd", "GeoZone_Class": "America", "Strategy_Type": null}', '{"Net_Worth": 7464526, "Yield_Rate": null, "Expense_Net": 0.0095, "Benchmark_Exp": 0.0092, "Turnover_Ratio": null}', '{"volume_metrics": {"Vol_3M": 23962, "Vol_Recent": 61720}, "moving_averages": {"MA_50": 11.614, "MA_200": 12.352}}', '{"asset_allocation": {"Bond_Weight": null, "Equity_Weight": null}, "bond_characteristics": {"Avg_Maturity": null, "Duration_Yrs": null}}', '{"valuation_metrics": {"PB_Ratio": null, "PE_Ratio": null, "PS_Ratio": null, "PCF_Ratio": null}}');
