INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (524, 'ESGN', 'ETF', 'US', 'American Fds, The Tax-Exempt Bo', 'American Funds Tax-Exempt Bond Fund Class A', 'Dollar', 'Value', 'Large', 'American Funds', 'PCX', NULL, 5690624, 0.0238, '2016-06-13', 0.98, 'The investment seeks a high level of current income exempt from federal income tax, consistent with the preservation of capital. The fund will invest at least 80% of its assets in, or derive at least 80% of its income from, securities that are exempt from regular federal income tax. It will not invest in securities that subject the investors to federal alternative minimum tax. It invests at least 65% in debt securities rated A- or better or A3 or better by Nationally Recognized Statistical Rating Organizations designated by the fund''s investment adviser, or unrated but determined by the fund''s investment adviser to be of equivalent quality.', 0.0045, NULL, 593, 200, 27.226, 27.717, NULL, NULL, 1.13, 5.65, 14.89, 0.69, NULL, NULL, '{"Cap_Size": "Large", "Quote_Mode": "ETF", "Currency_Base": "Dollar", "GeoZone_Class": "US", "Strategy_Type": "Value"}', '{"Net_Worth": 5690624, "Yield_Rate": 0.0238, "Expense_Net": 0.0045, "Benchmark_Exp": null, "Turnover_Ratio": 0.98}', '{"volume_metrics": {"Vol_3M": 593, "Vol_Recent": 200}, "moving_averages": {"MA_50": 27.226, "MA_200": 27.717}}', '{"asset_allocation": {"Bond_Weight": null, "Equity_Weight": null}, "bond_characteristics": {"Avg_Maturity": null, "Duration_Yrs": null}}', '{"valuation_metrics": {"PB_Ratio": 1.13, "PE_Ratio": 14.89, "PS_Ratio": 0.69, "PCF_Ratio": 5.65}}');
