INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (526, 'ESGV', 'ETF', 'usa', 'Applied Finance Select Fund Inv', 'Applied Finance Select Fund Investor Class Shares', 'US$', 'Growth', 'Large', 'Applied Finance Advisors', 'BTS', NULL, 4476920832, 0.0102, '2018-09-18', 0.06, 'The investment seeks long-term capital appreciation. The fund invests primarily in equity securities of U.S. companies whose market capitalizations are $3 billion or more, measured at the time of purchase. Equity securities in which the fund may invest include common and preferred stocks, rights and warrants, and securities convertible into equity securities. It may also invest in the securities of other investment companies including exchange-traded funds ("ETFs").', 0.0012, NULL, 262722, 303760, 84.54, 80.031, 0.9999, 0, 4.55, 17.3, 26.7, 2.9, NULL, NULL, '{"Cap_Size": "Large", "Quote_Mode": "ETF", "Currency_Base": "US$", "GeoZone_Class": "usa", "Strategy_Type": "Growth"}', '{"Net_Worth": 4476920832, "Yield_Rate": 0.0102, "Expense_Net": 0.0012, "Benchmark_Exp": null, "Turnover_Ratio": 0.06}', '{"volume_metrics": {"Vol_3M": 262722, "Vol_Recent": 303760}, "moving_averages": {"MA_50": 84.54, "MA_200": 80.031}}', '{"asset_allocation": {"Bond_Weight": 0, "Equity_Weight": 0.9999}, "bond_characteristics": {"Avg_Maturity": null, "Duration_Yrs": null}}', '{"valuation_metrics": {"PB_Ratio": 4.55, "PE_Ratio": 26.7, "PS_Ratio": 2.9, "PCF_Ratio": 17.3}}');
INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (527, 'ESGY', 'ETF', 'U.S.', 'AllianzGI International Value F', 'Virtus NFJ International Value Fund Class P', 'US Dollar', 'Growth', 'Large', 'Virtus', 'PCX', 'Large Blend', 5204632, NULL, '2021-06-29', NULL, 'The investment seeks long-term growth of capital and income. The fund normally invests at least 65% of its net assets (plus borrowings made for investment purposes) in common stocks and other equity securities (such as preferred stocks, convertible securities and warrants) of non-U.S. companies with market capitalizations greater than $1 billion. It normally invests significantly in securities that the portfolio managers expect will generate income (for example, by paying dividends).', 0.0039, 0.0036, 466, 1060, 43.885, 39.48, 1, 0, 11.32, 25.5, 37.84, 5.47, NULL, NULL, '{"Cap_Size": "Large", "Quote_Mode": "ETF", "Currency_Base": "US Dollar", "GeoZone_Class": "U.S.", "Strategy_Type": "Growth"}', '{"Net_Worth": 5204632, "Yield_Rate": null, "Expense_Net": 0.0039, "Benchmark_Exp": 0.0036, "Turnover_Ratio": null}', '{"volume_metrics": {"Vol_3M": 466, "Vol_Recent": 1060}, "moving_averages": {"MA_50": 43.885, "MA_200": 39.48}}', '{"asset_allocation": {"Bond_Weight": 0, "Equity_Weight": 1}, "bond_characteristics": {"Avg_Maturity": null, "Duration_Yrs": null}}', '{"valuation_metrics": {"PB_Ratio": 11.32, "PE_Ratio": 37.84, "PS_Ratio": 5.47, "PCF_Ratio": 25.5}}');
