INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (534, 'EUDV', 'ETF', 'United States', '361 Global Long/Short Equity Fu', '361 Global Long/Short Equity Fund Investor Class', 'USD', 'Growth', 'Large', '361 Funds', 'BTS', NULL, 8426431, 0.013, '2015-09-09', NULL, 'The investment seeks to achieve long-term capital appreciation and to preserve capital in down markets. The fund seeks to invest at least 80% of the value of its net assets (which include borrowings for investment purposes) in equity securities such as common stocks, warrants and rights. It may invest in equity securities of U.S. and foreign issuers in all market capitalization ranges without limitation. Under normal market conditions, the fund will invest in at least three different countries, with at least 40% of its net assets invested in securities of issuers located outside the United States.', 0.0056, NULL, 867, 1190, 53.578, 52.03, 0.9914, 0, 3.23, 13.13, 24.57, 2.14, NULL, NULL, '{"Cap_Size": "Large", "Quote_Mode": "ETF", "Currency_Base": "USD", "GeoZone_Class": "United States", "Strategy_Type": "Growth"}', '{"Net_Worth": 8426431, "Yield_Rate": 0.013, "Expense_Net": 0.0056, "Benchmark_Exp": null, "Turnover_Ratio": null}', '{"volume_metrics": {"Vol_3M": 867, "Vol_Recent": 1190}, "moving_averages": {"MA_50": 53.578, "MA_200": 52.03}}', '{"asset_allocation": {"Bond_Weight": 0, "Equity_Weight": 0.9914}, "bond_characteristics": {"Avg_Maturity": null, "Duration_Yrs": null}}', '{"valuation_metrics": {"PB_Ratio": 3.23, "PE_Ratio": 24.57, "PS_Ratio": 2.14, "PCF_Ratio": 13.13}}');
