INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (561, 'FAB', 'ETF', 'US', 'Water Island Diversified Event-', 'Water Island Event-Driven Fund Class A', 'USD', 'Value', 'Medium', 'Arbitrage Fund', 'NGM', 'Mid-Cap Value', 163311968, 0.0121, '2007-05-08', 0.98, 'The investment seeks to achieve capital growth. The fund invests in equity and debt and debt-like instruments (including high yield bonds commonly known as "junk bonds") of companies whose prices the fund''s investment adviser believes are or will be impacted by a corporate event. Specifically, the fund employs investment strategies designed to capture price movements generated by corporate events such as mergers, acquisitions, asset sales, restructurings, refinancings, recapitalizations, reorganizations or other special situations (referred to as "event-driven opportunities"). It is non-diversified.', 0.007, 0.0043, 17635, 17950, 73.071, 71.419, 0.9996, 0, 1.78, 8.88, 14.06, 1.22, NULL, NULL, '{"Cap_Size": "Medium", "Quote_Mode": "ETF", "Currency_Base": "USD", "GeoZone_Class": "US", "Strategy_Type": "Value"}', '{"Net_Worth": 163311968, "Yield_Rate": 0.0121, "Expense_Net": 0.007, "Benchmark_Exp": 0.0043, "Turnover_Ratio": 0.98}', '{"volume_metrics": {"Vol_3M": 17635, "Vol_Recent": 17950}, "moving_averages": {"MA_50": 73.071, "MA_200": 71.419}}', '{"asset_allocation": {"Bond_Weight": 0, "Equity_Weight": 0.9996}, "bond_characteristics": {"Avg_Maturity": null, "Duration_Yrs": null}}', '{"valuation_metrics": {"PB_Ratio": 1.78, "PE_Ratio": 14.06, "PS_Ratio": 1.22, "PCF_Ratio": 8.88}}');
