INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (569, 'FAUG', 'ETF', 'US', 'The AB Portfolios - AB Growth F', 'AB Growth Fund Class I', 'US Dollar', 'Blend', 'Large', 'AllianceBernstein', 'BTS', NULL, 81310960, NULL, '2019-11-07', NULL, 'The investment seeks long-term growth of capital. The fund invests primarily in a domestic equity securities of companies selected by the fund''s Adviser for their growth potential with in various market sectors. When selecting securities, the Adviser looks for companies that have experienced management teams, strong market positions, and the potential to deliver greater-than-expected earnings growth rates. The fund has the flexibility to invest across the capitalization spectrum. It may enter into derivatives transactions, such as options, futures contracts, forwards and swaps.', 0.0085, NULL, 38637, 72590, 37.65, 36.822, 0.9936, 0, 4.43, 17.58, 26.49, 2.96, NULL, NULL, '{"Cap_Size": "Large", "Quote_Mode": "ETF", "Currency_Base": "US Dollar", "GeoZone_Class": "US", "Strategy_Type": "Blend"}', '{"Net_Worth": 81310960, "Yield_Rate": null, "Expense_Net": 0.0085, "Benchmark_Exp": null, "Turnover_Ratio": null}', '{"volume_metrics": {"Vol_3M": 38637, "Vol_Recent": 72590}, "moving_averages": {"MA_50": 37.65, "MA_200": 36.822}}', '{"asset_allocation": {"Bond_Weight": 0, "Equity_Weight": 0.9936}, "bond_characteristics": {"Avg_Maturity": null, "Duration_Yrs": null}}', '{"valuation_metrics": {"PB_Ratio": 4.43, "PE_Ratio": 26.49, "PS_Ratio": 2.96, "PCF_Ratio": 17.58}}');
