INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (580, 'FCOM', 'ETF', 'U.S.A.', 'Invesco Global Growth Fund Clas', 'Invesco Global Growth Fund Class Y', 'Usd', 'Growth', 'Large', 'Invesco', 'PCX', 'Communications', 855794240, 0.0056, '2013-10-21', 0.23, 'The investment seeks long-term growth of capital. The fund invests primarily in equity securities and depositary receipts of domestic and foreign issuers. It will provide exposure to investments that are economically tied to at least three different countries, including the U.S. and at least 40%, unless market conditions are not deemed favorable, in which case at least 30%, of its net assets will provide exposure to investments that are economically tied to countries other than the U.S. The fund may invest up to 20% of its net assets in securities of issuers located in emerging markets countries.', 0.00084, 0.0035, 81541, 93360, 53.573, 53.057, 0.9974, 0, 4.04, 13.85, 27.58, 3.6, NULL, NULL, '{"Cap_Size": "Large", "Quote_Mode": "ETF", "Currency_Base": "Usd", "GeoZone_Class": "U.S.A.", "Strategy_Type": "Growth"}', '{"Net_Worth": 855794240, "Yield_Rate": 0.0056, "Expense_Net": 0.00084, "Benchmark_Exp": 0.0035, "Turnover_Ratio": 0.23}', '{"volume_metrics": {"Vol_3M": 81541, "Vol_Recent": 93360}, "moving_averages": {"MA_50": 53.573, "MA_200": 53.057}}', '{"asset_allocation": {"Bond_Weight": 0, "Equity_Weight": 0.9974}, "bond_characteristics": {"Avg_Maturity": null, "Duration_Yrs": null}}', '{"valuation_metrics": {"PB_Ratio": 4.04, "PE_Ratio": 27.58, "PS_Ratio": 3.6, "PCF_Ratio": 13.85}}');
INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (581, 'FCOR', 'ETF', 'USA', 'The AB Portfolios - AB Tax-Mana', 'AB Tax-Managed All Market Income Portfolio Class A', 'DOLLAR', NULL, NULL, 'AllianceBernstein', 'PCX', 'Corporate Bond', 292159936, 0.0236, '2014-10-06', 0.31, 'The investment seeks current income with consideration of capital appreciation. The Adviser allocates the fund''s investments primarily among a broad range of income-producing securities, including common stock of companies that regularly pay dividends (including real estate investment trusts, or REITs), preferred stocks, fixed-income securities (including those with lower credit ratings), and derivatives related to these types of securities. The fund pursues a global strategy, typically investing in securities of issuers located in the United States and in other countries throughout the world, including emerging market countries.', 0.0036, 0.0017, 22838, 32470, 55.333, 55.334, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 8.33, '{"Cap_Size": null, "Quote_Mode": "ETF", "Currency_Base": "DOLLAR", "GeoZone_Class": "USA", "Strategy_Type": null}', '{"Net_Worth": 292159936, "Yield_Rate": 0.0236, "Expense_Net": 0.0036, "Benchmark_Exp": 0.0017, "Turnover_Ratio": 0.31}', '{"volume_metrics": {"Vol_3M": 22838, "Vol_Recent": 32470}, "moving_averages": {"MA_50": 55.333, "MA_200": 55.334}}', '{"asset_allocation": {"Bond_Weight": null, "Equity_Weight": null}, "bond_characteristics": {"Avg_Maturity": null, "Duration_Yrs": 8.33}}', '{"valuation_metrics": {"PB_Ratio": null, "PE_Ratio": null, "PS_Ratio": null, "PCF