INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (594, 'FDMO', 'ETF', 'America', 'PGIM Jennison Global Equity Inc', 'PGIM Jennison Global Equity Income Fund- Class C', 'US Dollar', 'Growth', 'Large', 'PGIM Funds (Prudential)', 'PCX', 'Large Growth', 141130448, 0.0057, '2016-09-12', 1.38, 'The investment seeks income and capital appreciation. The fund invests under normal circumstances at least 80% of its investable assets in income-producing equity and equity-related securities. Equity and equity-related securities include common stocks, securities convertible or exchangeable for common stock or the cash value of such common stock, nonconvertible preferred stocks and convertible securities, warrants and rights that can be exercised to obtain stock.', 0.0029, 0.0039, 14166, 15740, 51.946, 48.856, 0.997, 0, 4.78, 16.17, 25.81, 2.92, NULL, NULL, '{"Cap_Size": "Large", "Quote_Mode": "ETF", "Currency_Base": "US Dollar", "GeoZone_Class": "America", "Strategy_Type": "Growth"}', '{"Net_Worth": 141130448, "Yield_Rate": 0.0057, "Expense_Net": 0.0029, "Benchmark_Exp": 0.0039, "Turnover_Ratio": 1.38}', '{"volume_metrics": {"Vol_3M": 14166, "Vol_Recent": 15740}, "moving_averages": {"MA_50": 51.946, "MA_200": 48.856}}', '{"asset_allocation": {"Bond_Weight": 0, "Equity_Weight": 0.997}, "bond_characteristics": {"Avg_Maturity": null, "Duration_Yrs": null}}', '{"valuation_metrics": {"PB_Ratio": 4.78, "PE_Ratio": 25.81, "PS_Ratio": 2.92, "PCF_Ratio": 16.17}}');
INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (828, 'GMF', 'ETF', 'U.S.', 'AMCAP Fund, Class F-2 Shares', 'American Funds AMCAP Fund Class F-2', 'AmericanDollar', 'Blend', 'Large', 'American Funds', 'PCX', 'Pacific/Asia ex-Japan Stk', 728634240, 0.0125, '2007-03-19', 0.08, 'The investment seeks long-term growth of capital. The fund invests primarily in common stocks of U.S. companies that have solid long-term growth records and the potential for good future growth. The basic investment philosophy of the investment adviser is to seek to invest in attractively valued companies that, in its opinion, represent good, long-term investment opportunities.', 0.0049, 0.0054, 14187, 13700, 126.653, 129.836, 0.9933, 0, 2.16, 12.83, 16.81, 1.22, NULL, NULL, '{"Cap_Size": "Large", "Quote_Mode": "ETF", "Currency_Base": "AmericanDollar", "GeoZone_Class": "U.S.", "Strategy_Type": "Blend"}', '{"Net_Worth": 728634240, "Yield_Rate": 0.0125, "Expense_Net": 0.0049, "Benchmark_Exp": 0.0054, "Turnover_Ratio": 0.08}', '{"volume_metrics": {"Vol_3M": 14187, "Vol_Recent": 13700}, "moving_averages": {"MA_50": 126.653, "MA_200": 129.836}}', '{"asset_allocation": {"Bond_Weight": 0, "Equity_Weight": 0.9933}, "bond_characteristics": {"Avg_Maturity": null, "Duration_Yrs": null}}', '{"valuation_metrics": {"PB_Ratio": 2.16, "PE_Ratio": 16.81, "PS_Ratio": 1.22, "PCF_Ratio": 12.83}}');
INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (595, 'FDNI', 'ETF', 'USA', 'Invesco U.S. Government Fund Cl', 'Invesco Income Fund Class R5', 'Dollar', 'Growth', 'Large', 'Invesco', 'NGM', 'Foreign Large Growth', 129466912, 0.0016, '2018-11-06', 0.23, 'The investment seeks current income, and secondarily, capital appreciation. The fund invests primarily in fixed-income securities and in derivatives and other instruments that have economic characteristics similar to such securities. A significant portion of these securities consists of privately-issued mortgage-backed and asset-backed securities such as commercial mortgage-backed securities (CMBS), residential mortgage-backed securities (RMBS), and collateralized loan obligations (CLOs). The fund invests in below-investment grade securities.', 0.0065, 0.0066, 17541, 10470, 41.79, 44.092, 0.9998, 0, 6.22, 26.97, 30.84, 1.04, NULL, NULL, '{"Cap_Size": "Large", "Quote_Mode": "ETF", "Currency_Base": "Dollar", "GeoZone_Class": "USA", "Strategy_Type": "Growth"}', '{"Net_Worth": 129466912, "Yield_Rate": 0.0016, "Expense_Net": 0.0065, "Benchmark_Exp": 0.0066, "Turnover_Ratio": 0.23}', '{"volume_metrics": {"Vol_3M": 17541, "Vol_Recent": 10470}, "moving_averages": {"MA_50": 41.79, "MA_200": 44.092}}', '{"asset_allocation": {"Bond_Weight": 0, "Equity_Weight": 0.9998}, "bond_characteristics": {"Avg_Maturity": null, "Duration_Yrs": null}}', '{"valuation_metrics": {"PB_Ratio": 6.22, "PE_Ratio": 30.84, "PS_Ratio": 1.04, "PCF_Ratio": 26.97}}');
