INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (598, 'FDTS', 'ETF', 'U.S.', 'Alger Small Cap Focus Fund Clas', 'Alger Small Cap Focus Fund Class Z', 'usd', 'Value', 'Medium', 'Alger', 'NGM', 'Foreign Small/Mid Value', 9522136, 0.023, '2012-02-15', 1.27, 'The investment seeks long-term capital appreciation. The fund normally invests at least 80% of its net assets, plus any borrowings for investment purposes, in equity securities of companies that, at the time of purchase of the securities, have total market capitalization between (1) the higher of (a) $5 billion or (b) the company in either the Russell 2000 Growth Index or the MSCI USA Small Cap Index with the highest capitalization, and (2) the company in either index with the lowest capitalization, at any time during the most recent 12-month period as reported by either index. Both indexes are broad-based indexes of small capitalization stocks.', 0.008, 0.0051, 1996, 5030, 47.303, 47.18, 0.99, 0, 0.98, 4.73, 9.3, 0.5, NULL, NULL, '{"Cap_Size": "Medium", "Quote_Mode": "ETF", "Currency_Base": "usd", "GeoZone_Class": "U.S.", "Strategy_Type": "Value"}', '{"Net_Worth": 9522136, "Yield_Rate": 0.023, "Expense_Net": 0.008, "Benchmark_Exp": 0.0051, "Turnover_Ratio": 1.27}', '{"volume_metrics": {"Vol_3M": 1996, "Vol_Recent": 5030}, "moving_averages": {"MA_50": 47.303, "MA_200": 47.18}}', '{"asset_allocation": {"Bond_Weight": 0, "Equity_Weight": 0.99}, "bond_characteristics": {"Avg_Maturity": null, "Duration_Yrs": null}}', '{"valuation_metrics": {"PB_Ratio": 0.98, "PE_Ratio": 9.3, "PS_Ratio": 0.5, "PCF_Ratio": 4.73}}');
INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (599, 'FDVV', 'ETF', 'U.S.A.', 'AGF Global Sustainable Growth E', 'AGF Global Sustainable Growth Equity Fund Class I', 'DOLLAR', 'Value', 'Large', 'AGF Investments', 'PCX', 'Large Value', 956446464, 0.0269, '2016-09-12', 0.49, 'The investment seeks to provide long-term capital growth. The fund invests, under normal circumstances, at least 80 percent of its net assets (plus the amounts of any borrowings) in equity securities. It generally invests in shares of companies located throughout the world, including in the United States. Under normal market conditions, the fund will invest at least 40 percent of its net assets, unless market conditions are deemed unfavorable by AGFA, the fund''s investment adviser, in companies that are economically tied to countries throughout the world, including by being organized outside of the U.S. or conducting substantial business outside of the U.S.', 0.0029, 0.0034, 194564, 132250, 38.733, 37.583, 0.9975, 0, 2.67, 12.6, 20.39, 2.73, NULL, NULL, '{"Cap_Size": "Large", "Quote_Mode": "ETF", "Currency_Base": "DOLLAR", "GeoZone_Class": "U.S.A.", "Strategy_Type": "Value"}', '{"Net_Worth": 956446464, "Yield_Rate": 0.0269, "Expense_Net": 0.0029, "Benchmark_Exp": 0.0034, "Turnover_Ratio": 0.49}', '{"volume_metrics": {"Vol_3M": 194564, "Vol_Recent": 132250}, "moving_averages": {"MA_50": 38.733, "MA_200": 37.583}}', '{"asset_allocation": {"Bond_Weight": 0, "Equity_Weight": 0.9975}, "bond_characteristics": {"Avg_Maturity": null, "Duration_Yrs": null}}', '{"valuation_metrics": {"PB_Ratio": 2.67, "PE_Ratio": 20.39, "PS_Ratio": 2.73, "PCF_Ratio": 12.6}}');
