INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (601, 'FEBZ', 'ETF', 'U.S.', 'AGF Emerging Markets Equity Fun', 'AGF Emerging Markets Equity Fund Class I', 'Dollar', 'Blend', 'Large', 'AGF Investments', 'BTS', NULL, 2036153, NULL, '2021-01-29', NULL, 'The investment seeks to provide capital growth. The fund invests, under normal circumstances, at least 80 percent of its net assets (plus the amounts of any borrowings) in equity securities issued by companies that are economically tied to emerging market countries. The equity securities in which it invests are primarily publicly traded common stocks. For the purpose of the fund''s 80% investment policy, equity securities also include preferred stock, convertible securities, warrants/rights, installment receipts, trust units and equity-linked investments such as depositary receipts and participation notes. It is non-diversified.', 0.0079, NULL, 400, 570, 28.971, 27.712, NULL, NULL, 4.3, 17.44, 27.59, 2.98, NULL, NULL, '{"Cap_Size": "Large", "Quote_Mode": "ETF", "Currency_Base": "Dollar", "GeoZone_Class": "U.S.", "Strategy_Type": "Blend"}', '{"Net_Worth": 2036153, "Yield_Rate": null, "Expense_Net": 0.0079, "Benchmark_Exp": null, "Turnover_Ratio": null}', '{"volume_metrics": {"Vol_3M": 400, "Vol_Recent": 570}, "moving_averages": {"MA_50": 28.971, "MA_200": 27.712}}', '{"asset_allocation": {"Bond_Weight": null, "Equity_Weight": null}, "bond_characteristics": {"Avg_Maturity": null, "Duration_Yrs": null}}', '{"valuation_metrics": {"PB_Ratio": 4.3, "PE_Ratio": 27.59, "PS_Ratio": 2.98, "PCF_Ratio": 17.44}}');
