INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (603, 'FEM', 'ETF', 'U.S.A.', 'The AB Portfolios - AB Growth F', 'AB Growth Fund Class C', 'US$', 'Value', 'Large', 'AllianceBernstein', 'NGM', 'Diversified Emerging Mkts', 555332096, 0.027, '2011-04-18', 1.11, 'The investment seeks long-term growth of capital. The fund invests primarily in a domestic equity securities of companies selected by the fund''s Adviser for their growth potential with in various market sectors. When selecting securities, the Adviser looks for companies that have experienced management teams, strong market positions, and the potential to deliver greater-than-expected earnings growth rates. The fund has the flexibility to invest across the capitalization spectrum. It may enter into derivatives transactions, such as options, futures contracts, forwards and swaps.', 0.008, 0.0056, 76311, 67520, 26.263, 27.15, 0.9936, 0, 1.02, 4.47, 7.95, 0.62, NULL, NULL, '{"Cap_Size": "Large", "Quote_Mode": "ETF", "Currency_Base": "US$", "GeoZone_Class": "U.S.A.", "Strategy_Type": "Value"}', '{"Net_Worth": 555332096, "Yield_Rate": 0.027, "Expense_Net": 0.008, "Benchmark_Exp": 0.0056, "Turnover_Ratio": 1.11}', '{"volume_metrics": {"Vol_3M": 76311, "Vol_Recent": 67520}, "moving_averages": {"MA_50": 26.263, "MA_200": 27.15}}', '{"asset_allocation": {"Bond_Weight": 0, "Equity_Weight": 0.9936}, "bond_characteristics": {"Avg_Maturity": null, "Duration_Yrs": null}}', '{"valuation_metrics": {"PB_Ratio": 1.02, "PE_Ratio": 7.95, "PS_Ratio": 0.62, "PCF_Ratio": 4.47}}');
INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (604, 'FEMB', 'ETF', 'America', 'American Century Growth Fd R6 C', 'American Century Growth Fund R6 Class', 'USD', NULL, NULL, 'American Century Investments', 'NGM', 'Emerging-Markets Local-Currency Bond', 289783616, 0.0568, '2014-11-04', 0.59, 'The investment seeks long-term capital growth. The fund invests in stocks of companies that the adviser believes will increase in value over time. The portfolio managers use a variety of analytical research tools and techniques to identify the stocks of larger-sized companies that meet their investment criteria. Normally, the fund''s portfolio will primarily consist of securities of companies demonstrating business improvement. Although the portfolio managers intend to invest the fund''s assets primarily in U.S. securities, the fund may invest in securities of foreign companies when these securities meet the portfolio managers'' standards of selection.', 0.0085, 0.0055, 68196, 45810, 32.128, 34.183, NULL, NULL, NULL, NULL, NULL, NULL, 7.37, 5.27, '{"Cap_Size": null, "Quote_Mode": "ETF", "Currency_Base": "USD", "GeoZone_Class": "America", "Strategy_Type": null}', '{"Net_Worth": 289783616, "Yield_Rate": 0.0568, "Expense_Net": 0.0085, "Benchmark_Exp": 0.0055, "Turnover_Ratio": 0.59}', '{"volume_metrics": {"Vol_3M": 68196, "Vol_Recent": 45810}, "moving_averages": {"MA_50": 32.128, "MA_200": 34.183}}', '{"asset_allocation": {"Bond_Weight": null, "Equity_Weight": null}, "bond_characteristics": {"Avg_Maturity": 7.37, "Duration_Yrs": 5.27}}', '{"valuation_metrics": {"PB_Ratio": null, "PE_Ratio": null, "PS_Ratio": null, "PCF_Ratio": null}}');
INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (605, 'FEMS', 'ETF', 'U.S.', 'Invesco Global Real Estate Clas', 'Invesco Global Real Estate Fund Class A', 'Usd', 'Value', 'Medium', 'Invesco', 'NGM', 'Diversified Emerging Mkts', 172725136, 0.0346, '2012-02-15', 1.23, 'The investment seeks total return through growth of capital and current income. The fund normally invests at least 80% of its net assets (plus any borrowings for investment purposes) in securities of real estate and real estate-related issuers, and in derivatives and other instruments that have economic characteristics similar to such securities. It invests primarily in real estate investment trusts (REITs) and equity securities (including common and preferred stock, and convertible securities) of domestic and foreign issuers. The fund will provide exposure to investments that are economically tied to at least three different countries, including the U.S.', 0.008, 0.0056, 13309, 13720, 41.602, 44.086, 0.9901, 0, 1, 4.65, 7.7, 0.61, NULL, NULL, '{"Cap_Size": "Medium", "Quote_Mode": "ETF", "Currency_Base": "Usd", "GeoZone_Class": "U.S.", "Strategy_Type": "Value"}', '{"Net_Worth": 172725136, "Yield_Rate": 0.0346, "Expense_Net": 0.008, "Benchmark_Exp": 0.0056, "Turnover_Ratio": 1.23}', '{"volume_metrics": {"Vol_3M": 13309, "Vol_Recent": 13720}, "moving_averages": {"MA_50": 41.602, "MA_200": 44.086}}', '{"asset_allocation": {"Bond_Weight": 0, "Equity_Weight": 0.9901}, "bond_characteristics": {"Avg_Maturity": null, "Duration_Yrs": null}}', '{"valuation_metrics": {"PB_Ratio": 1, "PE_Ratio": 7.7, "PS_Ratio": 0.61, "PCF_Ratio": 4.65}}');
INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (606, 'FENY', 'ETF', 'UNITED_STATES', 'The AB Portfolios - AB Growth F', 'AB Growth Fund Class A', 'AmericanDollar', 'Value', 'Large', 'AllianceBernstein', 'PCX', 'Equity Energy', 999069504, 0.0343, '2013-10-21', 0.17, 'The investment seeks long-term growth of capital. The fund invests primarily in a domestic equity securities of companies selected by the fund''s Adviser for their growth potential with in various market sectors. When selecting securities, the Adviser looks for companies that have experienced management teams, strong market positions, and the potential to deliver greater-than-expected earnings growth rates. The fund has the flexibility to invest across the capitalization spectrum. It may enter into derivatives transactions, such as options, futures contracts, forwards and swaps.', 0.00084, 0.0048, 972608, 890930, 15.509, 14.2, 0.9986, 0, 1.85, 11.73, NULL, 1.73, NULL, NULL, '{"Cap_Size": "Large", "Quote_Mode": "ETF", "Currency_Base": "AmericanDollar", "GeoZone_Class": "UNITED_STATES", "Strategy_Type": "Value"}', '{"Net_Worth": 999069504, "Yield_Rate": 0.0343, "Expense_Net": 0.00084, "Benchmark_Exp": 0.0048, "Turnover_Ratio": 0.17}', '{"volume_metrics": {"Vol_3M": 972608, "Vol_Recent": 890930}, "moving_averages": {"MA_50": 15.509, "MA_200": 14.2}}', '{"asset_allocation": {"Bond_Weight": 0, "Equity_Weight": 0.9986}, "bond_characteristics": {"Avg_Maturity": null, "Duration_Yrs": null}}', '{"valuation_metrics": {"PB_Ratio": 1.85, "PE_Ratio": null, "PS_Ratio": 1.73, "PCF_Ratio": 11.73}}');
