INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (608, 'FEUL', 'ETF', 'United States', 'Alger Small Cap Growth Fund Cla', 'Alger Small Cap Growth Fund Class C', 'US Dollar', NULL, NULL, 'Alger', 'PCX', 'Europe Stock', 19718568, NULL, '2018-05-10', NULL, 'The investment seeks long-term capital appreciation. The fund normally invests at least 80% of its net assets, plus any borrowings for investment purposes, in equity securities of companies that, at the time of purchase of the securities, have total market capitalization between (1) the higher of (a) $5 billion or (b) the company in either the Russell 2000 Growth Index or the MSCI USA Small Cap Index with the highest capitalization, and (2) the company in either index with the lowest capitalization, at any time during the most recent 12-month period as reported by either index.', 0.01, 0.0044, 74, 30, 112.054, 108.065, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '{"Cap_Size": null, "Quote_Mode": "ETF", "Currency_Base": "US Dollar", "GeoZone_Class": "United States", "Strategy_Type": null}', '{"Net_Worth": 19718568, "Yield_Rate": null, "Expense_Net": 0.01, "Benchmark_Exp": 0.0044, "Turnover_Ratio": null}', '{"volume_metrics": {"Vol_3M": 74, "Vol_Recent": 30}, "moving_averages": {"MA_50": 112.054, "MA_200": 108.065}}', '{"asset_allocation": {"Bond_Weight": null, "Equity_Weight": null}, "bond_characteristics": {"Avg_Maturity": null, "Duration_Yrs": null}}', '{"valuation_metrics": {"PB_Ratio": null, "PE_Ratio": null, "PS_Ratio": null, "PCF_Ratio": null}}');
