INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (611, 'FEX', 'ETF', 'United States', 'AB Sustainable Global Thematic ', 'AB Sustainable Global Thematic Fund Class I', 'AmericanDollar', 'Blend', 'Large', 'AllianceBernstein', 'NGM', 'Large Blend', 1188681216, 0.0082, '2007-05-08', 1.04, 'The investment seeks long-term growth of capital. The fund pursues opportunistic growth by investing in a global universe of companies that are positively exposed to sustainable investment themes. The Adviser employs a combination of "top-down" and "bottom-up" investment processes with the goal of identifying securities of companies worldwide, fitting into sustainable investment themes. The Adviser identifies sustainable investment themes that are broadly consistent with achieving the United Nations Sustainable Development Goals.', 0.0059, 0.0036, 27064, 19400, 89.614, 85.728, 0.9997, 0, 3, 13.52, 20.03, 1.93, NULL, NULL, '{"Cap_Size": "Large", "Quote_Mode": "ETF", "Currency_Base": "AmericanDollar", "GeoZone_Class": "United States", "Strategy_Type": "Blend"}', '{"Net_Worth": 1188681216, "Yield_Rate": 0.0082, "Expense_Net": 0.0059, "Benchmark_Exp": 0.0036, "Turnover_Ratio": 1.04}', '{"volume_metrics": {"Vol_3M": 27064, "Vol_Recent": 19400}, "moving_averages": {"MA_50": 89.614, "MA_200": 85.728}}', '{"asset_allocation": {"Bond_Weight": 0, "Equity_Weight": 0.9997}, "bond_characteristics": {"Avg_Maturity": null, "Duration_Yrs": null}}', '{"valuation_metrics": {"PB_Ratio": 3, "PE_Ratio": 20.03, "PS_Ratio": 1.93, "PCF_Ratio": 13.52}}');
