INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (641, 'FLAU', 'ETF', 'USA', 'Invesco High Yield Fund Class R', 'Invesco High Yield Fund R5 Class', 'Usd', 'Blend', 'Large', 'Invesco', 'PCX', NULL, 25125126, 0.0196, '2017-11-02', 0.0698, 'The investment seeks total return through growth of capital and current income. The fund invests, under normal circumstances, at least 80% of its net assets (plus any borrowings for investment purposes) in debt securities that are determined to be below investment grade quality, and in derivatives and other instruments that have economic characteristics similar to such securities. It may invest in preferred stocks and convertible securities, which are securities that generally pay interest and may be converted into common stock. The fund may invest up to 25% of its net assets in foreign securities.', 0.0009, NULL, 2612, 3910, 30.341, 30.444, 0.9999, 0, 2.31, 12.02, 24.87, 2.72, NULL, NULL, '{"Cap_Size": "Large", "Quote_Mode": "ETF", "Currency_Base": "Usd", "GeoZone_Class": "USA", "Strategy_Type": "Blend"}', '{"Net_Worth": 25125126, "Yield_Rate": 0.0196, "Expense_Net": 0.0009, "Benchmark_Exp": null, "Turnover_Ratio": 0.0698}', '{"volume_metrics": {"Vol_3M": 2612, "Vol_Recent": 3910}, "moving_averages": {"MA_50": 30.341, "MA_200": 30.444}}', '{"asset_allocation": {"Bond_Weight": 0, "Equity_Weight": 0.9999}, "bond_characteristics": {"Avg_Maturity": null, "Duration_Yrs": null}}', '{"valuation_metrics": {"PB_Ratio": 2.31, "PE_Ratio": 24.87, "PS_Ratio": 2.72, "PCF_Ratio": 12.02}}');
INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (642, 'FLAX', 'ETF', 'USA', 'American Beacon AHL Managed Fut', 'American Beacon AHL Managed Futures Strategy Fund A Class', 'usd', 'Blend', 'Large', 'American Beacon', 'PCX', NULL, 35294876, 0.0148, '2018-02-06', 0.1164, 'The investment seeks capital growth. The fund seeks to achieve its investment objective by implementing a quantitative trading strategy and systematic investment process designed to capitalize on price trends in a broad range of global markets including stock indices, bonds and bond futures, currency and currency futures, and interest rates by utilizing derivative instruments. It invests primarily in derivatives, including futures, and forward contracts,foreign currency forward contracts, including non-deliverable forwards ("NDFs"), and non-U.S. currency futures contracts. It is non-diversified.', 0.0019, NULL, 1280, 1800, 27.101, 28.256, 0.9974, 0, 1.88, 11.32, 18.25, 1.36, NULL, NULL, '{"Cap_Size": "Large", "Quote_Mode": "ETF", "Currency_Base": "usd", "GeoZone_Class": "USA", "Strategy_Type": "Blend"}', '{"Net_Worth": 35294876, "Yield_Rate": 0.0148, "Expense_Net": 0.0019, "Benchmark_Exp": null, "Turnover_Ratio": 0.1164}', '{"volume_metrics": {"Vol_3M": 1280, "Vol_Recent": 1800}, "moving_averages": {"MA_50": 27.101, "MA_200": 28.256}}', '{"asset_allocation": {"Bond_Weight": 0, "Equity_Weight": 0.9974}, "bond_characteristics": {"Avg_Maturity": null, "Duration_Yrs": null}}', '{"valuation_metrics": {"PB_Ratio": 1.88, "PE_Ratio": 18.25, "PS_Ratio": 1.36, "PCF_Ratio": 11.32}}');
