INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (678, 'FLQM', 'ETF', 'UNITED_STATES', 'American Century International ', 'American Century International Bond Fund Y Class', 'usd', 'Blend', 'Medium', 'American Century Investments', 'BTS', 'Mid-Cap Blend', 44027132, 0.0103, '2017-04-26', 0.2502, 'The investment seeks total return. Under normal market conditions, the fund invests at least 80% of its net assets in bonds. It will invest primarily in non-dollar denominated debt securities issued by foreign governments and foreign companies. The fund will also invest in high-yield debt securities. It may invest in emerging market debt securities. The fund is non-diversified.', 0.003, 0.0047, 6420, 4320, 46.045, 44.051, 0.9995, 0, 4.58, 14.51, 23.84, 1.92, NULL, NULL, '{"Cap_Size": "Medium", "Quote_Mode": "ETF", "Currency_Base": "usd", "GeoZone_Class": "UNITED_STATES", "Strategy_Type": "Blend"}', '{"Net_Worth": 44027132, "Yield_Rate": 0.0103, "Expense_Net": 0.003, "Benchmark_Exp": 0.0047, "Turnover_Ratio": 0.2502}', '{"volume_metrics": {"Vol_3M": 6420, "Vol_Recent": 4320}, "moving_averages": {"MA_50": 46.045, "MA_200": 44.051}}', '{"asset_allocation": {"Bond_Weight": 0, "Equity_Weight": 0.9995}, "bond_characteristics": {"Avg_Maturity": null, "Duration_Yrs": null}}', '{"valuation_metrics": {"PB_Ratio": 4.58, "PE_Ratio": 23.84, "PS_Ratio": 1.92, "PCF_Ratio": 14.51}}');
INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (663, 'FLJP', 'ETF', 'U.S.', 'Inflation-Adjusted Bond Fund - ', 'American Century Inflation-Adjusted Bond Fund R6 Class', 'DOLLAR', 'Blend', 'Large', 'American Century Investments', 'PCX', NULL, 602296704, 0.0148, '2017-11-02', 0.0576, 'The investment seeks total return and inflation protection consistent with investment in inflation-indexed securities. Under normal market conditions, the fund invests at least 80% of its net assets in inflation-adjusted bonds. It also may invest in derivative instruments such as futures contracts and swap agreements (including, but not limited to, inflation swap agreements and credit default swap agreements), bank loans, securities backed by mortgages or other assets and collateralized debt obligations. The fund may invest in U.S. Treasury futures, inflation swap agreements and credit default swap agreements to manage duration, inflation and credit exposure.', 0.0009, NULL, 205890, 200580, 30.303, 30.336, 0.9983, 0, 1.4, 9.53, 20.67, 1.07, NULL, NULL, '{"Cap_Size": "Large", "Quote_Mode": "ETF", "Currency_Base": "DOLLAR", "GeoZone_Class": "U.S.", "Strategy_Type": "Blend"}', '{"Net_Worth": 602296704, "Yield_Rate": 0.0148, "Expense_Net": 0.0009, "Benchmark_Exp": null, "Turnover_Ratio": 0.0576}', '{"volume_metrics": {"Vol_3M": 205890, "Vol_Recent": 200580}, "moving_averages": {"MA_50": 30.303, "MA_200": 30.336}}', '{"asset_allocation": {"Bond_Weight": 0, "Equity_Weight": 0.9983}, "bond_characteristics": {"Avg_Maturity": null, "Duration_Yrs": null}}', '{"valuation_metrics": {"PB_Ratio": 1.4, "PE_Ratio": 20.67, "PS_Ratio": 1.07, "PCF_Ratio": 9.53}}');
