INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (664, 'FLKR', 'ETF', 'United States', 'Aberdeen Global Infrastructure ', 'Aberdeen Global Infrastructure Fund Class A', 'US$', 'Value', 'Large', 'Aberdeen', 'PCX', NULL, 75317560, 0.0093, '2017-11-02', 0.0865, 'The investment seeks capital appreciation; current income is a secondary objective. The fund normally invests at least 80% of its net assets (plus the amount of any borrowings for investment purposes) in the equity securities of U.S. and non-U.S. infrastructure-related issuers. It maintains no less than 40% of its net assets (plus the amount of any borrowings for investment purposes) in the securities of issuers located outside of the United States and will allocate its assets among issuers located in no fewer than three different countries, one of which may be the United States.', 0.0009, NULL, 21985, 12550, 28.293, 31.017, 0.9979, 0, 1.28, 7.51, 18.56, 0.89, NULL, NULL, '{"Cap_Size": "Large", "Quote_Mode": "ETF", "Currency_Base": "US$", "GeoZone_Class": "United States", "Strategy_Type": "Value"}', '{"Net_Worth": 75317560, "Yield_Rate": 0.0093, "Expense_Net": 0.0009, "Benchmark_Exp": null, "Turnover_Ratio": 0.0865}', '{"volume_metrics": {"Vol_3M": 21985, "Vol_Recent": 12550}, "moving_averages": {"MA_50": 28.293, "MA_200": 31.017}}', '{"asset_allocation": {"Bond_Weight": 0, "Equity_Weight": 0.9979}, "bond_characteristics": {"Avg_Maturity": null, "Duration_Yrs": null}}', '{"valuation_metrics": {"PB_Ratio": 1.28, "PE_Ratio": 18.56, "PS_Ratio": 0.89, "PCF_Ratio": 7.51}}');
INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (665, 'FLLA', 'ETF', 'U.S.', 'Aberdeen Realty Income and Grow', 'Aberdeen Realty Income & Growth Fund Class A', 'usd', 'Blend', 'Large', 'Aberdeen', 'PCX', NULL, 5001382, 0.02, '2018-10-09', 0.1021, 'The investment seeks a high level of current income; capital appreciation is a secondary objective. The fund invests 80% of its net assets (plus the amount of any borrowings for investment purposes) in the securities of issuers which (i) are principally engaged in the real estate industry, (ii) are principally engaged in real estate financing or (iii) control real estate assets with an aggregate estimated value equal to no less than 50% of such issuer''s assets. It may invest up to 35% of its net assets in foreign securities. The fund may invest in companies of any market capitalization. It is non-diversified.', 0.0019, NULL, 1430, 920, 21.43, 23.357, 0.9909, 0, 1.97, 6.14, 19.25, 1.49, NULL, NULL, '{"Cap_Size": "Large", "Quote_Mode": "ETF", "Currency_Base": "usd", "GeoZone_Class": "U.S.", "Strategy_Type": "Blend"}', '{"Net_Worth": 5001382, "Yield_Rate": 0.02, "Expense_Net": 0.0019, "Benchmark_Exp": null, "Turnover_Ratio": 0.1021}', '{"volume_metrics": {"Vol_3M": 1430, "Vol_Recent": 920}, "moving_averages": {"MA_50": 21.43, "MA_200": 23.357}}', '{"asset_allocation": {"Bond_Weight": 0, "Equity_Weight": 0.9909}, "bond_characteristics": {"Avg_Maturity": null, "Duration_Yrs": null}}', '{"valuation_metrics": {"PB_Ratio": 1.97, "PE_Ratio": 19.25, "PS_Ratio": 1.49, "PCF_Ratio": 6.14}}');
