INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (671, 'FLN', 'ETF', 'UNITED_STATES', 'American Funds Int Bond Fd of A', 'American Funds Intermediate Bond Fund of America Class A', 'DOLLAR', 'Value', 'Large', 'American Funds', 'NGM', 'Latin America Stock', 11135348, 0.0151, '2011-04-18', 0.34, 'The investment seeks current income consistent with the maturity and quality standards and preservation of capital. The fund maintains a portfolio of bonds, other debt securities and money market instruments having a dollar-weighted average effective maturity of no less than three years and no greater than five years under normal market conditions. It invests primarily in bonds and other debt securities with quality ratings of A- or better or A3 or better or unrated but determined to be of equivalent quality by the fund''s investment adviser. The fund primarily invests in debt securities denominated in U.S. dollars.', 0.008, 0.0066, 2219, 1110, 17.453, 18.782, NULL, NULL, 1.66, 6.09, 11.12, 1.11, NULL, NULL, '{"Cap_Size": "Large", "Quote_Mode": "ETF", "Currency_Base": "DOLLAR", "GeoZone_Class": "UNITED_STATES", "Strategy_Type": "Value"}', '{"Net_Worth": 11135348, "Yield_Rate": 0.0151, "Expense_Net": 0.008, "Benchmark_Exp": 0.0066, "Turnover_Ratio": 0.34}', '{"volume_metrics": {"Vol_3M": 2219, "Vol_Recent": 1110}, "moving_averages": {"MA_50": 17.453, "MA_200": 18.782}}', '{"asset_allocation": {"Bond_Weight": null, "Equity_Weight": null}, "bond_characteristics": {"Avg_Maturity": null, "Duration_Yrs": null}}', '{"valuation_metrics": {"PB_Ratio": 1.66, "PE_Ratio": 11.12, "PS_