INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (679, 'FLQS', 'ETF', 'us', 'Sanford C. Bernstein Fund, Inc.', 'AB Intermediate California Municipal Portfolio Class A', 'Usd', 'Blend', 'Small', 'AllianceBernstein', 'BTS', 'Small Blend', 19092720, 0.0099, '2017-04-26', 0.3477, 'The investment seeks to provide safety of principal and maximize total return after taking account of federal and state taxes for California residents. The fund invests at least 80% of its net assets in a portfolio of municipal securities issued by the State of California or its political subdivisions, or otherwise exempt from California state income tax. It seeks to maintain an effective duration of three and one-half years to seven years. The fund may invest up to 20% of its total assets in fixed-income securities rated BB or B by national rating agencies, which are not investment-grade (commonly known as "junk bonds"). It is non-diversified.', 0.0035, 0.004, 1656, 1210, 39.712, 38.142, 0.9996, 0, 2.76, 10.42, 18.83, 1.29, NULL, NULL, '{"Cap_Size": "Small", "Quote_Mode": "ETF", "Currency_Base": "Usd", "GeoZone_Class": "us", "Strategy_Type": "Blend"}', '{"Net_Worth": 19092720, "Yield_Rate": 0.0099, "Expense_Net": 0.0035, "Benchmark_Exp": 0.004, "Turnover_Ratio": 0.3477}', '{"volume_metrics": {"Vol_3M": 1656, "Vol_Recent": 1210}, "moving_averages": {"MA_50": 39.712, "MA_200": 38.142}}', '{"asset_allocation": {"Bond_Weight": 0, "Equity_Weight": 0.9996}, "bond_characteristics": {"Avg_Maturity": null, "Duration_Yrs": null}}', '{"valuation_metrics": {"PB_Ratio": 2.76, "PE_Ratio": 18.83, "PS_Ratio": 1.29, "PCF_Ratio": 10.42}}');
