INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (691, 'FLV', 'ETF', 'America', 'Invesco International Growth Fu', 'Invesco International Growth Fund Class C', 'Dollar', 'Value', 'Large', 'Invesco', 'BTS', 'Large Value', 248814592, 0.0158, '2020-03-31', 0.73, 'The investment seeks long-term growth of capital. The fund invests primarily in equity securities and depositary receipts of foreign issuers. It will provide exposure to investments that are economically tied to at least three different countries outside of the U.S. The fund may also invest up to 1.25 times the amount of the exposure to emerging markets countries in the MSCI All Country World ex-U.S. Growth Index. The fund invests primarily in the securities of large-capitalization issuers and may invest a significant amount of its net assets in the securities of mid-capitalization issuers.', 0.0042, 0.0034, 17022, 8370, 60.765, 60.174, 0.9974, 0, 2.51, 13.76, 18.62, 2.28, NULL, NULL, '{"Cap_Size": "Large", "Quote_Mode": "ETF", "Currency_Base": "Dollar", "GeoZone_Class": "America", "Strategy_Type": "Value"}', '{"Net_Worth": 248814592, "Yield_Rate": 0.0158, "Expense_Net": 0.0042, "Benchmark_Exp": 0.0034, "Turnover_Ratio": 0.73}', '{"volume_metrics": {"Vol_3M": 17022, "Vol_Recent": 8370}, "moving_averages": {"MA_50": 60.765, "MA_200": 60.174}}', '{"asset_allocation": {"Bond_Weight": 0, "Equity_Weight": 0.9974}, "bond_characteristics": {"Avg_Maturity": null, "Duration_Yrs": null}}', '{"valuation_metrics": {"PB_Ratio": 2.51, "PE_Ratio": 18.62, "PS_Ratio": 2.28, "PCF_Ratio": 13.76}}');
