INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (699, 'FMF', 'ETF', 'U.S.A.', 'Alger Portfolios - Alger Income', 'Alger Growth & Income Portfolio I-2', 'AmericanDollar', NULL, NULL, 'Alger', 'PCX', 'Managed Futures', 58171064, 0.0002, '2013-08-01', NULL, 'The investment seeks to provide capital appreciation and current income. The fund invests primarily in equity securities such as common or preferred stocks which the advisor believes offer opportunities for capital appreciation and which also pay dividends. It is a fundamental policy of the fund to invest at least 65% of its total assets in dividend paying equity securities. The fund may invest up to 35% of its total assets in equity securities that do not pay dividends or in money market instruments and repurchase agreements.', 0.0095, 0.0087, 4711, 3790, 47.735, 47.974, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '{"Cap_Size": null, "Quote_Mode": "ETF", "Currency_Base": "AmericanDollar", "GeoZone_Class": "U.S.A.", "Strategy_Type": null}', '{"Net_Worth": 58171064, "Yield_Rate": 0.0002, "Expense_Net": 0.0095, "Benchmark_Exp": 0.0087, "Turnover_Ratio": null}', '{"volume_metrics": {"Vol_3M": 4711, "Vol_Recent": 3790}, "moving_averages": {"MA_50": 47.735, "MA_200": 47.974}}', '{"asset_allocation": {"Bond_Weight": null, "Equity_Weight": null}, "bond_characteristics": {"Avg_Maturity": null, "Duration_Yrs": null}}', '{"valuation_metrics": {"PB_Ratio": null, "PE_Ratio": null, "PS_Ratio": null, "PCF_Ratio": null}}');
INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (700, 'FMHI', 'ETF', 'US', 'AllianzGI Income Class and Grow', 'Virtus AllianzGl Income & Growth Fund Class P', 'Dollar', 'Blend', 'Small', 'Virtus', 'NGM', NULL, 225449248, 0.0301, '2017-11-02', 0.89, 'The investment seeks total return comprised of current income, current gains and capital appreciation. The fund seeks to achieve its objective by investing primarily in a combination of common stocks and other equity securities, debt securities and convertible securities. The allocation of the fund''s investments across asset classes will vary substantially from time to time. The fund''s investments in each asset class are based upon the portfolio managers'' assessment of economic conditions and market factors, including equity price levels, interest rate levels and their anticipated direction.', 0.0055, NULL, 46737, 45390, 55.78, 55.74, NULL, NULL, NULL, NULL, NULL, NULL, 17.63, 6.67, '{"Cap_Size": "Small", "Quote_Mode": "ETF", "Currency_Base": "Dollar", "GeoZone_Class": "US", "Strategy_Type": "Blend"}', '{"Net_Worth": 225449248, "Yield_Rate": 0.0301, "Expense_Net": 0.0055, "Benchmark_Exp": null, "Turnover_Ratio": 0.89}', '{"volume_metrics": {"Vol_3M": 46737, "Vol_Recent": 45390}, "moving_averages": {"MA_50": 55.78, "MA_200": 55.74}}', '{"asset_allocation": {"Bond_Weight": null, "Equity_Weight": null}, "bond_characteristics": {"Avg_Maturity": 17.63, "Duration_Yrs": 6.67}}', '{"valuation_metrics": {"PB_Ratio": null, "PE_Ratio": null, "PS_Ratio": null, "PCF_Ratio": null}}');
INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (701, 'FMIL', 'ETF', 'usa', 'Aberdeen Realty Income and Grow', 'Aberdeen Realty Income & Growth Fund Institutional Class', 'US Dollar', 'Value', 'Large', 'Aberdeen', 'BTS', 'Large Blend', 64246880, 0.0128, '2020-06-02', 0.1, 'The investment seeks a high level of current income; capital appreciation is a secondary objective. The fund invests 80% of its net assets (plus the amount of any borrowings for investment purposes) in the securities of issuers which (i) are principally engaged in the real estate industry, (ii) are principally engaged in real estate financing or (iii) control real estate assets with an aggregate estimated value equal to no less than 50% of such issuer''s assets. It may invest up to 35% of its net assets in foreign securities. The fund may invest in companies of any market capitalization. It is non-diversified.', 0.0059, 0.0036, 12898, 15110, 29.571, 28.928, 1, 0, 2.42, 11.4, 20.42, 1.69, NULL, NULL, '{"Cap_Size": "Large", "Quote_Mode": "ETF", "Currency_Base": "US Dollar", "GeoZone_Class": "usa", "Strategy_Type": "Value"}', '{"Net_Worth": 64246880, "Yield_Rate": 0.0128, "Expense_Net": 0.0059, "Benchmark_Exp": 0.0036, "Turnover_Ratio": 0.1}', '{"volume_metrics": {"Vol_3M": 12898, "Vol_Recent": 15110}, "moving_averages": {"MA_50": 29.571, "MA_200": 28.928}}', '{"asset_allocation": {"Bond_Weight": 0, "Equity_Weight": 1}, "bond_characteristics": {"Avg_Maturity": null, "Duration_Yrs": null}}', '{"valuation_metrics": {"PB_Ratio": 2.42, "PE_Ratio": 20.42, "PS_Ratio": 1.69, "PCF_Ratio": 11.4}}');
INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (702, 'FMNY', 'ETF', 'US', 'Horizon Active Income Fund - Ad', 'Horizon Active Income Fund Class A', 'US$', NULL, NULL, 'Horizon Investments', 'PCX', NULL, NULL, NULL, '2021-05-12', NULL, 'The investment seeks income. The fund seeks to achieve the fund''s investment objective by allocating assets across various sectors of the global securities markets. The manager executes this strategy by investing in exchange-traded funds ("ETFs"). The fund will invest primarily in U.S. Dollar denominated securities, but may also invest a portion of its assets in non-U.S. Dollar denominated securities.', 0.005, NULL, 5885, 2340, 30.008, 30.227, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '{"Cap_Size": null, "Quote_Mode": "ETF", "Currency_Base": "US$", "GeoZone_Class": "US", "Strategy_Type": null}', '{"Net_Worth": null, "Yield_Rate": null, "Expense_Net": 0.005, "Benchmark_Exp": null, "Turnover_Ratio": null}', '{"volume_metrics": {"Vol_3M": 5885, "Vol_Recent": 2340}, "moving_averages": {"MA_50": 30.008, "MA_200": 30.227}}', '{"asset_allocation": {"Bond_Weight": null, "Equity_Weight": null}, "bond_characteristics": {"Avg_Maturity": null, "Duration_Yrs": null}}', '{"valuation_metrics": {"PB_Ratio": null, "PE_Ratio": null, "PS_Ratio": null, "PCF_Ratio": null}}');
INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (703, 'FNCL', 'ETF', 'us', 'Invesco International Growth Fu', 'Invesco International Growth Fund Class A', 'usd', 'Value', 'Large', 'Invesco', 'PCX', 'Financial', 1762491904, 0.0169, '2013-10-21', 0.06, 'The investment seeks long-term growth of capital. The fund invests primarily in equity securities and depositary receipts of foreign issuers. It will provide exposure to investments that are economically tied to at least three different countries outside of the U.S. The fund may also invest up to 1.25 times the amount of the exposure to emerging markets countries in the MSCI All Country World ex-U.S. Growth Index. The fund invests primarily in the securities of large-capitalization issuers and may invest a significant amount of its net assets in the securities of mid-capitalization issuers.', 0.00084, 0.0038, 203417, 245860, 56.537, 53.095, 0.9974, 0, 1.62, NULL, 12.89, 2.24, NULL, NULL, '{"Cap_Size": "Large", "Quote_Mode": "ETF", "Currency_Base": "usd", "GeoZone_Class": "us", "Strategy_Type": "Value"}', '{"Net_Worth": 1762491904, "Yield_Rate": 0.0169, "Expense_Net": 0.00084, "Benchmark_Exp": 0.0038, "Turnover_Ratio": 0.06}', '{"volume_metrics": {"Vol_3M": 203417, "Vol_Recent": 245860}, "moving_averages": {"MA_50": 56.537, "MA_200": 53.095}}', '{"asset_allocation": {"Bond_Weight": 0, "Equity_Weight": 0.9974}, "bond_characteristics": {"Avg_Maturity": null, "Duration_Yrs": null}}', '{"valuation_metrics": {"PB_Ratio": 1.62, "PE_Ratio": 12.89, "PS_Ratio": 2.24, "PCF_Ratio": null}}');
