INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (704, 'FNDA', 'ETF', 'United States', 'Timber Point Alternative Income', 'Timber Point Alternative Income Fund Institutional Class Shares', 'DOLLAR', 'Value', 'Small', 'Crow Point', 'PCX', 'Small Blend', 4640305152, 0.0093, '2013-08-15', 0.24, 'The investment seeks to provide shareholders with above-average total returns over a complete market cycle primarily through capital appreciation and income generation. The fund seeks to achieve its investment objective under normal market conditions by allocating assets among credit-related instruments such as corporate bonds, municipal bonds, mortgage and asset-backed securities, and floating-rate securities. It may invest without limitation in investments tied economically to any country in the world, including emerging market countries.', 0.0025, 0.004, 157990, 205340, 55.163, 53.281, 0.9992, 0, 2.14, 9.08, 18.01, 1.25, NULL, NULL, '{"Cap_Size": "Small", "Quote_Mode": "ETF", "Currency_Base": "DOLLAR", "GeoZone_Class": "United States", "Strategy_Type": "Value"}', '{"Net_Worth": 4640305152, "Yield_Rate": 0.0093, "Expense_Net": 0.0025, "Benchmark_Exp": 0.004, "Turnover_Ratio": 0.24}', '{"volume_metrics": {"Vol_3M": 157990, "Vol_Recent": 205340}, "moving_averages": {"MA_50": 55.163, "MA_200": 53.281}}', '{"asset_allocation": {"Bond_Weight": 0, "Equity_Weight": 0.9992}, "bond_characteristics": {"Avg_Maturity": null, "Duration_Yrs": null}}', '{"valuation_metrics": {"PB_Ratio": 2.14, "PE_Ratio": 18.01, "PS_Ratio": 1.25, "PCF_Ratio": 9.08}}');
INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (705, 'FNDB', 'ETF', 'U.S.A.', 'AllianzGI International Small-C', 'Virtus AllianzGI International Small-Cap Fund Class R6', 'USD', 'Value', 'Large', 'Virtus', 'PCX', 'Large Value', 369908320, 0.0171, '2013-08-15', 0.14, 'The investment seeks maximum long-term capital appreciation. The fund seeks to achieve its objective by normally investing at least 80% of its net assets (plus borrowings made for investment purposes) in companies with smaller market capitalizations. It currently defines companies with smaller market capitalizations as those with market capitalizations comparable to companies included in the MSCI World Small-Cap Index. The advisor expects to maintain a weighted-average market capitalization between 50% and 200% of the weighted-average market capitalization of the securities in the MSCI World Small-Cap Index.', 0.0025, 0.0034, 17201, 23090, 56.073, 54.153, 0.9993, 0, 2.56, 11.31, 19.68, 1.42, NULL, NULL, '{"Cap_Size": "Large", "Quote_Mode": "ETF", "Currency_Base": "USD", "GeoZone_Class": "U.S.A.", "Strategy_Type": "Value"}', '{"Net_Worth": 369908320, "Yield_Rate": 0.0171, "Expense_Net": 0.0025, "Benchmark_Exp": 0.0034, "Turnover_Ratio": 0.14}', '{"volume_metrics": {"Vol_3M": 17201, "Vol_Recent": 23090}, "moving_averages": {"MA_50": 56.073, "MA_200": 54.153}}', '{"asset_allocation": {"Bond_Weight": 0, "Equity_Weight": 0.9993}, "bond_characteristics": {"Avg_Maturity": null, "Duration_Yrs": null}}', '{"valuation_metrics": {"PB_Ratio": 2.56, "PE_Ratio": 19.68, "PS_Ratio": 1.42, "PCF_Ratio": 11.31}}');
INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (706, 'FNDC', 'ETF', 'USA', 'Invesco International Growth Fu', 'Invesco International Growth Fund Class Y', 'US_DOLLAR', 'Value', 'Medium', 'Invesco', 'PCX', 'Foreign Small/Mid Value', 2675718656, 0.0178, '2013-08-15', 0.24, 'The investment seeks long-term growth of capital. The fund invests primarily in equity securities and depositary receipts of foreign issuers. It will provide exposure to investments that are economically tied to at least three different countries outside of the U.S. The fund may also invest up to 1.25 times the amount of the exposure to emerging markets countries in the MSCI All Country World ex-U.S. Growth Index. The fund invests primarily in the securities of large-capitalization issuers and may invest a significant amount of its net assets in the securities of mid-capitalization issuers.', 0.0039, 0.0051, 177043, 328180, 38.919, 38.993, 0.9911, 0.0002, 1.2, 6.92, 15.37, 0.69, NULL, NULL, '{"Cap_Size": "Medium", "Quote_Mode": "ETF", "Currency_Base": "US_DOLLAR", "GeoZone_Class": "USA", "Strategy_Type": "Value"}', '{"Net_Worth": 2675718656, "Yield_Rate": 0.0178, "Expense_Net": 0.0039, "Benchmark_Exp": 0.0051, "Turnover_Ratio": 0.24}', '{"volume_metrics": {"Vol_3M": 177043, "Vol_Recent": 328180}, "moving_averages": {"MA_50": 38.919, "MA_200": 38.993}}', '{"asset_allocation": {"Bond_Weight": 0.0002, "Equity_Weight": 0.9911}, "bond_characteristics": {"Avg_Maturity": null, "Duration_Yrs": null}}', '{"valuation_metrics": {"PB_Ratio": 1.2, "PE_Ratio": 15.37, "PS_Ratio": 0.69, "PCF_Ratio": 6.92}}');
INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (707, 'FNDE', 'ETF', 'U.S.', 'American Beacon International E', 'American Beacon International Equity Fund Class C', 'usd', 'Value', 'Large', 'American Beacon', 'PCX', 'Diversified Emerging Mkts', 4752213504, 0.0233, '2013-08-15', 0.25, 'The investment seeks long-term capital appreciation. The fund normally invests at least 80% of its net assets (plus the amount of any borrowings for investment purposes) in common stocks and securities convertible into common stocks (collectively, "stocks") of issuers based in at least three different countries located outside the United States. It primarily invests in countries comprising the MSCI EAFE Index©. The MSCI EAFE Index is designed to represent the performance of large- and mid-capitalization securities across 21 developed markets countries, including countries in Europe, Australasia and the Far East, and excluding the U.S. and Canada.', 0.0039, 0.0056, 810166, 1.10505e+06, 32.444, 31.791, NULL, NULL, 1.02, 4.91, 10.12, 0.71, NULL, NULL, '{"Cap_Size": "Large", "Quote_Mode": "ETF", "Currency_Base": "usd", "GeoZone_Class": "U.S.", "Strategy_Type": "Value"}', '{"Net_Worth": 4752213504, "Yield_Rate": 0.0233, "Expense_Net": 0.0039, "Benchmark_Exp": 0.0056, "Turnover_Ratio": 0.25}', '{"volume_metrics": {"Vol_3M": 810166, "Vol_Recent": 1105050}, "moving_averages": {"MA_50": 32.444, "MA_200": 31.791}}', '{"asset_allocation": {"Bond_Weight": null, "Equity_Weight": null}, "bond_characteristics": {"Avg_Maturity": null, "Duration_Yrs": null}}', '{"valuation_metrics": {"PB_Ratio": 1.02, "PE_Ratio": 10.12, "PS_Ratio": 0.71, "PCF_Ratio": 4.91}}');
INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (708, 'FNDF', 'ETF', 'us', NULL, 'Cavanal Hill Hedged Income Fund Institutional', 'US$', 'Value', 'Large', 'Cavanal Hill funds', 'PCX', 'Foreign Large Value', 6748741120, 0.0213, '2013-08-15', 0.15, 'The investment seeks current income with the potential for long-term capital appreciation with less volatility than the broad equity market. The fund invests primarily in dividend paying equity securities, with at least 80% of its net assets in income generating equity securities and equity-related instruments traded on U.S. exchanges. The advisor includes common stocks and securities convertible into common stocks of companies with any market capitalization and sponsored or unsponsored American Depositary Receipts (ADRs). The fund is non-diversified.', 0.0025, 0.0046, 647006, 950120, 33.325, 33.166, 0.9974, 0, 1.18, 6.2, 15.74, 0.84, NULL, NULL, '{"Cap_Size": "Large", "Quote_Mode": "ETF", "Currency_Base": "US$", "GeoZone_Class": "us", "Strategy_Type": "Value"}', '{"Net_Worth": 6748741120, "Yield_Rate": 0.0213, "Expense_Net": 0.0025, "Benchmark_Exp": 0.0046, "Turnover_Ratio": 0.15}', '{"volume_metrics": {"Vol_3M": 647006, "Vol_Recent": 950120}, "moving_averages": {"MA_50": 33.325, "MA_200": 33.166}}', '{"asset_allocation": {"Bond_Weight": 0, "Equity_Weight": 0.9974}, "bond_characteristics": {"Avg_Maturity": null, "Duration_Yrs": null}}', '{"valuation_metrics": {"PB_Ratio": 1.18, "PE_Ratio": 15.74, "PS_Ratio": 0.84, "PCF_Ratio": 6.2}}');
INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (709, 'FNDX', 'ETF', 'US', 'Sanford C. Bernstein Fund, Inc.', 'AB Intermediate Diversified Municipal Portfolio Class C', 'US_DOLLAR', 'Value', 'Large', 'AllianceBernstein', 'PCX', 'Large Value', 7162112512, 0.0181, '2013-08-15', 0.13, 'The investment seeks to provide safety of principal and maximize total return after taking account of federal taxes. The fund invests at least 80% of its net assets in municipal securities. It invests at least 80% of its total assets in municipal securities rated A, or better by national rating agencies, and comparably rated municipal notes. The fund may invest up to 20% of its total assets in fixed-income securities rated BB or B by national rating agencies, which are not investment-grade (commonly known as "junk bonds").', 0.0025, 0.0034, 515004, 349390, 56.478, 54.533, 0.9989, 0, 2.61, 11.56, 19.82, 1.44, NULL, NULL, '{"Cap_Size": "Large", "Quote_Mode": "ETF", "Currency_Base": "US_DOLLAR", "GeoZone_Class": "US", "Strategy_Type": "Value"}', '{"Net_Worth": 7162112512, "Yield_Rate": 0.0181, "Expense_Net": 0.0025, "Benchmark_Exp": 0.0034, "Turnover_Ratio": 0.13}', '{"volume_metrics": {"Vol_3M": 515004, "Vol_Recent": 349390}, "moving_averages": {"MA_50": 56.478, "MA_200": 54.533}}', '{"asset_allocation": {"Bond_Weight": 0, "Equity_Weight": 0.9989}, "bond_characteristics": {"Avg_Maturity": null, "Duration_Yrs": null}}', '{"valuation_metrics": {"PB_Ratio": 2.61, "PE_Ratio": 19.82, "PS_Ratio": 1.44, "PCF_Ratio": 11.56}}');
INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (710, 'FNGD', 'ETF', 'America', 'Horizon Active Income Fund - In', 'Horizon Active Income Fund Investor Class', 'AmericanDollar', 'Growth', 'Large', 'Horizon Investments', 'PCX', 'Trading--Inverse Equity', 43901048, NULL, '2018-01-22', NULL, 'The investment seeks income. The fund seeks to achieve the fund''s investment objective by allocating assets across various sectors of the global securities markets. The manager executes this strategy by investing in exchange-traded funds ("ETFs"). The fund will invest primarily in U.S. Dollar denominated securities, but may also invest a portion of its assets in non-U.S. Dollar denominated securities.', 0.0095, 0.0092, 8396082, 8.29454e+06, 2.05, 2.766, 1, 0, 7.27, 26.6, 29.23, 0.45, NULL, NULL, '{"Cap_Size": "Large", "Quote_Mode": "ETF", "Currency_Base": "AmericanDollar", "GeoZone_Class": "America", "Strategy_Type": "Growth"}', '{"Net_Worth": 43901048, "Yield_Rate": null, "Expense_Net": 0.0095, "Benchmark_Exp": 0.0092, "Turnover_Ratio": null}', '{"volume_metrics": {"Vol_3M": 8396082, "Vol_Recent": 8294540}, "moving_averages": {"MA_50": 2.05, "MA_200": 2.766}}', '{"asset_allocation": {"Bond_Weight": 0, "Equity_Weight": 1}, "bond_characteristics": {"Avg_Maturity": null, "Duration_Yrs": null}}', '{"valuation_metrics": {"PB_Ratio": 7.27, "PE_Ratio": 29.23, "PS_Ratio": 0.45, "PCF_Ratio": 26.6}}');
INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (711, 'FNGS', 'ETF', 'America', 'AQR International Momentum Styl', 'AQR International Momentum Style Fund Class I', 'Dollar', 'Growth', 'Large', 'AQR Funds', 'PCX', 'Technology', 76346592, NULL, '2019-11-12', NULL, 'The investment seeks long-term capital appreciation. The fund pursues a momentum investment style by investing primarily in equity or equity-related securities (including, but not limited to, exchange-traded funds, equity index futures, equity index swaps, depositary receipts and real estate investment trusts or securities with similar characteristics) of non-U.S. companies that the Adviser determines to have positive momentum. The Adviser considers a security to have positive momentum primarily if it has outperformed other securities on a relative basis over a recent time period. The fund invests significantly in common stocks.', 0.0058, 0.0053, 24519, 19430, 32.924, 30.864, 1, 0, 7.27, 26.6, 29.23, 0.45, NULL, NULL, '{"Cap_Size": "Large", "Quote_Mode": "ETF", "Currency_Base": "Dollar", "GeoZone_Class": "America", "Strategy_Type": "Growth"}', '{"Net_Worth": 76346592, "Yield_Rate": null, "Expense_Net": 0.0058, "Benchmark_Exp": 0.0053, "Turnover_Ratio": null}', '{"volume_metrics": {"Vol_3M": 24519, "Vol_Recent": 19430}, "moving_averages": {"MA_50": 32.924, "MA_200": 30.864}}', '{"asset_allocation": {"Bond_Weight": 0, "Equity_Weight": 1}, "bond_characteristics": {"Avg_Maturity": null, "Duration_Yrs": null}}', '{"valuation_metrics": {"PB_Ratio": 7.27, "PE_Ratio": 29.23, "PS_Ratio": 0.45, "PCF_Ratio": 26.6}}');
INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (712, 'FNGU', 'ETF', 'U.S.A.', 'Inflation-Adjusted Bond Fund - ', 'American Century Inflation-Adjusted Bond Fund G Class', 'US Dollar', 'Growth', 'Large', 'American Century Investments', 'PCX', 'Trading--Leveraged Equity', 1987731328, NULL, '2018-01-22', NULL, 'The investment seeks total return and inflation protection consistent with investment in inflation-indexed securities. Under normal market conditions, the fund invests at least 80% of its net assets in inflation-adjusted bonds. It also may invest in derivative instruments such as futures contracts and swap agreements (including, but not limited to, inflation swap agreements and credit default swap agreements), bank loans, securities backed by mortgages or other assets and collateralized debt obligations. The fund may invest in U.S. Treasury futures, inflation swap agreements and credit default swap agreements to manage duration, inflation and credit exposure.', 0.0095, 0.009, 2188082, 1.85373e+06, 41.097, 35.24, 1, 0, 7.27, 26.6, 29.23, 0.45, NULL, NULL, '{"Cap_Size": "Large", "Quote_Mode": "ETF", "Currency_Base": "US Dollar", "GeoZone_Class": "U.S.A.", "Strategy_Type": "Growth"}', '{"Net_Worth": 1987731328, "Yield_Rate": null, "Expense_Net": 0.0095, "Benchmark_Exp": 0.009, "Turnover_Ratio": null}', '{"volume_metrics": {"Vol_3M": 2188082, "Vol_Recent": 1853730}, "moving_averages": {"MA_50": 41.097, "MA_200": 35.24}}', '{"asset_allocation": {"Bond_Weight": 0, "Equity_Weight": 1}, "bond_characteristics": {"Avg_Maturity": null, "Duration_Yrs": null}}', '{"valuation_metrics": {"PB_Ratio": 7.27, "PE_Ratio": 29.23, "PS_Ratio": 0.45, "PCF_Ratio": 26.6}}');
