INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (716, 'FNX', 'ETF', 'USA', 'Columbia Income Opportunities F', 'Columbia Income Opportunities Fund Class A', 'Dollar', 'Blend', 'Medium', 'Columbia Threadneedle', 'NGM', 'Mid-Cap Blend', 1034784704, 0.0078, '2007-05-08', 1.15, 'The investment seeks a high total return through current income and capital appreciation. Under normal market conditions, the fund''s assets are invested primarily in income-producing debt securities, with an emphasis on the higher rated segment of the high-yield (junk bond) market. These income-producing debt instruments include corporate debt securities as well as bank loans. The fund will purchase only debt instruments rated B or above, or if unrated, determined to be of comparable quality. It may invest in debt instruments of any maturity and does not seek to maintain a particular dollar-weighted average maturity.', 0.006, 0.0047, 29970, 21370, 102.624, 98.932, 0.9997, 0, 2.48, 10.78, 16.81, 1.51, NULL, NULL, '{"Cap_Size": "Medium", "Quote_Mode": "ETF", "Currency_Base": "Dollar", "GeoZone_Class": "USA", "Strategy_Type": "Blend"}', '{"Net_Worth": 1034784704, "Yield_Rate": 0.0078, "Expense_Net": 0.006, "Benchmark_Exp": 0.0047, "Turnover_Ratio": 1.15}', '{"volume_metrics": {"Vol_3M": 29970, "Vol_Recent": 21370}, "moving_averages": {"MA_50": 102.624, "MA_200": 98.932}}', '{"asset_allocation": {"Bond_Weight": 0, "Equity_Weight": 0.9997}, "bond_characteristics": {"Avg_Maturity": null, "Duration_Yrs": null}}', '{"valuation_metrics": {"PB_Ratio": 2.48, "PE_Ratio": 16.81, "PS_Ratio": 1.51, "PCF_Ratio": 10.78}}');
