INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (720, 'FORH', 'ETF', 'us', 'Cavanal Hill Opportunistic Fd I', 'Cavanal Hill Opportunistic Fund Institutional', 'DOLLAR', 'Blend', 'Medium', 'Cavanal Hill funds', 'PCX', NULL, 17700930, NULL, '2021-04-29', NULL, 'The investment seeks positive investment returns. The fund invests in a wide range of financial instruments, market sectors and asset classes in the U.S. and foreign markets. It may invest in long and short positions in equity securities of issuers of any market capitalization. The fund may invest in fixed income securities of any credit quality and maturity, including fixed income securities that are not rated or rated below investment grade by a nationally recognized statistical rating organization (commonly known as "junk bonds").', 0.012, NULL, 725, 210, 24.67, 24.99, 1, 0, 1.58, 13, 16.85, 1.95, NULL, NULL, '{"Cap_Size": "Medium", "Quote_Mode": "ETF", "Currency_Base": "DOLLAR", "GeoZone_Class": "us", "Strategy_Type": "Blend"}', '{"Net_Worth": 17700930, "Yield_Rate": null, "Expense_Net": 0.012, "Benchmark_Exp": null, "Turnover_Ratio": null}', '{"volume_metrics": {"Vol_3M": 725, "Vol_Recent": 210}, "moving_averages": {"MA_50": 24.67, "MA_200": 24.99}}', '{"asset_allocation": {"Bond_Weight": 0, "Equity_Weight": 1}, "bond_characteristics": {"Avg_Maturity": null, "Duration_Yrs": null}}', '{"valuation_metrics": {"PB_Ratio": 1.58, "PE_Ratio": 16.85, "PS_Ratio": 1.95, "PCF_Ratio": 13}}');
INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (722, 'FPE', 'ETF', 'U.S.', 'American Century International ', 'American Century International Bond Fund C Class', 'Usd', NULL, NULL, 'American Century Investments', 'PCX', 'Preferred Stock', 7034221056, 0.0452, '2013-02-11', 0.43, 'The investment seeks total return. Under normal market conditions, the fund invests at least 80% of its net assets in bonds. It will invest primarily in non-dollar denominated debt securities issued by foreign governments and foreign companies. The fund will also invest in high-yield debt securities. It may invest in emerging market debt securities. The fund is non-diversified.', 0.0085, 0.0055, 1630733, 1.77806e+06, 20.447, 20.451, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 4.05, '{"Cap_Size": null, "Quote_Mode": "ETF", "Currency_Base": "Usd", "GeoZone_Class": "U.S.", "Strategy_Type": null}', '{"Net_Worth": 7034221056, "Yield_Rate": 0.0452, "Expense_Net": 0.0085, "Benchmark_Exp": 0.0055, "Turnover_Ratio": 0.43}', '{"volume_metrics": {"Vol_3M": 1630733, "Vol_Recent": 1778060}, "moving_averages": {"MA_50": 20.447, "MA_200": 20.451}}', '{"asset_allocation": {"Bond_Weight": null, "Equity_Weight": null}, "bond_characteristics": {"Avg_Maturity": null, "Duration_Yrs": 4.05}}', '{"valuation_metrics": {"PB_Ratio": null, "PE_Ratio": null, "PS_Ratio": null, "PCF_Ratio": null}}');
INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (724, 'FPFD', 'ETF', 'USA', 'Cavanal Hill Limited Duration F', 'Cavanal Hill Limited Duration Fund Institutional Class', 'US$', NULL, NULL, 'Cavanal Hill funds', 'BTS', 'Preferred Stock', 5023738, NULL, '2021-06-15', NULL, 'The investment seeks income and secondarily seeks capital appreciation. The fund invests primarily in debt obligations such as bonds, notes and debentures, and bills issued by U.S. corporations or by the U.S. government, its agencies or instrumentalities, municipal securities, mortgage-backed securities, asset-backed securities, and collateralized mortgage obligations and fixed income ETFs. It ivests at least 80% of its net assets in bonds and maintains an average portfolio duration of less than three and one-half years. The fund normally invests at least 65% of its net assets in interest-bearing bonds.', 0.0059, 0.0055, 13343, 23530, 25.171, 25.244, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '{"Cap_Size": null, "Quote_Mode": "ETF", "Currency_Base": "US$", "GeoZone_Class": "USA", "Strategy_Type": null}', '{"Net_Worth": 5023738, "Yield_Rate": null, "Expense_Net": 0.0059, "Benchmark_Exp": 0.0055, "Turnover_Ratio": null}', '{"volume_metrics": {"Vol_3M": 13343, "Vol_Recent": 23530}, "moving_averages": {"MA_50": 25.171, "MA_200": 25.244}}', '{"asset_allocation": {"Bond_Weight": null, "Equity_Weight": null}, "bond_characteristics": {"Avg_Maturity": null, "Duration_Yrs": null}}', '{"valuation_metrics": {"PB_Ratio": null, "PE_Ratio": null, "PS_Ratio": null, "PCF_Ratio": null}}');
INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (725, 'FPRO', 'ETF', 'us', 'Alger Small Cap Growth Institut', 'Alger SmallCap Growth Institutional Fund Class Z-2', 'usd', 'Blend', 'Medium', 'Alger', 'BTS', 'Real Estate', 14720710, NULL, '2021-02-02', NULL, 'The investment seeks long-term capital appreciation. The fund normally invests at least 80% of its net assets, plus any borrowings for investment purposes, in equity securities of companies that, at the time of purchase of the securities, have total market capitalization between (1) the higher of (a) $5 billion or (b) the company in either the Russell 2000 Growth Index or the MSCI USA Small Cap Index with the highest capitalization, and (2) the company in either index with the lowest capitalization, at any time during the most recent 12-month period as reported by either index. Both indexes are broad-based indexes of small capitalization stocks.', 0.0059, 0.0037, 7527, 8860, 24.971, 23.586, 1, 0, 2.89, 21.54, 40.23, 7.43, NULL, NULL, '{"Cap_Size": "Medium", "Quote_Mode": "ETF", "Currency_Base": "usd", "GeoZone_Class": "us", "Strategy_Type": "Blend"}', '{"Net_Worth": 14720710, "Yield_Rate": null, "Expense_Net": 0.0059, "Benchmark_Exp": 0.0037, "Turnover_Ratio": null}', '{"volume_metrics": {"Vol_3M": 7527, "Vol_Recent": 8860}, "moving_averages": {"MA_50": 24.971, "MA_200": 23.586}}', '{"asset_allocation": {"Bond_Weight": 0, "Equity_Weight": 1}, "bond_characteristics": {"Avg_Maturity": null, "Duration_Yrs": null}}', '{"valuation_metrics": {"PB_Ratio": 2.89, "PE_Ratio": 40.23, "PS_Ratio": 7.43, "PCF_Ratio": 21.54}}');
INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (822, 'GLDM', 'ETF', 'USA', 'Amana Mutual Funds Trust - Grow', 'Amana Mutual Funds Trust Growth Fund Investor', 'USD', NULL, NULL, 'Amana', 'PCX', NULL, 4602291712, NULL, '2018-06-25', NULL, 'The investment seeks long-term capital growth, consistent with Islamic principles. The fund normally invests at least 80% of total net assets in common stocks. It invests only in common stocks, including foreign stocks. Investment decisions are made in accordance with Islamic principles. The fund diversifies its investments across industries and companies, and principally follows a large-cap value investment style.', 0.0018, NULL, 2661420, 2.82989e+06, 17.803, 17.814, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '{"Cap_Size": null, "Quote_Mode": "ETF", "Currency_Base": "USD", "GeoZone_Class": "USA", "Strategy_Type": null}', '{"Net_Worth": 4602291712, "Yield_Rate": null, "Expense_Net": 0.0018, "Benchmark_Exp": null, "Turnover_Ratio": null}', '{"volume_metrics": {"Vol_3M": 2661420, "Vol_Recent": 2829890}, "moving_averages": {"MA_50": 17.803, "MA_200": 17.814}}', '{"asset_allocation": {"Bond_Weight": null, "Equity_Weight": null}, "bond_characteristics": {"Avg_Maturity": null, "Duration_Yrs": null}}', '{"valuation_metrics": {"PB_Ratio": null, "PE_Ratio": null, "PS_Ratio": null, "PCF_Ratio": null}}');
INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (726, 'FPXE', 'ETF', 'USA', 'Invesco Limited Term Muni Inc F', 'Invesco Limited Term Municipal Income Fund Class A2', 'Usd', 'Growth', 'Large', 'Invesco', 'NGM', 'Europe Stock', 6000902, 0.0111, '2018-10-02', 0.63, 'The investment seeks federal tax-exempt current income. The fund invests, under normal circumstances, at least 80% of its net assets (plus any borrowings for investment purposes) in municipal debt securities that (1) pay interest that is excluded from gross income for federal income tax purposes, and (2) do not produce income that will be considered to be an item of preference for purposes of the alternative minimum tax. At least 80% of its net assets will normally be invested in investment grade municipal debt securities. The advisor will attempt to maintain a dollar-weighted average effective portfolio maturity of five years or less.', 0.007, 0.0044, 2922, 5580, 31.835, 30.753, 0.9985, 0, 3.23, 18.83, 29.95, 2.5, NULL, NULL, '{"Cap_Size": "Large", "Quote_Mode": "ETF", "Currency_Base": "Usd", "GeoZone_Class": "USA", "Strategy_Type": "Growth"}', '{"Net_Worth": 6000902, "Yield_Rate": 0.0111, "Expense_Net": 0.007, "Benchmark_Exp": 0.0044, "Turnover_Ratio": 0.63}', '{"volume_metrics": {"Vol_3M": 2922, "Vol_Recent": 5580}, "moving_averages": {"MA_50": 31.835, "MA_200": 30.753}}', '{"asset_allocation": {"Bond_Weight": 0, "Equity_Weight": 0.9985}, "bond_characteristics": {"Avg_Maturity": null, "Duration_Yrs": null}}', '{"valuation_metrics": {"PB_Ratio": 3.23, "PE_Ratio": 29.95, "PS_Ratio": 2.5, "PCF_Ratio": 18.83}}');
INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (746, 'FTEC', 'ETF', 'us', 'AB Income Fund - C', 'AB Income Fund Class C', 'US$', 'Growth', 'Large', 'AllianceBernstein', 'PCX', 'Technology', 5952836096, 0.0067, '2013-10-21', 0.05, 'The investment seeks high current income consistent with preservation of capital. The fund pursues its objective by investing, under normal circumstances, at least 80% of its net assets in income-producing securities. It also normally invests at least 65% of its total assets in securities of U.S. and foreign governments, their agencies or instrumentalities and repurchase agreements relating to U.S. government securities. The fund normally invests at least 65% of its total assets in U.S. dollar denominated securities.', 0.00084, 0.0053, 243245, 306170, 127.241, 117.72, 0.999, 0, 10.29, 22.29, 34.36, 5.86, NULL, NULL, '{"Cap_Size": "Large", "Quote_Mode": "ETF", "Currency_Base": "US$", "GeoZone_Class": "us", "Strategy_Type": "Growth"}', '{"Net_Worth": 5952836096, "Yield_Rate": 0.0067, "Expense_Net": 0.00084, "Benchmark_Exp": 0.0053, "Turnover_Ratio": 0.05}', '{"volume_metrics": {"Vol_3M": 243245, "Vol_Recent": 306170}, "moving_averages": {"MA_50": 127.241, "MA_200": 117.72}}', '{"asset_allocation": {"Bond_Weight": 0, "Equity_Weight": 0.999}, "bond_characteristics": {"Avg_Maturity": null, "Duration_Yrs": null}}', '{"valuation_metrics": {"PB_Ratio": 10.29, "PE_Ratio": 34.36, "PS_Ratio": 5.86, "PCF_Ratio": 22.29}}');
INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (727, 'FPXI', 'ETF', 'U.S.A.', 'Ultra Short Tax-Free Income Fun', 'Cavanal HillUltra Short Tax-Free Income Fund Institutional', 'US$', 'Growth', 'Large', 'Cavanal Hill funds', 'NGM', 'Foreign Large Growth', 1255508224, 0.0036, '2014-11-04', 1.14, 'The investment seeks to generate current income exempt from federal income taxes consistent with the preservation of capital. The fund invests in a diversified portfolio of municipal bonds and debentures. As a matter of fundamental policy, it invests, under normal circumstances, at least 80% of its net assets in municipal securities, the income from which is both exempt from federal income tax and not subject to federal alternative minimum tax for individuals. The fund invests at least 80% of its net assets in tax-free bonds and maintains a dollar-weighted average maturity between 1 day to 1 year.', 0.007, 0.0066, 125574, 167380, 64.605, 66.749, 0.9982, 0, 5.55, 19.61, 31.29, 3.7, NULL, NULL, '{"Cap_Size": "Large", "Quote_Mode": "ETF", "Currency_Base": "US$", "GeoZone_Class": "U.S.A.", "Strategy_Type": "Growth"}', '{"Net_Worth": 1255508224, "Yield_Rate": 0.0036, "Expense_Net": 0.007, "Benchmark_Exp": 0.0066, "Turnover_Ratio": 1.14}', '{"volume_metrics": {"Vol_3M": 125574, "Vol_Recent": 167380}, "moving_averages": {"MA_50": 64.605, "MA_200": 66.749}}', '{"asset_allocation": {"Bond_Weight": 0, "Equity_Weight": 0.9982}, "bond_characteristics": {"Avg_Maturity": null, "Duration_Yrs": null}}', '{"valuation_metrics": {"PB_Ratio": 5.55, "PE_Ratio": 31.29, "PS_Ratio": 3.7, "PCF_Ratio": 19.61}}');
