INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (786, 'FXZ', 'ETF', 'U.S.', 'ALPS/Smith Balanced Opportunity', 'ALPS/Smith Balanced Opportunity Fund Investor Class', 'DOLLAR', 'Value', 'Medium', 'ALPS', 'PCX', 'Natural Resources', 514360896, 0.0123, '2007-05-08', 0.84, 'The investment seeks long-term capital growth, consistent with preservation of capital and balanced by current income. The fund pursues its investment objective by normally investing 60% of its assets in equity securities and 40% of its assets in fixed-income securities and cash equivalents. Equity securities in which the fund may invest include common stocks and preferred stocks. Its fixed-income investments may reflect a broad range of credit qualities and may include corporate debt securities, U.S. government obligations, agency mortgage-backed securities, asset-backed securities, and bank loans.', 0.0067, 0.0048, 87698, 68210, 59.778, 57.977, 0.9988, 0, 2.88, 11.48, 19.23, 1.76, NULL, NULL, '{"Cap_Size": "Medium", "Quote_Mode": "ETF", "Currency_Base": "DOLLAR", "GeoZone_Class": "U.S.", "Strategy_Type": "Value"}', '{"Net_Worth": 514360896, "Yield_Rate": 0.0123, "Expense_Net": 0.0067, "Benchmark_Exp": 0.0048, "Turnover_Ratio": 0.84}', '{"volume_metrics": {"Vol_3M": 87698, "Vol_Recent": 68210}, "moving_averages": {"MA_50": 59.778, "MA_200": 57.977}}', '{"asset_allocation": {"Bond_Weight": 0, "Equity_Weight": 0.9988}, "bond_characteristics": {"Avg_Maturity": null, "Duration_Yrs": null}}', '{"valuation_metrics": {"PB_Ratio": 2.88, "PE_Ratio": 19.23, "PS_Ratio": 1.76, "PCF_Ratio": 11.48}}');
