INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (788, 'FYLD', 'ETF', 'usa', 'AB Large Cap Growth Fund, Inc. ', 'AB Large Cap Growth Fund Class I', 'AmericanDollar', 'Value', 'Medium', 'AllianceBernstein', 'BTS', 'Foreign Small/Mid Value', 34519456, 0.0442, '2013-12-02', NULL, 'The investment seeks long-term growth of capital. The fund invests primarily in equity securities of a limited number of large, carefully selected, high-quality U.S. companies. It invests primarily in the domestic equity securities of companies selected by the fund''s Adviser for their growth potential within various market sectors. The fund emphasizes investments in large, seasoned companies. Under normal circumstances, the fund will invest at least 80% of its net assets in common stocks of large-capitalization companies. It may, at times, invest in shares of exchange-traded funds in lieu of making direct investments in securities.', 0.0059, 0.0051, 12345, 8570, 27.256, 27.726, NULL, NULL, 1.18, 6.29, 12.25, 0.9, NULL, NULL, '{"Cap_Size": "Medium", "Quote_Mode": "ETF", "Currency_Base": "AmericanDollar", "GeoZone_Class": "usa", "Strategy_Type": "Value"}', '{"Net_Worth": 34519456, "Yield_Rate": 0.0442, "Expense_Net": 0.0059, "Benchmark_Exp": 0.0051, "Turnover_Ratio": null}', '{"volume_metrics": {"Vol_3M": 12345, "Vol_Recent": 8570}, "moving_averages": {"MA_50": 27.256, "MA_200": 27.726}}', '{"asset_allocation": {"Bond_Weight": null, "Equity_Weight": null}, "bond_characteristics": {"Avg_Maturity": null, "Duration_Yrs": null}}', '{"valuation_metrics": {"PB_Ratio": 1.18, "PE_Ratio": 12.25, "P