INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (789, 'FYT', 'ETF', 'us', 'Alger Weatherbie Specialized Gr', 'Alger Weatherbie Specialized Growth Fund Class A', 'usd', 'Value', 'Small', 'Alger', 'NGM', 'Small Value', 323162176, 0.0093, '2011-04-19', 1.2, 'The investment seeks long-term capital appreciation. Under normal circumstances, the fund invests at least 80% of its net assets, plus any borrowings for investment purposes, in equity securities of smallcap and midcap companies. Equity securities include common or preferred stocks that are listed on U.S. or foreign exchanges. Smallcap or midcap companies are companies that, at the time of purchase, have total market capitalization within the range of companies included in the Russell 2500 Growth Index or the Russell Midcap Growth Index, respectively, as reported by the indexes as of the most recent quarter-end.', 0.007, 0.0035, 30883, 33480, 52.143, 51.142, 1, 0, 1.37, 7.32, 11.77, 1.05, NULL, NULL, '{"Cap_Size": "Small", "Quote_Mode": "ETF", "Currency_Base": "usd", "GeoZone_Class": "us", "Strategy_Type": "Value"}', '{"Net_Worth": 323162176, "Yield_Rate": 0.0093, "Expense_Net": 0.007, "Benchmark_Exp": 0.0035, "Turnover_Ratio": 1.2}', '{"volume_metrics": {"Vol_3M": 30883, "Vol_Recent": 33480}, "moving_averages": {"MA_50": 52.143, "MA_200": 51.142}}', '{"asset_allocation": {"Bond_Weight": 0, "Equity_Weight": 1}, "bond_characteristics": {"Avg_Maturity": null, "Duration_Yrs": null}}', '{"valuation_metrics": {"PB_Ratio": 1.37, "PE_Ratio": 11.77, "PS_Ratio": 1.05, "PCF_Ratio": 7.32}}');
