INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (791, 'GAA', 'ETF', 'U.S.', 'Invesco Short Duration Inflatio', 'Invesco Short Duration Inflation Protected Fund Class R5', 'DOLLAR', 'Value', 'Medium', 'Invesco', 'BTS', 'World Allocation', 54271560, 0.0199, '2014-12-09', NULL, 'The investment seeks to provide protection from the negative effects of unanticipated inflation. The fund invests under normal circumstances at least 80% of its net assets (plus any borrowings for investment purposes) in the component securities of the ICE BofA 1-5 Year US Inflation-Linked Treasury Index (the index) and in derivatives and other instruments that have economic characteristics similar to such securities. The index is comprised of U.S. Treasury Inflation Protected Securities (TIPS) with at least $1 billion in outstanding face value and a remaining term to final maturity of at least 1 year and less than 5 years at the time of index rebalancing.', 0.0037, 0.0058, 5314, 4820, 31.807, 31.7, NULL, NULL, 1.58, 7.08, 12.1, 0.9, 9.44, 7.2, '{"Cap_Size": "Medium", "Quote_Mode": "ETF", "Currency_Base": "DOLLAR", "GeoZone_Class": "U.S.", "Strategy_Type": "Value"}', '{"Net_Worth": 54271560, "Yield_Rate": 0.0199, "Expense_Net": 0.0037, "Benchmark_Exp": 0.0058, "Turnover_Ratio": null}', '{"volume_metrics": {"Vol_3M": 5314, "Vol_Recent": 4820}, "moving_averages": {"MA_50": 31.807, "MA_200": 31.7}}', '{"asset_allocation": {"Bond_Weight": null, "Equity_Weight": null}, "bond_characteristics": {"Avg_Maturity": 9.44, "Duration_Yrs": 7.2}}', '{"valuation_metrics": {"PB_Ratio": 1.58, "PE_Ratio": 12.1, "PS_Ratio": 0.9, "PCF_Ratio": 7.08}}');
INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (793, 'GAMR', 'ETF', 'United States', 'Alger Mid Cap Growth Institutio', 'Alger MidCap Growth Institutional Fund Class Z-2', 'Dollar', 'Growth', 'Medium', 'Alger', 'PCX', 'Technology', 143478720, 0.0083, '2016-03-08', 0.53, 'The investment seeks long-term capital appreciation. The fund invests at least 80% of its net assets in equity securities of companies that, at the time of purchase of the securities, have total market capitalization within the range of companies included in the Russell Midcap Growth Index or the S&P MidCap 400 Index, as reported by the indexes as of the most recent quarter-end. Both indexes are designed to track the performance of medium-capitalization stocks.', 0.0075, 0.0053, 7029, 8470, 90.091, 92.632, NULL, NULL, 3.23, 11.88, 19.85, 2.17, NULL, NULL, '{"Cap_Size": "Medium", "Quote_Mode": "ETF", "Currency_Base": "Dollar", "GeoZone_Class": "United States", "Strategy_Type": "Growth"}', '{"Net_Worth": 143478720, "Yield_Rate": 0.0083, "Expense_Net": 0.0075, "Benchmark_Exp": 0.0053, "Turnover_Ratio": 0.53}', '{"volume_metrics": {"Vol_3M": 7029, "Vol_Recent": 8470}, "moving_averages": {"MA_50": 90.091, "MA_200": 92.632}}', '{"asset_allocation": {"Bond_Weight": null, "Equity_Weight": null}, "bond_characteristics": {"Avg_Maturity": null, "Duration_Yrs": null}}', '{"valuation_metrics": {"PB_Ratio": 3.23, "PE_Ratio": 19.85, "PS_Ratio": 2.17, "PCF_Ratio": 11.88}}');
INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (794, 'GAZ', 'ETF', 'USA', 'AB Municipal Income Fund, Inc. ', 'AB Municipal Income Fund National Portfolio Class C', 'US$', NULL, NULL, 'AllianceBernstein', 'PCX', NULL, 5230272, NULL, '2017-03-08', NULL, 'The investment seeks to earn the highest level of current income, exempt from federal income tax, which is available without assuming what the Adviser considers to be undue risk to principal or income. The fund invests principally in high-yielding, predominantly investment grade municipal securities. It invests at least 80% of its net assets in municipal securities that pay interest that is exempt from federal income tax. These securities may pay interest that is subject to the federal alternative minimum tax ("AMT") for certain taxpayers. The fund may invest more than 25% of its assets in a single state.', 0.0045, NULL, 31698, 20170, 27.992, 21.038, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '{"Cap_Size": null, "Quote_Mode": "ETF", "Currency_Base": "US$", "GeoZone_Class": "USA", "Strategy_Type": null}', '{"Net_Worth": 5230272, "Yield_Rate": null, "Expense_Net": 0.0045, "Benchmark_Exp": null, "Turnover_Ratio": null}', '{"volume_metrics": {"Vol_3M": 31698, "Vol_Recent": 20170}, "moving_averages": {"MA_50": 27.992, "MA_200": 21.038}}', '{"asset_allocation": {"Bond_Weight": null, "Equity_Weight": null}, "bond_characteristics": {"Avg_Maturity": null, "Duration_Yrs": null}}', '{"valuation_metrics": {"PB_Ratio": null, "PE_Ratio": null, "PS_Ratio": null, "PCF_Ratio": null}}');
INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (795, 'GBDV', 'ETF', 'America', 'AllianzGI Large-Cap Value Fund ', 'Virtus NFJ Large-Cap Value Fund Administrative Class', 'usd', 'Value', 'Medium', 'Virtus', 'PCX', NULL, 2662585, 0.0362, '2019-12-26', NULL, 'The investment seeks long-term growth of capital and income. The fund normally invests at least 80% of its net assets (plus borrowings made for investment purposes) in common stocks and other equity securities of companies with large market capitalizations. It normally invests significantly in securities that the portfolio managers expect will generate income (for example, by paying dividends). In addition to common stocks and other equity securities, the fund may invest in real estate investment trusts (REITs) and in non-U.S. securities (including through American Depositary Receipts (ADRs)), including emerging market securities.', 0.0029, NULL, 545, 380, 21.175, 21.237, 0.9984, 0, 2.05, 8.87, 18.85, 1.34, NULL, NULL, '{"Cap_Size": "Medium", "Quote_Mode": "ETF", "Currency_Base": "usd", "GeoZone_Class": "America", "Strategy_Type": "Value"}', '{"Net_Worth": 2662585, "Yield_Rate": 0.0362, "Expense_Net": 0.0029, "Benchmark_Exp": null, "Turnover_Ratio": null}', '{"volume_metrics": {"Vol_3M": 545, "Vol_Recent": 380}, "moving_averages": {"MA_50": 21.175, "MA_200": 21.237}}', '{"asset_allocation": {"Bond_Weight": 0, "Equity_Weight": 0.9984}, "bond_characteristics": {"Avg_Maturity": null, "Duration_Yrs": null}}', '{"valuation_metrics": {"PB_Ratio": 2.05, "PE_Ratio": 18.85, "PS_Ratio": 1.34, "PCF_Ratio": 8.87}}');
INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (796, 'GBF', 'ETF', 'US', 'AB Municipal Income Fund, Inc. ', 'AB Municipal Income Fund New York Portfolio Advisor Class', 'US_DOLLAR', NULL, NULL, 'AllianceBernstein', 'PCX', 'Intermediate-Term Bond', 159124000, 0.0134, '2007-01-05', 0.24, 'The investment seeks to earn the highest level of current income exempt from both federal income tax and New York State and City income tax that is available without assuming what the Adviser considers to be undue risk to principal or income. The fund invests at least 80% of its net assets in municipal securities that pay interest that is exempt from federal income tax. These securities may pay interest that is subject to the federal alternative minimum tax ("AMT") for certain taxpayers. It invests at least 80% of its net assets in municipal securities of New York or municipal securities with interest that is otherwise exempt from New York state income tax.', 0.002, 0.0023, 28427, 10010, 121.771, 121.903, NULL, NULL, NULL, NULL, NULL, NULL, 9.51, 7.39, '{"Cap_Size": null, "Quote_Mode": "ETF", "Currency_Base": "US_DOLLAR", "GeoZone_Class": "US", "Strategy_Type": null}', '{"Net_Worth": 159124000, "Yield_Rate": 0.0134, "Expense_Net": 0.002, "Benchmark_Exp": 0.0023, "Turnover_Ratio": 0.24}', '{"volume_metrics": {"Vol_3M": 28427, "Vol_Recent": 10010}, "moving_averages": {"MA_50": 121.771, "MA_200": 121.903}}', '{"asset_allocation": {"Bond_Weight": null, "Equity_Weight": null}, "bond_characteristics": {"Avg_Maturity": 9.51, "Duration_Yrs": 7.39}}', '{"valuation_metrics": {"PB_Ratio": null, "PE_Ratio": null, "PS_Ratio": null, "PCF_Ratio": null}}');
