INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (810, 'GERM', 'ETF', 'USA', 'Alger Small Cap Growth Fund - C', 'FS Alternative Income Opportunities Fund Class A', 'USD', 'Growth', 'Medium', 'FS Investments', 'PCX', NULL, 54981400, NULL, '2020-06-17', 0.41, 'The investment seeks to provide positive returns through capital appreciation and income. The fund seeks to achieve its investment objective by seeking a bond-like risk profile with enhanced income by investing globally across the five major asset classes (commodities, currencies, fixed income, equities and credit). From time to time, the fund can have significant exposure to non-U.S. dollar denominated currencies (up to 50% of the fund''s assets), including emerging markets currencies. The fund is non-diversified.', 0.0068, NULL, 15077, 18490, 38.411, 38.892, 0.9739, 0.0205, 5.08, 13.56, 14.21, 3.29, NULL, NULL, '{"Cap_Size": "Medium", "Quote_Mode": "ETF", "Currency_Base": "USD", "GeoZone_Class": "USA", "Strategy_Type": "Growth"}', '{"Net_Worth": 54981400, "Yield_Rate": null, "Expense_Net": 0.0068, "Benchmark_Exp": null, "Turnover_Ratio": 0.41}', '{"volume_metrics": {"Vol_3M": 15077, "Vol_Recent": 18490}, "moving_averages": {"MA_50": 38.411, "MA_200": 38.892}}', '{"asset_allocation": {"Bond_Weight": 0.0205, "Equity_Weight": 0.9739}, "bond_characteristics": {"Avg_Maturity": null, "Duration_Yrs": null}}', '{"valuation_metrics": {"PB_Ratio": 5.08, "PE_Ratio": 14.21, "PS_Ratio": 3.29, "PCF_Ratio": 13.56}}');
