INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (801, 'GBUG', 'ETF', 'America', 'American Century Large Company ', 'American Century Investments Focused Large Cap Value Fund A Class', 'US$', NULL, NULL, 'American Century Investments', 'PCX', NULL, 39595136, NULL, '2019-10-07', NULL, 'The investment seeks long-term capital growth; income is a secondary objective. Under normal market conditions, the portfolio managers will invest at least 80% of the fund''s assets in securities of large capitalization companies. For purposes of this 80% test, the advisors define large capitalization companies as those with capitalizations within the range of the Russell 1000© Index. In selecting stocks for the fund, the portfolio managers look for companies whose stock price may not adequately reflect the company''s value.', NULL, NULL, 775, 1830, 29.172, 29.224, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '{"Cap_Size": null, "Quote_Mode": "ETF", "Currency_Base": "US$", "GeoZone_Class": "America", "Strategy_Type": null}', '{"Net_Worth": 39595136, "Yield_Rate": null, "Expense_Net": null, "Benchmark_Exp": null, "Turnover_Ratio": null}', '{"volume_metrics": {"Vol_3M": 775, "Vol_Recent": 1830}, "moving_averages": {"MA_50": 29.172, "MA_200": 29.224}}', '{"asset_allocation": {"Bond_Weight": null, "Equity_Weight": null}, "bond_characteristics": {"Avg_Maturity": null, "Duration_Yrs": null}}', '{"valuation_metrics": {"PB_Ratio": null, "PE_Ratio": null, "PS_Ratio": null, "PCF_Ratio": null}}');
INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (802, 'GCOR', 'ETF', 'USA', 'ALPS/Smith Balanced Opportunity', 'ALPS/Smith Balanced Opportunity Fund Class I', 'usd', NULL, NULL, 'ALPS', 'PCX', 'Intermediate-Term Bond', 213196352, NULL, '2020-09-08', NULL, 'The investment seeks long-term capital growth, consistent with preservation of capital and balanced by current income. The fund pursues its investment objective by normally investing 60% of its assets in equity securities and 40% of its assets in fixed-income securities and cash equivalents. Equity securities in which the fund may invest include common stocks and preferred stocks. Its fixed-income investments may reflect a broad range of credit qualities and may include corporate debt securities, U.S. government obligations, agency mortgage-backed securities, asset-backed securities, and bank loans.', 0.0014, 0.0023, 54159, 23520, 48.754, 48.866, NULL, NULL, NULL, NULL, NULL, NULL, 14.41, 6.24, '{"Cap_Size": null, "Quote_Mode": "ETF", "Currency_Base": "usd", "GeoZone_Class": "USA", "Strategy_Type": null}', '{"Net_Worth": 213196352, "Yield_Rate": null, "Expense_Net": 0.0014, "Benchmark_Exp": 0.0023, "Turnover_Ratio": null}', '{"volume_metrics": {"Vol_3M": 54159, "Vol_Recent": 23520}, "moving_averages": {"MA_50": 48.754, "MA_200": 48.866}}', '{"asset_allocation": {"Bond_Weight": null, "Equity_Weight": null}, "bond_characteristics": {"Avg_Maturity": 14.41, "Duration_Yrs": 6.24}}', '{"valuation_metrics": {"PB_Ratio": null, "PE_Ratio": null, "PS_Ratio": null, "PCF_Ratio": null}}');
