INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (804, 'GDMA', 'ETF', 'United States', 'Alger Small Cap Growth Fund Cla', 'Alger Small Cap Growth Fund Class A', 'DOLLAR', 'Value', 'Large', 'Alger', 'PCX', NULL, 121213328, 0.0051, '2018-11-14', 5.36, 'The investment seeks long-term capital appreciation. The fund normally invests at least 80% of its net assets, plus any borrowings for investment purposes, in equity securities of companies that, at the time of purchase of the securities, have total market capitalization between (1) the higher of (a) $5 billion or (b) the company in either the Russell 2000 Growth Index or the MSCI USA Small Cap Index with the highest capitalization, and (2) the company in either index with the lowest capitalization, at any time during the most recent 12-month period as reported by either index.', 0.0078, NULL, 5019, 6450, 31.929, 32.115, NULL, NULL, 1.81, 9.07, 17.55, 1.35, NULL, NULL, '{"Cap_Size": "Large", "Quote_Mode": "ETF", "Currency_Base": "DOLLAR", "GeoZone_Class": "United States", "Strategy_Type": "Value"}', '{"Net_Worth": 121213328, "Yield_Rate": 0.0051, "Expense_Net": 0.0078, "Benchmark_Exp": null, "Turnover_Ratio": 5.36}', '{"volume_metrics": {"Vol_3M": 5019, "Vol_Recent": 6450}, "moving_averages": {"MA_50": 31.929, "MA_200": 32.115}}', '{"asset_allocation": {"Bond_Weight": null, "Equity_Weight": null}, "bond_characteristics": {"Avg_Maturity": null, "Duration_Yrs": null}}', '{"valuation_metrics": {"PB_Ratio": 1.81, "PE_Ratio": 17.55, "PS_Ratio": 1.35, "PCF_Ratio": 9.07}}');
