INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (821, 'GLDI', 'ETF', 'U.S.A.', 'Disciplined Core Value Fund - A', 'American Century Disciplined Core Value Fund Class A', 'usd', NULL, NULL, 'American Century Investments', 'NGM', NULL, 102477456, 0.1456, '2013-01-29', NULL, 'The investment seeks long-term capital growth; income is a secondary consideration. In selecting stocks for the fund, the managers use quantitative and qualitative management techniques in a multi-step process. The managers evaluate stocks, primarily large capitalization, publicly traded U.S. companies based on an objective set of measures, including valuation, quality, growth, and sentiment. The portfolio managers use quantitative models to build a portfolio of stocks from the ranking that they believe will provide the optimal balance between risk and expected return.', 0.0065, NULL, 123535, 130550, 8.443, 8.697, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '{"Cap_Size": null, "Quote_Mode": "ETF", "Currency_Base": "usd", "GeoZone_Class": "U.S.A.", "Strategy_Type": null}', '{"Net_Worth": 102477456, "Yield_Rate": 0.1456, "Expense_Net": 0.0065, "Benchmark_Exp": null, "Turnover_Ratio": null}', '{"volume_metrics": {"Vol_3M": 123535, "Vol_Recent": 130550}, "moving_averages": {"MA_50": 8.443, "MA_200": 8.697}}', '{"asset_allocation": {"Bond_Weight": null, "Equity_Weight": null}, "bond_characteristics": {"Avg_Maturity": null, "Duration_Yrs": null}}', '{"valuation_metrics": {"PB_Ratio": null, "PE_Ratio": null, "PS_Ratio": null, "PCF_Ratio": null}}');
INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (823, 'GLIF', 'ETF', 'America', 'Amana Mutual Funds Trust - Inco', 'Amana Mutual Funds Trust Income Fund Investor', 'Dollar', 'Value', 'Large', 'Amana', 'PCX', 'Infrastructure', 4028154, 0.024, '2019-05-22', 3.2282, 'The investment seeks current income and preservation of capital, consistent with Islamic principles; current income is its primary objective. The fund normally invests at least 80% of its total net assets in income-producing securities, primarily dividend-paying common stocks. It invests primarily in dividend-paying common stocks, including foreign stocks. Investment decisions are made in accordance with Islamic principles. The fund diversifies its investments across industries and companies, and principally follows a large-cap value investment style.', 0.0046, 0.0045, 867, 870, 27.622, 26.84, NULL, NULL, 2.27, 10.84, 23.05, 1.86, NULL, NULL, '{"Cap_Size": "Large", "Quote_Mode": "ETF", "Currency_Base": "Dollar", "GeoZone_Class": "America", "Strategy_Type": "Value"}', '{"Net_Worth": 4028154, "Yield_Rate": 0.024, "Expense_Net": 0.0046, "Benchmark_Exp": 0.0045, "Turnover_Ratio": 3.2282}', '{"volume_metrics": {"Vol_3M": 867, "Vol_Recent": 870}, "moving_averages": {"MA_50": 27.622, "MA_200": 26.84}}', '{"asset_allocation": {"Bond_Weight": null, "Equity_Weight": null}, "bond_characteristics": {"Avg_Maturity": null, "Duration_Yrs": null}}', '{"valuation_metrics": {"PB_Ratio": 2.27, "PE_Ratio": 23.05, "PS_Ratio": 1.86, "PCF_Ratio": 10.84}}');
INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (824, 'GLIN', 'ETF', 'usa', 'Amana Participation Fund Invest', 'Amana Participation Fund Investor Shares', 'US_DOLLAR', 'Growth', 'Large', 'Amana', 'PCX', 'India Equity', 75047096, 0.002, '2010-08-24', 1.33, 'The investment seeks capital preservation and current income, consistent with Islamic principles; capital preservation is its primary objective. Under normal conditions, the fund invests at least 80% of its total net assets in short and intermediate-term Islamic income-producing investments. It invests at least 65% of its assets in securities rated within the four highest grades (Aaa, Aa, A, Baa) by a nationally-recognized rating agency and may invest up to 35% in unrated and high-yield notes and certificates, which may be considered equivalent to "junk bonds". The fund is non-diversified.', 0.0094, 0.0084, 9624, 17100, 42.223, 38.698, 0.9969, 0, 5.37, 18.12, 27.91, 3.92, NULL, NULL, '{"Cap_Size": "Large", "Quote_Mode": "ETF", "Currency_Base": "US_DOLLAR", "GeoZone_Class": "usa", "Strategy_Type": "Growth"}', '{"Net_Worth": 75047096, "Yield_Rate": 0.002, "Expense_Net": 0.0094, "Benchmark_Exp": 0.0084, "Turnover_Ratio": 1.33}', '{"volume_metrics": {"Vol_3M": 9624, "Vol_Recent": 17100}, "moving_averages": {"MA_50": 42.223, "MA_200": 38.698}}', '{"asset_allocation": {"Bond_Weight": 0, "Equity_Weight": 0.9969}, "bond_characteristics": {"Avg_Maturity": null, "Duration_Yrs": null}}', '{"valuation_metrics": {"PB_Ratio": 5.37, "PE_Ratio": 27.91, "PS_Ratio": 3.92, "PCF_Ratio": 18.12}}');
INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (825, 'GLL', 'ETF', 'UNITED_STATES', 'AB Municipal Income Fund II - M', 'AB Municipal Income Fund II Massachusetts Portfolio Advisor Class', 'USD', NULL, NULL, 'AllianceBernstein', 'PCX', 'Trading--Inverse Commodities', 32835246, NULL, '2008-12-01', NULL, 'The investment seeks to earn the highest level of current income exempt from both federal income tax and Commonwealth of Massachusetts personal income tax that is available without assuming what the Adviser considers to be undue risk. The fund invests at least 80% of its net assets in municipal securities that pay interest that is exempt from federal income tax. These securities may pay interest that is subject to the federal AMT for certain taxpayers. It normally invests at least 80% of its net assets in municipal securities of Massachusetts or municipal securities with interest that is otherwise exempt from Massachusetts state income tax.', 0.0132, 0.0085, 79811, 77200, 33.358, 33.993, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '{"Cap_Size": null, "Quote_Mode": "ETF", "Currency_Base": "USD", "GeoZone_Class": "UNITED_STATES", "Strategy_Type": null}', '{"Net_Worth": 32835246, "Yield_Rate": null, "Expense_Net": 0.0132, "Benchmark_Exp": 0.0085, "Turnover_Ratio": null}', '{"volume_metrics": {"Vol_3M": 79811, "Vol_Recent": 77200}, "moving_averages": {"MA_50": 33.358, "MA_200": 33.993}}', '{"asset_allocation": {"Bond_Weight": null, "Equity_Weight": null}, "bond_characteristics": {"Avg_Maturity": null, "Duration_Yrs": null}}', '{"valuation_metrics": {"PB_Ratio": 