INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (840, 'GRES', 'ETF', 'U.S.', 'AlphaSimplex Managed Futures St', 'AlphaSimplex Managed Futures Strategy Fund Class A', 'USD', 'Value', 'Large', 'Natixis Funds', 'PCX', 'Natural Resources', 21526258, 0.0889, '2009-10-27', NULL, 'The investment seeks to provide capital appreciation. The adviser expected that no more than 25% of the fund''s total assets will be dedicated to initial and variation margin payments relating to the fund''s derivative transactions. The advisor expects that under normal market conditions the fund will invest at least 75% of its total assets in money market and other short-term, high-quality securities. The fund will concentrate its investments in the financial services industry, which means it will normally invest at least 25% of its total assets in securities and other obligations of issuers in such industry.', 0.0078, 0.0048, 7866, 4750, 29.858, 29.051, NULL, NULL, 1.85, 8.77, 16.71, 1.36, NULL, 0.71, '{"Cap_Size": "Large", "Quote_Mode": "ETF", "Currency_Base": "USD", "GeoZone_Class": "U.S.", "Strategy_Type": "Value"}', '{"Net_Worth": 21526258, "Yield_Rate": 0.0889, "Expense_Net": 0.0078, "Benchmark_Exp": 0.0048, "Turnover_Ratio": null}', '{"volume_metrics": {"Vol_3M": 7866, "Vol_Recent": 4750}, "moving_averages": {"MA_50": 29.858, "MA_200": 29.051}}', '{"asset_allocation": {"Bond_Weight": null, "Equity_Weight": null}, "bond_characteristics": {"Avg_Maturity": null, "Duration_Yrs": 0.71}}', '{"valuation_metrics": {"PB_Ratio": 1.85, "PE_Ratio": 16.71, "PS_Ratio": 1.36, "PCF_Ratio": 8.77}}');
INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (841, 'GRID', 'ETF', 'USA', 'American Mutual Fund, Class C S', 'American Funds American Mutual Fund Class C', 'USD', 'Growth', 'Large', 'American Funds', 'NGM', 'Miscellaneous Sector', 425897824, 0.0079, '2009-11-16', 0.53, 'The investment seeks current income, growth of capital and conservation of principal. The fund invests primarily in common stocks of companies that are likely to participate in the growth of the American economy and whose dividends appear to be sustainable. It invests primarily in securities of issuers domiciled in the United States and Canada. The fund may also invest in bonds and other debt securities, including those issued by the U.S. government and by federal agencies and instrumentalities.', 0.007, 0.0067, 71812, 92530, 99.617, 93.486, 0.9994, 0, 3.66, 16.45, 33.74, 2.41, NULL, NULL, '{"Cap_Size": "Large", "Quote_Mode": "ETF", "Currency_Base": "USD", "GeoZone_Class": "USA", "Strategy_Type": "Growth"}', '{"Net_Worth": 425897824, "Yield_Rate": 0.0079, "Expense_Net": 0.007, "Benchmark_Exp": 0.0067, "Turnover_Ratio": 0.53}', '{"volume_metrics": {"Vol_3M": 71812, "Vol_Recent": 92530}, "moving_averages": {"MA_50": 99.617, "MA_200": 93.486}}', '{"asset_allocation": {"Bond_Weight": 0, "Equity_Weight": 0.9994}, "bond_characteristics": {"Avg_Maturity": null, "Duration_Yrs": null}}', '{"valuation_metrics": {"PB_Ratio": 3.66, "PE_Ratio": 33.74, "PS_Ratio": 2.41, "PCF_Ratio": 16.45}}');
INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (842, 'GRN', 'ETF', 'U.S.', 'AAMA Equity Fund', 'AAMA Equity Fund', 'AmericanDollar', NULL, NULL, 'AAMA', 'PCX', NULL, 61024408, NULL, '2019-09-10', NULL, 'The investment seeks to generate long term capital appreciation. The fund, under normal market circumstances, will invest at least 80% of its net assets (including the amount of any borrowings for investment purposes) in equity securities of any size capitalization. It invests primarily in common stocks and ETFs, but may also invest in other types of equity securities including, preferred stock, investments in foreign equity securities through U.S. stock exchange listed ADRs, REITs, or mutual funds that invest in the types of securities in which the fund would normally invest, and securities convertible into such securities.', NULL, NULL, 64399, 105591, 25.06, 21.47, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '{"Cap_Size": null, "Quote_Mode": "ETF", "Currency_Base": "AmericanDollar", "GeoZone_Class": "U.S.", "Strategy_Type": null}', '{"Net_Worth": 61024408, "Yield_Rate": null, "Expense_Net": null, "Benchmark_Exp": null, "Turnover_Ratio": null}', '{"volume_metrics": {"Vol_3M": 64399, "Vol_Recent": 105591}, "moving_averages": {"MA_50": 25.06, "MA_200": 21.47}}', '{"asset_allocation": {"Bond_Weight": null, "Equity_Weight": null}, "bond_characteristics": {"Avg_Maturity": null, "Duration_Yrs": null}}', '{"valuation_metrics": {"PB_Ratio": null, "PE_Ratio": null, "PS_Ratio": null, "PCF_Ratio": null}}');
