INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (848, 'GSIE', 'ETF', 'USA', 'Disciplined Core Value Fund - I', 'American Century Disciplined Core Value Fund I Class', 'Usd', 'Blend', 'Large', 'American Century Investments', 'PCX', 'Foreign Large Blend', 2589396224, 0.0194, '2015-11-06', 0.2, 'The investment seeks long-term capital growth; income is a secondary consideration. In selecting stocks for the fund, the managers use quantitative and qualitative management techniques in a multi-step process. The managers evaluate stocks, primarily large capitalization, publicly traded U.S. companies based on an objective set of measures, including valuation, quality, growth, and sentiment. The portfolio managers use quantitative models to build a portfolio of stocks from the ranking that they believe will provide the optimal balance between risk and expected return.', 0.0025, 0.0037, 458461, 598240, 35.024, 34.799, 0.9993, 0, 2.07, 9.92, 19.43, 1.29, NULL, NULL, '{"Cap_Size": "Large", "Quote_Mode": "ETF", "Currency_Base": "Usd", "GeoZone_Class": "USA", "Strategy_Type": "Blend"}', '{"Net_Worth": 2589396224, "Yield_Rate": 0.0194, "Expense_Net": 0.0025, "Benchmark_Exp": 0.0037, "Turnover_Ratio": 0.2}', '{"volume_metrics": {"Vol_3M": 458461, "Vol_Recent": 598240}, "moving_averages": {"MA_50": 35.024, "MA_200": 34.799}}', '{"asset_allocation": {"Bond_Weight": 0, "Equity_Weight": 0.9993}, "bond_characteristics": {"Avg_Maturity": null, "Duration_Yrs": null}}', '{"valuation_metrics": {"PB_Ratio": 2.07, "PE_Ratio": 19.43, "PS_Ratio": 1.29, "PCF_Ratio": 9.92}}');
INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (908, 'HOLD', 'ETF', 'US', 'AQR International Defensive Sty', 'AQR International Defensive Style Fund Class I', 'Dollar', NULL, NULL, 'AQR Funds', 'PCX', 'Ultrashort Bond', 42432388, 0.0085, '2014-01-14', NULL, 'The investment seeks total return. The fund pursues a "defensive" investment style, seeking to provide downside protection with upside potential through active stock selection, risk management and diversification. It pursues its objective by investing, under normal market conditions, at least 80% of its net assets (including any borrowings for investment purposes) in Equity Instruments of International Issuers.', 0.0036, 0.0022, 262, 370, 98.511, 98.65, NULL, NULL, NULL, NULL, NULL, NULL, 0.69, 0.6, '{"Cap_Size": null, "Quote_Mode": "ETF", "Currency_Base": "Dollar", "GeoZone_Class": "US", "Strategy_Type": null}', '{"Net_Worth": 42432388, "Yield_Rate": 0.0085, "Expense_Net": 0.0036, "Benchmark_Exp": 0.0022, "Turnover_Ratio": null}', '{"volume_metrics": {"Vol_3M": 262, "Vol_Recent": 370}, "moving_averages": {"MA_50": 98.511, "MA_200": 98.65}}', '{"asset_allocation": {"Bond_Weight": null, "Equity_Weight": null}, "bond_characteristics": {"Avg_Maturity": 0.69, "Duration_Yrs": 0.6}}', '{"valuation_metrics": {"PB_Ratio": null, "PE_Ratio": null, "PS_Ratio": null, "PCF_Ratio": null}}');
INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (849, 'GSIG', 'ETF', 'UNITED_STATES', 'Alger Portfolios - Alger Mid Ca', 'Alger Mid Cap Growth Portfolio Class I-2', 'DOLLAR', NULL, NULL, 'Alger', 'PCX', 'Short-Term Bond', 27625298, NULL, '2020-07-07', 0.03, 'The investment seeks long-term capital appreciation. The advisor focuses on mid-sized companies that the advisor believes demonstrate promising growth potential. Under normal circumstances, it invests at least 80% of its net assets in equity securities of companies that, at the time of purchase of the securities, have total market capitalization within the range of companies included in the Russell Midcap Growth Index or the S&P MidCap 400 Index, as reported by the indexes as of the most recent quarter-end. Both indexes are designed to track the performance of medium-capitalization stocks.', 0.0014, 0.0026, 638, 460, 49.862, 50.146, NULL, NULL, NULL, NULL, NULL, NULL, 3.2, 2.76, '{"Cap_Size": null, "Quote_Mode": "ETF", "Currency_Base": "DOLLAR", "GeoZone_Class": "UNITED_STATES", "Strategy_Type": null}', '{"Net_Worth": 27625298, "Yield_Rate": null, "Expense_Net": 0.0014, "Benchmark_Exp": 0.0026, "Turnover_Ratio": 0.03}', '{"volume_metrics": {"Vol_3M": 638, "Vol_Recent": 460}, "moving_averages": {"MA_50": 49.862, "MA_200": 50.146}}', '{"asset_allocation": {"Bond_Weight": null, "Equity_Weight": null}, "bond_characteristics": {"Avg_Maturity": 3.2, "Duration_Yrs": 2.76}}', '{"valuation_metrics": {"PB_Ratio": null, "PE_Ratio": null, "PS_Ratio": null, "PCF_Ratio": null}}');
INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (850, 'GSJY', 'ETF', 'UNITED_STATES', 'American Fds, American High-Inc', 'American High-Income Municipal Bond Fund Class A', 'AmericanDollar', 'Blend', 'Large', 'American Funds', 'PCX', 'Japan Stock', 22399658, 0.0145, '2016-03-02', 0.18, 'The investment seeks a high level of current income exempt from regular federal income tax. Under normal circumstances, the fund will invest at least 80% of its assets in, or derive at least 80% of its income from, securities that are exempt from regular federal income tax and may subject the investors to alternative minimum tax. It may invest, without limitation, in securities that may subject the investors to federal alternative minimum tax. The fund invests at least 50% of its portfolio in debt securities rated BBB+ or below or Baa1 or below, or unrated but determined by the fund''s investment adviser to be of equivalent quality.', 0.0025, 0.004, 891, 850, 37.929, 37.924, 1, 0, 1.43, 8.72, 16.54, 0.98, NULL, NULL, '{"Cap_Size": "Large", "Quote_Mode": "ETF", "Currency_Base": "AmericanDollar", "GeoZone_Class": "UNITED_STATES", "Strategy_Type": "Blend"}', '{"Net_Worth": 22399658, "Yield_Rate": 0.0145, "Expense_Net": 0.0025, "Benchmark_Exp": 0.004, "Turnover_Ratio": 0.18}', '{"volume_metrics": {"Vol_3M": 891, "Vol_Recent": 850}, "moving_averages": {"MA_50": 37.929, "MA_200": 37.924}}', '{"asset_allocation": {"Bond_Weight": 0, "Equity_Weight": 1}, "bond_characteristics": {"Avg_Maturity": null, "Duration_Yrs": null}}', '{"valuation_metrics": {"PB_Ratio": 1.43, "PE_Ratio": 16.54, "PS_Ratio": 0.98, "PCF_Ratio": 8.72}}');
INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (851, 'GSLC', 'ETF', 'U.S.', 'Invesco High Yield Fund Class A', 'Invesco High Yield Fund Class A', 'US$', 'Blend', 'Large', 'Invesco', 'PCX', 'Large Blend', 13078893568, 0.0106, '2015-09-17', 0.17, 'The investment seeks total return through growth of capital and current income. The fund invests, under normal circumstances, at least 80% of its net assets (plus any borrowings for investment purposes) in debt securities that are determined to be below investment grade quality, and in derivatives and other instruments that have economic characteristics similar to such securities. It may invest in preferred stocks and convertible securities, which are securities that generally pay interest and may be converted into common stock. The fund may invest up to 25% of its net assets in foreign securities.', 0.0009, 0.0036, 347374, 317120, 90.746, 85.984, 1, 0, 4.89, 15.96, 26.14, 2.43, NULL, NULL, '{"Cap_Size": "Large", "Quote_Mode": "ETF", "Currency_Base": "US$", "GeoZone_Class": "U.S.", "Strategy_Type": "Blend"}', '{"Net_Worth": 13078893568, "Yield_Rate": 0.0106, "Expense_Net": 0.0009, "Benchmark_Exp": 0.0036, "Turnover_Ratio": 0.17}', '{"volume_metrics": {"Vol_3M": 347374, "Vol_Recent": 317120}, "moving_averages": {"MA_50": 90.746, "MA_200": 85.984}}', '{"asset_allocation": {"Bond_Weight": 0, "Equity_Weight": 1}, "bond_characteristics": {"Avg_Maturity": null, "Duration_Yrs": null}}', '{"valuation_metrics": {"PB_Ratio": 4.89, "PE_Ratio": 26.14, "PS_Ratio": 2.43, "PCF_Ratio": 15.96}}');
INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (852, 'GSP', 'ETF', 'UNITED_STATES', 'Amana Developing World Fund Ins', 'Amana Mutual Funds Trust Developing World Fund Institutional', 'usd', NULL, NULL, 'Amana', 'PCX', 'Commodities Broad Basket', 20610176, NULL, '2006-06-06', NULL, 'The investment seeks long-term capital growth, consistent with Islamic principles. The fund invests only in common stocks of companies with significant exposure (50% or more of production assets, or revenues) to countries with developing economies and/or markets. Investment decisions are made in accordance with Islamic principles. It diversifies its investments across the industries, companies, and countries of the developing world, and principally follows a large-cap value investment style.', 0.0075, 0.0081, 6712, 13500, 17.003, 15.158, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '{"Cap_Size": null, "Quote_Mode": "ETF", "Currency_Base": "usd", "GeoZone_Class": "UNITED_STATES", "Strategy_Type": null}', '{"Net_Worth": 20610176, "Yield_Rate": null, "Expense_Net": 0.0075, "Benchmark_Exp": 0.0081, "Turnover_Ratio": null}', '{"volume_metrics": {"Vol_3M": 6712, "Vol_Recent": 13500}, "moving_averages": {"MA_50": 17.003, "MA_200": 15.158}}', '{"asset_allocation": {"Bond_Weight": null, "Equity_Weight": null}, "bond_characteristics": {"Avg_Maturity": null, "Duration_Yrs": null}}', '{"valuation_metrics": {"PB_Ratio": null, "PE_Ratio": null, "PS_Ratio": null, "PCF_Ratio": null}}');
INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (910, 'HSCZ', 'ETF', 'USA', 'AQR International Defensive Sty', 'AQR International Defensive Style Fund Class R6', 'DOLLAR', 'Blend', 'Medium', 'AQR Funds', 'PCX', 'Foreign Small/Mid Blend', 94722592, 0.0129, '2015-06-29', 0.09, 'The investment seeks total return. The fund pursues a "defensive" investment style, seeking to provide downside protection with upside potential through active stock selection, risk management and diversification. It pursues its objective by investing, under normal market conditions, at least 80% of its net assets (including any borrowings for investment purposes) in Equity Instruments of International Issuers.', 0.0043, 0.0034, 10588, 12880, 37.409, 36.466, NULL, NULL, 1.57, 9.62, 18.82, 1.09, NULL, NULL, '{"Cap_Size": "Medium", "Quote_Mode": "ETF", "Currency_Base": "DOLLAR", "GeoZone_Class": "USA", "Strategy_Type": "Blend"}', '{"Net_Worth": 94722592, "Yield_Rate": 0.0129, "Expense_Net": 0.0043, "Benchmark_Exp": 0.0034, "Turnover_Ratio": 0.09}', '{"volume_metrics": {"Vol_3M": 10588, "Vol_Recent": 12880}, "moving_averages": {"MA_50": 37.409, "MA_200": 36.466}}', '{"asset_allocation": {"Bond_Weight": null, "Equity_Weight": null}, "bond_characteristics": {"Avg_Maturity": null, "Duration_Yrs": null}}', '{"valuation_metrics": {"PB_Ratio": 1.57, "PE_Ratio": 18.82, "PS_Ratio": 1.09, "PCF_Ratio": 9.62}}');
INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (854, 'GSSC', 'ETF', 'United States', 'Amana Income Fund Institutional', 'Amana Mutual Funds Trust Income Fund Institutional', 'US_DOLLAR', 'Blend', 'Small', 'Amana', 'PCX', 'Small Blend', 428315104, 0.0074, '2017-06-28', 0.2, 'The investment seeks current income and preservation of capital, consistent with Islamic principles; current income is its primary objective. The fund normally invests at least 80% of its total net assets in income-producing securities, primarily dividend-paying common stocks. It invests primarily in dividend-paying common stocks, including foreign stocks. Investment decisions are made in accordance with Islamic principles. The fund diversifies its investments across industries and companies, and principally follows a large-cap value investment style.', 0.002, 0.004, 29741, 43600, 66.452, 64.228, 1, 0, 2.43, 9.96, 16.32, 1.25, NULL, NULL, '{"Cap_Size": "Small", "Quote_Mode": "ETF", "Currency_Base": "US_DOLLAR", "GeoZone_Class": "United States", "Strategy_Type": "Blend"}', '{"Net_Worth": 428315104, "Yield_Rate": 0.0074, "Expense_Net": 0.002, "Benchmark_Exp": 0.004, "Turnover_Ratio": 0.2}', '{"volume_metrics": {"Vol_3M": 29741, "Vol_Recent": 43600}, "moving_averages": {"MA_50": 66.452, "MA_200": 64.228}}', '{"asset_allocation": {"Bond_Weight": 0, "Equity_Weight": 1}, "bond_characteristics": {"Avg_Maturity": null, "Duration_Yrs": null}}', '{"valuation_metrics": {"PB_Ratio": 2.43, "PE_Ratio": 16.32, "PS_Ratio": 1.25, "PCF_Ratio": 9.96}}');
INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (855, 'GSST', 'ETF', 'US', 'Amana Participation Fund Instit', 'Amana Participation Fund Institutional Shares', 'Dollar', 'Value', 'Medium', 'Amana', 'BTS', NULL, 271456224, 0.0077, '2019-04-15', 0.63, 'The investment seeks capital preservation and current income, consistent with Islamic principles; capital preservation is its primary objective. Under normal conditions, the fund invests at least 80% of its total net assets in short and intermediate-term Islamic income-producing investments. It invests at least 65% of its assets in securities rated within the four highest grades (Aaa, Aa, A, Baa) by a nationally-recognized rating agency and may invest up to 35% in unrated and high-yield notes and certificates, which may be considered equivalent to "junk bonds". The fund is non-diversified.', 0.0016, NULL, 37351, 50170, 50.626, 50.706, NULL, NULL, NULL, NULL, NULL, NULL, 10.27, 0.71, '{"Cap_Size": "Medium", "Quote_Mode": "ETF", "Currency_Base": "Dollar", "GeoZone_Class": "US", "Strategy_Type": "Value"}', '{"Net_Worth": 271456224, "Yield_Rate": 0.0077, "Expense_Net": 0.0016, "Benchmark_Exp": null, "Turnover_Ratio": 0.63}', '{"volume_metrics": {"Vol_3M": 37351, "Vol_Recent": 50170}, "moving_averages": {"MA_50": 50.626, "MA_200": 50.706}}', '{"asset_allocation": {"Bond_Weight": null, "Equity_Weight": null}, "bond_characteristics": {"Avg_Maturity": 10.27, "Duration_Yrs": 0.71}}', '{"valuation_metrics": {"PB_Ratio": null, "PE_Ratio": null, "PS_Ratio": null, "PCF_Ratio": null}}');
INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (856, 'GSUS', 'ETF', 'US', 'American Century Emerging Marke', 'American Century Emerging Markets Fund I Class', 'Usd', 'Blend', 'Large', 'American Century Investments', 'BTS', 'Large Blend', 400820544, 0.0125, '2020-05-12', 0.01, 'The investment seeks capital growth. The fund invests at least 80% of its net assets in equity securities of companies located in emerging market countries. The manager considers an emerging market country to be any country other than a developed country. The fund invests in securities denominated in foreign currencies and in foreign securities that are represented in the U.S. securities markets by American Depositary Receipts (ADRs) or similar depositary arrangements.', 0.0007, 0.0036, 12816, 27040, 63.203, 59.855, 1, 0, 4.62, 18, 26.84, 3.04, NULL, NULL, '{"Cap_Size": "Large", "Quote_Mode": "ETF", "Currency_Base": "Usd", "GeoZone_Class": "US", "Strategy_Type": "Blend"}', '{"Net_Worth": 400820544, "Yield_Rate": 0.0125, "Expense_Net": 0.0007, "Benchmark_Exp": 0.0036, "Turnover_Ratio": 0.01}', '{"volume_metrics": {"Vol_3M": 12816, "Vol_Recent": 27040}, "moving_averages": {"MA_50": 63.203, "MA_200": 59.855}}', '{"asset_allocation": {"Bond_Weight": 0, "Equity_Weight": 1}, "bond_characteristics": {"Avg_Maturity": null, "Duration_Yrs": null}}', '{"valuation_metrics": {"PB_Ratio": 4.62, "PE_Ratio": 26.84, "PS_Ratio": 3.04, "PCF_Ratio": 18}}');
INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (1126, 'KBND', 'ETF', 'US', 'Ariel Focus Fund Investor Cl', 'Ariel Focus Fund Investor Class', 'DOLLAR', NULL, NULL, 'Ariel Investments', 'PCX', 'Emerging-Markets Local-Currency Bond', 12175437, 0.0237, '2014-12-02', NULL, 'The investment seeks long-term capital appreciation. The fund invests primarily in equity securities of companies of any size in order to provide investors access to superior opportunities in companies of all market capitalizations. The essence of the fund''s strategy is a combination of patience and stock selection. The fund seeks to hold investments for a relatively long period of time-generally three to five years or more. It is non-diversified.', 0.0058, 0.0055, 1401, 480, 35.131, 35.031, NULL, NULL, NULL, NULL, NULL, NULL, 3.92, NULL, '{"Cap_Size": null, "Quote_Mode": "ETF", "Currency_Base": "DOLLAR", "GeoZone_Class": "US", "Strategy_Type": null}', '{"Net_Worth": 12175437, "Yield_Rate": 0.0237, "Expense_Net": 0.0058, "Benchmark_Exp": 0.0055, "Turnover_Ratio": null}', '{"volume_metrics": {"Vol_3M": 1401, "Vol_Recent": 480}, "moving_averages": {"MA_50": 35.131, "MA_200": 35.031}}', '{"asset_allocation": {"Bond_Weight": null, "Equity_Weight": null}, "bond_characteristics": {"Avg_Maturity": 3.92, "Duration_Yrs": null}}', '{"valuation_metrics": {"PB_Ratio": null, "PE_Ratio": null, "PS_Ratio": null, "PCF_Ratio": null}}');
INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (858, 'GTIP', 'ETF', 'USA', 'MainGate MLP Fund Class A', 'MainGate MLP Fund Class A', 'US$', NULL, NULL, 'MainGate Trust', 'BTS', 'Inflation-Protected Bond', 103947792, 0.0164, '2018-10-02', 0.43, 'The investment seeks total return. The fund seeks to generate total return, comprised of capital appreciation and income, by investing in master limited partnership interests. It seeks to achieve its investment objective by investing at least 80% of its net assets (plus borrowings for investment purposes) in MLP interests under normal circumstances. MLPs are publicly traded partnerships primarily engaged in the transportation, storage, processing, refining, marketing, exploration, production, and mining of minerals and natural resources. Under normal circumstances, the fund concentrates its investments in MLPs in the energy sector. It is non-diversified.', 0.0012, 0.0016, 30461, 40800, 58.324, 57.733, 0, 0.9986, NULL, NULL, NULL, NULL, 7.98, 7.66, '{"Cap_Size": null, "Quote_Mode": "ETF", "Currency_Base": "US$", "GeoZone_Class": "USA", "Strategy_Type": null}', '{"Net_Worth": 103947792, "Yield_Rate": 0.0164, "Expense_Net": 0.0012, "Benchmark_Exp": 0.0016, "Turnover_Ratio": 0.43}', '{"volume_metrics": {"Vol_3M": 30461, "Vol_Recent": 40800}, "moving_averages": {"MA_50": 58.324, "MA_200": 57.733}}', '{"asset_allocation": {"Bond_Weight": 0.9986, "Equity_Weight": 0}, "bond_characteristics": {"Avg_Maturity": 7.98, "Duration_Yrs": 7.66}}', '{"valuation_metrics": {"PB_Ratio": null, "PE_Ratio": null, "PS_Ratio": null, "PCF_Ratio": null}}');
