INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (871, 'HAP', 'ETF', 'usa', 'American Growth Fund, Inc. - Cl', 'American Growth Fund Series One Class C', 'DOLLAR', 'Value', 'Large', 'American Growth', 'PCX', 'Natural Resources', 76142640, 0.0205, '2008-08-29', 0.26, 'The investment seeks growth of capital. The fund uses a consistent approach to build the fund''s security portfolio which is made up primarily of common stocks and securities convertible into common stock. These securities are issued by large companies, and to a lesser extent, small and mid-sized companies. When a company''s fundamentals are strong, the managers believe earnings growth will follow.', 0.0049, 0.0048, 10111, 3620, 47.425, 46.324, 0.9981, 0, 1.94, 9.33, 18.86, 1.24, NULL, NULL, '{"Cap_Size": "Large", "Quote_Mode": "ETF", "Currency_Base": "DOLLAR", "GeoZone_Class": "usa", "Strategy_Type": "Value"}', '{"Net_Worth": 76142640, "Yield_Rate": 0.0205, "Expense_Net": 0.0049, "Benchmark_Exp": 0.0048, "Turnover_Ratio": 0.26}', '{"volume_metrics": {"Vol_3M": 10111, "Vol_Recent": 3620}, "moving_averages": {"MA_50": 47.425, "MA_200": 46.324}}', '{"asset_allocation": {"Bond_Weight": 0, "Equity_Weight": 0.9981}, "bond_characteristics": {"Avg_Maturity": null, "Duration_Yrs": null}}', '{"valuation_metrics": {"PB_Ratio": 1.94, "PE_Ratio": 18.86, "PS_Ratio": 1.24, "PCF_Ratio": 9.33}}');
