INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (876, 'HDAW', 'ETF', 'usa', 'AB Bond Fund, Inc. - AB All Mar', 'AB All Market Real Return Portfolio Class A', 'Dollar', 'Value', 'Large', 'AllianceBernstein', 'PCX', 'Foreign Large Value', 24533348, 0.0467, '2015-08-12', 0.4, 'The investment seeks to maximize real return over inflation. The managers expect to invest its assets principally in the following instruments that, in the judgment of the Adviser, are affected directly or indirectly by the level and change in rate of inflation: inflation-indexed fixed-income securities, such as TIPS and similar bonds issued by governments outside of the United States; commodities; commodity-related equity securities; real estate equity securities; inflation sensitive equity securities; securities and derivatives linked to the price of other assets; and currencies. It is non-diversified.', 0.002, 0.0046, 3541, 2540, 24.696, 25.611, NULL, NULL, 1.71, 8.55, 13.75, 1.2, NULL, NULL, '{"Cap_Size": "Large", "Quote_Mode": "ETF", "Currency_Base": "Dollar", "GeoZone_Class": "usa", "Strategy_Type": "Value"}', '{"Net_Worth": 24533348, "Yield_Rate": 0.0467, "Expense_Net": 0.002, "Benchmark_Exp": 0.0046, "Turnover_Ratio": 0.4}', '{"volume_metrics": {"Vol_3M": 3541, "Vol_Recent": 2540}, "moving_averages": {"MA_50": 24.696, "MA_200": 25.611}}', '{"asset_allocation": {"Bond_Weight": null, "Equity_Weight": null}, "bond_characteristics": {"Avg_Maturity": null, "Duration_Yrs": null}}', '{"valuation_metrics": {"PB_Ratio": 1.71, "PE_Ratio": 13.75, "PS_Ratio": 1.2, "PCF_Ratio": 8.55}}');
