INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (902, 'HJPX', 'ETF', 'U.S.', 'AB Bond Fund, Inc. - AB Bond In', 'AB Bond Inflation Strategy Class I', 'usd', 'Blend', 'Large', 'AllianceBernstein', 'PCX', 'Japan Stock', 3505979, 0.0116, '2015-09-29', 0.08, 'The investment seeks to maximize real return without assuming what the Adviser considers to be undue risk. The fund pursues its objective by investing principally in inflation-indexed securities (such as Treasury Inflation-Protected Securities ("TIPS") or inflation-indexed securities from issuers other than the U.S. Treasury) or by gaining inflation protection through derivatives transactions, such as inflation (CPI) swaps or total return swaps linked to TIPS. Under normal circumstances, it invests at least 80% of its net assets in fixed-income securities.', 0.0048, 0.004, 577, 280, 36.22, 35.284, NULL, NULL, 1.43, 9.42, 17.46, 1.08, NULL, NULL, '{"Cap_Size": "Large", "Quote_Mode": "ETF", "Currency_Base": "usd", "GeoZone_Class": "U.S.", "Strategy_Type": "Blend"}', '{"Net_Worth": 3505979, "Yield_Rate": 0.0116, "Expense_Net": 0.0048, "Benchmark_Exp": 0.004, "Turnover_Ratio": 0.08}', '{"volume_metrics": {"Vol_3M": 577, "Vol_Recent": 280}, "moving_averages": {"MA_50": 36.22, "MA_200": 35.284}}', '{"asset_allocation": {"Bond_Weight": null, "Equity_Weight": null}, "bond_characteristics": {"Avg_Maturity": null, "Duration_Yrs": null}}', '{"valuation_metrics": {"PB_Ratio": 1.43, "PE_Ratio": 17.46, "PS_Ratio": 1.08, "PCF_Ratio": 9.42}}');
INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (903, 'HKND', 'ETF', 'usa', 'Fundamental Investors, Class A ', 'American Funds Fundamental Investors Class A', 'USD', 'Value', 'Large', 'American Funds', 'PCX', NULL, 66569064, NULL, '2021-02-24', NULL, 'The investment seeks long-term growth of capital and income. The fund invests primarily in common stocks of companies that appear to offer superior opportunities for capital growth and most of which have a history of paying dividends. It may invest significantly in securities of issuers domiciled outside the United States. The investment adviser uses a system of multiple portfolio managers in managing the fund''s assets.', 0.0011, NULL, 6932, 1120, 28.444, 27.58, 0.9989, 0, 3.6, 10.91, 22.52, 1.32, NULL, NULL, '{"Cap_Size": "Large", "Quote_Mode": "ETF", "Currency_Base": "USD", "GeoZone_Class": "usa", "Strategy_Type": "Value"}', '{"Net_Worth": 66569064, "Yield_Rate": null, "Expense_Net": 0.0011, "Benchmark_Exp": null, "Turnover_Ratio": null}', '{"volume_metrics": {"Vol_3M": 6932, "Vol_Recent": 1120}, "moving_averages": {"MA_50": 28.444, "MA_200": 27.58}}', '{"asset_allocation": {"Bond_Weight": 0, "Equity_Weight": 0.9989}, "bond_characteristics": {"Avg_Maturity": null, "Duration_Yrs": null}}', '{"valuation_metrics": {"PB_Ratio": 3.6, "PE_Ratio": 22.52, "PS_Ratio": 1.32, "PCF_Ratio": 10.91}}');
INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (904, 'HLAL', 'ETF', 'US', 'Ancora Microcap Fund Class I', 'Ancora MicroCap Fund Class I', 'DOLLAR', 'Blend', 'Large', 'Ancora', 'NGM', 'Large Blend', 116635472, 0.0101, '2019-07-15', NULL, 'The investment seeks capital appreciation. Under normal circumstances, the fund invests at least 80% of the assets in equity securities of companies whose equity securities have a total market value of under $700,000,000. Equity securities consist of common stock, preferred stock and securities convertible into common or preferred stock. It emphasizes a "value" style of investing. In deciding which securities to buy and which to sell, the Advisor will give primary consideration to fundamental factors.', 0.005, 0.0036, 20751, 24390, 40.044, 37.809, 1, 0, 5.1, 18.1, 29.37, 2.89, NULL, NULL, '{"Cap_Size": "Large", "Quote_Mode": "ETF", "Currency_Base": "DOLLAR", "GeoZone_Class": "US", "Strategy_Type": "Blend"}', '{"Net_Worth": 116635472, "Yield_Rate": 0.0101, "Expense_Net": 0.005, "Benchmark_Exp": 0.0036, "Turnover_Ratio": null}', '{"volume_metrics": {"Vol_3M": 20751, "Vol_Recent": 24390}, "moving_averages": {"MA_50": 40.044, "MA_200": 37.809}}', '{"asset_allocation": {"Bond_Weight": 0, "Equity_Weight": 1}, "bond_characteristics": {"Avg_Maturity": null, "Duration_Yrs": null}}', '{"valuation_metrics": {"PB_Ratio": 5.1, "PE_Ratio": 29.37, "PS_Ratio": 2.89, "PCF_Ratio": 18.1}}');
INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (905, 'HLGE', 'ETF', 'us', 'AllianzGI Convertible Class P', 'Virtus AllianzGI Convertible Fund Class P', 'AmericanDollar', 'Blend', 'Medium', 'Virtus', 'PCX', 'Mid-Cap Blend', 25308960, NULL, '2021-03-16', NULL, 'The investment seeks maximum total return, consisting of capital appreciation and current income. The fund seeks to achieve its objective by normally investing at least 80% of its net assets (plus borrowings made for investment purposes) in convertible securities. Convertible securities include, but are not limited to, corporate bonds, debentures, notes or preferred stocks and their hybrids that can be converted into (exchanged for) equity securities or other securities (such as warrants or options) that provide an opportunity for equity participation.', 0.0044, 0.0047, 356, 280, 27.304, 26.571, 0.9986, 0, 3.59, 11.89, 20.03, 1.42, NULL, NULL, '{"Cap_Size": "Medium", "Quote_Mode": "ETF", "Currency_Base": "AmericanDollar", "GeoZone_Class": "us", "Strategy_Type": "Blend"}', '{"Net_Worth": 25308960, "Yield_Rate": null, "Expense_Net": 0.0044, "Benchmark_Exp": 0.0047, "Turnover_Ratio": null}', '{"volume_metrics": {"Vol_3M": 356, "Vol_Recent": 280}, "moving_averages": {"MA_50": 27.304, "MA_200": 26.571}}', '{"asset_allocation": {"Bond_Weight": 0, "Equity_Weight": 0.9986}, "bond_characteristics": {"Avg_Maturity": null, "Duration_Yrs": null}}', '{"valuation_metrics": {"PB_Ratio": 3.59, "PE_Ratio": 20.03, "PS_Ratio": 1.42, "PCF_Ratio": 11.89}}');
INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (1032, 'IUS', 'ETF', 'US', 'Artisan Focus Fund Institutiona', 'Artisan Focus Fund Institutional Shares', 'US_DOLLAR', 'Value', 'Large', 'Artisan', 'NGM', 'Large Value', 180727904, 0.0146, '2018-09-12', 0.15, 'The investment seeks maximum long-term capital appreciation. The fund''s investment approach is based on thematic idea generation, a systematic framework for analyzing companies and proactive risk management. It may invest up to 50% of its total assets at market value at the time of purchase in securities of non-U.S. companies (including depositary receipts). The fund is non-diversified.', 0.0019, 0.0034, 11132, 15310, 38.563, 37.191, 0.9995, 0, 3.32, 11.53, 20.54, 1.21, NULL, NULL, '{"Cap_Size": "Large", "Quote_Mode": "ETF", "Currency_Base": "US_DOLLAR", "GeoZone_Class": "US", "Strategy_Type": "Value"}', '{"Net_Worth": 180727904, "Yield_Rate": 0.0146, "Expense_Net": 0.0019, "Benchmark_Exp": 0.0034, "Turnover_Ratio": 0.15}', '{"volume_metrics": {"Vol_3M": 11132, "Vol_Recent": 15310}, "moving_averages": {"MA_50": 38.563, "MA_200": 37.191}}', '{"asset_allocation": {"Bond_Weight": 0, "Equity_Weight": 0.9995}, "bond_characteristics": {"Avg_Maturity": null, "Duration_Yrs": null}}', '{"valuation_metrics": {"PB_Ratio": 3.32, "PE_Ratio": 20.54, "PS_Ratio": 1.21, "PCF_Ratio": 11.53}}');
INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (907, 'HNDL', 'ETF', 'UNITED_STATES', 'NT Disciplined Growth Fund - G ', 'American Century NT Disciplined Growth Fund G Class', 'DOLLAR', 'Blend', 'Large', 'American Century Investments', 'NGM', 'Allocation--15% to 30% Equity', 693417600, 0.0685, '2018-01-16', NULL, 'The investment seeks long-term capital growth. The portfolio managers initially identify an eligible universe of growth stocks then use quantitative and qualitative management techniques in a multi-step process. The managers rank stocks, primarily large capitalization, publicly traded U.S. companies from most attractive to least attractive based on an objective set of measures, including valuation, quality, growth, and sentiment. The portfolio managers use a quantitative model to build a portfolio of stocks from the ranking that they believe will provide the optimal balance between risk and expected return.', 0.0117, 0.0094, 642462, 555440, 25.591, 25.399, NULL, NULL, 4.27, 13.72, 25.64, 2.71, 7.98, 6.14, '{"Cap_Size": "Large", "Quote_Mode": "ETF", "Currency_Base": "DOLLAR", "GeoZone_Class": "UNITED_STATES", "Strategy_Type": "Blend"}', '{"Net_Worth": 693417600, "Yield_Rate": 0.0685, "Expense_Net": 0.0117, "Benchmark_Exp": 0.0094, "Turnover_Ratio": null}', '{"volume_metrics": {"Vol_3M": 642462, "Vol_Recent": 555440}, "moving_averages": {"MA_50": 25.591, "MA_200": 25.399}}', '{"asset_allocation": {"Bond_Weight": null, "Equity_Weight": null}, "bond_characteristics": {"Avg_Maturity": 7.98, "Duration_Yrs": 6.14}}', '{"valuation_metrics": {"PB_Ratio": 4.27, "PE_Ratio": 25.64, "PS_Ratio": 2.71, "PCF_Ratio": 13.72}}');
INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (911, 'HSMV', 'ETF', 'America', 'AllianzGI Dividend Value Fund C', 'Virtus NFJ Dividend Value Fund Class R6', 'usd', 'Blend', 'Small', 'Virtus', 'PCX', 'Small Blend', 14562346, 0.0091, '2020-04-06', 0.05, 'The investment seeks long-term growth of capital and income. The fund seeks to achieve its investment objective by normally investing at least 80% of its net assets (plus borrowings made for investment purposes) in common stocks and other equity securities of companies that pay or are expected to pay dividends. Under normal conditions, it will invest primarily in common stocks of companies with market capitalizations greater than $3.5 billion.', 0.008, 0.004, 943, 1000, 33.471, 32.625, NULL, NULL, 2.71, 13.19, 22.86, 1.7, NULL, NULL, '{"Cap_Size": "Small", "Quote_Mode": "ETF", "Currency_Base": "usd", "GeoZone_Class": "America", "Strategy_Type": "Blend"}', '{"Net_Worth": 14562346, "Yield_Rate": 0.0091, "Expense_Net": 0.008, "Benchmark_Exp": 0.004, "Turnover_Ratio": 0.05}', '{"volume_metrics": {"Vol_3M": 943, "Vol_Recent": 1000}, "moving_averages": {"MA_50": 33.471, "MA_200": 32.625}}', '{"asset_allocation": {"Bond_Weight": null, "Equity_Weight": null}, "bond_characteristics": {"Avg_Maturity": null, "Duration_Yrs": null}}', '{"valuation_metrics": {"PB_Ratio": 2.71, "PE_Ratio": 22.86, "PS_Ratio": 1.7, "PCF_Ratio": 13.19}}');
INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (1311, 'NUSA', 'ETF', 'U.S.', 'American Century Small Cap Valu', 'American Century Small Cap Value Fund C Class', 'Dollar', NULL, NULL, 'American Century Investments', 'PCX', 'Short-Term Bond', 40378372, 0.0236, '2017-03-31', 0.51, 'The investment seeks long-term capital growth; income is a secondary consideration. Under normal market conditions, the portfolio managers will invest at least 80% of the fund''s net assets in small cap companies. The portfolio managers consider small cap companies to include those with market capitalizations no larger than that of the largest company in the S&P Small Cap 600© Index or the Russell 2000© Index.', 0.002, 0.0026, 9898, 6650, 24.944, 25.189, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '{"Cap_Size": null, "Quote_Mode": "ETF", "Currency_Base": "Dollar", "GeoZone_Class": "U.S.", "Strategy_Type": null}', '{"Net_Worth": 40378372, "Yield_Rate": 0.0236, "Expense_Net": 0.002, "Benchmark_Exp": 0.0026, "Turnover_Ratio": 0.51}', '{"volume_metrics": {"Vol_3M": 9898, "Vol_Recent": 6650}, "moving_averages": {"MA_50": 24.944, "MA_200": 25.189}}', '{"asset_allocation": {"Bond_Weight": null, "Equity_Weight": null}, "bond_characteristics": {"Avg_Maturity": null, "Duration_Yrs": null}}', '{"valuation_metrics": {"PB_Ratio": null, "PE_Ratio": null, "PS_Ratio": null, "PCF_Ratio": null}}');
