INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (921, 'HYDB', 'ETF', 'usa', 'Angel Oak High Yield Opportunit', 'Angel Oak High Yield Opportunities Fund Class A', 'usd', NULL, NULL, 'Angel Oak', 'BTS', 'High Yield Bond', 137517392, 0.054, '2017-07-11', 0.67, 'The investment seeks to earn a high level of current income; capital appreciation is a secondary objective. In pursuing its objective, the fund normally invests at least 80% of its net assets, plus any borrowings for investment purposes, in below investment grade bonds of corporate issuers. These "high yield" securities (also known as "junk bonds") will generally be rated BB or lower by Standard & Poor''s Rating Group ("S&P") or will be of equivalent quality rating from another Nationally Recognized Statistical Ratings Organization.', 0.0035, 0.0047, 21751, 23170, 51.487, 51.571, NULL, NULL, NULL, NULL, NULL, NULL, 4.44, 3.64, '{"Cap_Size": null, "Quote_Mode": "ETF", "Currency_Base": "usd", "GeoZone_Class": "usa", "Strategy_Type": null}', '{"Net_Worth": 137517392, "Yield_Rate": 0.054, "Expense_Net": 0.0035, "Benchmark_Exp": 0.0047, "Turnover_Ratio": 0.67}', '{"volume_metrics": {"Vol_3M": 21751, "Vol_Recent": 23170}, "moving_averages": {"MA_50": 51.487, "MA_200": 51.571}}', '{"asset_allocation": {"Bond_Weight": null, "Equity_Weight": null}, "bond_characteristics": {"Avg_Maturity": 4.44, "Duration_Yrs": 3.64}}', '{"valuation_metrics": {"PB_Ratio": null, "PE_Ratio": null, "PS_Ratio": null, "PCF_Ratio": null}}');
