INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (923, 'HYEM', 'ETF', 'U.S.A.', 'Sanford C. Bernstein Fund, Inc.', 'AB Intermediate New York Municipal Portfolio Class A', 'Usd', NULL, NULL, 'AllianceBernstein', 'PCX', 'Emerging Markets Bond', 1215785728, 0.0522, '2012-05-08', 0.31, 'The investment seeks to provide safety of principal and maximize total return after taking account of federal, state and local taxes for New York residents. The fund invests at least 80% of its net assets in a portfolio of municipal securities issued by the State of New York or its political subdivisions, or otherwise exempt from New York state income tax. It invests at least 80% of its total assets in municipal securities rated A, or better by national rating agencies, and comparably rated municipal notes. The fund is non-diversified.', 0.004, 0.0046, 299137, 302640, 22.756, 23.464, NULL, NULL, NULL, NULL, NULL, NULL, 7.98, 3.63, '{"Cap_Size": null, "Quote_Mode": "ETF", "Currency_Base": "Usd", "GeoZone_Class": "U.S.A.", "Strategy_Type": null}', '{"Net_Worth": 1215785728, "Yield_Rate": 0.0522, "Expense_Net": 0.004, "Benchmark_Exp": 0.0046, "Turnover_Ratio": 0.31}', '{"volume_metrics": {"Vol_3M": 299137, "Vol_Recent": 302640}, "moving_averages": {"MA_50": 22.756, "MA_200": 23.464}}', '{"asset_allocation": {"Bond_Weight": null, "Equity_Weight": null}, "bond_characteristics": {"Avg_Maturity": 7.98, "Duration_Yrs": 3.63}}', '{"valuation_metrics": {"PB_Ratio": null, "PE_Ratio": null, "PS_Ratio": null, "PCF_Ratio": null}}');
INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (1171, 'LD', 'ETF', 'USA', 'Aristotle Small Cap Equity Fund', 'Aristotle Small Cap Equity Fund Class I', 'AmericanDollar', NULL, NULL, 'Aristotle', 'PCX', NULL, 738678, NULL, '2008-06-24', NULL, 'The investment seeks long-term capital appreciation. Under normal circumstances, the fund invests at least 80% of its net assets (including amounts borrowed for investment purposes) in equity securities of small capitalization companies. Aristotle Capital Boston, LLC, the fund''s Advisor, considers small capitalization companies to be those companies that, at the time of initial purchase, have a market capitalization equal to or less than that of the largest company in the Russell 2000© Index during the most recent 12-month period.', 0.0075, NULL, 198, 120, 47.823, 45.587, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '{"Cap_Size": null, "Quote_Mode": "ETF", "Currency_Base": "AmericanDollar", "GeoZone_Class": "USA", "Strategy_Type": null}', '{"Net_Worth": 738678, "Yield_Rate": null, "Expense_Net": 0.0075, "Benchmark_Exp": null, "Turnover_Ratio": null}', '{"volume_metrics": {"Vol_3M": 198, "Vol_Recent": 120}, "moving_averages": {"MA_50": 47.823, "MA_200": 45.587}}', '{"asset_allocation": {"Bond_Weight": null, "Equity_Weight": null}, "bond_characteristics": {"Avg_Maturity": null, "Duration_Yrs": null}}', '{"valuation_metrics": {"PB_Ratio": null, "PE_Ratio": null, "PS_Ratio": null, "PCF_Ratio": null}}');
