INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (925, 'HYHG', 'ETF', 'USA', 'AB Municipal Income Fund II - N', 'AB Municipal Income Fund II New Jersey Portfolio Class A', 'AmericanDollar', NULL, NULL, 'AllianceBernstein', 'BTS', 'Nontraditional Bond', 110355544, 0.0483, '2013-05-21', NULL, 'The investment seeks to earn the highest level of current income exempt from both federal income tax and State of New Jersey personal income tax that is available without assuming what the Adviser considers to be undue risk. The fund invests at least 80% of its net assets in municipal securities that pay interest that is exempt from federal income tax. These securities may pay interest that is subject to the federal alternative minimum tax ("AMT") for certain taxpayers. It invests at least 80% of its net assets in municipal securities of New Jersey or municipal securities with interest that is otherwise exempt from New Jersey state income tax.', 0.0051, 0.0059, 12762, 23120, 62.712, 62.699, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '{"Cap_Size": null, "Quote_Mode": "ETF", "Currency_Base": "AmericanDollar", "GeoZone_Class": "USA", "Strategy_Type": null}', '{"Net_Worth": 110355544, "Yield_Rate": 0.0483, "Expense_Net": 0.0051, "Benchmark_Exp": 0.0059, "Turnover_Ratio": null}', '{"volume_metrics": {"Vol_3M": 12762, "Vol_Recent": 23120}, "moving_averages": {"MA_50": 62.712, "MA_200": 62.699}}', '{"asset_allocation": {"Bond_Weight": null, "Equity_Weight": null}, "bond_characteristics": {"Avg_Maturity": null, "Duration_Yrs": null}}', '{"valuation_metrics": {"PB_Ratio": null, "PE_Ratio": null, "PS_Ratio": null, "PCF_Ratio": null}}');
