INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (940, 'IBBJ', 'ETF', 'United States', 'AllianzGI Mid-Cap Value Fund Cl', 'Virtus NFJ Mid-Cap Value Fund Class R6', 'US$', 'Growth', 'Small', 'Virtus', 'NGM', 'Health', 8242210, NULL, '2020-08-03', NULL, 'The investment seeks long-term growth of capital and income. The fund seeks to achieve its investment objective by normally investing at least 80% of its net assets (plus borrowings made for investment purposes) in common stocks and other equity securities of companies with medium market capitalizations. It normally invests significantly in securities that the portfolio managers expect will generate income (for example, by paying dividends). The portfolio managers use a value investing style focusing on companies whose securities the portfolio managers believe have attractive valuation and fundamental strength.', 0.0045, 0.0049, 2666, 3130, 29.334, 31.229, 0.9964, 0, 4.67, NULL, NULL, 1.94, NULL, NULL, '{"Cap_Size": "Small", "Quote_Mode": "ETF", "Currency_Base": "US$", "GeoZone_Class": "United States", "Strategy_Type": "Growth"}', '{"Net_Worth": 8242210, "Yield_Rate": null, "Expense_Net": 0.0045, "Benchmark_Exp": 0.0049, "Turnover_Ratio": null}', '{"volume_metrics": {"Vol_3M": 2666, "Vol_Recent": 3130}, "moving_averages": {"MA_50": 29.334, "MA_200": 31.229}}', '{"asset_allocation": {"Bond_Weight": 0, "Equity_Weight": 0.9964}, "bond_characteristics": {"Avg_Maturity": null, "Duration_Yrs": null}}', '{"valuation_metrics": {"PB_Ratio": 4.67, "PE_Ratio": null, "PS_Ratio": 1.94, "PCF_Ratio": null}}');
INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (941, 'IBBQ', 'ETF', 'US', 'NT Global Real Estate - Investo', 'American Century NT Global Real Estate Fund Investor Class', 'Usd', 'Growth', 'Medium', 'American Century Investments', 'NGM', 'Health', 65236412, NULL, '2021-06-09', NULL, 'The investment seeks high total investment return through a combination of capital appreciation and current income. The fund invests at least 80% of its net assets in equity securities issued by real estate investment trusts and other companies engaged in the real estate industry. The portfolio managers consider a company to be engaged in the real estate industry if at least 50% of its revenues or 50% of the market value of its assets at the time the securities are purchased by the fund are attributed to the ownership, construction, management or sale of real estate.', 0.0019, 0.0049, 15390, 16270, 24.852, 25.639, 0.9996, 0, 6, 16.55, 28.45, 3.4, NULL, NULL, '{"Cap_Size": "Medium", "Quote_Mode": "ETF", "Currency_Base": "Usd", "GeoZone_Class": "US", "Strategy_Type": "Growth"}', '{"Net_Worth": 65236412, "Yield_Rate": null, "Expense_Net": 0.0019, "Benchmark_Exp": 0.0049, "Turnover_Ratio": null}', '{"volume_metrics": {"Vol_3M": 15390, "Vol_Recent": 16270}, "moving_averages": {"MA_50": 24.852, "MA_200": 25.639}}', '{"asset_allocation": {"Bond_Weight": 0, "Equity_Weight": 0.9996}, "bond_characteristics": {"Avg_Maturity": null, "Duration_Yrs": null}}', '{"valuation_metrics": {"PB_Ratio": 6, "PE_Ratio": 28.45, "PS_Ratio": 3.4, "PCF_Ratio": 16.55}}');
