INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (1100, 'JOET', 'ETF', 'US', 'American Century One Choice 203', 'American Century Investments One Choice 2030 Portfolio R Class', 'usd', 'Growth', 'Large', 'American Century Investments', 'NGM', NULL, 74026920, NULL, '2020-11-17', NULL, 'The investment seeks the highest total return consistent with its asset mix. The fund is a "fund of funds," meaning that it seeks to achieve its objective by investing in other American Century mutual funds (the underlying funds) that represent a variety of asset classes and investment styles. The target date in the fund name (2030) refers to the approximate year an investor plans to retire and likely would stop making new investments in the fund.', 0.0029, NULL, 46508, 106200, 31.511, 29.269, NULL, NULL, 5.01, 19.84, 26.29, 2.93, NULL, NULL, '{"Cap_Size": "Large", "Quote_Mode": "ETF", "Currency_Base": "usd", "GeoZone_Class": "US", "Strategy_Type": "Growth"}', '{"Net_Worth": 74026920, "Yield_Rate": null, "Expense_Net": 0.0029, "Benchmark_Exp": null, "Turnover_Ratio": null}', '{"volume_metrics": {"Vol_3M": 46508, "Vol_Recent": 106200}, "moving_averages": {"MA_50": 31.511, "MA_200": 29.269}}', '{"asset_allocation": {"Bond_Weight": null, "Equity_Weight": null}, "bond_characteristics": {"Avg_Maturity": null, "Duration_Yrs": null}}', '{"valuation_metrics": {"PB_Ratio": 5.01, "PE_Ratio": 26.29, "PS_Ratio": 2.93, "PCF_Ratio": 19.84}}');
