INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (964, 'IDLV', 'ETF', 'usa', 'American Century One Choice Por', 'American Century Investments One Choice Portfolio: Conservative Investor Class', 'US Dollar', 'Blend', 'Large', 'American Century Investments', 'PCX', 'Foreign Large Blend', 747850560, 0.0232, '2012-01-13', NULL, 'The investment seeks the highest total return consistent with its asset mix. The fund invests in other American Century Investments mutual funds (the underlying funds) that represent a variety of asset classes and investment styles. Its asset allocation strategy emphasizes investments in fixed-income securities and short-term investments, but maintains a sizeable portion of the fund''s assets in equity securities. The fund invests 45% of its assets in underlying funds that invest in stocks, 49% of its assets in underlying funds that invest in bonds, and 6% of its assets in underlying funds that invest in cash equivalents.', 0.0025, 0.0037, 54332, 76370, 31.417, 31.229, 0.9985, 0, 1.89, 9.97, 18.81, 1.4, NULL, NULL, '{"Cap_Size": "Large", "Quote_Mode": "ETF", "Currency_Base": "US Dollar", "GeoZone_Class": "usa", "Strategy_Type": "Blend"}', '{"Net_Worth": 747850560, "Yield_Rate": 0.0232, "Expense_Net": 0.0025, "Benchmark_Exp": 0.0037, "Turnover_Ratio": null}', '{"volume_metrics": {"Vol_3M": 54332, "Vol_Recent": 76370}, "moving_averages": {"MA_50": 31.417, "MA_200": 31.229}}', '{"asset_allocation": {"Bond_Weight": 0, "Equity_Weight": 0.9985}, "bond_characteristics": {"Avg_Maturity": null, "Duration_Yrs": null}}', '{"valuation_metrics": {"PB_Ratio": 1.89, "PE_Ratio": 18.81, "PS_Ratio": 1.4, "PCF_Ratio": 9.97}}');
INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (965, 'IDMO', 'ETF', 'US', 'Alger Small Cap Focus Fund Clas', 'Alger Small Cap Focus Fund Class A', 'AmericanDollar', 'Growth', 'Large', 'Alger', 'PCX', 'Foreign Large Growth', 8476011, 0.0158, '2012-02-23', NULL, 'The investment seeks long-term capital appreciation. The fund normally invests at least 80% of its net assets, plus any borrowings for investment purposes, in equity securities of companies that, at the time of purchase of the securities, have total market capitalization between (1) the higher of (a) $5 billion or (b) the company in either the Russell 2000 Growth Index or the MSCI USA Small Cap Index with the highest capitalization, and (2) the company in either index with the lowest capitalization, at any time during the most recent 12-month period as reported by either index. Both indexes are broad-based indexes of small capitalization stocks.', 0.0025, 0.0066, 8498, 1140, 36.78, 34.755, 0.9978, 0, 4.61, 20.24, 25.44, 2.98, NULL, NULL, '{"Cap_Size": "Large", "Quote_Mode": "ETF", "Currency_Base": "AmericanDollar", "GeoZone_Class": "US", "Strategy_Type": "Growth"}', '{"Net_Worth": 8476011, "Yield_Rate": 0.0158, "Expense_Net": 0.0025, "Benchmark_Exp": 0.0066, "Turnover_Ratio": null}', '{"volume_metrics": {"Vol_3M": 8498, "Vol_Recent": 1140}, "moving_averages": {"MA_50": 36.78, "MA_200": 34.755}}', '{"asset_allocation": {"Bond_Weight": 0, "Equity_Weight": 0.9978}, "bond_characteristics": {"Avg_Maturity": null, "Duration_Yrs": null}}', '{"valuation_metrics": {"PB_Ratio": 4.61, "PE_Ratio": 25.44, "PS_Ratio": 2.98, "PCF_Ratio": 20.24}}');
