INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (970, 'IEI', 'ETF', 'UNITED_STATES', 'AllianzGI Focused Growth Fund C', 'Virtus AllianzGI Focused Growth Fund Class P', 'US_DOLLAR', NULL, NULL, 'Virtus', 'NGM', 'Intermediate Government', 10870721536, 0.0084, '2007-01-05', 0.49, 'The investment seeks long-term capital appreciation. The fund seeks to achieve its investment objective by normally investing primarily in equity securities of U.S. companies with market capitalizations of at least $1 billion. It may also invest up to 20% of its assets in non-U.S. securities (but no more than 10% in any one non-U.S. country or 10% in emerging market securities). The fund is non-diversified.', 0.0015, 0.0011, 1051477, 1.82246e+06, 129.32, 130.438, 0, 0.9962, NULL, NULL, NULL, NULL, 4.94, 4.7, '{"Cap_Size": null, "Quote_Mode": "ETF", "Currency_Base": "US_DOLLAR", "GeoZone_Class": "UNITED_STATES", "Strategy_Type": null}', '{"Net_Worth": 10870721536, "Yield_Rate": 0.0084, "Expense_Net": 0.0015, "Benchmark_Exp": 0.0011, "Turnover_Ratio": 0.49}', '{"volume_metrics": {"Vol_3M": 1051477, "Vol_Recent": 1822460}, "moving_averages": {"MA_50": 129.32, "MA_200": 130.438}}', '{"asset_allocation": {"Bond_Weight": 0.9962, "Equity_Weight": 0}, "bond_characteristics": {"Avg_Maturity": 4.94, "Duration_Yrs": 4.7}}', '{"valuation_metrics": {"PB_Ratio": null, "PE_Ratio": null, "PS_Ratio": null, "PCF_Ratio": null}}');
INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (971, 'IEUR', 'ETF', 'United States', 'AB Municipal Income Fund II - O', 'AB Municipal Income Fund II Ohio Portfolio Class A', 'US$', 'Blend', 'Large', 'AllianceBernstein', 'PCX', 'Europe Stock', 5184926208, 0.024, '2014-06-10', 0.03, 'The investment seeks to earn the highest level of current income exempt from both federal income tax and State of Ohio personal income tax that is available without assuming what the Adviser considers to be undue risk. The fund invests at least 80% of its net assets in municipal securities that pay interest that is exempt from federal income tax. These securities may pay interest that is subject to the federal alternative minimum tax ("AMT") for certain taxpayers. It invests at least 80% of its net assets in municipal securities of Ohio or municipal securities with interest that is otherwise exempt from Ohio state income tax.', 0.0009, 0.0044, 748309, 756200, 57.986, 57.347, 0.9925, 0, 2.03, 10.94, 21.28, 1.57, NULL, NULL, '{"Cap_Size": "Large", "Quote_Mode": "ETF", "Currency_Base": "US$", "GeoZone_Class": "United States", "Strategy_Type": "Blend"}', '{"Net_Worth": 5184926208, "Yield_Rate": 0.024, "Expense_Net": 0.0009, "Benchmark_Exp": 0.0044, "Turnover_Ratio": 0.03}', '{"volume_metrics": {"Vol_3M": 748309, "Vol_Recent": 756200}, "moving_averages": {"MA_50": 57.986, "MA_200": 57.347}}', '{"asset_allocation": {"Bond_Weight": 0, "Equity_Weight": 0.9925}, "bond_characteristics": {"Avg_Maturity": null, "Duration_Yrs": null}}', '{"valuation_metrics": {"PB_Ratio": 2.03, "PE_Ratio": 21.28, "PS_Ratio": 1.57, "PCF_Ratio": 10.94}}');
INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (972, 'IEUS', 'ETF', 'United States', 'AB Municipal Income Fund II - O', 'AB Municipal Income Fund II Ohio Portfolio Class C', 'Dollar', 'Blend', 'Medium', 'AllianceBernstein', 'NGM', 'Europe Stock', 369970432, 0.0167, '2007-11-12', 0.2, 'The investment seeks to earn the highest level of current income exempt from both federal income tax and State of Ohio personal income tax that is available without assuming what the Adviser considers to be undue risk. The fund invests at least 80% of its net assets in municipal securities that pay interest that is exempt from federal income tax. These securities may pay interest that is subject to the federal alternative minimum tax ("AMT") for certain taxpayers. It invests at least 80% of its net assets in municipal securities of Ohio or municipal securities with interest that is otherwise exempt from Ohio state income tax.', 0.004, 0.0044, 55600, 30840, 70.684, 70.251, NULL, NULL, 1.95, 10.18, 20.36, 1.31, NULL, NULL, '{"Cap_Size": "Medium", "Quote_Mode": "ETF", "Currency_Base": "Dollar", "GeoZone_Class": "United States", "Strategy_Type": "Blend"}', '{"Net_Worth": 369970432, "Yield_Rate": 0.0167, "Expense_Net": 0.004, "Benchmark_Exp": 0.0044, "Turnover_Ratio": 0.2}', '{"volume_metrics": {"Vol_3M": 55600, "Vol_Recent": 30840}, "moving_averages": {"MA_50": 70.684, "MA_200": 70.251}}', '{"asset_allocation": {"Bond_Weight": null, "Equity_Weight": null}, "bond_characteristics": {"Avg_Maturity": null, "Duration_Yrs": null}}', '{"valuation_metrics": {"PB_Ratio": 1.95, "PE_Ratio": 20.