INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (973, 'IFGL', 'ETF', 'UNITED_STATES', NULL, 'Angel Oak Core Impact Fund Institutional Class', 'US$', 'Value', 'Medium', 'Angel Oak', 'NGM', 'Global Real Estate', 260420896, 0.022, '2007-11-12', 0.09, 'The investment seeks total return while giving special consideration to positive aggregate environmental, social and governance outcomes. The fund will principally invest in a diverse portfolio of investments that Angel Oak Capital Advisors (the "Adviser") believes have positive aggregate ESG impact outcomes. The fixed income instruments in which the fund invests may include those of issuers from the United States and other countries, including foreign debt securities denominated in U.S. dollars. Under normal circumstances, the fund will concentrate its investments in mortgage loans, RMBS and CMBS. The fund is non-diversified.', 0.0048, 0.0053, 46858, 53790, 28.768, 29.118, NULL, NULL, 1.01, 16.56, 15.34, 5.58, NULL, NULL, '{"Cap_Size": "Medium", "Quote_Mode": "ETF", "Currency_Base": "US$", "GeoZone_Class": "UNITED_STATES", "Strategy_Type": "Value"}', '{"Net_Worth": 260420896, "Yield_Rate": 0.022, "Expense_Net": 0.0048, "Benchmark_Exp": 0.0053, "Turnover_Ratio": 0.09}', '{"volume_metrics": {"Vol_3M": 46858, "Vol_Recent": 53790}, "moving_averages": {"MA_50": 28.768, "MA_200": 29.118}}', '{"asset_allocation": {"Bond_Weight": null, "Equity_Weight": null}, "bond_characteristics": {"Avg_Maturity": null, "Duration_Yrs": null}}', '{"valuation_metrics": {"PB_Ratio": 1.01, "PE_Ratio": 15.34, "PS_Ratio": 5.58, "PCF_Ratio": 16.56}}');
