INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (984, 'IGSB', 'ETF', 'America', 'AllianzGI Emerging Markets Oppo', 'Virtus AllianzGI Emerging Markets Opportunities Fund Class A', 'USD', NULL, NULL, 'Virtus', 'NGM', 'Short-Term Bond', 26633134080, 0.0202, '2007-01-05', 0.29, 'The investment seeks maximum long-term capital appreciation. The fund seeks to achieve its investment objective by normally investing at least 80% of its net assets (plus borrowings made for investment purposes) in securities of companies that are tied economically to countries with emerging securities markets-that is, countries with securities markets that are, in the opinion of the portfolio managers, less sophisticated than more developed markets in terms of participation by investors, analyst coverage, liquidity and/or regulation.', 0.0006, 0.0026, 2855171, 3.28403e+06, 54.296, 54.651, NULL, NULL, NULL, NULL, NULL, NULL, 3.01, 2.79, '{"Cap_Size": null, "Quote_Mode": "ETF", "Currency_Base": "USD", "GeoZone_Class": "America", "Strategy_Type": null}', '{"Net_Worth": 26633134080, "Yield_Rate": 0.0202, "Expense_Net": 0.0006, "Benchmark_Exp": 0.0026, "Turnover_Ratio": 0.29}', '{"volume_metrics": {"Vol_3M": 2855171, "Vol_Recent": 3284030}, "moving_averages": {"MA_50": 54.296, "MA_200": 54.651}}', '{"asset_allocation": {"Bond_Weight": null, "Equity_Weight": null}, "bond_characteristics": {"Avg_Maturity": 3.01, "Duration_Yrs": 2.79}}', '{"valuation_metrics": {"PB_Ratio": null, "PE_Ratio": null, "PS_Ratio": null, "PCF_Ratio": null}}');
