INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (987, 'IHY', 'ETF', 'usa', 'Angel Oak UltraShort Income Fun', 'Angel Oak UltraShort Income Fund Class A', 'US Dollar', 'Value', 'Large', 'Angel Oak', 'PCX', 'High Yield Bond', 107884008, 0.045, '2012-04-02', 0.33, 'The investment seeks to provide current income while seeking to minimize price volatility and maintain liquidity. The fund invests primarily in mortgage-backed and other asset-backed fixed income securities, corporate and other debt securities, and collateralized loan obligations ("CLOs"), which are backed by a pool of loans, and other collateralized debt obligations ("CDOs"), which are backed by a pool of debt. It may invest, without limitation, in Debt Instruments of any quality and maturity, including high-yield securities (also known as "junk bonds"), and securities that are not rated by any rating agencies. The fund is non-diversified.', 0.004, 0.0047, 35837, 72840, 24.46, 25.354, NULL, NULL, 9.17, NULL, 59.99, 1.95, 11.43, 3.4, '{"Cap_Size": "Large", "Quote_Mode": "ETF", "Currency_Base": "US Dollar", "GeoZone_Class": "usa", "Strategy_Type": "Value"}', '{"Net_Worth": 107884008, "Yield_Rate": 0.045, "Expense_Net": 0.004, "Benchmark_Exp": 0.0047, "Turnover_Ratio": 0.33}', '{"volume_metrics": {"Vol_3M": 35837, "Vol_Recent": 72840}, "moving_averages": {"MA_50": 24.46, "MA_200": 25.354}}', '{"asset_allocation": {"Bond_Weight": null, "Equity_Weight": null}, "bond_characteristics": {"Avg_Maturity": 11.43, "Duration_Yrs": 3.4}}', '{"valuation_metrics": {"PB_Ratio": 9.17, "PE_Ratio": 59.99, "PS_Ratio": 1.95, "PCF_Ratio": null}}');
