INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (989, 'IIGD', 'ETF', 'U.S.', 'American Century One Choice Por', 'American Century Investments One Choice Portfolio: Very Aggressive Investor Class', 'usd', NULL, NULL, 'American Century Investments', 'PCX', 'Short-Term Bond', 76120352, 0.0131, '2018-07-25', 0.74, 'The investment seeks the highest total return consistent with its asset mix. The fund invests in other American Century Investments mutual funds (the underlying funds) that represent a variety of asset classes and investment styles. Its asset allocation strategy generally invests in equity securities. However, if the portfolio managers believe it is prudent, the fund may invest a portion of its assets in fixed-income securities and short-term investments. The fund invests 100% of its assets in underlying funds that invest in stocks.', 0.0013, 0.0026, 17787, 24150, 26.487, 26.653, 0, 0.9952, NULL, NULL, NULL, NULL, 4.01, 3.67, '{"Cap_Size": null, "Quote_Mode": "ETF", "Currency_Base": "usd", "GeoZone_Class": "U.S.", "Strategy_Type": null}', '{"Net_Worth": 76120352, "Yield_Rate": 0.0131, "Expense_Net": 0.0013, "Benchmark_Exp": 0.0026, "Turnover_Ratio": 0.74}', '{"volume_metrics": {"Vol_3M": 17787, "Vol_Recent": 24150}, "moving_averages": {"MA_50": 26.487, "MA_200": 26.653}}', '{"asset_allocation": {"Bond_Weight": 0.9952, "Equity_Weight": 0}, "bond_characteristics": {"Avg_Maturity": 4.01, "Duration_Yrs": 3.67}}', '{"valuation_metrics": {"PB_Ratio": null, "PE_Ratio": null, "PS_Ratio": null, "PCF_Ratio": null}}');
INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (990, 'IIGV', 'ETF', 'U.S.', 'AB Municipal Income Fund II - P', 'AB Municipal Income Fund II Pennsylvania Portfolio Class A', 'Usd', NULL, NULL, 'AllianceBernstein', 'PCX', 'Corporate Bond', 34479644, 0.0383, '2018-07-25', 1.78, 'The investment seeks to earn the highest level of current income exempt from both federal income tax and Commonwealth of Pennsylvania personal income tax that is available without assuming what the Adviser considers to be undue risk. The fund invests at least 80% of its net assets in municipal securities that pay interest that is exempt from federal income tax. These securities may pay interest that is subject to the federal alternative minimum tax ("AMT") for certain taxpayers. It invests at least 80% of its net assets in municipal securities of Pennsylvania or municipal securities with interest that is otherwise exempt from Pennsylvania state income tax.', 0.0013, 0.0017, 7850, 3540, 27.271, 27.39, 0, 0.9984, NULL, NULL, NULL, NULL, 7.87, 6.8, '{"Cap_Size": null, "Quote_Mode": "ETF", "Currency_Base": "Usd", "GeoZone_Class": "U.S.", "Strategy_Type": null}', '{"Net_Worth": 34479644, "Yield_Rate": 0.0383, "Expense_Net": 0.0013, "Benchmark_Exp": 0.0017, "Turnover_Ratio": 1.78}', '{"volume_metrics": {"Vol_3M": 7850, "Vol_Recent": 3540}, "moving_averages": {"MA_50": 27.271, "MA_200": 27.39}}', '{"asset_allocation": {"Bond_Weight": 0.9984, "Equity_Weight": 0}, "bond_characteristics": {"Avg_Maturity": 7.87, "Duration_Yrs": 6.8}}', '{"valuation_metrics": {"PB_Ratio": null, "PE_Ratio": null, "PS_Ratio": null, "PCF_Ratio": null}}');
