INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (997, 'IMFL', 'ETF', 'America', 'Artisan High Income Fund Adviso', 'Artisan High Income Fund Advisor Shares', 'DOLLAR', 'Value', 'Large', 'Artisan', 'BTS', NULL, 131953568, NULL, '2021-02-24', NULL, 'The investment seeks to provide total return through a combination of current income and capital appreciation. Under normal circumstances, the fund will invest primarily in instruments that are rated, at the time of purchase, below investment grade (below BBB- by Standard & Poor''s Rating Services ("S&P") or Fitch, Inc. ("Fitch") or below Baa3 by Moody''s Investors Service, Inc. ("Moody''s")), or comparably rated by another nationally recognized statistical rating organization ("NRSRO"), or unrated but determined by Artisan Partners to be of comparable quality.', 0.0034, NULL, 2677, 4750, 26.322, 26.635, 0.9988, 0, 1.41, 7.55, 17.46, 0.78, NULL, NULL, '{"Cap_Size": "Large", "Quote_Mode": "ETF", "Currency_Base": "DOLLAR", "GeoZone_Class": "America", "Strategy_Type": "Value"}', '{"Net_Worth": 131953568, "Yield_Rate": null, "Expense_Net": 0.0034, "Benchmark_Exp": null, "Turnover_Ratio": null}', '{"volume_metrics": {"Vol_3M": 2677, "Vol_Recent": 4750}, "moving_averages": {"MA_50": 26.322, "MA_200": 26.635}}', '{"asset_allocation": {"Bond_Weight": 0, "Equity_Weight": 0.9988}, "bond_characteristics": {"Avg_Maturity": null, "Duration_Yrs": null}}', '{"valuation_metrics": {"PB_Ratio": 1.41, "PE_Ratio": 17.46, "PS_Ratio": 0.78, "PCF_Ratio": 7.55}}');
