INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (1007, 'INFR', 'ETF', 'America', 'Artisan Small Cap Fund - Adviso', 'Artisan Small Cap Fund Advisor Shares', 'US$', 'Value', 'Large', 'Artisan', 'NGM', 'Infrastructure', 12400311, 0.0271, '2016-12-29', 0.56, 'The investment seeks maximum long-term capital growth. The fund''s investment team employs a fundamental investment process to construct a diversified portfolio of U.S. small-cap growth companies. It invests primarily in US companies and, under normal circumstances, the fund invests no less than 80% of its net assets plus any borrowings for investment purposes at market value at the time of purchase in the common stocks of small companies.', 0.004, 0.0045, 1540, 1630, 30.974, 31.128, NULL, NULL, 1.78, 8.73, 19.87, 2.07, NULL, NULL, '{"Cap_Size": "Large", "Quote_Mode": "ETF", "Currency_Base": "US$", "GeoZone_Class": "America", "Strategy_Type": "Value"}', '{"Net_Worth": 12400311, "Yield_Rate": 0.0271, "Expense_Net": 0.004, "Benchmark_Exp": 0.0045, "Turnover_Ratio": 0.56}', '{"volume_metrics": {"Vol_3M": 1540, "Vol_Recent": 1630}, "moving_averages": {"MA_50": 30.974, "MA_200": 31.128}}', '{"asset_allocation": {"Bond_Weight": null, "Equity_Weight": null}, "bond_characteristics": {"Avg_Maturity": null, "Duration_Yrs": null}}', '{"valuation_metrics": {"PB_Ratio": 1.78, "PE_Ratio": 19.87, "PS_Ratio": 2.07, "PCF_Ratio": 8.73}}');
