INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (1016, 'IQDF', 'ETF', 'usa', 'Yorktown Growth Fund Institutio', 'Yorktown Growth Fund Class Institutional', 'US_DOLLAR', 'Value', 'Large', 'Yorktown Funds', 'PCX', 'Foreign Large Value', 608012480, 0.0307, '2013-04-12', 0.74, 'The investment seeks growth of capital. The fund invests in securities that, in the opinion of Yorktown Management & Research Company, Inc. (the "Adviser"), offer the opportunity for growth of capital. It can include stocks of any size, within any sector, and at times the Adviser may emphasize one or more particular sectors. The fund may also invest in other U.S. and foreign securities, including securities convertible into common stock and securities issued through private placements, and securities issued by investment companies ("underlying funds").', 0.0047, 0.0046, 46825, 68610, 25.695, 26.2, NULL, NULL, 1.8, 9.54, 13.06, 1.25, NULL, NULL, '{"Cap_Size": "Large", "Quote_Mode": "ETF", "Currency_Base": "US_DOLLAR", "GeoZone_Class": "usa", "Strategy_Type": "Value"}', '{"Net_Worth": 608012480, "Yield_Rate": 0.0307, "Expense_Net": 0.0047, "Benchmark_Exp": 0.0046, "Turnover_Ratio": 0.74}', '{"volume_metrics": {"Vol_3M": 46825, "Vol_Recent": 68610}, "moving_averages": {"MA_50": 25.695, "MA_200": 26.2}}', '{"asset_allocation": {"Bond_Weight": null, "Equity_Weight": null}, "bond_characteristics": {"Avg_Maturity": null, "Duration_Yrs": null}}', '{"valuation_metrics": {"PB_Ratio": 1.8, "PE_Ratio": 13.06, "PS_Ratio": 1.25, "PCF_Ratio": 9.54}}');
