INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (1017, 'IQDG', 'ETF', 'US', 'AB Large Cap Growth Fund, Inc. ', 'AB Large Cap Growth Fund Advisor Class', 'AmericanDollar', 'Blend', 'Large', 'AllianceBernstein', 'BTS', 'Foreign Large Growth', 249603808, 0.0211, '2016-04-07', 0.66, 'The investment seeks long-term growth of capital. The fund invests primarily in equity securities of a limited number of large, carefully selected, high-quality U.S. companies. It invests primarily in the domestic equity securities of companies selected by the fund''s Adviser for their growth potential within various market sectors. The fund emphasizes investments in large, seasoned companies. Under normal circumstances, the fund will invest at least 80% of its net assets in common stocks of large-capitalization companies. It may, at times, invest in shares of exchange-traded funds in lieu of making direct investments in securities.', 0.0042, 0.0066, 46277, 28960, 39.064, 39.455, 1, 0, 4.33, 14.01, 22.63, 2.92, NULL, NULL, '{"Cap_Size": "Large", "Quote_Mode": "ETF", "Currency_Base": "AmericanDollar", "GeoZone_Class": "US", "Strategy_Type": "Blend"}', '{"Net_Worth": 249603808, "Yield_Rate": 0.0211, "Expense_Net": 0.0042, "Benchmark_Exp": 0.0066, "Turnover_Ratio": 0.66}', '{"volume_metrics": {"Vol_3M": 46277, "Vol_Recent": 28960}, "moving_averages": {"MA_50": 39.064, "MA_200": 39.455}}', '{"asset_allocation": {"Bond_Weight": 0, "Equity_Weight": 1}, "bond_characteristics": {"Avg_Maturity": null, "Duration_Yrs": null}}', '{"valuation_metrics": {"PB_Ratio": 4.33, "PE_Ratio": 22.63, "PS_Ratio": 2.92, "PCF_Ratio": 14.01}}');
