INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (1019, 'IQIN', 'ETF', 'usa', 'Artisan Global Discovery Fund -', 'Artisan Global Discovery Fund Institutional Shares', 'Usd', 'Value', 'Large', 'Artisan', 'PCX', 'Foreign Large Value', 241393568, 0.0292, '2018-12-12', NULL, 'The investment seeks maximum long-term capital growth. The fund''s investment team employs a fundamental investment process to construct a diversified portfolio of U.S. and non-U.S. growth companies across a broad capitalization range. The team seeks to invest in companies that it believes possess franchise characteristics, are benefiting from an accelerating profit cycle and are trading at a discount to its estimate of private market value. The fund primarily invests in common stocks and other equity securities of U.S. and non-U.S. companies, including depositary receipts.', 0.0025, 0.0046, 1841, 1000, 32.926, 32.872, 0.9993, 0, 1.33, 6.35, 16.34, 0.63, NULL, NULL, '{"Cap_Size": "Large", "Quote_Mode": "ETF", "Currency_Base": "Usd", "GeoZone_Class": "usa", "Strategy_Type": "Value"}', '{"Net_Worth": 241393568, "Yield_Rate": 0.0292, "Expense_Net": 0.0025, "Benchmark_Exp": 0.0046, "Turnover_Ratio": null}', '{"volume_metrics": {"Vol_3M": 1841, "Vol_Recent": 1000}, "moving_averages": {"MA_50": 32.926, "MA_200": 32.872}}', '{"asset_allocation": {"Bond_Weight": 0, "Equity_Weight": 0.9993}, "bond_characteristics": {"Avg_Maturity": null, "Duration_Yrs": null}}', '{"valuation_metrics": {"PB_Ratio": 1.33, "PE_Ratio": 16.34, "PS_Ratio": 0.63, "PCF_Ratio": 6.35}}');
