INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (1028, 'ISWN', 'ETF', 'U.S.', 'Artisan Select Equity Fund - In', 'Artisan Select Equity Fund Institutional Shares', 'Dollar', 'Blend', 'Large', 'Artisan', 'PCX', NULL, 33717144, NULL, '2021-01-25', NULL, 'The investment seeks maximum long-term capital growth. Under normal market conditions, the fund invests no less than 80% of its net assets plus any borrowings for investment purposes at market value at the time of purchase in equity securities or instruments that have similar economic characteristics. It will invest primarily in U.S. companies but may invest up to 20% of its total assets at market value at the time of purchase in non-U.S. companies, including those in emerging and less developed markets. The fund is non-diversified.', 0.0049, NULL, 9030, 2650, 25.287, 25.254, 0.2044, 0.7926, 1.84, 10.75, 22.04, 1.55, NULL, NULL, '{"Cap_Size": "Large", "Quote_Mode": "ETF", "Currency_Base": "Dollar", "GeoZone_Class": "U.S.", "Strategy_Type": "Blend"}', '{"Net_Worth": 33717144, "Yield_Rate": null, "Expense_Net": 0.0049, "Benchmark_Exp": null, "Turnover_Ratio": null}', '{"volume_metrics": {"Vol_3M": 9030, "Vol_Recent": 2650}, "moving_averages": {"MA_50": 25.287, "MA_200": 25.254}}', '{"asset_allocation": {"Bond_Weight": 0.7926, "Equity_Weight": 0.2044}, "bond_characteristics": {"Avg_Maturity": null, "Duration_Yrs": null}}', '{"valuation_metrics": {"PB_Ratio": 1.84, "PE_Ratio": 22.04, "PS_Ratio": 1.55, "PCF_Ratio": 10.75}}');
