INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (1030, 'ITM', 'ETF', 'usa', 'Artisan Global Opportunities Fd', 'Artisan Global Opportunities Fund Institutional Class', 'Dollar', NULL, NULL, 'Artisan', 'BTS', 'Muni National Long', 1871150208, 0.0198, '2007-12-04', 0.06, 'The investment seeks maximum long-term capital growth. The fund''s investment team employs a fundamental investment process to construct a diversified portfolio of U.S. and non-U.S. growth companies across a broad capitalization range. The team seeks to invest in companies that the advisor believes possess franchise characteristics, are benefiting from an accelerating profit cycle and are trading at a discount to its estimate of private market value.', 0.0024, 0.0026, 162053, 177240, 51.147, 51.558, 0, 0.9998, NULL, NULL, NULL, NULL, 11.01, 6.21, '{"Cap_Size": null, "Quote_Mode": "ETF", "Currency_Base": "Dollar", "GeoZone_Class": "usa", "Strategy_Type": null}', '{"Net_Worth": 1871150208, "Yield_Rate": 0.0198, "Expense_Net": 0.0024, "Benchmark_Exp": 0.0026, "Turnover_Ratio": 0.06}', '{"volume_metrics": {"Vol_3M": 162053, "Vol_Recent": 177240}, "moving_averages": {"MA_50": 51.147, "MA_200": 51.558}}', '{"asset_allocation": {"Bond_Weight": 0.9998, "Equity_Weight": 0}, "bond_characteristics": {"Avg_Maturity": 11.01, "Duration_Yrs": 6.21}}', '{"valuation_metrics": {"PB_Ratio": null, "PE_Ratio": null, "PS_Ratio": null, "PCF_Ratio": null}}');
INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (1031, 'ITOT', 'ETF', 'USA', 'Artisan Small Cap Fund Institut', 'Artisan Small Cap Fund Institutional Shares', 'US Dollar', 'Blend', 'Large', 'Artisan', 'PCX', 'Large Blend', 40086081536, 0.0122, '2004-01-20', 0.05, 'The investment seeks maximum long-term capital growth. The fund''s investment team employs a fundamental investment process to construct a diversified portfolio of U.S. small-cap growth companies. It invests primarily in US companies and, under normal circumstances, the fund invests no less than 80% of its net assets plus any borrowings for investment purposes at market value at the time of purchase in the common stocks of small companies.', 0.0003, 0.0036, 1933185, 3.1329e+06, 103.679, 98.744, 0.9977, 0, 4.16, 16.98, 25.52, 2.73, NULL, NULL, '{"Cap_Size": "Large", "Quote_Mode": "ETF", "Currency_Base": "US Dollar", "GeoZone_Class": "USA", "Strategy_Type": "Blend"}', '{"Net_Worth": 40086081536, "Yield_Rate": 0.0122, "Expense_Net": 0.0003, "Benchmark_Exp": 0.0036, "Turnover_Ratio": 0.05}', '{"volume_metrics": {"Vol_3M": 1933185, "Vol_Recent": 3132900}, "moving_averages": {"MA_50": 103.679, "MA_200": 98.744}}', '{"asset_allocation": {"Bond_Weight": 0, "Equity_Weight": 0.9977}, "bond_characteristics": {"Avg_Maturity": null, "Duration_Yrs": null}}', '{"valuation_metrics": {"PB_Ratio": 4.16, "PE_Ratio": 25.52, "PS_Ratio": 2.73, "PCF_Ratio": 16.98}}');
INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (1033, 'IUSB', 'ETF', 'United States', 'Artisan Developing World Fund -', 'Artisan Developing World Fund Institutional Shares', 'US$', NULL, NULL, 'Artisan', 'NGM', NULL, 14493035520, 0.021, '2014-06-10', 1.8, 'The investment seeks long-term capital appreciation. The fund''s investment team employs a fundamental investment process to construct a diversified portfolio of securities that offers exposure to developing world economies. In pursuit of this goal, the team generally invests substantially in equity securities of issuers domiciled in or economically tied to countries the team considers to have characteristics typical of the developing world. Under normal circumstances, the fund invests substantially in equity securities of issuers domiciled in or economically tied to one or more markets in the developing world.', 0.0006, NULL, 1130554, 1.27852e+06, 53.072, 53.269, NULL, NULL, NULL, NULL, NULL, NULL, 8.05, 6.37, '{"Cap_Size": null, "Quote_Mode": "ETF", "Currency_Base": "US$", "GeoZone_Class": "United States", "Strategy_Type": null}', '{"Net_Worth": 14493035520, "Yield_Rate": 0.021, "Expense_Net": 0.0006, "Benchmark_Exp": null, "Turnover_Ratio": 1.8}', '{"volume_metrics": {"Vol_3M": 1130554, "Vol_Recent": 1278520}, "moving_averages": {"MA_50": 53.072, "MA_200": 53.269}}', '{"asset_allocation": {"Bond_Weight": null, "Equity_Weight": null}, "bond_characteristics": {"Avg_Maturity": 8.05, "Duration_Yrs": 6.37}}', '{"valuation_metrics": {"PB_Ratio": null, "PE_Ratio": null, "PS_Ratio": null, "PCF_Ratio": null}}');
INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (1034, 'IUSS', 'ETF', 'UNITED_STATES', 'Yorktown Short Term Bond Fund I', 'Yorktown Short Term Bond Fund Class Institutional', 'USD', 'Blend', 'Small', 'Yorktown Funds', 'NGM', 'Small Blend', 44719192, 0.0061, '2018-09-12', 0.28, 'The investment seeks income consistent with the preservation of capital. Under normal circumstances, the fund invests at least 80% of its assets in fixed income securities that, in the Adviser''s opinion, offer the opportunity for income consistent with preservation of capital. Its portfolio will have an average aggregate maturity of not more than three years. The fund seeks to provide diversification by allocating its investments among various areas of the fixed income markets. It primarily invests in the investment grade debt securities of various types.', 0.0023, 0.004, 5870, 8750, 39.305, 38.174, 1, 0, 2.7, 10.26, 20.25, 1.31, NULL, NULL, '{"Cap_Size": "Small", "Quote_Mode": "ETF", "Currency_Base": "USD", "GeoZone_Class": "UNITED_STATES", "Strategy_Type": "Blend"}', '{"Net_Worth": 44719192, "Yield_Rate": 0.0061, "Expense_Net": 0.0023, "Benchmark_Exp": 0.004, "Turnover_Ratio": 0.28}', '{"volume_metrics": {"Vol_3M": 5870, "Vol_Recent": 8750}, "moving_averages": {"MA_50": 39.305, "MA_200": 38.174}}', '{"asset_allocation": {"Bond_Weight": 0, "Equity_Weight": 1}, "bond_characteristics": {"Avg_Maturity": null, "Duration_Yrs": null}}', '{"valuation_metrics": {"PB_Ratio": 2.7, "PE_Ratio": 20.25, "PS_Ratio": 1.31, "PCF_Ratio": 10.26}}');
INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (1035, 'IUSV', 'ETF', 'USA', 'Yorktown Master Allocation Fund', 'Yorktown Master Allocation Fund Class A', 'US$', 'Value', 'Large', 'Yorktown Funds', 'NGM', 'Large Value', 10406422528, 0.0194, '2000-07-24', 0.25, 'The investment seeks long-term capital appreciation and current income. The fund invests its assets in a variety of equity and debt securities. It also invests in the securities of other open-end mutual funds managed by the Adviser, but reserves the right to invest fund assets in other equity and debt securities as it deems appropriate in seeking to achieve the fund''s investment objective. The Adviser does not presently intend to invest fund assets in individual equity or debt securities.', 0.0004, 0.0034, 494401, 698050, 73.692, 72.012, 0.997, 0, 2.62, 12.83, 19.92, 1.95, NULL, NULL, '{"Cap_Size": "Large", "Quote_Mode": "ETF", "Currency_Base": "US$", "GeoZone_Class": "USA", "Strategy_Type": "Value"}', '{"Net_Worth": 10406422528, "Yield_Rate": 0.0194, "Expense_Net": 0.0004, "Benchmark_Exp": 0.0034, "Turnover_Ratio": 0.25}', '{"volume_metrics": {"Vol_3M": 494401, "Vol_Recent": 698050}, "moving_averages": {"MA_50": 73.692, "MA_200": 72.012}}', '{"asset_allocation": {"Bond_Weight": 0, "Equity_Weight": 0.997}, "bond_characteristics": {"Avg_Maturity": null, "Duration_Yrs": null}}', '{"valuation_metrics": {"PB_Ratio": 2.62, "PE_Ratio": 19.92, "PS_Ratio": 1.95, "PCF_Ratio": 12.83}}');
