INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (1058, 'JDIV', 'ETF', 'United States', 'AAM/Phocas Real Estate Fund - C', 'AAM/Phocas Real Estate Fund Class A Shares', 'USD', 'Value', 'Medium', 'AAM', 'PCX', 'Mid-Cap Value', 35709952, 0.0317, '2017-11-08', NULL, 'The investment seeks long-term total investment return through a combination of capital appreciation and current income. Under normal market conditions, the fund invests at least 80% of its net assets, plus borrowings for investment purposes, in securities of equity real estate investment trusts ("REITs") and companies of any size market capitalization which primarily own, manage and invest in underlying real estate assets. Therefore, it invests at least 25% of its net assets (i.e., concentrates) in the real estate industry. The fund is non-diversified.', 0.0012, 0.0043, 10885, 6600, 32.75, 32.279, 0.9987, 0, 2.47, 10.77, 19.09, 1.43, NULL, NULL, '{"Cap_Size": "Medium", "Quote_Mode": "ETF", "Currency_Base": "USD", "GeoZone_Class": "United States", "Strategy_Type": "Value"}', '{"Net_Worth": 35709952, "Yield_Rate": 0.0317, "Expense_Net": 0.0012, "Benchmark_Exp": 0.0043, "Turnover_Ratio": null}', '{"volume_metrics": {"Vol_3M": 10885, "Vol_Recent": 6600}, "moving_averages": {"MA_50": 32.75, "MA_200": 32.279}}', '{"asset_allocation": {"Bond_Weight": 0, "Equity_Weight": 0.9987}, "bond_characteristics": {"Avg_Maturity": null, "Duration_Yrs": null}}', '{"valuation_metrics": {"PB_Ratio": 2.47, "PE_Ratio": 19.09, "PS_Ratio": 1.43, "PCF_Ratio": 10.77}}');
