INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (1063, 'JGLD', 'ETF', 'U.S.', 'Cavanal Hill Limited Duration F', 'Cavanal Hill Limited Duration Fund Investor Class', 'usd', 'Blend', 'Small', 'Cavanal Hill funds', 'PCX', 'Equity Precious Metals', 2465944, NULL, '2020-11-30', NULL, 'The investment seeks income and secondarily seeks capital appreciation. The fund invests primarily in debt obligations such as bonds, notes and debentures, and bills issued by U.S. corporations or by the U.S. government, its agencies or instrumentalities, municipal securities, mortgage-backed securities, asset-backed securities, and collateralized mortgage obligations and fixed income ETFs. It ivests at least 80% of its net assets in bonds and maintains an average portfolio duration of less than three and one-half years. The fund normally invests at least 65% of its net assets in interest-bearing bonds.', 0.0049, 0.0057, 2220, 1190, 23.271, 24.455, 0.9981, 0, 1.56, 5.93, 10.69, 1.4, NULL, NULL, '{"Cap_Size": "Small", "Quote_Mode": "ETF", "Currency_Base": "usd", "GeoZone_Class": "U.S.", "Strategy_Type": "Blend"}', '{"Net_Worth": 2465944, "Yield_Rate": null, "Expense_Net": 0.0049, "Benchmark_Exp": 0.0057, "Turnover_Ratio": null}', '{"volume_metrics": {"Vol_3M": 2220, "Vol_Recent": 1190}, "moving_averages": {"MA_50": 23.271, "MA_200": 24.455}}', '{"asset_allocation": {"Bond_Weight": 0, "Equity_Weight": 0.9981}, "bond_characteristics": {"Avg_Maturity": null, "Duration_Yrs": null}}', '{"valuation_metrics": {"PB_Ratio": 1.56, "PE_Ratio": 10.69, "PS_Ratio": 1.4, "PCF_Ratio": 5.93}}');
