INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (1064, 'JHCB', 'ETF', 'USA', 'Pinnacle TrendRating Innovative', 'Pinnacle TrendRating Innovative Equity Fund Class A', 'DOLLAR', 'Growth', 'Medium', 'Pinnacle', 'PCX', NULL, 20284924, NULL, '2021-03-30', NULL, 'The investment seeks high total return. Under normal market conditions, the fund invests at least 95% of its assets in equity securities. The advisor intends to invest in 25 of the 500 largest market capitalized common stocks, excluding ADRs, trading in the U.S. based on a rank given to each of these stocks by the adviser every month. The adviser ranks each stock using the TrendRating Smart Momentum Score ("SMS"), a proprietary system of TrendRating S. A., which considers 8 out of over 350 factors that TrendRating''s research has determined to be the most effective in capturing medium to long term price trends ranging from a few months to a few quarters.', 0.0029, NULL, 238, 360, 25.555, 25.674, NULL, NULL, NULL, NULL, NULL, NULL, 10.44, 8.35, '{"Cap_Size": "Medium", "Quote_Mode": "ETF", "Currency_Base": "DOLLAR", "GeoZone_Class": "USA", "Strategy_Type": "Growth"}', '{"Net_Worth": 20284924, "Yield_Rate": null, "Expense_Net": 0.0029, "Benchmark_Exp": null, "Turnover_Ratio": null}', '{"volume_metrics": {"Vol_3M": 238, "Vol_Recent": 360}, "moving_averages": {"MA_50": 25.555, "MA_200": 25.674}}', '{"asset_allocation": {"Bond_Weight": null, "Equity_Weight": null}, "bond_characteristics": {"Avg_Maturity": 10.44, "Duration_Yrs": 8.35}}', '{"valuation_metrics": {"PB_Ratio": null, "PE_Ratio": null, "PS_Ratio": null, "PCF_Ratio": null}}');
INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (1065, 'JHCS', 'ETF', 'us', 'AllianzGI Preferred Securities ', 'Virtus AllianzGI Preferred Securities and Income Fund Class P', 'Dollar', 'Blend', 'Large', 'Virtus', 'PCX', 'Communications', 31738204, 0.0076, '2019-03-12', 0.2, 'The investment seeks total return consisting of high current income and capital appreciation. The fund seeks to achieve its objective by normally investing at least 80% of its net assets (plus borrowings made for investment purposes) in preferred securities or debt securities issued by U.S. and non-U.S. issuers. Under normal market conditions, it will also invest at least 25% of its total assets in the financials sector. The fund may invest without limit in non-U.S. securities, including securities issued in local currencies, and may invest up to 15% of its assets in emerging markets securities.', 0.004, 0.0035, 982, 1540, 37.414, 38.248, 0.9981, 0, 3.34, 11.07, 25.27, 2.8, NULL, NULL, '{"Cap_Size": "Large", "Quote_Mode": "ETF", "Currency_Base": "Dollar", "GeoZone_Class": "us", "Strategy_Type": "Blend"}', '{"Net_Worth": 31738204, "Yield_Rate": 0.0076, "Expense_Net": 0.004, "Benchmark_Exp": 0.0035, "Turnover_Ratio": 0.2}', '{"volume_metrics": {"Vol_3M": 982, "Vol_Recent": 1540}, "moving_averages": {"MA_50": 37.414, "MA_200": 38.248}}', '{"asset_allocation": {"Bond_Weight": 0, "Equity_Weight": 0.9981}, "bond_characteristics": {"Avg_Maturity": null, "Duration_Yrs": null}}', '{"valuation_metrics": {"PB_Ratio": 3.34, "PE_Ratio": 25.27, "PS_Ratio": 2.8, "PCF_Ratio": 11.07}}');
INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (1066, 'JHEM', 'ETF', 'America', 'Ultra Short Tax-Free Income Fun', 'Cavanal Hill Ultra Short Tax-Free Income Fund Investor', 'Dollar', 'Blend', 'Large', 'Cavanal Hill funds', 'PCX', 'Diversified Emerging Mkts', 741810816, 0.0174, '2018-09-27', 0.25, 'The investment seeks to generate current income exempt from federal income taxes consistent with the preservation of capital. The fund invests in a diversified portfolio of municipal bonds and debentures. As a matter of fundamental policy, it invests, under normal circumstances, at least 80% of its net assets in municipal securities, the income from which is both exempt from federal income tax and not subject to federal alternative minimum tax for individuals. The fund invests at least 80% of its net assets in tax-free bonds and maintains a dollar-weighted average maturity between 1 day to 1 year.', 0.0049, 0.0056, 16290, 25800, 29.865, 30.62, NULL, NULL, 1.85, 9.5, 15.32, 1.14, NULL, NULL, '{"Cap_Size": "Large", "Quote_Mode": "ETF", "Currency_Base": "Dollar", "GeoZone_Class": "America", "Strategy_Type": "Blend"}', '{"Net_Worth": 741810816, "Yield_Rate": 0.0174, "Expense_Net": 0.0049, "Benchmark_Exp": 0.0056, "Turnover_Ratio": 0.25}', '{"volume_metrics": {"Vol_3M": 16290, "Vol_Recent": 25800}, "moving_averages": {"MA_50": 29.865, "MA_200": 30.62}}', '{"asset_allocation": {"Bond_Weight": null, "Equity_Weight": null}, "bond_characteristics": {"Avg_Maturity": null, "Duration_Yrs": null}}', '{"valuation_metrics": {"PB_Ratio": 1.85, "PE_Ratio": 15.32, "PS_Ratio": 1.14, "PCF_Ratio": 9.5}}');
