INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (1071, 'JHMF', 'ETF', 'U.S.A.', 'Columbia Disciplined Core Fund ', 'Columbia Disciplined Core Fund Class A', 'USD', 'Value', 'Large', 'Columbia Threadneedle', 'PCX', 'Financial', 37700160, 0.0142, '2015-09-28', 0.11, 'The investment seeks to provide shareholders with long-term capital growth. Under normal market conditions, at least 80% of the fund''s net assets (including the amount of any borrowings for investment purposes) are invested in equity securities of companies with market capitalizations greater than $5 billion at the time of purchase or that are within the market capitalization range of companies in the S&P 500 Index (the index) at the time of purchase. It may invest in derivatives, such as futures (including equity futures and index futures) for cash equitization purposes.', 0.004, 0.0038, 5279, 26230, 53.43, 50.819, NULL, NULL, 1.9, NULL, 15.19, 2.41, NULL, NULL, '{"Cap_Size": "Large", "Quote_Mode": "ETF", "Currency_Base": "USD", "GeoZone_Class": "U.S.A.", "Strategy_Type": "Value"}', '{"Net_Worth": 37700160, "Yield_Rate": 0.0142, "Expense_Net": 0.004, "Benchmark_Exp": 0.0038, "Turnover_Ratio": 0.11}', '{"volume_metrics": {"Vol_3M": 5279, "Vol_Recent": 26230}, "moving_averages": {"MA_50": 53.43, "MA_200": 50.819}}', '{"asset_allocation": {"Bond_Weight": null, "Equity_Weight": null}, "bond_characteristics": {"Avg_Maturity": null, "Duration_Yrs": null}}', '{"valuation_metrics": {"PB_Ratio": 1.9, "PE_Ratio": 15.19, "PS_Ratio": 2.41, "PCF_Ratio": null}}');
INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (1072, 'JHMH', 'ETF', 'US', 'LKCM Aquinas Catholic Equity Fu', 'LKCM Aquinas Catholic Equity Fund', 'AmericanDollar', 'Blend', 'Large', 'LKCM', 'PCX', 'Health', 48881768, 0.0169, '2015-09-28', 0.11, 'The investment seeks to maximize long-term capital appreciation, while incorporating Catholic values investing principles in the investment process. The fund invests at least 80% of its net assets (plus any borrowings for investment purposes) in equity securities. It primarily invests in companies the Adviser believes are likely to have above-average growth in revenues and/or earnings, above-average returns on shareholders'' equity, potential for above-average capital appreciation, and/or companies the Adviser believes have attractive relative valuations.', 0.004, 0.0049, 5275, 2120, 49.139, 47.727, NULL, NULL, 4.65, 15.38, 25.6, 1.56, NULL, NULL, '{"Cap_Size": "Large", "Quote_Mode": "ETF", "Currency_Base": "AmericanDollar", "GeoZone_Class": "US", "Strategy_Type": "Blend"}', '{"Net_Worth": 48881768, "Yield_Rate": 0.0169, "Expense_Net": 0.004, "Benchmark_Exp": 0.0049, "Turnover_Ratio": 0.11}', '{"volume_metrics": {"Vol_3M": 5275, "Vol_Recent": 2120}, "moving_averages": {"MA_50": 49.139, "MA_200": 47.727}}', '{"asset_allocation": {"Bond_Weight": null, "Equity_Weight": null}, "bond_characteristics": {"Avg_Maturity": null, "Duration_Yrs": null}}', '{"valuation_metrics": {"PB_Ratio": 4.65, "PE_Ratio": 25.6, "PS_Ratio": 1.56, "PCF_Ratio": 15.38}}');
