INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (1083, 'JJA', 'ETF', 'US', 'AQR Multi-Asset Fund Class I', 'AQR Multi-Asset Fund Class I', 'AmericanDollar', NULL, NULL, 'AQR Funds', 'PCX', NULL, 13203177, NULL, '2018-01-17', NULL, 'The investment seeks total return. The fund allocates assets among major asset classes (including, but not limited to, developed market equities, nominal and inflation-linked government bonds issued by developed countries, developed and emerging market currencies, and commodities). It will generally have some level of investment in the majority of asset classes and Instruments but there is no stated limit on the percentage of assets the fund can invest in a particular Instrument or the percentage of assets the fund will allocate to any one asset class, and at times the fund may focus on a small number of Instruments or asset classes. It is non-diversified.', 0.0045, NULL, 6303, 4670, 21.412, 20.636, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '{"Cap_Size": null, "Quote_Mode": "ETF", "Currency_Base": "AmericanDollar", "GeoZone_Class": "US", "Strategy_Type": null}', '{"Net_Worth": 13203177, "Yield_Rate": null, "Expense_Net": 0.0045, "Benchmark_Exp": null, "Turnover_Ratio": null}', '{"volume_metrics": {"Vol_3M": 6303, "Vol_Recent": 4670}, "moving_averages": {"MA_50": 21.412, "MA_200": 20.636}}', '{"asset_allocation": {"Bond_Weight": null, "Equity_Weight": null}, "bond_characteristics": {"Avg_Maturity": null, "Duration_Yrs": null}}', '{"valuation_metrics": {"PB_Ratio": null, "PE_Ratio": null, "PS_Ratio": null, "PCF_Ratio": null}}');
