INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (1086, 'JJG', 'ETF', 'usa', 'Horizon Active Risk Assist Fund', 'Horizon Active Risk Assist Fund Class A', 'US_DOLLAR', NULL, NULL, 'Horizon Investments', 'PCX', NULL, 22311148, NULL, '2018-01-17', NULL, 'The investment seeks to capture the majority of the returns associated with equity market investments, while mitigating downside risk through use of a risk overlay strategy. The fund seeks to achieve its objective by using a multi-discipline active asset allocation investment approach. The adviser executes its global securities allocation strategy by allocating assets across various sectors of the global securities markets. Normally the fund invests a majority of its assets in ETFs that invest primarily in equity securities; however, certain ETFs in which the fund may invest primarily in fixed income securities.', 0.0045, NULL, 3438, 8240, 63.489, 63.229, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '{"Cap_Size": null, "Quote_Mode": "ETF", "Currency_Base": "US_DOLLAR", "GeoZone_Class": "usa", "Strategy_Type": null}', '{"Net_Worth": 22311148, "Yield_Rate": null, "Expense_Net": 0.0045, "Benchmark_Exp": null, "Turnover_Ratio": null}', '{"volume_metrics": {"Vol_3M": 3438, "Vol_Recent": 8240}, "moving_averages": {"MA_50": 63.489, "MA_200": 63.229}}', '{"asset_allocation": {"Bond_Weight": null, "Equity_Weight": null}, "bond_characteristics": {"Avg_Maturity": null, "Duration_Yrs": null}}', '{"valuation_metrics": {"PB_Ratio": null, "PE_Ratio": null, "PS_Ratio": null, "PCF_Ratio": null}}');
INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (1087, 'JJM', 'ETF', 'usa', 'Ariel Fund Instl Cl', 'Ariel Fund Institutional Class', 'Dollar', NULL, NULL, 'Ariel Investments', 'PCX', NULL, 11448368, NULL, '2018-01-17', NULL, 'The investment seeks long-term capital appreciation. The fund invests in small/mid cap undervalued companies that show strong potential for growth. It invests primarily in equity securities of U.S. companies that have market capitalizations within the range of the companies in the Russell 2500TM Index, measured at the time of initial purchase.', 0.0045, NULL, 690, 320, 63.605, 60.161, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '{"Cap_Size": null, "Quote_Mode": "ETF", "Currency_Base": "Dollar", "GeoZone_Class": "usa", "Strategy_Type": null}', '{"Net_Worth": 11448368, "Yield_Rate": null, "Expense_Net": 0.0045, "Benchmark_Exp": null, "Turnover_Ratio": null}', '{"volume_metrics": {"Vol_3M": 690, "Vol_Recent": 320}, "moving_averages": {"MA_50": 63.605, "MA_200": 60.161}}', '{"asset_allocation": {"Bond_Weight": null, "Equity_Weight": null}, "bond_characteristics": {"Avg_Maturity": null, "Duration_Yrs": null}}', '{"valuation_metrics": {"PB_Ratio": null, "PE_Ratio": null, "PS_Ratio": null, "PCF_Ratio": null}}');
INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (1096, 'JMST', 'ETF', 'America', 'Archer Balanced Fund', 'Archer Balanced Fund', 'US$', 'Value', 'Medium', 'Archer', 'BTS', NULL, 1571094400, 0.0074, '2018-10-16', 1.53, 'The investment seeks total return. The fund seeks to achieve its objective of total return, by investing in a diversified portfolio of equity and fixed income securities. Total return is composed of both income and capital appreciation. As a Balanced Fund, under normal circumstances, the fund will invest up to 70%, but not less than 25% of its total assets in equity securities. Further, under normal circumstances, it will invest at least 30%, but not less than 25% of its total assets in fixed income securities, cash and cash equivalents.', 0.0018, NULL, 379270, 330920, 51.044, 51.056, NULL, NULL, NULL, NULL, NULL, NULL, 0.74, 0.7, '{"Cap_Size": "Medium", "Quote_Mode": "ETF", "Currency_Base": "US$", "GeoZone_Class": "America", "Strategy_Type": "Value"}', '{"Net_Worth": 1571094400, "Yield_Rate": 0.0074, "Expense_Net": 0.0018, "Benchmark_Exp": null, "Turnover_Ratio": 1.53}', '{"volume_metrics": {"Vol_3M": 379270, "Vol_Recent": 330920}, "moving_averages": {"MA_50": 51.044, "MA_200": 51.056}}', '{"asset_allocation": {"Bond_Weight": null, "Equity_Weight": null}, "bond_characteristics": {"Avg_Maturity": 0.74, "Duration_Yrs": 0.7}}', '{"valuation_metrics": {"PB_Ratio": null, "PE_Ratio": null, "PS_Ratio": null, "PCF_Ratio": null}}');
