INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (1110, 'JPST', 'ETF', 'USA', 'One Choice In Retirement Portfo', 'American Century Investments One Choice In Retirement Portfolio R6 Class', 'US Dollar', NULL, NULL, 'American Century Investments', 'BTS', 'Ultrashort Bond', 17318914048, 0.0094, '2017-05-17', NULL, 'The investment seeks current income; capital appreciation is a secondary objective. The fund is a "fund of funds," meaning that it seeks to achieve its objective by investing in other American Century mutual funds (the underlying funds) that represent a variety of asset classes and investment styles. The fund''s investments generally will be allocated among the major asset classes as follow: 45% of its assets in equity securities (stock funds); 45% of its assets in fixed-income securities (bond funds); and 10% of its assets in cash equivalents (money market funds). The neutral mix of One Choice In Retirement Portfolio is expected to remain fixed over time.', 0.0018, 0.0022, 2559964, 2.80336e+06, 50.628, 50.707, NULL, NULL, NULL, NULL, NULL, NULL, 1.43, 0.86, '{"Cap_Size": null, "Quote_Mode": "ETF", "Currency_Base": "US Dollar", "GeoZone_Class": "USA", "Strategy_Type": null}', '{"Net_Worth": 17318914048, "Yield_Rate": 0.0094, "Expense_Net": 0.0018, "Benchmark_Exp": 0.0022, "Turnover_Ratio": null}', '{"volume_metrics": {"Vol_3M": 2559964, "Vol_Recent": 2803360}, "moving_averages": {"MA_50": 50.628, "MA_200": 50.707}}', '{"asset_allocation": {"Bond_Weight": null, "Equity_Weight": null}, "bond_characteristics": {"Avg_Maturity": 1.43, "Duration_Yrs": 0.86}}',