INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (1147, 'KNG', 'ETF', 'us', 'AB Institutional Funds, Inc. - ', 'AB Global Real Estate Investment Fund II Class I', 'usd', 'Value', 'Large', 'AllianceBernstein', 'BTS', 'Large Value', 195788880, 0.0332, '2018-03-26', 0.86, 'The investment seeks total return from long-term growth of capital and income. The fund invests at least 80% of its net assets in the equity securities of real estate investment trusts, or REITs, and other real estate industry companies, such as real estate operating companies. It invests in U.S. and non-U.S. issuers. The fund invests significantly (at least 40%--unless market conditions are not deemed favorable by the Adviser) in securities of non-U.S. companies. It invests in the equity securities of companies located in at least three countries.', 0.0075, 0.0034, 37025, 39200, 54.403, 53.478, 0.9962, 0, 3.14, 13.84, 24.37, 1.51, NULL, NULL, '{"Cap_Size": "Large", "Quote_Mode": "ETF", "Currency_Base": "usd", "GeoZone_Class": "us", "Strategy_Type": "Value"}', '{"Net_Worth": 195788880, "Yield_Rate": 0.0332, "Expense_Net": 0.0075, "Benchmark_Exp": 0.0034, "Turnover_Ratio": 0.86}', '{"volume_metrics": {"Vol_3M": 37025, "Vol_Recent": 39200}, "moving_averages": {"MA_50": 54.403, "MA_200": 53.478}}', '{"asset_allocation": {"Bond_Weight": 0, "Equity_Weight": 0.9962}, "bond_characteristics": {"Avg_Maturity": null, "Duration_Yrs": null}}', '{"valuation_metrics": {"PB_Ratio": 3.14, "PE_Ratio": 24.37, "PS_Ratio": 1.51, "PCF_Ratio": 13.84}}');
INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (1148, 'KNGS', 'ETF', 'America', 'AMG River Road Small-Mid Cap Va', 'AMG River Road Small-Mid Cap Value Fund Class I', 'US$', 'Growth', 'Large', 'AMG Funds', 'BTS', NULL, 12151462, NULL, '2020-12-29', NULL, 'The investment seeks to provide long-term capital appreciation. The fund invests at least 80% of its net assets, plus the amount of any borrowings for investment purposes, in equity securities of small- and mid-capitalization companies that the subadviser believes are undervalued. The subadviser considers small- and mid-capitalization companies to be those with market capitalizations at the time of acquisition within the range of capitalizations of companies in the Russell 2500© Index. Value investing involves buying stocks that the subadviser believes are out of favor and/or undervalued in comparison to their peers or their prospects for growth.', 0.006, NULL, 1620, 2090, 28.121, 27.914, NULL, NULL, 3.95, 25.43, 24.34, 4.46, NULL, NULL, '{"Cap_Size": "Large", "Quote_Mode": "ETF", "Currency_Base": "US$", "GeoZone_Class": "America", "Strategy_Type": "Growth"}', '{"Net_Worth": 12151462, "Yield_Rate": null, "Expense_Net": 0.006, "Benchmark_Exp": null, "Turnover_Ratio": null}', '{"volume_metrics": {"Vol_3M": 1620, "Vol_Recent": 2090}, "moving_averages": {"MA_50": 28.121, "MA_200": 27.914}}', '{"asset_allocation": {"Bond_Weight": null, "Equity_Weight": null}, "bond_characteristics": {"Avg_Maturity": null, "Duration_Yrs": null}}', '{"valuation_metrics": {"PB_Ratio": 3.95, "PE_Ratio": 24.34, "PS_Ratio": 4.46, "PCF_Ra