INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (1174, 'LDUR', 'ETF', 'USA', 'Aristotle Core Equity Fund Clas', 'Aristotle Core Equity Fund Class I Shares', 'USD', NULL, NULL, 'Aristotle', 'PCX', 'Short-Term Bond', 1129705856, 0.0157, '2014-01-22', 3.78, 'The investment seeks long-term growth of capital. Under normal circumstances, the fund invests at least 80% of its net assets (including amounts borrowed for investment purposes) in equity securities. Its investments in equity securities may include common stocks, preferred stocks, convertible preferred stocks, depository receipts, shares of publicly-traded real estate investment trusts ("REITs"), warrants and rights.', 0.0056, 0.0026, 65725, 67310, 101.394, 101.734, NULL, NULL, NULL, NULL, NULL, NULL, 1.01, 1.72, '{"Cap_Size": null, "Quote_Mode": "ETF", "Currency_Base": "USD", "GeoZone_Class": "USA", "Strategy_Type": null}', '{"Net_Worth": 1129705856, "Yield_Rate": 0.0157, "Expense_Net": 0.0056, "Benchmark_Exp": 0.0026, "Turnover_Ratio": 3.78}', '{"volume_metrics": {"Vol_3M": 65725, "Vol_Recent": 67310}, "moving_averages": {"MA_50": 101.394, "MA_200": 101.734}}', '{"asset_allocation": {"Bond_Weight": null, "Equity_Weight": null}, "bond_characteristics": {"Avg_Maturity": 1.01, "Duration_Yrs": 1.72}}', '{"valuation_metrics": {"PB_Ratio": null, "PE_Ratio": null, "PS_Ratio": null, "PCF_Ratio": null}}');
INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (1175, 'LEAD', 'ETF', 'US', 'Aristotle/Saul Global Equity Fu', 'Aristotle/Saul Global Equity Fund Class I', 'US$', 'Blend', 'Large', 'Aristotle', 'BTS', NULL, 43286464, 0.0077, '2016-01-06', NULL, 'The investment seeks to maximize long-term capital appreciation and income. The fund primarily invests its assets in equity securities that are listed on an exchange or that are otherwise publicly traded in the United States or in a foreign country. It may also invest in exchange-traded funds ("ETFs"). Under normal market conditions, the Global Equity Fund invests in at least three different countries, including emerging market countries, with at least 40% of its net assets invested in securities of issuers located outside the United States. The Global Equity Fund''s investments in foreign securities may include investments through ADRs, EDRs, and GDRs.', 0.0043, NULL, 3687, 4180, 56.972, 53.696, NULL, NULL, 5.9, 18.22, 24.5, 2.17, NULL, NULL, '{"Cap_Size": "Large", "Quote_Mode": "ETF", "Currency_Base": "US$", "GeoZone_Class": "US", "Strategy_Type": "Blend"}', '{"Net_Worth": 43286464, "Yield_Rate": 0.0077, "Expense_Net": 0.0043, "Benchmark_Exp": null, "Turnover_Ratio": null}', '{"volume_metrics": {"Vol_3M": 3687, "Vol_Recent": 4180}, "moving_averages": {"MA_50": 56.972, "MA_200": 53.696}}', '{"asset_allocation": {"Bond_Weight": null, "Equity_Weight": null}, "bond_characteristics": {"Avg_Maturity": null, "Duration_Yrs": null}}', '{"valuation_metrics": {"PB_Ratio": 5.9, "PE_Ratio": 24.5, "PS_Ratio": 2.17, "PCF_Ratio": 18.22}}');
INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (1176, 'LEGR', 'ETF', 'U.S.A.', 'AllianzGI Global Small-Cap Fund', 'Virtus AllianzGI Global Small-Cap Fund Class P', 'US$', 'Value', 'Large', 'Virtus', 'NGM', NULL, 108572280, 0.0083, '2018-01-25', 0.25, 'The investment seeks long-term capital appreciation. The fund seeks to achieve its objective by normally investing at least 80% of its net assets (plus borrowings made for investment purposes) in companies with market capitalizations comparable to those of companies included in the MSCI World Small-Cap Index. Under normal market conditions, the Advisor expects to maintain a weighted-average market capitalization between 50% and 200% of the weighted-average market capitalization of the securities in the MSCI World Small-Cap Index.', 0.0065, NULL, 21650, 24190, 43.59, 42.297, 0.9959, 0, 1.6, 9.2, 16.84, 1.41, NULL, NULL, '{"Cap_Size": "Large", "Quote_Mode": "ETF", "Currency_Base": "US$", "GeoZone_Class": "U.S.A.", "Strategy_Type": "Value"}', '{"Net_Worth": 108572280, "Yield_Rate": 0.0083, "Expense_Net": 0.0065, "Benchmark_Exp": null, "Turnover_Ratio": 0.25}', '{"volume_metrics": {"Vol_3M": 21650, "Vol_Recent": 24190}, "moving_averages": {"MA_50": 43.59, "MA_200": 42.297}}', '{"asset_allocation": {"Bond_Weight": 0, "Equity_Weight": 0.9959}, "bond_characteristics": {"Avg_Maturity": null, "Duration_Yrs": null}}', '{"valuation_metrics": {"PB_Ratio": 1.6, "PE_Ratio": 16.84, "PS_Ratio": 1.41, "PCF_Ratio": 9.2}}');
INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (1177, 'LEXI', 'ETF', 'USA', 'Aristotle Value Equity Fund - C', 'Aristotle Value Equity Fund Class I', 'AmericanDollar', NULL, NULL, 'Aristotle', 'PCX', 'Allocation--70% to 85% Equity', 17155524, NULL, '2021-06-30', NULL, 'The investment seeks to maximize long-term capital appreciation. Under normal market conditions, the fund invests at least 80% of its net assets (including amounts borrowed for investment purposes) in equity securities. The fund''s investments in equity securities may include common stocks, depository receipts, and exchange-traded funds ("ETFs") that invest primarily in equity securities. It seeks to meet its investment objective by investing primarily in equity securities of domestic and foreign issuers that are listed on a U.S. exchange or that are otherwise publicly traded in the United States but may invest up to 20% of its total assets in ADRs and GDRs.', 0.0103, 0.0052, 5300, 3560, 26.091, 25.781, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '{"Cap_Size": null, "Quote_Mode": "ETF", "Currency_Base": "AmericanDollar", "GeoZone_Class": "USA", "Strategy_Type": null}', '{"Net_Worth": 17155524, "Yield_Rate": null, "Expense_Net": 0.0103, "Benchmark_Exp": 0.0052, "Turnover_Ratio": null}', '{"volume_metrics": {"Vol_3M": 5300, "Vol_Recent": 3560}, "moving_averages": {"MA_50": 26.091, "MA_200": 25.781}}', '{"asset_allocation": {"Bond_Weight": null, "Equity_Weight": null}, "bond_characteristics": {"Avg_Maturity": null, "Duration_Yrs": null}}', '{"valuation_metrics": {"PB_Ratio": null, "PE_Ratio": null, "PS_Ratio": null, "PCF_Ratio": null}}');
INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (1178, 'LFEQ', 'ETF', 'United States', 'American Century One Choice in ', 'American Century Investments One Choice In Retirement Portfolio R Class', 'DOLLAR', 'Blend', 'Large', 'American Century Investments', 'PCX', NULL, 31922180, 0.0185, '2017-10-04', NULL, 'The investment seeks current income; capital appreciation is a secondary objective. The fund is a "fund of funds," meaning that it seeks to achieve its objective by investing in other American Century mutual funds (the underlying funds) that represent a variety of asset classes and investment styles. The fund''s investments generally will be allocated among the major asset classes as follow: 45% of its assets in equity securities (stock funds); 45% of its assets in fixed-income securities (bond funds); and 10% of its assets in cash equivalents (money market funds). The neutral mix of One Choice In Retirement Portfolio is expected to remain fixed over time.', 0.0058, NULL, 9132, 18810, 42.181, 39.863, 0.9977, 0, 4.28, 17.23, 27.4, 2.94, NULL, NULL, '{"Cap_Size": "Large", "Quote_Mode": "ETF", "Currency_Base": "DOLLAR", "GeoZone_Class": "United States", "Strategy_Type": "Blend"}', '{"Net_Worth": 31922180, "Yield_Rate": 0.0185, "Expense_Net": 0.0058, "Benchmark_Exp": null, "Turnover_Ratio": null}', '{"volume_metrics": {"Vol_3M": 9132, "Vol_Recent": 18810}, "moving_averages": {"MA_50": 42.181, "MA_200": 39.863}}', '{"asset_allocation": {"Bond_Weight": 0, "Equity_Weight": 0.9977}, "bond_characteristics": {"Avg_Maturity": null, "Duration_Yrs": null}}', '{"valuation_metrics": {"PB_Ratio": 4.28, "PE_Ratio": 27.4, "PS_Ratio": 2.94, "PCF_Ratio": 17.23}}');
INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (1179, 'LGBT', 'ETF', 'UNITED_STATES', 'Aristotle Credit Opportunities ', 'Aristotle Strategic Credit Fund', 'AmericanDollar', NULL, NULL, 'Aristotle', 'NGM', NULL, NULL, NULL, '2021-05-17', NULL, 'The investment seeks income and capital appreciation. Under normal circumstances, the fund invests at least 80% of its net assets (plus any borrowings for investment purposes) in debt securities. The types of debt securities in which the fund may invest include, but are not limited to, corporate bonds, notes and debentures of U.S. and non-U.S. issuers, and bank loans of U.S. and non-U.S. corporate issuers. The fund''s investments in foreign securities include securities in both developed and emerging markets.', 0.0075, NULL, 1175, 2810, 27.365, 26.724, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '{"Cap_Size": null, "Quote_Mode": "ETF", "Currency_Base": "AmericanDollar", "GeoZone_Class": "UNITED_STATES", "Strategy_Type": null}', '{"Net_Worth": null, "Yield_Rate": null, "Expense_Net": 0.0075, "Benchmark_Exp": null, "Turnover_Ratio": null}', '{"volume_metrics": {"Vol_3M": 1175, "Vol_Recent": 2810}, "moving_averages": {"MA_50": 27.365, "MA_200": 26.724}}', '{"asset_allocation": {"Bond_Weight": null, "Equity_Weight": null}, "bond_characteristics": {"Avg_Maturity": null, "Duration_Yrs": null}}', '{"valuation_metrics": {"PB_Ratio": null, "PE_Ratio": null, "PS_Ratio": null, "PCF_Ratio": null}}');
INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (1180, 'LGH', 'ETF', 'UNITED_STATES', 'Nuveen Small Cap Select Cl I', 'Nuveen Small Cap Select Fund Class I', 'US_DOLLAR', 'Blend', 'Large', 'Nuveen', 'PCX', 'Large Blend', 195732064, 0.0019, '2019-10-09', 1.28, 'The investment seeks capital appreciation. Under normal market conditions, the fund invests at least 80% of the sum of its net assets and the amount of any borrowings for investment purposes in common stocks of small-capitalization companies. Small-capitalization companies are defined as companies that have market capitalizations within the market capitalization range of the companies in the Russell 2000© Index on the last business day of the month in which its most recent reconstitution was completed.', 0.0123, 0.0036, 42446, 34500, 43.305, 40.039, NULL, NULL, 4.81, 18.2, 27.37, 3.17, NULL, NULL, '{"Cap_Size": "Large", "Quote_Mode": "ETF", "Currency_Base": "US_DOLLAR", "GeoZone_Class": "UNITED_STATES", "Strategy_Type": "Blend"}', '{"Net_Worth": 195732064, "Yield_Rate": 0.0019, "Expense_Net": 0.0123, "Benchmark_Exp": 0.0036, "Turnover_Ratio": 1.28}', '{"volume_metrics": {"Vol_3M": 42446, "Vol_Recent": 34500}, "moving_averages": {"MA_50": 43.305, "MA_200": 40.039}}', '{"asset_allocation": {"Bond_Weight": null, "Equity_Weight": null}, "bond_characteristics": {"Avg_Maturity": null, "Duration_Yrs": null}}', '{"valuation_metrics": {"PB_Ratio": 4.81, "PE_Ratio": 27.37, "PS_Ratio": 3.17, "PCF_Ratio": 18.2}}');
INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (1307, 'NULV', 'ETF', 'U.S.A.', 'American Century Small Cap Valu', 'American Century Small Cap Value Fund R6 Class', 'Usd', 'Value', 'Large', 'American Century Investments', 'BTS', NULL, 917930624, 0.0125, '2016-12-13', 0.38, 'The investment seeks long-term capital growth; income is a secondary consideration. Under normal market conditions, the portfolio managers will invest at least 80% of the fund''s net assets in small cap companies. The portfolio managers consider small cap companies to include those with market capitalizations no larger than that of the largest company in the S&P Small Cap 600© Index or the Russell 2000© Index.', 0.0035, NULL, 110583, 111200, 38.985, 37.825, 0.999, 0, 2.83, 12.77, 21.59, 1.74, NULL, NULL, '{"Cap_Size": "Large", "Quote_Mode": "ETF", "Currency_Base": "Usd", "GeoZone_Class": "U.S.A.", "Strategy_Type": "Value"}', '{"Net_Worth": 917930624, "Yield_Rate": 0.0125, "Expense_Net": 0.0035, "Benchmark_Exp": null, "Turnover_Ratio": 0.38}', '{"volume_metrics": {"Vol_3M": 110583, "Vol_Recent": 111200}, "moving_averages": {"MA_50": 38.985, "MA_200": 37.825}}', '{"asset_allocation": {"Bond_Weight": 0, "Equity_Weight": 0.999}, "bond_characteristics": {"Avg_Maturity": null, "Duration_Yrs": null}}', '{"valuation_metrics": {"PB_Ratio": 2.83, "PE_Ratio": 21.59, "PS_Ratio": 1.74, "PCF_Ratio": 12.77}}');
INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (1181, 'LGLV', 'ETF', 'us', 'AMG River Road Small Cap Value ', 'AMG River Road Small Cap Value Fund Class N', 'DOLLAR', 'Blend', 'Large', 'AMG Funds', 'PCX', 'Large Blend', 573564736, 0.0207, '2013-02-20', 0.25, 'The investment seeks long-term capital appreciation. Under normal conditions, the fund invests at least 80% of its assets in equity securities of small-cap companies that the subadviser believes are undervalued. Value investing involves buying stocks that are out of favor and/or undervalued in comparison to their peers or their prospects for growth. The fund may also invest in mid-cap companies, which the adviser currently considersto be companies with market capitalizations at the time of acquisition within the range of capitalizations of companies in the Russell Midcap© Index.', 0.0012, 0.0036, 24637, 13330, 140.81, 134.844, 0.9977, 0, 3.87, 18.33, 25.63, 3.14, NULL, NULL, '{"Cap_Size": "Large", "Quote_Mode": "ETF", "Currency_Base": "DOLLAR", "GeoZone_Class": "us", "Strategy_Type": "Blend"}', '{"Net_Worth": 573564736, "Yield_Rate": 0.0207, "Expense_Net": 0.0012, "Benchmark_Exp": 0.0036, "Turnover_Ratio": 0.25}', '{"volume_metrics": {"Vol_3M": 24637, "Vol_Recent": 13330}, "moving_averages": {"MA_50": 140.81, "MA_200": 134.844}}', '{"asset_allocation": {"Bond_Weight": 0, "Equity_Weight": 0.9977}, "bond_characteristics": {"Avg_Maturity": null, "Duration_Yrs": null}}', '{"valuation_metrics": {"PB_Ratio": 3.87, "PE_Ratio": 25.63, "PS_Ratio": 3.14, "PCF_Ratio": 18.33}}');
INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (1182, 'LGOV', 'ETF', 'U.S.A.', 'AB Global Real Estate Investmen', 'AB Global Real Estate Investment Fund Advisor Class', 'US Dollar', NULL, NULL, 'AllianceBernstein', 'PCX', 'Long Government', 36199008, 0.0323, '2019-01-22', 1.74, 'The investment seeks total return from long-term growth of capital and income. Under normal circumstances, the fund invests at least 80% of its net assets in the equity securities of real estate investment trusts, or REITs, and other real estate industry companies, such as real estate operating companies, or REOCs. It invests in U.S. and non-U.S. issuers. Under normal circumstances, it invests significantly (at least 40%--unless market conditions are not deemed favorable by the Adviser) in securities of non-U.S. companies. In addition, the fund invests, under normal circumstances, in the equity securities of companies located in at least three countries.', 0.007, 0.0014, 7929, 3750, 27.653, 27.616, NULL, NULL, NULL, NULL, NULL, NULL, 15.8, 9.31, '{"Cap_Size": null, "Quote_Mode": "ETF", "Currency_Base": "US Dollar", "GeoZone_Class": "U.S.A.", "Strategy_Type": null}', '{"Net_Worth": 36199008, "Yield_Rate": 0.0323, "Expense_Net": 0.007, "Benchmark_Exp": 0.0014, "Turnover_Ratio": 1.74}', '{"volume_metrics": {"Vol_3M": 7929, "Vol_Recent": 3750}, "moving_averages": {"MA_50": 27.653, "MA_200": 27.616}}', '{"asset_allocation": {"Bond_Weight": null, "Equity_Weight": null}, "bond_characteristics": {"Avg_Maturity": 15.8, "Duration_Yrs": 9.31}}', '{"valuation_metrics": {"PB_Ratio": null, "PE_Ratio": null, "PS_Ratio": null, "PCF_Ratio": null}}');
INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (1183, 'LIT', 'ETF', 'US', 'AMG River Road Small-Mid Cap Va', 'AMG River Road Small-Mid Cap Value Fund Class Z', 'AmericanDollar', 'Growth', 'Large', 'AMG Funds', 'PCX', 'Natural Resources', 3639320576, 0.0017, '2010-07-22', 0.6514, 'The investment seeks to provide long-term capital appreciation. The fund invests at least 80% of its net assets, plus the amount of any borrowings for investment purposes, in equity securities of small- and mid-capitalization companies that the subadviser believes are undervalued. The subadviser considers small- and mid-capitalization companies to be those with market capitalizations at the time of acquisition within the range of capitalizations of companies in the Russell 2500© Index. Value investing involves buying stocks that the subadviser believes are out of favor and/or undervalued in comparison to their peers or their prospects for growth.', 0.0075, 0.0048, 1049482, 1.27813e+06, 88.92, 75.087, 0.9968, 0, 4.95, 20.73, 40.26, 2.77, NULL, NULL, '{"Cap_Size": "Large", "Quote_Mode": "ETF", "Currency_Base": "AmericanDollar", "GeoZone_Class": "US", "Strategy_Type": "Growth"}', '{"Net_Worth": 3639320576, "Yield_Rate": 0.0017, "Expense_Net": 0.0075, "Benchmark_Exp": 0.0048, "Turnover_Ratio": 0.6514}', '{"volume_metrics": {"Vol_3M": 1049482, "Vol_Recent": 1278130}, "moving_averages": {"MA_50": 88.92, "MA_200": 75.087}}', '{"asset_allocation": {"Bond_Weight": 0, "Equity_Weight": 0.9968}, "bond_characteristics": {"Avg_Maturity": null, "Duration_Yrs": null}}', '{"valuation_metrics": {"PB_Ratio": 4.95, "PE_Ratio": 40.26, "PS_Ratio": 2.77, "PCF_Ratio": 20.73}}');
INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (1184, 'LIV', 'ETF', 'United States', 'American Century One Choice in ', 'American Century Investments One Choice In Retirement Portfolio A Class', 'AmericanDollar', 'Growth', 'Large', 'American Century Investments', 'BTS', NULL, 6739939, NULL, '2020-10-14', NULL, 'The investment seeks current income; capital appreciation is a secondary objective. The fund is a "fund of funds," meaning that it seeks to achieve its objective by investing in other American Century mutual funds (the underlying funds) that represent a variety of asset classes and investment styles. The fund''s investments generally will be allocated among the major asset classes as follow: 45% of its assets in equity securities (stock funds); 45% of its assets in fixed-income securities (bond funds); and 10% of its assets in cash equivalents (money market funds). The neutral mix of One Choice In Retirement Portfolio is expected to remain fixed over time.', 0.0049, NULL, 156, 390, 27.542, 26.938, 1, 0, 6.58, 21.85, 36.56, 3.56, NULL, NULL, '{"Cap_Size": "Large", "Quote_Mode": "ETF", "Currency_Base": "AmericanDollar", "GeoZone_Class": "United States", "Strategy_Type": "Growth"}', '{"Net_Worth": 6739939, "Yield_Rate": null, "Expense_Net": 0.0049, "Benchmark_Exp": null, "Turnover_Ratio": null}', '{"volume_metrics": {"Vol_3M": 156, "Vol_Recent": 390}, "moving_averages": {"MA_50": 27.542, "MA_200": 26.938}}', '{"asset_allocation": {"Bond_Weight": 0, "Equity_Weight": 1}, "bond_characteristics": {"Avg_Maturity": null, "Duration_Yrs": null}}', '{"valuation_metrics": {"PB_Ratio": 6.58, "PE_Ratio": 36.56, "PS_Ratio": 3.56, "PCF_Ratio": 21.85}}');
INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (1185, 'LKOR', 'ETF', 'America', 'Artisan High Income Fund Invest', 'Artisan High Income Fund Investor Shares', 'US_DOLLAR', 'Growth', 'Medium', 'Artisan', 'BTS', NULL, 48531428, 0.032, '2015-09-23', 0.74, 'The investment seeks to provide total return through a combination of current income and capital appreciation. Under normal circumstances, the fund will invest primarily in instruments that are rated, at the time of purchase, below investment grade (below BBB- by Standard & Poor''s Rating Services ("S&P") or Fitch, Inc. ("Fitch") or below Baa3 by Moody''s Investors Service, Inc. ("Moody''s")), or comparably rated by another nationally recognized statistical rating organization ("NRSRO"), or unrated but determined by Artisan Partners to be of comparable quality.', 0.0022, NULL, 4420, 3230, 60.294, 59.7, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 14.59, '{"Cap_Size": "Medium", "Quote_Mode": "ETF", "Currency_Base": "US_DOLLAR", "GeoZone_Class": "America", "Strategy_Type": "Growth"}', '{"Net_Worth": 48531428, "Yield_Rate": 0.032, "Expense_Net": 0.0022, "Benchmark_Exp": null, "Turnover_Ratio": 0.74}', '{"volume_metrics": {"Vol_3M": 4420, "Vol_Recent": 3230}, "moving_averages": {"MA_50": 60.294, "MA_200": 59.7}}', '{"asset_allocation": {"Bond_Weight": null, "Equity_Weight": null}, "bond_characteristics": {"Avg_Maturity": null, "Duration_Yrs": 14.59}}', '{"valuation_metrics": {"PB_Ratio": null, "PE_Ratio": null, "PS_Ratio": null, "PCF_Ratio": null}}');
INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (1186, 'LMBS', 'ETF', 'usa', 'Artisan Global Value Fund Inves', 'Artisan Global Value Fund Investor Class', 'AmericanDollar', NULL, NULL, 'Artisan', 'NGM', 'Short Government', 7260252160, 0.0218, '2014-11-04', 4.34, 'The investment seeks maximum long-term capital growth. The fund''s investment team employs a fundamental investment process to construct a diversified portfolio of securities of undervalued U.S. and non-U.S. companies. The team seeks to invest in what the team considers to be high quality, undervalued companies with strong balance sheets and shareholder-oriented management teams. Under normal market conditions, the fund primarily invests in common stocks and other equity securities, both within and outside the U.S.', 0.0068, 0.0013, 828003, 777760, 50.388, 50.832, NULL, NULL, NULL, NULL, NULL, NULL, 4.33, 1.42, '{"Cap_Size": null, "Quote_Mode": "ETF", "Currency_Base": "AmericanDollar", "GeoZone_Class": "usa", "Strategy_Type": null}', '{"Net_Worth": 7260252160, "Yield_Rate": 0.0218, "Expense_Net": 0.0068, "Benchmark_Exp": 0.0013, "Turnover_Ratio": 4.34}', '{"volume_metrics": {"Vol_3M": 828003, "Vol_Recent": 777760}, "moving_averages": {"MA_50": 50.388, "MA_200": 50.832}}', '{"asset_allocation": {"Bond_Weight": null, "Equity_Weight": null}, "bond_characteristics": {"Avg_Maturity": 4.33, "Duration_Yrs": 1.42}}', '{"valuation_metrics": {"PB_Ratio": null, "PE_Ratio": null, "PS_Ratio": null, "PCF_Ratio": null}}');
INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (1187, 'LOPP', 'ETF', 'US', 'Artisan Global Equity Fund Inve', 'Artisan Global Equity Fund Investor Class', 'Usd', NULL, NULL, 'Artisan', 'PCX', NULL, 9048931, NULL, '2021-01-29', NULL, 'The investment seeks maximum long-term capital growth. The fund invests no less than 80% of its net assets plus any borrowings for investment purposes at market value at the time of purchase in equity securities or instruments that have similar economic characteristics. It may invest in securities both within and outside the U.S., including emerging and less developed markets. Securities in which the fund may invest may include common stocks, preferred stocks, convertible securities, depositary receipts and rights and warrants to buy common stocks.', NULL, NULL, 512, 160, 29.068, 28.064, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '{"Cap_Size": null, "Quote_Mode": "ETF", "Currency_Base": "Usd", "GeoZone_Class": "US", "Strategy_Type": null}', '{"Net_Worth": 9048931, "Yield_Rate": null, "Expense_Net": null, "Benchmark_Exp": null, "Turnover_Ratio": null}', '{"volume_metrics": {"Vol_3M": 512, "Vol_Recent": 160}, "moving_averages": {"MA_50": 29.068, "MA_200": 28.064}}', '{"asset_allocation": {"Bond_Weight": null, "Equity_Weight": null}, "bond_characteristics": {"Avg_Maturity": null, "Duration_Yrs": null}}', '{"valuation_metrics": {"PB_Ratio": null, "PE_Ratio": null, "PS_Ratio": null, "PCF_Ratio": null}}');
INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (1188, 'LOPX', 'ETF', 'UNITED_STATES', 'Artisan International Fund Inv ', 'Artisan International Fund Investor Class', 'Dollar', NULL, NULL, 'Artisan', 'PCX', 'Small Blend', NULL, NULL, '2021-07-22', NULL, 'The investment seeks maximum long-term capital growth. The fund invests primarily in developed markets but also may invest up to 35% of the fund''s total assets at market value at the time of purchase in emerging and less developed markets. Under normal market conditions, it is substantially fully invested in common stocks and similar securities, and invests at least 65% of its net assets at market value at the time of purchase in securities of non-U.S. companies.', 0.005, 0.004, 1138, 810, 9.305, 9.28, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '{"Cap_Size": null, "Quote_Mode": "ETF", "Currency_Base": "Dollar", "GeoZone_Class": "UNITED_STATES", "Strategy_Type": null}', '{"Net_Worth": null, "Yield_Rate": null, "Expense_Net": 0.005, "Benchmark_Exp": 0.004, "Turnover_Ratio": null}', '{"volume_metrics": {"Vol_3M": 1138, "Vol_Recent": 810}, "moving_averages": {"MA_50": 9.305, "MA_200": 9.28}}', '{"asset_allocation": {"Bond_Weight": null, "Equity_Weight": null}, "bond_characteristics": {"Avg_Maturity": null, "Duration_Yrs": null}}', '{"valuation_metrics": {"PB_Ratio": null, "PE_Ratio": null, "PS_Ratio": null, "PCF_Ratio": null}}');
