INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (1220, 'MDIV', 'ETF', 'UNITED_STATES', 'AllainzGI Small-Cap Blend Fund ', 'Virtus AllianzGI Small-Cap Fund R6', 'AmericanDollar', 'Value', 'Medium', 'Virtus', 'NGM', 'Allocation--50% to 70% Equity', 491046688, 0.0479, '2012-08-13', 1.06, 'The investment seeks long-term growth of capital and income. The fund seeks to achieve its objective by normally investing at least 80% of its net assets (plus borrowings made for investment purposes) in companies with smaller market capitalizations. The manager expects to invest principally in U.S. companies but may invest to a lesser extent in non-U.S. companies. The manager currently considers smaller market capitalization companies to be companies with market capitalizations that are smaller than the largest company in the fund''s benchmark, in the Russell 2000 Index.', 0.0068, 0.0072, 75283, 79280, 16.617, 16.601, NULL, NULL, 2.03, 8.19, 12.75, 1.16, NULL, 2.23, '{"Cap_Size": "Medium", "Quote_Mode": "ETF", "Currency_Base": "AmericanDollar", "GeoZone_Class": "UNITED_STATES", "Strategy_Type": "Value"}', '{"Net_Worth": 491046688, "Yield_Rate": 0.0479, "Expense_Net": 0.0068, "Benchmark_Exp": 0.0072, "Turnover_Ratio": 1.06}', '{"volume_metrics": {"Vol_3M": 75283, "Vol_Recent": 79280}, "moving_averages": {"MA_50": 16.617, "MA_200": 16.601}}', '{"asset_allocation": {"Bond_Weight": null, "Equity_Weight": null}, "bond_characteristics": {"Avg_Maturity": null, "Duration_Yrs": 2.23}}', '{"valuation_metrics": {"PB_Ratio": 2.03, "PE_Ratio": 12.75, "PS_Ratio": 1.16, "PCF_Ratio": 8.19}}');
INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (1227, 'MFMS', 'ETF', 'United States', 'AAM/HIMCO Short Duration Fund C', 'AAM/HIMCO Short Duration Fund Class C', 'US Dollar', 'Growth', 'Small', 'AAM', 'BTS', 'Small Growth', 185586048, 0.0538, '2018-10-29', 0.27, 'The investment seeks current income and long-term total return. The fund has an investment policy whereby at least 80% of the fund''s net assets (plus any borrowings for investment purposes) will be invested, under normal circumstances, in fixed income instruments. It normally invests at least 65% of its total assets in "investment grade" securities. The fund may invest up to 35% of its total assets in non-investment grade securities (often called "junk bonds"), as well as bank loans and loan participation interests.', 0.0085, 0.0033, 13540, 11710, 39.281, 39.095, NULL, NULL, 5.18, 27.75, 43.61, 4.44, NULL, NULL, '{"Cap_Size": "Small", "Quote_Mode": "ETF", "Currency_Base": "US Dollar", "GeoZone_Class": "United States", "Strategy_Type": "Growth"}', '{"Net_Worth": 185586048, "Yield_Rate": 0.0538, "Expense_Net": 0.0085, "Benchmark_Exp": 0.0033, "Turnover_Ratio": 0.27}', '{"volume_metrics": {"Vol_3M": 13540, "Vol_Recent": 11710}, "moving_averages": {"MA_50": 39.281, "MA_200": 39.095}}', '{"asset_allocation": {"Bond_Weight": null, "Equity_Weight": null}, "bond_characteristics": {"Avg_Maturity": null, "Duration_Yrs": null}}', '{"valuation_metrics": {"PB_Ratio": 5.18, "PE_Ratio": 43.61, "PS_Ratio": 4.44, "PCF_Ratio": 27.75}}');
INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (1222, 'MDYV', 'ETF', 'us', 'AB Cap Fund, Inc. - AB Select U', 'AB Select US Long/Short Portfolio Class C', 'DOLLAR', 'Value', 'Small', 'AllianceBernstein', 'PCX', 'Mid-Cap Value', 1641398656, 0.0149, '2005-11-08', 0.45, 'The investment seeks long-term growth of capital. Under normal circumstances, the fund invests at least 80% of its net assets in equity securities of U.S. companies, short positions in such securities, and cash and U.S. cash equivalents. Its investments will be focused on securities of companies with large and medium market capitalizations, but it may also take long and short positions in securities of small-capitalization companies. The fund may invest in non-U.S. companies, but currently intends to limit its investments in such companies to no more than 10% of its net assets.', 0.0015, 0.0043, 118231, 88930, 69.749, 67.947, 0.9986, 0, 2.06, 9.9, 18.2, 1.29, NULL, NULL, '{"Cap_Size": "Small", "Quote_Mode": "ETF", "Currency_Base": "DOLLAR", "GeoZone_Class": "us", "Strategy_Type": "Value"}', '{"Net_Worth": 1641398656, "Yield_Rate": 0.0149, "Expense_Net": 0.0015, "Benchmark_Exp": 0.0043, "Turnover_Ratio": 0.45}', '{"volume_metrics": {"Vol_3M": 118231, "Vol_Recent": 88930}, "moving_averages": {"MA_50": 69.749, "MA_200": 67.947}}', '{"asset_allocation": {"Bond_Weight": 0, "Equity_Weight": 0.9986}, "bond_characteristics": {"Avg_Maturity": null, "Duration_Yrs": null}}', '{"valuation_metrics": {"PB_Ratio": 2.06, "PE_Ratio": 18.2, "PS_Ratio": 1.29, "PCF_Ratio": 9.9}}');
INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (1223, 'MEAR', 'ETF', 'usa', 'American Century Small Company ', 'American Century Small Company Fund I Class', 'AmericanDollar', NULL, NULL, 'American Century Investments', 'BTS', 'Muni National Short', 265965104, 0.0048, '2015-03-03', 1.08, 'The investment seeks long-term capital growth by investing primarily in common stocks of small companies. Under normal market conditions, the fund will invest at least 80% of its net assets in stocks of smaller-capitalization U.S. companies. The portfolio managers consider small companies to be those that, at the time of investment, have a market capitalization not greater than that of the largest company in the Russell 2000© Index.', 0.0025, 0.0023, 29014, 36270, 50.137, 50.188, NULL, NULL, NULL, NULL, NULL, NULL, 0.68, 0.6, '{"Cap_Size": null, "Quote_Mode": "ETF", "Currency_Base": "AmericanDollar", "GeoZone_Class": "usa", "Strategy_Type": null}', '{"Net_Worth": 265965104, "Yield_Rate": 0.0048, "Expense_Net": 0.0025, "Benchmark_Exp": 0.0023, "Turnover_Ratio": 1.08}', '{"volume_metrics": {"Vol_3M": 29014, "Vol_Recent": 36270}, "moving_averages": {"MA_50": 50.137, "MA_200": 50.188}}', '{"asset_allocation": {"Bond_Weight": null, "Equity_Weight": null}, "bond_characteristics": {"Avg_Maturity": 0.68, "Duration_Yrs": 0.6}}', '{"valuation_metrics": {"PB_Ratio": null, "PE_Ratio": null, "PS_Ratio": null, "PCF_Ratio": null}}');
