INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (1233, 'MID', 'ETF', 'US', NULL, 'American Century Short Duration Fund G Class', 'USD', 'Growth', 'Medium', 'American Century Investments', 'PCX', 'Mid-Cap Growth', 17595048, NULL, '2020-07-15', 0.02, 'The investment seeks to maximize total return; as a secondary objective, the fund seeks a high level of income. The fund invests at least 65% of its assets in investment-grade, non-money market debt securities. No more than 10% of the fund''s assets may be invested in non-dollar denominated debt securities. The weighted average duration of the fund''s portfolio must be three years or shorter.', 0.0045, 0.0046, 2896, 3790, 59.832, 55.669, 0.99, 0, 7.63, 28.07, 49.26, 6.01, NULL, NULL, '{"Cap_Size": "Medium", "Quote_Mode": "ETF", "Currency_Base": "USD", "GeoZone_Class": "US", "Strategy_Type": "Growth"}', '{"Net_Worth": 17595048, "Yield_Rate": null, "Expense_Net": 0.0045, "Benchmark_Exp": 0.0046, "Turnover_Ratio": 0.02}', '{"volume_metrics": {"Vol_3M": 2896, "Vol_Recent": 3790}, "moving_averages": {"MA_50": 59.832, "MA_200": 55.669}}', '{"asset_allocation": {"Bond_Weight": 0, "Equity_Weight": 0.99}, "bond_characteristics": {"Avg_Maturity": null, "Duration_Yrs": null}}', '{"valuation_metrics": {"PB_Ratio": 7.63, "PE_Ratio": 49.26, "PS_Ratio": 6.01, "PCF_Ratio": 28.07}}');
