INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (1556, 'RJI', 'ETF', 'USA', 'Baird Aggregate Bond Fund Insti', 'Baird Aggregate Bond Fund Class Institutional', 'AmericanDollar', NULL, NULL, 'Baird', 'PCX', 'Commodities Broad Basket', 145075600, NULL, '2007-10-17', NULL, 'The investment seeks an annual rate of total return, before fund expenses, greater than the annual rate of total return of the Bloomberg Barclays U.S.A.gregate Bond Index. The fund normally invests at least 80% of its net assets in the following types of U.S. dollar-denominated debt obligations: U.S. government and other public-sector entities; asset-backed and mortgage-backed obligations of U.S. and foreign issuers; corporate debt of U.S. and foreign issuers.', 0.0075, 0.0081, 93057, 111970, 6.921, 6.282, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '{"Cap_Size": null, "Quote_Mode": "ETF", "Currency_Base": "AmericanDollar", "GeoZone_Class": "USA", "Strategy_Type": null}', '{"Net_Worth": 145075600, "Yield_Rate": null, "Expense_Net": 0.0075, "Benchmark_Exp": 0.0081, "Turnover_Ratio": null}', '{"volume_metrics": {"Vol_3M": 93057, "Vol_Recent": 111970}, "moving_averages": {"MA_50": 6.921, "MA_200": 6.282}}', '{"asset_allocation": {"Bond_Weight": null, "Equity_Weight": null}, "bond_characteristics": {"Avg_Maturity": null, "Duration_Yrs": null}}', '{"valuation_metrics": {"PB_Ratio": null, "PE_Ratio": null, "PS_Ratio": null, "PCF_Ratio": null}}');
INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (1236, 'MIG', 'ETF', 'UNITED_STATES', 'Nuveen Small Cap Select Fund Cl', 'Nuveen Small Cap Select Fund Class R6', 'usd', NULL, NULL, 'Nuveen', 'BTS', 'Corporate Bond', 15021559, NULL, '2020-12-01', NULL, 'The investment seeks capital appreciation. Under normal market conditions, the fund invests at least 80% of the sum of its net assets and the amount of any borrowings for investment purposes in common stocks of small-capitalization companies. Small-capitalization companies are defined as companies that have market capitalizations within the market capitalization range of the companies in the Russell 2000© Index on the last business day of the month in which its most recent reconstitution was completed.', 0.002, 0.0017, 543, 380, 24.858, 24.852, NULL, NULL, NULL, NULL, NULL, NULL, 11.72, 7.25, '{"Cap_Size": null, "Quote_Mode": "ETF", "Currency_Base": "usd", "GeoZone_Class": "UNITED_STATES", "Strategy_Type": null}', '{"Net_Worth": 15021559, "Yield_Rate": null, "Expense_Net": 0.002, "Benchmark_Exp": 0.0017, "Turnover_Ratio": null}', '{"volume_metrics": {"Vol_3M": 543, "Vol_Recent": 380}, "moving_averages": {"MA_50": 24.858, "MA_200": 24.852}}', '{"asset_allocation": {"Bond_Weight": null, "Equity_Weight": null}, "bond_characteristics": {"Avg_Maturity": 11.72, "Duration_Yrs": 7.25}}', '{"valuation_metrics": {"PB_Ratio": null, "PE_Ratio": null, "PS_Ratio": null, "PCF_Ratio": null}}');
