INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (1282, 'NERD', 'ETF', 'U.S.A.', 'Alger Spectra Fund Class I', 'Alger Spectra Fund Class I', 'DOLLAR', 'Growth', 'Medium', 'Alger', 'PCX', 'Consumer Cyclical', 98946024, 0.01, '2019-06-03', 0.93, 'The investment seeks long-term capital appreciation. The fund invests primarily in the equity securities of companies of any size that the manager believes demonstrate promising growth potential. Equity securities include common or preferred stocks that are listed on U.S. or foreign exchanges. It may invest a significant portion of its assets in securities of companies conducting business within a single sector, including the information technology, consumer discretionary, and health care sectors.', 0.005, 0.0045, 18782, 19400, 26.808, 29.686, 0.993, 0, 4.09, 18.2, 25.69, 2.73, NULL, NULL, '{"Cap_Size": "Medium", "Quote_Mode": "ETF", "Currency_Base": "DOLLAR", "GeoZone_Class": "U.S.A.", "Strategy_Type": "Growth"}', '{"Net_Worth": 98946024, "Yield_Rate": 0.01, "Expense_Net": 0.005, "Benchmark_Exp": 0.0045, "Turnover_Ratio": 0.93}', '{"volume_metrics": {"Vol_3M": 18782, "Vol_Recent": 19400}, "moving_averages": {"MA_50": 26.808, "MA_200": 29.686}}', '{"asset_allocation": {"Bond_Weight": 0, "Equity_Weight": 0.993}, "bond_characteristics": {"Avg_Maturity": null, "Duration_Yrs": null}}', '{"valuation_metrics": {"PB_Ratio": 4.09, "PE_Ratio": 25.69, "PS_Ratio": 2.73, "PCF_Ratio": 18.2}}');
INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (1238, 'MINC', 'ETF', 'US', 'American Century Select Fund R ', 'American Century Select Fund R Class', 'US_DOLLAR', 'Value', 'Medium', 'American Century Investments', 'PCX', NULL, 99690896, 0.0193, '2013-03-19', NULL, 'The investment seeks long-term capital growth. The fund normally invests in stocks of companies that the adviser believes will increase in value over time. The portfolio managers make their investment decisions based primarily on their analysis of individual companies, rather than on broad economic forecasts. The portfolio managers use a variety of analytical research tools and techniques to identify the stocks of larger-sized companies that meet their investment criteria. Under normal market conditions, the portfolio managers seek securities of companies whose earnings or revenues are not only growing, but growing at an accelerated pace.', 0.0076, NULL, 6508, 5380, 48.608, 48.795, NULL, NULL, NULL, NULL, NULL, NULL, 3.06, 2.01, '{"Cap_Size": "Medium", "Quote_Mode": "ETF", "Currency_Base": "US_DOLLAR", "GeoZone_Class": "US", "Strategy_Type": "Value"}', '{"Net_Worth": 99690896, "Yield_Rate": 0.0193, "Expense_Net": 0.0076, "Benchmark_Exp": null, "Turnover_Ratio": null}', '{"volume_metrics": {"Vol_3M": 6508, "Vol_Recent": 5380}, "moving_averages": {"MA_50": 48.608, "MA_200": 48.795}}', '{"asset_allocation": {"Bond_Weight": null, "Equity_Weight": null}, "bond_characteristics": {"Avg_Maturity": 3.06, "Duration_Yrs": 2.01}}', '{"valuation_metrics": {"PB_Ratio": null, "PE_Ratio": null, "PS_Ratio": null, "PCF_Ratio": null}}');
INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (1239, 'MINN', 'ETF', 'us', 'AlphaSimplex Managed Futures St', 'AlphaSimplex Managed Futures Strategy Fund Class C', 'US_DOLLAR', NULL, NULL, 'Natixis Funds', 'BTS', 'Muni Minnesota', 12605519, NULL, '2021-03-11', NULL, 'The investment seeks to provide capital appreciation. The adviser expected that no more than 25% of the fund''s total assets will be dedicated to initial and variation margin payments relating to the fund''s derivative transactions. The advisor expects that under normal market conditions the fund will invest at least 75% of its total assets in money market and other short-term, high-quality securities. The fund will concentrate its investments in the financial services industry, which means it will normally invest at least 25% of its total assets in securities and other obligations of issuers in such industry.', 0.0039, NULL, 5996, 2840, 25.002, 25.185, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '{"Cap_Size": null, "Quote_Mode": "ETF", "Currency_Base": "US_DOLLAR", "GeoZone_Class": "us", "Strategy_Type": null}', '{"Net_Worth": 12605519, "Yield_Rate": null, "Expense_Net": 0.0039, "Benchmark_Exp": null, "Turnover_Ratio": null}', '{"volume_metrics": {"Vol_3M": 5996, "Vol_Recent": 2840}, "moving_averages": {"MA_50": 25.002, "MA_200": 25.185}}', '{"asset_allocation": {"Bond_Weight": null, "Equity_Weight": null}, "bond_characteristics": {"Avg_Maturity": null, "Duration_Yrs": null}}', '{"valuation_metrics": {"PB_Ratio": null, "PE_Ratio": null, "PS_Ratio": null, "PCF_Ratio": null}}');
INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (1241, 'MJ', 'ETF', 'UNITED_STATES', 'Absolute Strategies Insti Share', 'Absolute Strategies Fund Institutional Class', 'DOLLAR', 'Growth', 'Small', 'Absolute Strategies', 'PCX', 'Miscellaneous Sector', 1605340544, 0.0175, '2015-12-03', 0.46, 'The investment seeks long-term capital appreciation with an emphasis on absolute returns and low sensitivity to traditional financial market indices such as the S&P 500©. The fund''s investment adviser, believes that there are important benefits that come from investing through skilled asset managers whose strategies, when combined, seek to provide attractive long-term risk-adjusted returns, with lower volatility and low sensitivity to traditional market measures. Absolute selects the fund''s Subadvisers and determines the portion of the fund''s assets to be allocated to each Subadviser.', 0.0075, 0.0067, 1335629, 1.56156e+06, 13.989, 18.451, 0.9451, 0.048, 2.66, NULL, NULL, 3.05, NULL, NULL, '{"Cap_Size": "Small", "Quote_Mode": "ETF", "Currency_Base": "DOLLAR", "GeoZone_Class": "UNITED_STATES", "Strategy_Type": "Growth"}', '{"Net_Worth": 1605340544, "Yield_Rate": 0.0175, "Expense_Net": 0.0075, "Benchmark_Exp": 0.0067, "Turnover_Ratio": 0.46}', '{"volume_metrics": {"Vol_3M": 1335629, "Vol_Recent": 1561560}, "moving_averages": {"MA_50": 13.989, "MA_200": 18.451}}', '{"asset_allocation": {"Bond_Weight": 0.048, "Equity_Weight": 0.9451}, "bond_characteristics": {"Avg_Maturity": null, "Duration_Yrs": null}}', '{"valuation_metrics": {"PB_Ratio": 2.66, "PE_Ratio": null, "PS_Ratio":