INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (1268, 'MUB', 'ETF', 'United States', 'AB Cap Fund, Inc. - AB Select U', 'AB Select US Long/Short Portfolio Class A', 'DOLLAR', NULL, NULL, 'AllianceBernstein', 'PCX', 'Muni National Interm', 22714054656, 0.0196, '2007-09-07', 0.1, 'The investment seeks long-term growth of capital. Under normal circumstances, the fund invests at least 80% of its net assets in equity securities of U.S. companies, short positions in such securities, and cash and U.S. cash equivalents. Its investments will be focused on securities of companies with large and medium market capitalizations, but it may also take long and short positions in securities of small-capitalization companies. The fund may invest in non-U.S. companies, but currently intends to limit its investments in such companies to no more than 10% of its net assets.', 0.0007, 0.0029, 1364342, 1.46476e+06, 116.033, 116.638, NULL, NULL, NULL, NULL, NULL, NULL, 5.25, 6.15, '{"Cap_Size": null, "Quote_Mode": "ETF", "Currency_Base": "DOLLAR", "GeoZone_Class": "United States", "Strategy_Type": null}', '{"Net_Worth": 22714054656, "Yield_Rate": 0.0196, "Expense_Net": 0.0007, "Benchmark_Exp": 0.0029, "Turnover_Ratio": 0.1}', '{"volume_metrics": {"Vol_3M": 1364342, "Vol_Recent": 1464760}, "moving_averages": {"MA_50": 116.033, "MA_200": 116.638}}', '{"asset_allocation": {"Bond_Weight": null, "Equity_Weight": null}, "bond_characteristics": {"Avg_Maturity": 5.25, "Duration_Yrs": 6.15}}', '{"valuation_metrics": {"PB_Ratio": null, "PE_Ratio": null, "PS_Ratio": null, "PCF_Ratio": null}}');
INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (1269, 'MUNI', 'ETF', 'UNITED_STATES', 'American Century Select Fund - ', 'American Century Select Fund R5 Class', 'US Dollar', NULL, NULL, 'American Century Investments', 'PCX', 'Muni National Interm', 635808000, 0.0173, '2009-11-30', 0.34, 'The investment seeks long-term capital growth. The fund normally invests in stocks of companies that the adviser believes will increase in value over time. The portfolio managers make their investment decisions based primarily on their analysis of individual companies, rather than on broad economic forecasts. The portfolio managers use a variety of analytical research tools and techniques to identify the stocks of larger-sized companies that meet their investment criteria. Under normal market conditions, the portfolio managers seek securities of companies whose earnings or revenues are not only growing, but growing at an accelerated pace.', 0.0035, 0.0029, 41203, 34930, 56.229, 56.541, NULL, NULL, NULL, NULL, NULL, NULL, 4.93, 4.47, '{"Cap_Size": null, "Quote_Mode": "ETF", "Currency_Base": "US Dollar", "GeoZone_Class": "UNITED_STATES", "Strategy_Type": null}', '{"Net_Worth": 635808000, "Yield_Rate": 0.0173, "Expense_Net": 0.0035, "Benchmark_Exp": 0.0029, "Turnover_Ratio": 0.34}', '{"volume_metrics": {"Vol_3M": 41203, "Vol_Recent": 34930}, "moving_averages": {"MA_50": 56.229, "MA_200": 56.541}}', '{"asset_allocation": {"Bond_Weight": null, "Equity_Weight": null}, "bond_characteristics": {"Avg_Maturity": 4.93, "Duration_Yrs": 4.47}}', '{"valuation_metrics": {"PB_Ratio": null, "PE_Ratio": null, "PS_Ratio": null, "PCF_Ratio": null}}');
