INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (1272, 'MVP', 'ETF', 'us', 'American Century Strategic Allo', 'American Century Strategic Allocation: Moderate Fund R6 Class', 'US Dollar', 'Blend', 'Small', 'American Century Investments', 'PCX', NULL, 11515677, NULL, '2021-03-16', NULL, 'The investment seeks the highest level of total return consistent with its asset mix. The fund''s asset allocation strategy diversifies investments among equity securities, bonds and money market instruments. It usually invests 64% of its assets in stocks, 32% of its assets in bonds, and 4% of its assets in cash equivalents. The fund also invests in a variety of debt securities payable in U.S. and foreign currencies. It may invest in any type of U.S. or foreign equity security that meets certain fundamental and technical standards. The fund may invest up to 10% of its assets in below investment-grade securities.', 0.0075, NULL, 8382, 33150, 14.279, 14.514, NULL, NULL, 3.99, 12.87, NULL, 2.93, NULL, NULL, '{"Cap_Size": "Small", "Quote_Mode": "ETF", "Currency_Base": "US Dollar", "GeoZone_Class": "us", "Strategy_Type": "Blend"}', '{"Net_Worth": 11515677, "Yield_Rate": null, "Expense_Net": 0.0075, "Benchmark_Exp": null, "Turnover_Ratio": null}', '{"volume_metrics": {"Vol_3M": 8382, "Vol_Recent": 33150}, "moving_averages": {"MA_50": 14.279, "MA_200": 14.514}}', '{"asset_allocation": {"Bond_Weight": null, "Equity_Weight": null}, "bond_characteristics": {"Avg_Maturity": null, "Duration_Yrs": null}}', '{"valuation_metrics": {"PB_Ratio": 3.99, "PE_Ratio": null, "PS_Ratio": 2.93, "PCF_Ratio": 12.87}}');
INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (1273, 'MVV', 'ETF', 'us', 'Invesco Summit Fund Class A', 'Invesco Summit Fund Class A', 'US Dollar', 'Blend', 'Medium', 'Invesco', 'PCX', 'Trading--Leveraged Equity', 175027920, 0.0013, '2006-06-19', 0.31, 'The investment seeks long-term growth of capital. The fund invests primarily in equity securities of issuers of all market capitalizations that are considered by the fund''s portfolio managers to have potential for earnings or revenue growth. The principal type of equity securities in which it invests is common stock. The fund does not invest in companies whose primary business involves alcohol, tobacco or gambling. It may invest up to 25% of its net assets in foreign securities, including up to 10% of its net assets in emerging markets countries, i.e., those that are generally in the early stages of their industrial cycles. The fund is non-diversified.', 0.0095, 0.009, 50222, 86470, 68.212, 64.591, NULL, NULL, NULL, NULL, NULL, 1.77, NULL, NULL, '{"Cap_Size": "Medium", "Quote_Mode": "ETF", "Currency_Base": "US Dollar", "GeoZone_Class": "us", "Strategy_Type": "Blend"}', '{"Net_Worth": 175027920, "Yield_Rate": 0.0013, "Expense_Net": 0.0095, "Benchmark_Exp": 0.009, "Turnover_Ratio": 0.31}', '{"volume_metrics": {"Vol_3M": 50222, "Vol_Recent": 86470}, "moving_averages": {"MA_50": 68.212, "MA_200": 64.591}}', '{"asset_allocation": {"Bond_Weight": null, "Equity_Weight": null}, "bond_characteristics": {"Avg_Maturity": null, "Duration_Yrs": null}}', '{"valuation_metrics": {"PB_Ratio": null, "PE_Ratio": null, "PS_Ratio": 1.77, "PCF_Ratio": null}}');
INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (1274, 'MXDU', 'ETF', 'America', 'AQR Small Cap Momentum Style Fu', 'AQR Small Cap Momentum Style Fund Class N', 'AmericanDollar', 'Blend', 'Large', 'AQR Funds', 'PCX', 'Large Blend', 119548696, 0.016, '2017-09-15', 0.4, 'The investment seeks long-term capital appreciation. The fund pursues a momentum investment style by investing primarily in equity or equity-related securities (including, but not limited to, exchange-traded funds, equity index futures and real estate investment trusts) of small-cap companies traded on a principal U.S. exchange or over-the-counter market that the Adviser determines to have positive momentum. Under normal market circumstances, it will invest at least 80% of its net assets (including any borrowings for investment purposes) in small-cap U.S. companies. The fund invests significantly in common stocks.', 0.0034, 0.0036, 2637, 12950, 41.237, 40.274, 0.9971, 0, 4.15, 15.39, 25.23, 2.46, NULL, NULL, '{"Cap_Size": "Large", "Quote_Mode": "ETF", "Currency_Base": "AmericanDollar", "GeoZone_Class": "America", "Strategy_Type": "Blend"}', '{"Net_Worth": 119548696, "Yield_Rate": 0.016, "Expense_Net": 0.0034, "Benchmark_Exp": 0.0036, "Turnover_Ratio": 0.4}', '{"volume_metrics": {"Vol_3M": 2637, "Vol_Recent": 12950}, "moving_averages": {"MA_50": 41.237, "MA_200": 40.274}}', '{"asset_allocation": {"Bond_Weight": 0, "Equity_Weight": 0.9971}, "bond_characteristics": {"Avg_Maturity": null, "Duration_Yrs": null}}', '{"valuation_metrics": {"PB_Ratio": 4.15, "PE_Ratio": 25.23, "PS_Ratio": 2.46, "PCF_Ratio": 15.39}}');
