INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (1278, 'NAIL', 'ETF', 'USA', 'Invesco Summit Fund Class Y', 'Invesco Summit Fund Class Y', 'US$', 'Value', 'Medium', 'Invesco', 'PCX', 'Trading--Leveraged Equity', 470225600, NULL, '2015-08-19', 1.34, 'The investment seeks long-term growth of capital. The fund invests primarily in equity securities of issuers of all market capitalizations that are considered by the fund''s portfolio managers to have potential for earnings or revenue growth. The principal type of equity securities in which it invests is common stock. The fund does not invest in companies whose primary business involves alcohol, tobacco or gambling. It may invest up to 25% of its net assets in foreign securities, including up to 10% of its net assets in emerging markets countries, i.e., those that are generally in the early stages of their industrial cycles. The fund is non-diversified.', 0.01, 0.009, 386911, 272940, 85.411, 81.366, NULL, NULL, 2.64, 11.06, 13.48, 1.25, NULL, NULL, '{"Cap_Size": "Medium", "Quote_Mode": "ETF", "Currency_Base": "US$", "GeoZone_Class": "USA", "Strategy_Type": "Value"}', '{"Net_Worth": 470225600, "Yield_Rate": null, "Expense_Net": 0.01, "Benchmark_Exp": 0.009, "Turnover_Ratio": 1.34}', '{"volume_metrics": {"Vol_3M": 386911, "Vol_Recent": 272940}, "moving_averages": {"MA_50": 85.411, "MA_200": 81.366}}', '{"asset_allocation": {"Bond_Weight": null, "Equity_Weight": null}, "bond_characteristics": {"Avg_Maturity": null, "Duration_Yrs": null}}', '{"valuation_metrics": {"PB_Ratio": 2.64, "PE_Ratio": 13.48, "PS_Ratio": 1.25, "PCF_Ratio": 11.06}}');
INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (1279, 'NANR', 'ETF', 'US', 'Alger Weatherbie Specialized Gr', 'Alger Weatherbie Specialized Growth Fund Class Z', 'Dollar', 'Value', 'Large', 'Alger', 'PCX', 'Natural Resources', 558150656, 0.0241, '2015-12-15', 0.22, 'The investment seeks long-term capital appreciation. Under normal circumstances, the fund invests at least 80% of its net assets, plus any borrowings for investment purposes, in equity securities of smallcap and midcap companies. Equity securities include common or preferred stocks that are listed on U.S. or foreign exchanges. Smallcap or midcap companies are companies that, at the time of purchase, have total market capitalization within the range of companies included in the Russell 2500 Growth Index or the Russell Midcap Growth Index, respectively, as reported by the indexes as of the most recent quarter-end.', 0.0035, 0.0048, 23498, 9340, 43.186, 41.083, 0.9982, 0, 1.85, 12.72, 25.35, 2.05, NULL, NULL, '{"Cap_Size": "Large", "Quote_Mode": "ETF", "Currency_Base": "Dollar", "GeoZone_Class": "US", "Strategy_Type": "Value"}', '{"Net_Worth": 558150656, "Yield_Rate": 0.0241, "Expense_Net": 0.0035, "Benchmark_Exp": 0.0048, "Turnover_Ratio": 0.22}', '{"volume_metrics": {"Vol_3M": 23498, "Vol_Recent": 9340}, "moving_averages": {"MA_50": 43.186, "MA_200": 41.083}}', '{"asset_allocation": {"Bond_Weight": 0, "Equity_Weight": 0.9982}, "bond_characteristics": {"Avg_Maturity": null, "Duration_Yrs": null}}', '{"valuation_metrics": {"PB_Ratio": 1.85, "PE_Ratio": 25.35, "PS_Ratio": 2.05, "PCF_Ratio": 12.72}}');
