INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (1302, 'NUEM', 'ETF', 'U.S.A.', 'AllianzGl Global Sustainability', 'Virtus AllianzGI Global Sustainability Fund Institutional Class', 'US Dollar', 'Blend', 'Large', 'Virtus', 'BTS', NULL, 92348056, 0.0119, '2017-06-06', 0.81, 'The investment seeks long-term capital appreciation. The fund seeks to achieve its investment objective by creating a portfolio of global equities with a focus on companies that the portfolio managers believe exhibit strong records with respect to environmental, social, and corporate governance ("ESG") factors. It normally invests primarily in equity securities of both U.S. and non-U.S. companies, including emerging market securities. Under normal market conditions, the fund will invest at least 40% of its assets in non-U.S. securities.', 0.0045, NULL, 19596, 29280, 34.278, 35.179, 0.9972, 0, 2.28, 12.66, 19.06, 1.7, NULL, NULL, '{"Cap_Size": "Large", "Quote_Mode": "ETF", "Currency_Base": "US Dollar", "GeoZone_Class": "U.S.A.", "Strategy_Type": "Blend"}', '{"Net_Worth": 92348056, "Yield_Rate": 0.0119, "Expense_Net": 0.0045, "Benchmark_Exp": null, "Turnover_Ratio": 0.81}', '{"volume_metrics": {"Vol_3M": 19596, "Vol_Recent": 29280}, "moving_averages": {"MA_50": 34.278, "MA_200": 35.179}}', '{"asset_allocation": {"Bond_Weight": 0, "Equity_Weight": 0.9972}, "bond_characteristics": {"Avg_Maturity": null, "Duration_Yrs": null}}', '{"valuation_metrics": {"PB_Ratio": 2.28, "PE_Ratio": 19.06, "PS_Ratio": 1.7, "PCF_Ratio": 12.66}}');
