INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (1306, 'NULG', 'ETF', 'UNITED_STATES', 'American Beacon Small Cap Value', 'American Beacon Small Cap Value Fund C Class', 'US$', 'Growth', 'Large', 'American Beacon', 'BTS', NULL, 660049280, 0.0017, '2016-12-13', 0.86, 'The investment seeks long-term capital appreciation and current income. Under normal circumstances, at least 80% of the fund''s net assets (plus the amount of any borrowings for investment purposes) are invested in equity securities of small market capitalization U.S. companies. These companies have market capitalizations of $5 billion or less at the time of investment. The fund''s investments may include common stocks, preferred stocks, real estate investment trusts ("REITs"), American Depositary Receipts ("ADRs"), master limited partnerships ("MLPs"), and U.S. dollar-denominated foreign stocks traded on U.S. exchanges (collectively, "stocks").', 0.0035, NULL, 93953, 57990, 70.105, 64.637, 0.9984, 0, 10.34, 28.42, 40.21, 6.72, NULL, NULL, '{"Cap_Size": "Large", "Quote_Mode": "ETF", "Currency_Base": "US$", "GeoZone_Class": "UNITED_STATES", "Strategy_Type": "Growth"}', '{"Net_Worth": 660049280, "Yield_Rate": 0.0017, "Expense_Net": 0.0035, "Benchmark_Exp": null, "Turnover_Ratio": 0.86}', '{"volume_metrics": {"Vol_3M": 93953, "Vol_Recent": 57990}, "moving_averages": {"MA_50": 70.105, "MA_200": 64.637}}', '{"asset_allocation": {"Bond_Weight": 0, "Equity_Weight": 0.9984}, "bond_characteristics": {"Avg_Maturity": null, "Duration_Yrs": null}}', '{"valuation_metrics": {"PB_Ratio": 10.34, "PE_Ratio": 40.21, "PS_Ratio": 6.72, "PCF_Ratio": 28.42}}');
