INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (1335, 'OUNZ', 'ETF', 'UNITED_STATES', 'Invesco Limited Term Muni Inc F', 'Invesco Limited Term Municipal Income Fund Class A', 'USD', NULL, NULL, 'Invesco', 'PCX', NULL, 466021472, NULL, '2014-05-16', NULL, 'The investment seeks federal tax-exempt current income. The fund invests, under normal circumstances, at least 80% of its net assets (plus any borrowings for investment purposes) in municipal debt securities that (1) pay interest that is excluded from gross income for federal income tax purposes, and (2) do not produce income that will be considered to be an item of preference for purposes of the alternative minimum tax. At least 80% of its net assets will normally be invested in investment grade municipal debt securities. The advisor will attempt to maintain a dollar-weighted average effective portfolio maturity of five years or less.', 0.0025, NULL, 308493, 300080, 17.417, 17.431, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '{"Cap_Size": null, "Quote_Mode": "ETF", "Currency_Base": "USD", "GeoZone_Class": "UNITED_STATES", "Strategy_Type": null}', '{"Net_Worth": 466021472, "Yield_Rate": null, "Expense_Net": 0.0025, "Benchmark_Exp": null, "Turnover_Ratio": null}', '{"volume_metrics": {"Vol_3M": 308493, "Vol_Recent": 300080}, "moving_averages": {"MA_50": 17.417, "MA_200": 17.431}}', '{"asset_allocation": {"Bond_Weight": null, "Equity_Weight": null}, "bond_characteristics": {"Avg_Maturity": null, "Duration_Yrs": null}}', '{"valuation_metrics": {"PB_Ratio": null, "PE_Ratio": null, "PS_Ratio": null, "PCF_Ratio": null}}');
