INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (1340, 'OVL', 'ETF', 'us', 'American Century International ', 'American Century International Growth Fund R6 Class', 'US$', 'Blend', 'Large', 'American Century Investments', 'PCX', 'Large Blend', 185318080, 0.0251, '2019-09-30', NULL, 'The investment seeks capital growth. The fund invests primarily in securities of companies located in at least three developed countries world-wide (excluding the United States). Under normal market conditions, the fund''s portfolio managers seek securities of companies whose earnings, revenues or key business fundamentals are not only growing, but growing at an accelerating pace.', 0.0079, 0.0036, 9774, 5870, 39.109, 37.062, 0.9999, 0, 4.27, 17.31, 25.99, 2.89, NULL, NULL, '{"Cap_Size": "Large", "Quote_Mode": "ETF", "Currency_Base": "US$", "GeoZone_Class": "us", "Strategy_Type": "Blend"}', '{"Net_Worth": 185318080, "Yield_Rate": 0.0251, "Expense_Net": 0.0079, "Benchmark_Exp": 0.0036, "Turnover_Ratio": null}', '{"volume_metrics": {"Vol_3M": 9774, "Vol_Recent": 5870}, "moving_averages": {"MA_50": 39.109, "MA_200": 37.062}}', '{"asset_allocation": {"Bond_Weight": 0, "Equity_Weight": 0.9999}, "bond_characteristics": {"Avg_Maturity": null, "Duration_Yrs": null}}', '{"valuation_metrics": {"PB_Ratio": 4.27, "PE_Ratio": 25.99, "PS_Ratio": 2.89, "PCF_Ratio": 17.31}}');
INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (1343, 'OVS', 'ETF', 'USA', 'Anchor Risk Managed Global Stra', 'Anchor Risk Managed Global Strategies Fund Institutional Class Shares', 'US Dollar', 'Blend', 'Small', 'Anchor', 'PCX', 'Small Blend', 5615300, 0.0189, '2019-09-30', NULL, 'The investment seeks to achieve above average total returns over a full market cycle with lower correlation and reduced risk when compared to traditional world indices. The fund seeks to achieve its investment objective by allocating assets among various strategies based on the adviser''s research and analysis regarding market trends. It will invest at least 40% of its assets (plus the amount of borrowings, if any) in long and short positions in exchange-traded funds, mutual funds and derivative instruments registered and offered in the U.S. with underlying holdings in non-U.S. companies.', 0.0083, 0.004, 982, 330, 37.569, 36.646, NULL, NULL, 2.2, 10.4, 17.55, 1.24, NULL, NULL, '{"Cap_Size": "Small", "Quote_Mode": "ETF", "Currency_Base": "US Dollar", "GeoZone_Class": "USA", "Strategy_Type": "Blend"}', '{"Net_Worth": 5615300, "Yield_Rate": 0.0189, "Expense_Net": 0.0083, "Benchmark_Exp": 0.004, "Turnover_Ratio": null}', '{"volume_metrics": {"Vol_3M": 982, "Vol_Recent": 330}, "moving_averages": {"MA_50": 37.569, "MA_200": 36.646}}', '{"asset_allocation": {"Bond_Weight": null, "Equity_Weight": null}, "bond_characteristics": {"Avg_Maturity": null, "Duration_Yrs": null}}', '{"valuation_metrics": {"PB_Ratio": 2.2, "PE_Ratio": 17.55, "PS_Ratio": 1.24, "PCF_Ratio": 10.4}}');
INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (1344, 'OVT', 'ETF', 'UNITED_STATES', 'American Century Heritage Fd A ', 'American Century Heritage Fund A Class', 'AmericanDollar', NULL, NULL, 'American Century Investments', 'PCX', 'Short-Term Bond', 35412800, NULL, '2021-01-14', NULL, 'The investment seeks long-term capital growth. The fund normally invests in stocks of medium-sized companies that the adviser believes will increase in value over time, using an investment strategy developed by the fund''s investment advisor. In implementing this strategy, the portfolio managers make their investment decisions based primarily on their analysis of individual companies, rather than on broad economic forecasts. Management of the fund is based on the belief that durable franchises in a growing industry can sustain above average earnings growth.', 0.008, 0.0026, 10522, 2510, 24.897, 25.059, NULL, NULL, NULL, NULL, NULL, NULL, 3, 2.8, '{"Cap_Size": null, "Quote_Mode": "ETF", "Currency_Base": "AmericanDollar", "GeoZone_Class": "UNITED_STATES", "Strategy_Type": null}', '{"Net_Worth": 35412800, "Yield_Rate": null, "Expense_Net": 0.008, "Benchmark_Exp": 0.0026, "Turnover_Ratio": null}', '{"volume_metrics": {"Vol_3M": 10522, "Vol_Recent": 2510}, "moving_averages": {"MA_50": 24.897, "MA_200": 25.059}}', '{"asset_allocation": {"Bond_Weight": null, "Equity_Weight": null}, "bond_characteristics": {"Avg_Maturity": 3, "Duration_Yrs": 2.8}}', '{"valuation_metrics": {"PB_Ratio": null, "PE_Ratio": null, "PS_Ratio": null, "PCF_Ratio": null}}');
