INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (1351, 'PAVE', 'ETF', 'U.S.A.', 'Voya Global Multi-Asset Fund cl', 'Atlas U.S. Tactical Income Fund Class A', 'AmericanDollar', 'Blend', 'Medium', 'ATLAS US. TACTICAL INCOME FUND, INC.', 'BTS', NULL, 3688363008, 0.0035, '2017-03-06', NULL, 'The investment seeks to maximize total return, consistent with preservation of capital. The fund invests primarily in fixed-income securities, including U.S. government, mortgage-backed, and corporate debt securities and municipal obligations. It normally will invest at least 80% of its assets in a diversified portfolio of fixed-income instruments of varying maturities, and normally will maintain an average portfolio duration of negative 3 years to plus 6 years. The fund will generally invest up to 20% of its total assets in large capitalization stocks including through the use of passive investments, such as exchange traded funds ("ETFs").', 0.0047, NULL, 1457300, 1.70467e+06, 27.387, 26.16, 0.9989, 0, 3.64, 13.84, 28.3, 1.78, NULL, NULL, '{"Cap_Size": "Medium", "Quote_Mode": "ETF", "Currency_Base": "AmericanDollar", "GeoZone_Class": "U.S.A.", "Strategy_Type": "Blend"}', '{"Net_Worth": 3688363008, "Yield_Rate": 0.0035, "Expense_Net": 0.0047, "Benchmark_Exp": null, "Turnover_Ratio": null}', '{"volume_metrics": {"Vol_3M": 1457300, "Vol_Recent": 1704670}, "moving_averages": {"MA_50": 27.387, "MA_200": 26.16}}', '{"asset_allocation": {"Bond_Weight": 0, "Equity_Weight": 0.9989}, "bond_characteristics": {"Avg_Maturity": null, "Duration_Yrs": null}}', '{"valuation_metrics": {"PB_Ratio": 3.64, "PE_Ratio": 28.3, "PS_Ratio": 1.78, "PCF_Ratio": 13.84}}');
