INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (1360, 'PBUS', 'ETF', 'UNITED_STATES', 'Aquila Three Peaks High Income ', 'Aquila Three Peaks High Income Fund Class A', 'US Dollar', 'Blend', 'Large', 'Aquila', 'BTS', 'Large Blend', 2058950272, 0.0098, '2017-09-22', 0.05, 'The investment seeks to obtain high current income; capital appreciation is a secondary objective. The fund normally invests at least 80% of its net assets plus any borrowings for investment purposes in income-producing securities. Its portfolio will typically include a high proportion, perhaps even 100%, of high-yield/high-risk securities rated below investment grade. The bonds the fund purchases can be of any maturity but the average effective weighted maturity of the fund''s portfolio will normally be within one year of the average maturity of the Bloomberg Barclays US Corporate High Yield Total Return Index Value Unhedged.', 0.0004, 0.0036, 125174, 18670, 46.251, 43.792, 1, 0, 4.53, 17.9, 26.71, 3.01, NULL, NULL, '{"Cap_Size": "Large", "Quote_Mode": "ETF", "Currency_Base": "US Dollar", "GeoZone_Class": "UNITED_STATES", "Strategy_Type": "Blend"}', '{"Net_Worth": 2058950272, "Yield_Rate": 0.0098, "Expense_Net": 0.0004, "Benchmark_Exp": 0.0036, "Turnover_Ratio": 0.05}', '{"volume_metrics": {"Vol_3M": 125174, "Vol_Recent": 18670}, "moving_averages": {"MA_50": 46.251, "MA_200": 43.792}}', '{"asset_allocation": {"Bond_Weight": 0, "Equity_Weight": 1}, "bond_characteristics": {"Avg_Maturity": null, "Duration_Yrs": null}}', '{"valuation_metrics": {"PB_Ratio": 4.53, "PE_Ratio": 26.71, "PS_Ratio": 3.01, "PCF_Ratio": 17.9}}');
