INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (1392, 'PHB', 'ETF', 'us', 'AB Equity Income Fund, Inc. - C', 'AB Equity Income Fund Class C', 'DOLLAR', 'Value', 'Small', 'AllianceBernstein', 'PCX', NULL, 829724224, 0.0381, '2007-11-15', 0.35, 'The investment seeks current income and long-term growth of capital. The fund invests primarily in a diversified portfolio of equity securities of U.S. companies. Under normal circumstances, it invests at least 80% of its net assets in equity securities. The fund invests primarily in income-producing securities, targeting an investment in such securities of at least 65% of its total assets. It seeks current income and capital growth from investments in a wide range of industries.', 0.005, NULL, 423484, 354970, 19.405, 19.44, NULL, NULL, NULL, NULL, NULL, NULL, 5.04, 3.7, '{"Cap_Size": "Small", "Quote_Mode": "ETF", "Currency_Base": "DOLLAR", "GeoZone_Class": "us", "Strategy_Type": "Value"}', '{"Net_Worth": 829724224, "Yield_Rate": 0.0381, "Expense_Net": 0.005, "Benchmark_Exp": null, "Turnover_Ratio": 0.35}', '{"volume_metrics": {"Vol_3M": 423484, "Vol_Recent": 354970}, "moving_averages": {"MA_50": 19.405, "MA_200": 19.44}}', '{"asset_allocation": {"Bond_Weight": null, "Equity_Weight": null}, "bond_characteristics": {"Avg_Maturity": 5.04, "Duration_Yrs": 3.7}}', '{"valuation_metrics": {"PB_Ratio": null, "PE_Ratio": null, "PS_Ratio": null, "PCF_Ratio": null}}');
