INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (1403, 'PJAN', 'ETF', 'United States', 'AB Bond Fund, Inc. - AB Municip', 'AB Municipal Bond Inflation Strategy Class A', 'AmericanDollar', 'Blend', 'Large', 'AllianceBernstein', 'BTS', NULL, 369664416, NULL, '2018-12-31', NULL, 'The investment seeks to maximize real after-tax return for investors subject to federal income taxes, without undue risk to principal. The fund pursues its objective by investing principally in high-quality, predominantly investment-grade, municipal securities that pay interest exempt from federal taxation. It will invest at least 80% of its total assets in fixed-income securities rated A or better or the equivalent by one or more national rating agencies. The fund may invest up to 20% of its total assets in fixed-income securities rated BB or B or the equivalent by one or more national rating agencies, which are not investment-grade ("junk bonds").', 0.0079, NULL, 39996, 13440, 32.99, 32.344, 0.9929, 0, 4.42, 17.56, 26.45, 2.96, NULL, NULL, '{"Cap_Size": "Large", "Quote_Mode": "ETF", "Currency_Base": "AmericanDollar", "GeoZone_Class": "United States", "Strategy_Type": "Blend"}', '{"Net_Worth": 369664416, "Yield_Rate": null, "Expense_Net": 0.0079, "Benchmark_Exp": null, "Turnover_Ratio": null}', '{"volume_metrics": {"Vol_3M": 39996, "Vol_Recent": 13440}, "moving_averages": {"MA_50": 32.99, "MA_200": 32.344}}', '{"asset_allocation": {"Bond_Weight": 0, "Equity_Weight": 0.9929}, "bond_characteristics": {"Avg_Maturity": null, "Duration_Yrs": null}}', '{"valuation_metrics": {"PB_Ratio": 4.42, "PE_Ratio": 26.45, "PS_Ratio": 2.96, "PCF_Ratio": 17.56}}');
