INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (1419, 'PPH', 'ETF', 'America', 'Aegis Value Fd Inc', 'Aegis Value Fund Class I', 'AmericanDollar', 'Value', 'Large', 'Aegis', 'NGM', 'Health', 232719376, 0.0153, '2011-12-20', 0.18, 'The investment seeks long-term capital appreciation. The fund invests primarily in common stocks that the fund''s investment advisor believes are significantly undervalued relative to the market based on fundamental accounting measures including book value (assets less liabilities), revenues, or cash flow. It has no percentage allocation for investments in small- or mid-capitalization companies, and the fund may invest up to 100% of its portfolio in the securities of these companies.', 0.0035, 0.0049, 35863, 43850, 73.953, 72.575, 0.9989, 0, 2.93, 11.66, 20.1, 0.86, NULL, NULL, '{"Cap_Size": "Large", "Quote_Mode": "ETF", "Currency_Base": "AmericanDollar", "GeoZone_Class": "America", "Strategy_Type": "Value"}', '{"Net_Worth": 232719376, "Yield_Rate": 0.0153, "Expense_Net": 0.0035, "Benchmark_Exp": 0.0049, "Turnover_Ratio": 0.18}', '{"volume_metrics": {"Vol_3M": 35863, "Vol_Recent": 43850}, "moving_averages": {"MA_50": 73.953, "MA_200": 72.575}}', '{"asset_allocation": {"Bond_Weight": 0, "Equity_Weight": 0.9989}, "bond_characteristics": {"Avg_Maturity": null, "Duration_Yrs": null}}', '{"valuation_metrics": {"PB_Ratio": 2.93, "PE_Ratio": 20.1, "PS_Ratio": 0.86, "PCF_Ratio": 11.66}}');
