INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (1439, 'PSCX', 'ETF', 'America', NULL, 'Avantis Core Fixed Income Fund Institutional Class', 'USD', 'Blend', 'Large', 'Avantis Investors', 'BTS', 'Large Blend', 2180644, NULL, '2020-12-22', NULL, 'The investment seeks to maximize total return. The fund invests primarily in investment grade quality debt obligations from a diverse group of U.S. and non-U.S. issuers. Under normal market conditions, it will invest at least 80% of its net assets, plus any borrowings for investment purposes, in fixed income securities. Fixed income securities in which the fund may invest include corporate bonds and notes issued by U.S. and foreign corporations, securities issued by governments and their agencies, instrumentalities, or sponsored corporations-including supranational organizations.', 0.0075, 0.0036, 1006, 1750, 22.219, 21.819, 0.9931, 0, 4.42, 17.56, 26.45, 2.96, NULL, NULL, '{"Cap_Size": "Large", "Quote_Mode": "ETF", "Currency_Base": "USD", "GeoZone_Class": "America", "Strategy_Type": "Blend"}', '{"Net_Worth": 2180644, "Yield_Rate": null, "Expense_Net": 0.0075, "Benchmark_Exp": 0.0036, "Turnover_Ratio": null}', '{"volume_metrics": {"Vol_3M": 1006, "Vol_Recent": 1750}, "moving_averages": {"MA_50": 22.219, "MA_200": 21.819}}', '{"asset_allocation": {"Bond_Weight": 0, "Equity_Weight": 0.9931}, "bond_characteristics": {"Avg_Maturity": null, "Duration_Yrs": null}}', '{"valuation_metrics": {"PB_Ratio": 4.42, "PE_Ratio": 26.45, "PS_Ratio": 2.96, "PCF_Ratio": 17.56}}');
INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (1440, 'PSEP', 'ETF', 'United States', 'American Century Value Fund - I', 'American Century Value Fund I Class', 'Usd', 'Blend', 'Large', 'American Century Investments', 'BTS', NULL, 187920288, NULL, '2019-08-30', 0.03, 'The investment seeks long-term capital growth; income is a secondary objective. In selecting stocks for the fund, the portfolio managers look for companies of all sizes whose stock price may not reflect the company''s value. The managers attempt to purchase the stocks of these undervalued companies and hold each stock until the price has increased to, or is higher than, a level the managers believe more accurately reflects the fair value of the company. The fund may invest a portion of its assets in foreign securities when these securities meet the portfolio managers'' standards of selection.', 0.0079, NULL, 74614, 20120, 29.779, 29.327, 0.9998, 0, 4.42, 17.56, 26.46, 2.96, NULL, NULL, '{"Cap_Size": "Large", "Quote_Mode": "ETF", "Currency_Base": "Usd", "GeoZone_Class": "United States", "Strategy_Type": "Blend"}', '{"Net_Worth": 187920288, "Yield_Rate": null, "Expense_Net": 0.0079, "Benchmark_Exp": null, "Turnover_Ratio": 0.03}', '{"volume_metrics": {"Vol_3M": 74614, "Vol_Recent": 20120}, "moving_averages": {"MA_50": 29.779, "MA_200": 29.327}}', '{"asset_allocation": {"Bond_Weight": 0, "Equity_Weight": 0.9998}, "bond_characteristics": {"Avg_Maturity": null, "Duration_Yrs": null}}', '{"valuation_metrics": {"PB_Ratio": 4.42, "PE_Ratio": 26.46, "PS_Ratio": 2.96, "PCF_Ratio": 17.56}}');
INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (1441, 'PSET', 'ETF', 'us', NULL, 'Avantis Core Municipal Fixed Income Fund Institutional Class', 'US_DOLLAR', 'Blend', 'Large', 'Avantis Investors', 'NGM', NULL, 41021444, 0.0098, '2016-03-21', 1.037, 'The investment seeks current income that is exempt from federal income tax. The fund will invest at least 80% of its net assets, plus any borrowings for investment purposes, in municipal fixed income securities with interest payments exempt from federal income tax. A municipal fixed income security is a debt obligation issued by or on behalf of a state, its political subdivisions, agencies or instrumentalities, the District of Columbia or a U.S. territory or possession. It will invest primarily in investment grade securities as rated by an independent rating agency or determined by the advisor to be of comparable credit quality if a rating is unavailable.', 0.0015, NULL, 22237, 3080, 56.409, 53.339, 0.9983, 0, 7.05, 19.02, 26.52, 3.21, NULL, NULL, '{"Cap_Size": "Large", "Quote_Mode": "ETF", "Currency_Base": "US_DOLLAR", "GeoZone_Class": "us", "Strategy_Type": "Blend"}', '{"Net_Worth": 41021444, "Yield_Rate": 0.0098, "Expense_Net": 0.0015, "Benchmark_Exp": null, "Turnover_Ratio": 1.037}', '{"volume_metrics": {"Vol_3M": 22237, "Vol_Recent": 3080}, "moving_averages": {"MA_50": 56.409, "MA_200": 53.339}}', '{"asset_allocation": {"Bond_Weight": 0, "Equity_Weight": 0.9983}, "bond_characteristics": {"Avg_Maturity": null, "Duration_Yrs": null}}', '{"valuation_metrics": {"PB_Ratio": 7.05, "PE_Ratio": 26.52, "PS_Ratio": 3.21, "PCF_Ratio": 19.02}}');
INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (1442, 'PSFD', 'ETF', 'US', 'Arin Large Cap Theta Fund Advis', 'Arin Large Cap Theta Fund Advisor Class', 'US_DOLLAR', 'Blend', 'Large', 'Nottingham', 'BTS', 'Large Blend', 2877681, NULL, '2020-12-22', NULL, 'The investment seeks maximum relative total return versus the S&P 500 Stock Index through a combination of capital appreciation and current income. The fund normally will invest at least 80% of net assets, plus borrowings for investment purposes, in a portfolio of securities whose value is based on companies with market capitalizations that qualify them as "large-cap" companies. The advisor considers a company to be a "large cap" company if its market capitalization is at least $10 billion.', 0.0075, 0.0036, 3345, 3840, 23.763, 22.949, 0.9932, 0, 4.42, 17.56, 26.45, 2.96, NULL, NULL, '{"Cap_Size": "Large", "Quote_Mode": "ETF", "Currency_Base": "US_DOLLAR", "GeoZone_Class": "US", "Strategy_Type": "Blend"}', '{"Net_Worth": 2877681, "Yield_Rate": null, "Expense_Net": 0.0075, "Benchmark_Exp": 0.0036, "Turnover_Ratio": null}', '{"volume_metrics": {"Vol_3M": 3345, "Vol_Recent": 3840}, "moving_averages": {"MA_50": 23.763, "MA_200": 22.949}}', '{"asset_allocation": {"Bond_Weight": 0, "Equity_Weight": 0.9932}, "bond_characteristics": {"Avg_Maturity": null, "Duration_Yrs": null}}', '{"valuation_metrics": {"PB_Ratio": 4.42, "PE_Ratio": 26.45, "PS_Ratio": 2.96, "PCF_Ratio": 17.56}}');
INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (1444, 'PSFJ', 'ETF', 'U.S.A.', 'American Beacon Small Cap Value', 'American Beacon Small Cap Value Fund Investor Class', 'USD', NULL, NULL, 'American Beacon', 'BTS', 'Large Blend', 20, NULL, '2021-06-30', NULL, 'The investment seeks long-term capital appreciation and current income. Under normal circumstances, at least 80% of the fund''s net assets (plus the amount of any borrowings for investment purposes) are invested in equity securities of small market capitalization U.S. companies. These companies have market capitalizations of $5 billion or less at the time of investment. The fund''s investments may include common stocks, preferred stocks, real estate investment trusts ("REITs"), American Depositary Receipts ("ADRs"), master limited partnerships ("MLPs"), and U.S. dollar-denominated foreign stocks traded on U.S. exchanges (collectively, "stocks").', 0.0075, 0.0036, 2820, 2100, 21.171, 20.975, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '{"Cap_Size": null, "Quote_Mode": "ETF", "Currency_Base": "USD", "GeoZone_Class": "U.S.A.", "Strategy_Type": null}', '{"Net_Worth": 20, "Yield_Rate": null, "Expense_Net": 0.0075, "Benchmark_Exp": 0.0036, "Turnover_Ratio": null}', '{"volume_metrics": {"Vol_3M": 2820, "Vol_Recent": 2100}, "moving_averages": {"MA_50": 21.171, "MA_200": 20.975}}', '{"asset_allocation": {"Bond_Weight": null, "Equity_Weight": null}, "bond_characteristics": {"Avg_Maturity": null, "Duration_Yrs": null}}', '{"valuation_metrics": {"PB_Ratio": null, "PE_Ratio": null, "PS_Ratio": null, "PCF_Ratio": null}}');
