INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (1452, 'PSMM', 'ETF', 'usa', 'Avantis U.S. Small Cap Value Fu', 'Avantis U.S. Small Cap Value Fund Institutional Class', 'AmericanDollar', 'Blend', 'Large', 'Avantis Investors', 'BTS', 'Allocation--30% to 50% Equity', 12626441, 0.0218, '2017-02-21', 0.43, 'The investment seeks long-term capital appreciation. The fund invests primarily in a diverse group of U.S. small cap companies across market sectors and industry groups. It seeks securities of companies that the manager expects to have higher returns by placing an enhanced emphasis on securities of companies with smaller market capitalizations and securities of companies the manager defines as high profitability or value companies. Under normal market conditions, the fund will invest at least 80% of its assets in securities of small capitalization companies located in the United States.', 0.0033, 0.0037, 11230, 8110, 15.671, 15.387, NULL, NULL, 2.49, 10.66, 19.86, 1.39, 8.87, 6.2, '{"Cap_Size": "Large", "Quote_Mode": "ETF", "Currency_Base": "AmericanDollar", "GeoZone_Class": "usa", "Strategy_Type": "Blend"}', '{"Net_Worth": 12626441, "Yield_Rate": 0.0218, "Expense_Net": 0.0033, "Benchmark_Exp": 0.0037, "Turnover_Ratio": 0.43}', '{"volume_metrics": {"Vol_3M": 11230, "Vol_Recent": 8110}, "moving_averages": {"MA_50": 15.671, "MA_200": 15.387}}', '{"asset_allocation": {"Bond_Weight": null, "Equity_Weight": null}, "bond_characteristics": {"Avg_Maturity": 8.87, "Duration_Yrs": 6.2}}', '{"valuation_metrics": {"PB_Ratio": 2.49, "PE_Ratio": 19.86, "PS_Ratio": 1.39, "PCF_