INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (1459, 'PY', 'ETF', 'USA', 'CIBC Atlas Disciplined Equity F', 'CIBC Atlas Disciplined Equity Fund Institutional Class', 'US Dollar', 'Value', 'Medium', 'CIBC Private Wealth Management', 'NGM', NULL, 32322664, 0.0248, '2016-03-21', 0.476, 'The investment seeks long-term capital appreciation and, secondarily, current income. The fund invests at least 80% of its net assets, plus any borrowings for investment purposes, in equity securities and other instruments that have economic characteristics similar to equity securities. It invests primarily in equity securities of U.S. and foreign issuers, and the fund may also invest up to 25% of its net assets in foreign securities. It may invest in the securities of issuers of all capitalization sizes; however, a substantial number of the issuers in which the fund invests are large-capitalization issuers.', 0.0015, NULL, 15506, 2090, 43.25, 42.214, 0.9978, 0, 2.26, 7.81, 14.6, 1, NULL, NULL, '{"Cap_Size": "Medium", "Quote_Mode": "ETF", "Currency_Base": "US Dollar", "GeoZone_Class": "USA", "Strategy_Type": "Value"}', '{"Net_Worth": 32322664, "Yield_Rate": 0.0248, "Expense_Net": 0.0015, "Benchmark_Exp": null, "Turnover_Ratio": 0.476}', '{"volume_metrics": {"Vol_3M": 15506, "Vol_Recent": 2090}, "moving_averages": {"MA_50": 43.25, "MA_200": 42.214}}', '{"asset_allocation": {"Bond_Weight": 0, "Equity_Weight": 0.9978}, "bond_characteristics": {"Avg_Maturity": null, "Duration_Yrs": null}}', '{"valuation_metrics": {"PB_Ratio": 2.26, "PE_Ratio": 14.6, "PS_Ratio": 1, "PCF_Ratio": 7.81}}');
INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (1460, 'PYPE', 'ETF', 'U.S.A.', 'CIBC Atlas All Cap Growth Fund ', 'CIBC Atlas All Cap Growth Fund Institutional Class', 'Usd', NULL, NULL, 'CIBC Private Wealth Management', 'PCX', 'Energy Limited Partnership', 19591200, 0.0716, '2018-08-20', NULL, 'The investment seeks long-term capital appreciation. The fund seeks to achieve its investment objective by investing primarily in common stocks of U.S. companies without regard to market capitalizations. The fund''s investment strategy focuses on identifying stocks within multiple industry groups. It may invest up to 100% of its net assets in common stocks, and may also invest in preferred stocks, of U.S. companies. Additionally, the fund may invest up to 30% of its net assets in securities of "foreign issuers." The fund may invest up to 25% of its net assets in securities of "foreign issuers" located in emerging markets.', 0.0085, 0.0074, 538, 200, 19.066, 18.251, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '{"Cap_Size": null, "Quote_Mode": "ETF", "Currency_Base": "Usd", "GeoZone_Class": "U.S.A.", "Strategy_Type": null}', '{"Net_Worth": 19591200, "Yield_Rate": 0.0716, "Expense_Net": 0.0085, "Benchmark_Exp": 0.0074, "Turnover_Ratio": null}', '{"volume_metrics": {"Vol_3M": 538, "Vol_Recent": 200}, "moving_averages": {"MA_50": 19.066, "MA_200": 18.251}}', '{"asset_allocation": {"Bond_Weight": null, "Equity_Weight": null}, "bond_characteristics": {"Avg_Maturity": null, "Duration_Yrs": null}}', '{"valuation_metrics": {"PB_Ratio": null, "PE_Ratio": null, "PS_Ratio": null, "PCF_Ratio": null}}');
INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (1461, 'PYZ', 'ETF', 'America', 'CIBC Atlas Income Opportunities', 'CIBC Atlas Income Opportunities Fund Institutional Class', 'Usd', 'Value', 'Small', 'CIBC Private Wealth Management', 'NGM', 'Natural Resources', 217172528, 0.005, '2006-10-12', NULL, 'The investment seeks current income and long-term capital appreciation. Under normal circumstances, the fund invests at least 80% of its net assets, plus any borrowings for investment purposes, in income producing securities. The fund invests in a combination of common stock, preferred stock, convertible securities, fixed income securities (including corporate bonds, mortgage-backed and asset-backed securities, U.S. government securities, and money market instruments) and other investment companies (including exchange-traded funds ("ETFs") and closed-end investment companies ("closed-end funds").', 0.006, 0.0048, 19465, 7250, 90.509, 87.641, 0.9992, 0, 2.43, 10.51, 19.15, 1.19, NULL, NULL, '{"Cap_Size": "Small", "Quote_Mode": "ETF", "Currency_Base": "Usd", "GeoZone_Class": "America", "Strategy_Type": "Value"}', '{"Net_Worth": 217172528, "Yield_Rate": 0.005, "Expense_Net": 0.006, "Benchmark_Exp": 0.0048, "Turnover_Ratio": null}', '{"volume_metrics": {"Vol_3M": 19465, "Vol_Recent": 7250}, "moving_averages": {"MA_50": 90.509, "MA_200": 87.641}}', '{"asset_allocation": {"Bond_Weight": 0, "Equity_Weight": 0.9992}, "bond_characteristics": {"Avg_Maturity": null, "Duration_Yrs": null}}', '{"valuation_metrics": {"PB_Ratio": 2.43, "PE_Ratio": 19.15, "PS_Ratio": 1.19, "PCF_Ratio": 10.51}}');
INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (1462, 'PZA', 'ETF', 'UNITED_STATES', 'CIBC Atlas Mid Cap Equity Fund ', 'CIBC Atlas Mid Cap Equity Fund Institutional Class', 'USD', 'Growth', 'Medium', 'CIBC Private Wealth Management', 'PCX', NULL, 2358317568, 0.0233, '2007-10-11', 0.15, 'The investment seeks long-term capital appreciation. Under normal circumstances, the fund invests at least 80% of its net assets, plus any borrowings for investment purposes, in equity securities of mid-capitalization companies. While the adviser expects to invest primarily in common stock, it may also invest in other equity securities, including preferred stock, convertible securities and American Depositary Receipts ("ADRs"). It may invest up to 25% of its net assets in foreign securities, including ADRs.', 0.0028, NULL, 368331, 355720, 26.907, 27.065, 0, 0.9978, NULL, NULL, NULL, NULL, 20.98, 8.96, '{"Cap_Size": "Medium", "Quote_Mode": "ETF", "Currency_Base": "USD", "GeoZone_Class": "UNITED_STATES", "Strategy_Type": "Growth"}', '{"Net_Worth": 2358317568, "Yield_Rate": 0.0233, "Expense_Net": 0.0028, "Benchmark_Exp": null, "Turnover_Ratio": 0.15}', '{"volume_metrics": {"Vol_3M": 368331, "Vol_Recent": 355720}, "moving_averages": {"MA_50": 26.907, "MA_200": 27.065}}', '{"asset_allocation": {"Bond_Weight": 0.9978, "Equity_Weight": 0}, "bond_characteristics": {"Avg_Maturity": 20.98, "Duration_Yrs": 8.96}}', '{"valuation_metrics": {"PB_Ratio": null, "PE_Ratio": null, "PS_Ratio": null, "PCF_Ratio": null}}');
INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (1497, 'QQEW', 'ETF', 'U.S.', 'AllianzGI High Yield Bond Fund ', 'Virtus AllianzGI High Yield Bond Fund Administrative Class', 'USD', 'Growth', 'Large', 'Virtus', 'NGM', 'Large Growth', 1284150528, 0.0027, '2006-04-19', 0.28, 'The investment seeks a high level of current income and capital growth. The fund seeks to achieve its objective by normally investing at least 80% of its net assets (plus borrowings made for investment purposes) in high yield securities ("junk bonds"), which are fixed income securities rated below investment grade or unrated and determined to be of similar quality. The fund''s fixed income securities may be fixed-, variable- or floating-rate.', 0.0058, 0.0039, 44068, 37720, 115.986, 110.715, 0.9995, 0, 5.82, 20.53, 32.4, 2.04, NULL, NULL, '{"Cap_Size": "Large", "Quote_Mode": "ETF", "Currency_Base": "USD", "GeoZone_Class": "U.S.", "Strategy_Type": "Growth"}', '{"Net_Worth": 1284150528, "Yield_Rate": 0.0027, "Expense_Net": 0.0058, "Benchmark_Exp": 0.0039, "Turnover_Ratio": 0.28}', '{"volume_metrics": {"Vol_3M": 44068, "Vol_Recent": 37720}, "moving_averages": {"MA_50": 115.986, "MA_200": 110.715}}', '{"asset_allocation": {"Bond_Weight": 0, "Equity_Weight": 0.9995}, "bond_characteristics": {"Avg_Maturity": null, "Duration_Yrs": null}}', '{"valuation_metrics": {"PB_Ratio": 5.82, "PE_Ratio": 32.4, "PS_Ratio": 2.04, "PCF_Ratio": 20.53}}');
