INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (1481, 'QJUN', 'ETF', 'United States', 'CIBC Atlas International Growth', 'CIBC Atlas International Growth Fund Institutional Class Shares', 'USD', NULL, NULL, 'CIBC Private Wealth Management', 'BTS', NULL, NULL, NULL, '2021-06-18', NULL, 'The investment seeks to provide long-term capital appreciation. The fund seeks to achieve its investment objective by investing primarily in common stocks of U.S. issuers and common stocks and American Depositary Receipts ("ADRs") of foreign issuers without regard to market capitalizations. It typically invests in securities of issuers domiciled in at least three non-U.S. countries, with at least 40% of the fund''s net assets invested in securities of foreign issuers. The fund''s investments in securities of foreign issuers may include securities of issuers located in emerging markets.', 0.009, NULL, 14522, 1340, 20.926, 20.707, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '{"Cap_Size": null, "Quote_Mode": "ETF", "Currency_Base": "USD", "GeoZone_Class": "United States", "Strategy_Type": null}', '{"Net_Worth": null, "Yield_Rate": null, "Expense_Net": 0.009, "Benchmark_Exp": null, "Turnover_Ratio": null}', '{"volume_metrics": {"Vol_3M": 14522, "Vol_Recent": 1340}, "moving_averages": {"MA_50": 20.926, "MA_200": 20.707}}', '{"asset_allocation": {"Bond_Weight": null, "Equity_Weight": null}, "bond_characteristics": {"Avg_Maturity": null, "Duration_Yrs": null}}', '{"valuation_metrics": {"PB_Ratio": null, "PE_Ratio": null, "PS_Ratio": null, "PCF_Ratio": null}}');
INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (1482, 'QLC', 'ETF', 'usa', 'CIBC Atlas Equity Income Fund I', 'CIBC Atlas Equity Income Fund Institutional Class', 'AmericanDollar', 'Blend', 'Large', 'CIBC Private Wealth Management', 'BTS', NULL, 94831312, 0.0118, '2015-09-23', 0.48, 'The investment seeks current income and long-term capital appreciation. The fund invests in publicly traded securities without regard to market capitalizations. Its investment strategy focuses on identifying stocks within multiple industry groups. The fund seeks to generate current income while also providing capital appreciation. It has wide flexibility in the types of securities used to generate a current income yield. The fund may also invest up to 30% of its net assets in securities of "foreign issuers." It may invest up to 25% of its net assets in securities of "foreign issuers" located in emerging markets.', 0.0032, NULL, 6100, 3370, 49.71, 47.325, 0.9928, 0, 4.01, 16.05, 24.31, 2.43, NULL, NULL, '{"Cap_Size": "Large", "Quote_Mode": "ETF", "Currency_Base": "AmericanDollar", "GeoZone_Class": "usa", "Strategy_Type": "Blend"}', '{"Net_Worth": 94831312, "Yield_Rate": 0.0118, "Expense_Net": 0.0032, "Benchmark_Exp": null, "Turnover_Ratio": 0.48}', '{"volume_metrics": {"Vol_3M": 6100, "Vol_Recent": 3370}, "moving_averages": {"MA_50": 49.71, "MA_200": 47.325}}', '{"asset_allocation": {"Bond_Weight": 0, "Equity_Weight": 0.9928}, "bond_characteristics": {"Avg_Maturity": null, "Duration_Yrs": null}}', '{"valuation_metrics": {"PB_Ratio": 4.01, "PE_Ratio": 24.31, "PS_Ratio": 2.43, "PCF_Ratio": 16.05}}');
INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (1483, 'QLD', 'ETF', 'usa', 'Columbia Capital Allocation Agg', 'Columbia Capital Allocation Aggressive Portfolio Class A', 'US Dollar', 'Growth', 'Large', 'Columbia Threadneedle', 'PCX', 'Trading--Leveraged Equity', 5185311744, NULL, '2006-06-19', 0.33, 'The investment seeks the highest level of total return that is consistent with an aggressive level of risk. The fund is a "fund of funds" that seeks to achieve its investment objective by investing under normal circumstances in a combination of underlying funds for which the Investment Manager or an affiliate serves as investment adviser or principal underwriter. It may also invest up to 20% of its net assets in other funds, including third party advised (unaffiliated) funds and exchange-traded funds (ETFs), equity securities, fixed income securities and derivative instruments.', 0.0095, 0.009, 3111084, 4.67513e+06, 82.33, 71.882, NULL, NULL, NULL, NULL, NULL, 3.45, NULL, NULL, '{"Cap_Size": "Large", "Quote_Mode": "ETF", "Currency_Base": "US Dollar", "GeoZone_Class": "usa", "Strategy_Type": "Growth"}', '{"Net_Worth": 5185311744, "Yield_Rate": null, "Expense_Net": 0.0095, "Benchmark_Exp": 0.009, "Turnover_Ratio": 0.33}', '{"volume_metrics": {"Vol_3M": 3111084, "Vol_Recent": 4675130}, "moving_averages": {"MA_50": 82.33, "MA_200": 71.882}}', '{"asset_allocation": {"Bond_Weight": null, "Equity_Weight": null}, "bond_characteristics": {"Avg_Maturity": null, "Duration_Yrs": null}}', '{"valuation_metrics": {"PB_Ratio": null, "PE_Ratio": null, "PS_Ratio": 3.45, "PCF_Ratio": null}}');
INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (1484, 'QLS', 'ETF', 'UNITED_STATES', 'American Century Intermediate-T', 'American Century Intermediate Term Tax-Free Bond Fund I Class', 'US_DOLLAR', 'Blend', 'Large', 'American Century Investments', 'PCX', 'Long-Short Equity', 12191308, 0.0191, '2015-03-23', NULL, 'The investment seeks safety of principal and high current income that is exempt from federal income tax. The fund primarily invests in investment-grade debt securities and, under normal market conditions, will invest at least 80% of its net assets in debt securities with interest payments exempt from federal income tax. The fund''s weighted average maturity will be not less than three years nor more than ten years. However, there is no maturity limit on individual securities. The portfolio managers also may buy investment-grade debt securities with interest payments exempt from regular federal income tax, but not exempt from the federal alternative minimum tax.', 0.0062, 0.0095, 6020, 3220, 27.677, 27.092, NULL, NULL, 2.26, 13.05, 19.97, 1.93, 8.96, 6.81, '{"Cap_Size": "Large", "Quote_Mode": "ETF", "Currency_Base": "US_DOLLAR", "GeoZone_Class": "UNITED_STATES", "Strategy_Type": "Blend"}', '{"Net_Worth": 12191308, "Yield_Rate": 0.0191, "Expense_Net": 0.0062, "Benchmark_Exp": 0.0095, "Turnover_Ratio": null}', '{"volume_metrics": {"Vol_3M": 6020, "Vol_Recent": 3220}, "moving_averages": {"MA_50": 27.677, "MA_200": 27.092}}', '{"asset_allocation": {"Bond_Weight": null, "Equity_Weight": null}, "bond_characteristics": {"Avg_Maturity": 8.96, "Duration_Yrs": 6.81}}', '{"valuation_metrics": {"PB_Ratio": 2.26, "PE_Ratio": 19.97, "PS_Ratio": 1.93, "PCF_Ratio": 13.05}}');
INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (1485, 'QLTA', 'ETF', 'U.S.', 'Acclivity Mid Cap Multi-Style F', 'Acclivity Mid Cap Multi-Style Fund Class I', 'AmericanDollar', NULL, NULL, 'Innealta Capital', 'PCX', 'Corporate Bond', 1193336320, 0.0204, '2012-02-14', 0.16, 'The investment seeks long term capital appreciation. Under normal market conditions, the fund is expected to hold approximately 300 different stocks, where no individual issuer represents more than 5% of the portfolio total value. The Adviser defines a mid-capitalization company as any company that is neither in the highest 80% of U.S. aggregate market capitalization nor in the lowest 8% of U.S. aggregate market capitalization. As a non-fundamental policy, the fund will invest at least 80% of its total assets in equity securities of mid-cap companies. It may obtain exposure to equity securities through futures and options on futures contracts.', 0.0015, 0.0017, 113820, 97960, 56.333, 56.378, NULL, NULL, NULL, NULL, NULL, NULL, 11.56, 8.32, '{"Cap_Size": null, "Quote_Mode": "ETF", "Currency_Base": "AmericanDollar", "GeoZone_Class": "U.S.", "Strategy_Type": null}', '{"Net_Worth": 1193336320, "Yield_Rate": 0.0204, "Expense_Net": 0.0015, "Benchmark_Exp": 0.0017, "Turnover_Ratio": 0.16}', '{"volume_metrics": {"Vol_3M": 113820, "Vol_Recent": 97960}, "moving_averages": {"MA_50": 56.333, "MA_200": 56.378}}', '{"asset_allocation": {"Bond_Weight": null, "Equity_Weight": null}, "bond_characteristics": {"Avg_Maturity": 11.56, "Duration_Yrs": 8.32}}', '{"valuation_metrics": {"PB_Ratio": null, "PE_Ratio": null, "PS_Ratio": null, "PCF_Ratio": null}}');
