INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (1489, 'QMAR', 'ETF', 'America', 'AXS Sustainable Income Fund Cla', 'AXS Sustainable Income Fund Class I', 'DOLLAR', 'Growth', 'Large', 'AXS', 'BTS', NULL, 12618387, NULL, '2021-03-18', NULL, 'The investment seeks to generate current income. In seeking to achieve its investment objective, the fund primarily invests in a portfolio of U.S. dollar-denominated corporate debt securities. The advisor intends to invest in notes, bonds, debentures and commercial paper, which are the most common types of corporate debt securities. While the fund may invest in corporate debt securities of any credit quality, under normal market conditions, it will primarily invest in high yield securities. The fund may also invest in U.S. dollar-denominated securities of issuers domiciled outside of the United States.', 0.009, NULL, 5395, 4860, 22.282, 21.611, NULL, NULL, 8.09, 21.14, 33.46, 3.21, NULL, NULL, '{"Cap_Size": "Large", "Quote_Mode": "ETF", "Currency_Base": "DOLLAR", "GeoZone_Class": "America", "Strategy_Type": "Growth"}', '{"Net_Worth": 12618387, "Yield_Rate": null, "Expense_Net": 0.009, "Benchmark_Exp": null, "Turnover_Ratio": null}', '{"volume_metrics": {"Vol_3M": 5395, "Vol_Recent": 4860}, "moving_averages": {"MA_50": 22.282, "MA_200": 21.611}}', '{"asset_allocation": {"Bond_Weight": null, "Equity_Weight": null}, "bond_characteristics": {"Avg_Maturity": null, "Duration_Yrs": null}}', '{"valuation_metrics": {"PB_Ratio": 8.09, "PE_Ratio": 33.46, "PS_Ratio": 3.21, "PCF_Ratio": 21.14}}');
INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (1490, 'QMN', 'ETF', 'United States', 'Acclivity Small Cap Value Fund ', 'Acclivity Small Cap Value Fund Class I', 'DOLLAR', 'Blend', 'Large', 'Innealta Capital', 'PCX', NULL, 17793492, 0.0208, '2012-10-03', NULL, 'The investment seeks long-term capital appreciation. Under normal market conditions, the fund will invest at least 80% of its total assets in equity securities of small cap U.S. companies. The Adviser defines a small capitalization value company as any company that simultaneously meets the following two requirements: (i) be in the lowest 8% of U.S. aggregate market capitalization; and (ii) exhibit a low market value relative to its book value. The fund will also use futures and options on futures contracts for U.S. equity securities and indices, and exchange-traded-funds ("ETFs") to adjust market exposure or manage cash needs.', 0.0062, NULL, 1751, 870, 27.115, 27.267, NULL, NULL, 1.94, 10.33, 16.69, 1.34, 5.95, 2.52, '{"Cap_Size": "Large", "Quote_Mode": "ETF", "Currency_Base": "DOLLAR", "GeoZone_Class": "United States", "Strategy_Type": "Blend"}', '{"Net_Worth": 17793492, "Yield_Rate": 0.0208, "Expense_Net": 0.0062, "Benchmark_Exp": null, "Turnover_Ratio": null}', '{"volume_metrics": {"Vol_3M": 1751, "Vol_Recent": 870}, "moving_averages": {"MA_50": 27.115, "MA_200": 27.267}}', '{"asset_allocation": {"Bond_Weight": null, "Equity_Weight": null}, "bond_characteristics": {"Avg_Maturity": 5.95, "Duration_Yrs": 2.52}}', '{"valuation_metrics": {"PB_Ratio": 1.94, "PE_Ratio": 16.69, "PS_Ratio": 1.34, "PCF_Ratio": 10.33}}');
