INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (1519, 'RALS', 'ETF', 'us', 'Aquila Tax-Free Trust of Arizon', 'Aquila Tax-Free Trust of Arizona Class C', 'US_DOLLAR', 'Value', 'Large', 'Aquila', 'PCX', NULL, 5096239, 0.0125, '2010-12-02', NULL, 'The investment seeks to provide the investors as high a level of current income exempt from Arizona state and regular Federal income taxes as is consistent with preservation of capital. Under normal circumstances, at least 80% of the fund''s net assets will be invested in municipal obligations that pay interest exempt, in the opinion of bond counsel, from Arizona state and regular Federal income taxes, the income paid upon which will not be subject to the Federal alternative minimum tax on individuals. These obligations can be of any maturity, but the fund''s weighted average maturity has traditionally been between 5 and 15 years. The fund is non-diversified.', 0.0095, NULL, 749, 700, 31.105, 31.799, NULL, NULL, 2.48, 11.13, 19.36, 1.5, NULL, NULL, '{"Cap_Size": "Large", "Quote_Mode": "ETF", "Currency_Base": "US_DOLLAR", "GeoZone_Class": "us", "Strategy_Type": "Value"}', '{"Net_Worth": 5096239, "Yield_Rate": 0.0125, "Expense_Net": 0.0095, "Benchmark_Exp": null, "Turnover_Ratio": null}', '{"volume_metrics": {"Vol_3M": 749, "Vol_Recent": 700}, "moving_averages": {"MA_50": 31.105, "MA_200": 31.799}}', '{"asset_allocation": {"Bond_Weight": null, "Equity_Weight": null}, "bond_characteristics": {"Avg_Maturity": null, "Duration_Yrs": null}}', '{"valuation_metrics": {"PB_Ratio": 2.48, "PE_Ratio": 19.36, "PS_Ratio": 1.5, "PCF_Ratio": 11.13}}');
