INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (1534, 'REK', 'ETF', 'U.S.', 'Brown Advisory Equity Income Fd', 'Brown Advisory Equity Income Fund Advisor Shares', 'US$', NULL, NULL, 'Brown Advisory Funds', 'PCX', 'Trading--Inverse Equity', 7460586, NULL, '2010-03-16', NULL, 'The investment seeks to provide current dividend yield and dividend growth. The fund normally invests at least 80% of the value of its net assets (plus borrowings for investment purposes) in a diversified portfolio of dividend paying equity securities. Equity securities include domestic and foreign common and preferred stock, convertible debt securities, American Depositary Receipts ("ADRs"), Master Limited Partnerships ("MLPs"), real estate investment trusts ("REITs") and exchange traded funds ("ETFs"), and the Adviser may also invest in private placements in these types of securities.', 0.0095, 0.0092, 14604, 18590, 8.708, 9.355, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '{"Cap_Size": null, "Quote_Mode": "ETF", "Currency_Base": "US$", "GeoZone_Class": "U.S.", "Strategy_Type": null}', '{"Net_Worth": 7460586, "Yield_Rate": null, "Expense_Net": 0.0095, "Benchmark_Exp": 0.0092, "Turnover_Ratio": null}', '{"volume_metrics": {"Vol_3M": 14604, "Vol_Recent": 18590}, "moving_averages": {"MA_50": 8.708, "MA_200": 9.355}}', '{"asset_allocation": {"Bond_Weight": null, "Equity_Weight": null}, "bond_characteristics": {"Avg_Maturity": null, "Duration_Yrs": null}}', '{"valuation_metrics": {"PB_Ratio": null, "PE_Ratio": null, "PS_Ratio": null, "PCF_Ratio": null}}');
INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (1535, 'REMX', 'ETF', 'us', NULL, 'BlackRock Defensive Advantage Emerging Markets Fund Investor A', 'US Dollar', 'Growth', 'Medium', 'BlackRock', 'PCX', 'Equity Precious Metals', 758353856, 0.0063, '2010-10-27', 0.7, 'The investment seeks to provide long-term capital appreciation. Under normal circumstances, the fund seeks to invest at least 80% of its net assets, plus the amount of any borrowings for investment purposes, in equity securities issued by, or tied economically to, companies in emerging markets and derivatives that have similar economic characteristics to such securities. It primarily intends to invest in equity securities, which include common stock, preferred stock and convertible securities, or other financial instruments that are components of, or have characteristics similar to, the securities included in the MSCI EM Index.', 0.0059, 0.0057, 205306, 206300, 113.838, 96.382, NULL, NULL, 3.8, 22.4, 24.11, 2.33, NULL, NULL, '{"Cap_Size": "Medium", "Quote_Mode": "ETF", "Currency_Base": "US Dollar", "GeoZone_Class": "us", "Strategy_Type": "Growth"}', '{"Net_Worth": 758353856, "Yield_Rate": 0.0063, "Expense_Net": 0.0059, "Benchmark_Exp": 0.0057, "Turnover_Ratio": 0.7}', '{"volume_metrics": {"Vol_3M": 205306, "Vol_Recent": 206300}, "moving_averages": {"MA_50": 113.838, "MA_200": 96.382}}', '{"asset_allocation": {"Bond_Weight": null, "Equity_Weight": null}, "bond_characteristics": {"Avg_Maturity": null, "Duration_Yrs": null}}', '{"valuation_metrics": {"PB_Ratio": 3.8, "PE_Ratio": 24.11, "PS_Ratio": 2.33, "PCF_Ratio": 22.4}}');
