INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (1545, 'RFEM', 'ETF', 'UNITED_STATES', 'Brown Advisory Flexible Equity ', 'Brown Advisory Flexible Equity Fund Institutional Shares', 'US_DOLLAR', 'Blend', 'Large', 'Brown Advisory Funds', 'NGM', 'Diversified Emerging Mkts', 56266224, 0.0179, '2016-06-14', 0.89, 'The investment seeks to achieve long-term growth of capital. The fund normally invests at least 80% of the value of its net assets (plus any borrowings for investment purposes) in a diversified portfolio of equity securities. It invests primarily in securities of medium and large market capitalization companies that the Adviser believes have strong, or improving, long-term business characteristics and share prices that do not reflect these favorable fundamental attributes. The fund may invest up to 15% of its net assets in foreign securities, including emerging markets.', 0.0095, 0.0056, 3535, 3260, 67.906, 71.801, 0.9927, 0.0001, 2.35, 9.4, 12.96, 1.56, NULL, NULL, '{"Cap_Size": "Large", "Quote_Mode": "ETF", "Currency_Base": "US_DOLLAR", "GeoZone_Class": "UNITED_STATES", "Strategy_Type": "Blend"}', '{"Net_Worth": 56266224, "Yield_Rate": 0.0179, "Expense_Net": 0.0095, "Benchmark_Exp": 0.0056, "Turnover_Ratio": 0.89}', '{"volume_metrics": {"Vol_3M": 3535, "Vol_Recent": 3260}, "moving_averages": {"MA_50": 67.906, "MA_200": 71.801}}', '{"asset_allocation": {"Bond_Weight": 0.0001, "Equity_Weight": 0.9927}, "bond_characteristics": {"Avg_Maturity": null, "Duration_Yrs": null}}', '{"valuation_metrics": {"PB_Ratio": 2.35, "PE_Ratio": 12.96, "PS_Ratio": 1.56, "PCF