INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (1546, 'RFEU', 'ETF', 'America', 'Brown Advisory Growth Equity Fd', 'Brown Advisory Growth Equity Fund Institutional Shares', 'US_DOLLAR', 'Growth', 'Large', 'Brown Advisory Funds', 'NGM', 'Europe Stock', 18660816, 0.0218, '2016-04-14', 0.87, 'The investment seeks to achieve capital appreciation by primarily investing in equity securities. The fund normally invests at least 80% of the value of its net assets (plus any borrowings for investment purposes) in equity securities of domestic companies. It invests primarily in securities of medium and large market capitalization companies that the Adviser believes have exhibited an above average rate of earnings growth and that have prospects for above average, sustainable growth in the future. Medium and large market capitalization companies are those companies with market capitalizations generally greater than $2 billion at the time of purchase.', 0.0083, 0.0044, 1235, 940, 76.055, 74.542, 0.9945, 0, 3.18, 15.18, 18.22, 1.65, NULL, NULL, '{"Cap_Size": "Large", "Quote_Mode": "ETF", "Currency_Base": "US_DOLLAR", "GeoZone_Class": "America", "Strategy_Type": "Growth"}', '{"Net_Worth": 18660816, "Yield_Rate": 0.0218, "Expense_Net": 0.0083, "Benchmark_Exp": 0.0044, "Turnover_Ratio": 0.87}', '{"volume_metrics": {"Vol_3M": 1235, "Vol_Recent": 940}, "moving_averages": {"MA_50": 76.055, "MA_200": 74.542}}', '{"asset_allocation": {"Bond_Weight": 0, "Equity_Weight": 0.9945}, "bond_characteristics": {"Avg_Maturity": null, "Duration_Yrs": null}}', '{"valuation_metrics": {"PB_Ratio":