INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (1557, 'RJN', 'ETF', 'usa', 'BlackRock 60/40 Target Allocati', 'BlackRock 60/40 Target Allocation Fund Investor A Shares', 'Dollar', NULL, NULL, 'BlackRock', 'PCX', NULL, 3892150, NULL, '2007-10-17', NULL, 'The investment seeks long term capital appreciation, and current income is also a consideration. The fund, which is a fund of funds, normally obtains exposure to equity securities in an amount equal to 60% of its assets and exposure to fixed-income securities in an amount equal to 40% of its assets. Normally, the advisor intends to invest primarily in affiliated open-end funds and affiliated ETFs. The fund may, when consistent with its investment objective, buy or sell options or futures, or enter into total return swaps and foreign currency transactions (collectively, commonly known as derivatives).', 0.0075, NULL, 14292, 11970, 2.811, 2.385, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '{"Cap_Size": null, "Quote_Mode": "ETF", "Currency_Base": "Dollar", "GeoZone_Class": "usa", "Strategy_Type": null}', '{"Net_Worth": 3892150, "Yield_Rate": null, "Expense_Net": 0.0075, "Benchmark_Exp": null, "Turnover_Ratio": null}', '{"volume_metrics": {"Vol_3M": 14292, "Vol_Recent": 11970}, "moving_averages": {"MA_50": 2.811, "MA_200": 2.385}}', '{"asset_allocation": {"Bond_Weight": null, "Equity_Weight": null}, "bond_characteristics": {"Avg_Maturity": null, "Duration_Yrs": null}}', '{"valuation_metrics": {"PB_Ratio": null, "PE_Ratio": null, "PS_Ratio": null, "PCF_Ratio": null}}');
INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (1558, 'RJZ', 'ETF', 'USA', 'Baird Aggregate Bond Fd Investo', 'Baird Aggregate Bond Fund Class Investor', 'AmericanDollar', NULL, NULL, 'Baird', 'PCX', NULL, 5610550, NULL, '2007-10-17', NULL, 'The investment seeks an annual rate of total return, before fund expenses, greater than the annual rate of total return of the Bloomberg Barclays U.S.A.gregate Bond Index. The fund normally invests at least 80% of its net assets in the following types of U.S. dollar-denominated debt obligations: U.S. government and other public-sector entities; asset-backed and mortgage-backed obligations of U.S. and foreign issuers; corporate debt of U.S. and foreign issuers.', 0.0075, NULL, 880, 1020, 11.307, 11.096, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '{"Cap_Size": null, "Quote_Mode": "ETF", "Currency_Base": "AmericanDollar", "GeoZone_Class": "USA", "Strategy_Type": null}', '{"Net_Worth": 5610550, "Yield_Rate": null, "Expense_Net": 0.0075, "Benchmark_Exp": null, "Turnover_Ratio": null}', '{"volume_metrics": {"Vol_3M": 880, "Vol_Recent": 1020}, "moving_averages": {"MA_50": 11.307, "MA_200": 11.096}}', '{"asset_allocation": {"Bond_Weight": null, "Equity_Weight": null}, "bond_characteristics": {"Avg_Maturity": null, "Duration_Yrs": null}}', '{"valuation_metrics": {"PB_Ratio": null, "PE_Ratio": null, "PS_Ratio": null, "PCF_Ratio": null}}');
INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (1559, 'RLY', 'ETF', 'UNITED_STATES', 'Brown Advisory- WMC Strategic E', 'Brown Advisory WMC Strategic European Equity Fund Advisor Shares', 'DOLLAR', 'Value', 'Large', 'Brown Advisory Funds', 'PCX', 'World Allocation', 130358616, 0.0193, '2012-04-25', NULL, 'The investment seeks to achieve total return by investing principally in equity securities issued by companies established or operating in Europe. Under normal conditions, the fund seeks to achieve its investment objective by investing at least 80% of the value of its net assets (plus any borrowings for investment purposes) in equity securities of companies which are domiciled in or exercise the predominant part of their economic activity in Europe - defined as countries included in the MSCI Europe Index.', 0.005, 0.0058, 33562, 62290, 29.651, 28.509, NULL, NULL, 1.91, 10.65, 21.72, 1.84, 7.48, 7.07, '{"Cap_Size": "Large", "Quote_Mode": "ETF", "Currency_Base": "DOLLAR", "GeoZone_Class": "UNITED_STATES", "Strategy_Type": "Value"}', '{"Net_Worth": 130358616, "Yield_Rate": 0.0193, "Expense_Net": 0.005, "Benchmark_Exp": 0.0058, "Turnover_Ratio": null}', '{"volume_metrics": {"Vol_3M": 33562, "Vol_Recent": 62290}, "moving_averages": {"MA_50": 29.651, "MA_200": 28.509}}', '{"asset_allocation": {"Bond_Weight": null, "Equity_Weight": null}, "bond_characteristics": {"Avg_Maturity": 7.48, "Duration_Yrs": 7.07}}', '{"valuation_metrics": {"PB_Ratio": 1.91, "PE_Ratio": 21.72, "PS_Ratio": 1.84, "PCF_Ratio": 10.65}}');
INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (1570, 'RODE', 'ETF', 'America', 'BlackRock Systematic Multi-Stra', 'BlackRock Systematic Multi-Strategy Fund Investor A Shares', 'US Dollar', 'Value', 'Large', 'BlackRock', 'BTS', 'Foreign Large Value', 5801187, 0.0343, '2017-05-10', 1.56, 'The investment seeks total return comprised of current income and capital appreciation. The fund seeks to achieve its investment objective by investing in a range of global asset classes, with a focus on fixed and floating rate debt securities and equity securities. It will normally invest in both U.S. and non-U.S. securities, including securities of companies located in emerging markets.', 0.0029, 0.0046, 267, 110, 28.795, 28.833, 0.9959, 0, 1.4, 6.38, 12.12, 0.73, NULL, NULL, '{"Cap_Size": "Large", "Quote_Mode": "ETF", "Currency_Base": "US Dollar", "GeoZone_Class": "America", "Strategy_Type": "Value"}', '{"Net_Worth": 5801187, "Yield_Rate": 0.0343, "Expense_Net": 0.0029, "Benchmark_Exp": 0.0046, "Turnover_Ratio": 1.56}', '{"volume_metrics": {"Vol_3M": 267, "Vol_Recent": 110}, "moving_averages": {"MA_50": 28.795, "MA_200": 28.833}}', '{"asset_allocation": {"Bond_Weight": 0, "Equity_Weight": 0.9959}, "bond_characteristics": {"Avg_Maturity": null, "Duration_Yrs": null}}', '{"valuation_metrics": {"PB_Ratio": 1.4, "PE_Ratio": 12.12, "PS_Ratio": 0.73, "PCF_Ratio": 6.38}}');
INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (1565, 'RNRG', 'ETF', 'U.S.', 'American Funds American Balance', 'American Funds American Balanced Fund Class F-1', 'USD', 'Blend', 'Medium', 'American Funds', 'NGM', 'Utilities', 131166288, 0.026, '2015-05-27', 0.2927, 'The investment seeks conservation of capital, current income and long-term growth of capital and income. The fund uses a balanced approach to invest in a broad range of securities, including common stocks and investment-grade bonds. It also invests in securities issued and guaranteed by the U.S. government and by federal agencies and instrumentalities. In addition, the fund may invest a portion of its assets in common stocks, most of which have a history of paying dividends, bonds and other securities of issuers domiciled outside the United States.', 0.0065, 0.0042, 46969, 83370, 16.178, 16.059, 0.999, 0, 2.3, 11.8, 24.81, 3.85, NULL, NULL, '{"Cap_Size": "Medium", "Quote_Mode": "ETF", "Currency_Base": "USD", "GeoZone_Class": "U.S.", "Strategy_Type": "Blend"}', '{"Net_Worth": 131166288, "Yield_Rate": 0.026, "Expense_Net": 0.0065, "Benchmark_Exp": 0.0042, "Turnover_Ratio": 0.2927}', '{"volume_metrics": {"Vol_3M": 46969, "Vol_Recent": 83370}, "moving_averages": {"MA_50": 16.178, "MA_200": 16.059}}', '{"asset_allocation": {"Bond_Weight": 0, "Equity_Weight": 0.999}, "bond_characteristics": {"Avg_Maturity": null, "Duration_Yrs": null}}', '{"valuation_metrics": {"PB_Ratio": 2.3, "PE_Ratio": 24.81, "PS_Ratio": 3.85, "PCF_Ratio": 11.8}}');
INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (1560, 'RNDM', 'ETF', 'USA', 'Brown Advisory Intermediate Inc', 'Brown Advisory Intermediate Income Advisor Shares', 'US_DOLLAR', 'Blend', 'Large', 'Brown Advisory Funds', 'NGM', 'Foreign Large Blend', 24950948, 0.025, '2017-06-20', 0.89, 'The investment seeks to provide a high level of current income consistent with preservation of principal within an intermediate-term maturity structure. The fund normally invests at least 80% of the value of its net assets (plus any borrowings for investment purposes) in fixed income securities such as U.S. government securities, corporate fixed income securities, mortgage-backed and asset-backed securities. It may also invest in other investment companies that invest in similar fixed income securities and the fund may count such holdings towards the fund''s 80% investment policy. It may invest in derivatives instruments.', 0.0065, 0.0037, 1666, 720, 55.514, 55.645, NULL, NULL, 2.14, 11.52, 21.24, 1.52, NULL, NULL, '{"Cap_Size": "Large", "Quote_Mode": "ETF", "Currency_Base": "US_DOLLAR", "GeoZone_Class": "USA", "Strategy_Type": "Blend"}', '{"Net_Worth": 24950948, "Yield_Rate": 0.025, "Expense_Net": 0.0065, "Benchmark_Exp": 0.0037, "Turnover_Ratio": 0.89}', '{"volume_metrics": {"Vol_3M": 1666, "Vol_Recent": 720}, "moving_averages": {"MA_50": 55.514, "MA_200": 55.645}}', '{"asset_allocation": {"Bond_Weight": null, "Equity_Weight": null}, "bond_characteristics": {"Avg_Maturity": null, "Duration_Yrs": null}}', '{"valuation_metrics": {"PB_Ratio": 2.14, "PE_Ratio": 21.24, "PS_Ratio": 1.52, "PCF_Ratio": 11.52}}');
INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (1561, 'RNDV', 'ETF', 'America', 'BlackRock Funds II, BlackRock M', 'BlackRock Multi-Asset Income Portfolio Investor A Shares', 'DOLLAR', 'Value', 'Large', 'BlackRock', 'NGM', 'Large Value', 13251442, 0.0194, '2017-06-20', 0.89, 'The investment seeks to maximize current income with consideration for capital appreciation. The fund may invest up to 60% of its assets in equity securities and up to 100% of its assets in fixed income securities. In addition, it may invest in structured notes that provide exposure to covered call options or other types of financial instruments. The fund may also invest up to 15% of its assets in collateralized debt obligations ("CDOs"), including collateralized loan obligations ("CLOs").', 0.005, 0.0034, 5838, 2680, 29.735, 29.318, 0.9953, 0, 3.29, 11.29, 22.14, 1.61, NULL, NULL, '{"Cap_Size": "Large", "Quote_Mode": "ETF", "Currency_Base": "DOLLAR", "GeoZone_Class": "America", "Strategy_Type": "Value"}', '{"Net_Worth": 13251442, "Yield_Rate": 0.0194, "Expense_Net": 0.005, "Benchmark_Exp": 0.0034, "Turnover_Ratio": 0.89}', '{"volume_metrics": {"Vol_3M": 5838, "Vol_Recent": 2680}, "moving_averages": {"MA_50": 29.735, "MA_200": 29.318}}', '{"asset_allocation": {"Bond_Weight": 0, "Equity_Weight": 0.9953}, "bond_characteristics": {"Avg_Maturity": null, "Duration_Yrs": null}}', '{"valuation_metrics": {"PB_Ratio": 3.29, "PE_Ratio": 22.14, "PS_Ratio": 1.61, "PCF_Ratio": 11.29}}');
INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (1562, 'RNEM', 'ETF', 'U.S.A.', 'iShares Short-Term TIPS Bond In', 'iShares Short-Term TIPS Bond Index Fund Investor A Shares', 'Dollar', 'Value', 'Large', 'BlackRock', 'NGM', 'Diversified Emerging Mkts', 7499187, 0.0359, '2017-06-20', 0.75, 'The investment seeks to track the investment results of an index composed of U.S. 0-5 Year Treasury Inflation-Protected Securities ("TIPS"). The fund seeks to track the investment results of the Bloomberg Barclays U.S. Treasury Inflation-Protected Securities 0-5 Years Index (Series-L) (the "underlying index"), which measures the performance of inflation-protected public obligations of the U.S. Treasury that have a remaining maturity of less than five years. It generally invests at least 90% of its assets, plus the amount of any borrowing for investment purposes, in securities of the underlying index.', 0.0075, 0.0056, 314, 310, 48.314, 49.405, NULL, NULL, 1.29, 9.3, 11.44, 0.75, NULL, NULL, '{"Cap_Size": "Large", "Quote_Mode": "ETF", "Currency_Base": "Dollar", "GeoZone_Class": "U.S.A.", "Strategy_Type": "Value"}', '{"Net_Worth": 7499187, "Yield_Rate": 0.0359, "Expense_Net": 0.0075, "Benchmark_Exp": 0.0056, "Turnover_Ratio": 0.75}', '{"volume_metrics": {"Vol_3M": 314, "Vol_Recent": 310}, "moving_averages": {"MA_50": 48.314, "MA_200": 49.405}}', '{"asset_allocation": {"Bond_Weight": null, "Equity_Weight": null}, "bond_characteristics": {"Avg_Maturity": null, "Duration_Yrs": null}}', '{"valuation_metrics": {"PB_Ratio": 1.29, "PE_Ratio": 11.44, "PS_Ratio": 0.75, "PCF_Ratio": 9.3}}');
INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (1563, 'RNLC', 'ETF', 'U.S.', 'Brown Advisory Sustainable Bond', 'Brown Advisory Sustainable Bond Fund Institutional Shares', 'Dollar', 'Blend', 'Large', 'Brown Advisory Funds', 'NGM', 'Large Blend', 28950998, 0.0107, '2017-06-20', 0.34, 'The investment seeks to provide a competitive total return consistent with preservation of principal while giving special consideration to certain environmental, social and governance ("ESG") criteria. The fund''s investment objective by investing at least 80% of the value of its net assets (plus any borrowings for investment purposes) in either fixed income securities of issuers that satisfy the fund''s ESG criteria or in securities where the use of the proceeds satisfy the fund''s ESG criteria. The fund may invest up to 20% of its assets in high-yield securities ("junk bonds" ).', 0.006, 0.0036, 2308, 1250, 33.444, 32.109, 0.9976, 0, 3.85, 15.19, 24.7, 2.09, NULL, NULL, '{"Cap_Size": "Large", "Quote_Mode": "ETF", "Currency_Base": "Dollar", "GeoZone_Class": "U.S.", "Strategy_Type": "Blend"}', '{"Net_Worth": 28950998, "Yield_Rate": 0.0107, "Expense_Net": 0.006, "Benchmark_Exp": 0.0036, "Turnover_Ratio": 0.34}', '{"volume_metrics": {"Vol_3M": 2308, "Vol_Recent": 1250}, "moving_averages": {"MA_50": 33.444, "MA_200": 32.109}}', '{"asset_allocation": {"Bond_Weight": 0, "Equity_Weight": 0.9976}, "bond_characteristics": {"Avg_Maturity": null, "Duration_Yrs": null}}', '{"valuation_metrics": {"PB_Ratio": 3.85, "PE_Ratio": 24.7, "PS_Ratio": 2.09, "PCF_Ratio": 15.19}}');
INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (1564, 'RNMC', 'ETF', 'usa', 'American Balanced Fund, Class C', 'American Funds American Balanced Fund Class C', 'Usd', 'Value', 'Medium', 'American Funds', 'NGM', 'Mid-Cap Blend', 18806884, 0.0119, '2017-06-20', 0.6, 'The investment seeks conservation of capital, current income and long-term growth of capital and income. The fund uses a balanced approach to invest in a broad range of securities, including common stocks and investment-grade bonds. It also invests in securities issued and guaranteed by the U.S. government and by federal agencies and instrumentalities. In addition, the fund may invest a portion of its assets in common stocks, most of which have a history of paying dividends, bonds and other securities of issuers domiciled outside the United States.', 0.006, 0.0047, 2672, 780, 29.734, 28.956, 0.9969, 0, 2.69, 11.58, 20.13, 1.55, NULL, NULL, '{"Cap_Size": "Medium", "Quote_Mode": "ETF", "Currency_Base": "Usd", "GeoZone_Class": "usa", "Strategy_Type": "Value"}', '{"Net_Worth": 18806884, "Yield_Rate": 0.0119, "Expense_Net": 0.006, "Benchmark_Exp": 0.0047, "Turnover_Ratio": 0.6}', '{"volume_metrics": {"Vol_3M": 2672, "Vol_Recent": 780}, "moving_averages": {"MA_50": 29.734, "MA_200": 28.956}}', '{"asset_allocation": {"Bond_Weight": 0, "Equity_Weight": 0.9969}, "bond_characteristics": {"Avg_Maturity": null, "Duration_Yrs": null}}', '{"valuation_metrics": {"PB_Ratio": 2.69, "PE_Ratio": 20.13, "PS_Ratio": 1.55, "PCF_Ratio": 11.58}}');
INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (1566, 'RNSC', 'ETF', 'U.S.', 'BMO Large Cap Growth Fund Class', 'BMO Large-Cap Growth Fund Class A', 'Usd', 'Value', 'Small', 'BMO Funds', 'NGM', 'Small Blend', 10222069, 0.0111, '2017-06-20', 0.71, 'The investment seeks to provide capital appreciation. The fund invests at least 80% of its assets in common stocks of large-sized U.S. companies similar in size, at the time of purchase, to those within the Russell 1000© Growth Index. The Adviser selects stocks using a unique, growth-oriented approach, focusing on high quality companies with sustainable earnings growth that are available at reasonable prices, which combines the use of proprietary analytical tools and the qualitative judgments of the investment team.', 0.006, 0.004, 4451, 2150, 29.388, 28.981, 0.9947, 0, 2.12, 9.45, 17.27, 1.18, NULL, NULL, '{"Cap_Size": "Small", "Quote_Mode": "ETF", "Currency_Base": "Usd", "GeoZone_Class": "U.S.", "Strategy_Type": "Value"}', '{"Net_Worth": 10222069, "Yield_Rate": 0.0111, "Expense_Net": 0.006, "Benchmark_Exp": 0.004, "Turnover_Ratio": 0.71}', '{"volume_metrics": {"Vol_3M": 4451, "Vol_Recent": 2150}, "moving_averages": {"MA_50": 29.388, "MA_200": 28.981}}', '{"asset_allocation": {"Bond_Weight": 0, "Equity_Weight": 0.9947}, "bond_characteristics": {"Avg_Maturity": null, "Duration_Yrs": null}}', '{"valuation_metrics": {"PB_Ratio": 2.12, "PE_Ratio": 17.27, "PS_Ratio": 1.18, "PCF_Ratio": 9.45}}');
INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (1567, 'ROAM', 'ETF', 'United States', 'BlackRock Large Cap Srs Fds, Bl', 'BlackRock Event Driven Equity Fund Investor A Shares', 'Dollar', 'Value', 'Large', 'BlackRock', 'PCX', 'Diversified Emerging Mkts', 43490088, 0.0285, '2015-02-25', 0.77, 'The investment seeks long-term capital growth. Normally, the fund invests at least 80% of its net assets in equity securities and related derivative instruments with similar economic characteristics. It seeks to achieve its investment objective by employing an event driven strategy, primarily investing in companies that have announced a material change or in companies that the advisor expects to undergo a material change. The fund''s investment in equity securities may include common stock, preferred stock, securities convertible into common stock, non-convertible preferred stock, and depositary receipts.', 0.0044, 0.0056, 2175, 1880, 24.665, 24.775, NULL, NULL, 1.41, 7.01, 11.81, 0.79, NULL, NULL, '{"Cap_Size": "Large", "Quote_Mode": "ETF", "Currency_Base": "Dollar", "GeoZone_Class": "United States", "Strategy_Type": "Value"}', '{"Net_Worth": 43490088, "Yield_Rate": 0.0285, "Expense_Net": 0.0044, "Benchmark_Exp": 0.0056, "Turnover_Ratio": 0.77}', '{"volume_metrics": {"Vol_3M": 2175, "Vol_Recent": 1880}, "moving_averages": {"MA_50": 24.665, "MA_200": 24.775}}', '{"asset_allocation": {"Bond_Weight": null, "Equity_Weight": null}, "bond_characteristics": {"Avg_Maturity": null, "Duration_Yrs": null}}', '{"valuation_metrics": {"PB_Ratio": 1.41, "PE_Ratio": 11.81, "PS_Ratio": 0.79, "PCF_Ratio": 7.01}}');
INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (1568, 'ROBO', 'ETF', 'UNITED_STATES', 'Pioneer Solutions - Balanced Fu', 'Pioneer Solutions - Balanced Fund Class R', 'US_DOLLAR', 'Growth', 'Medium', 'Amundi US', 'PCX', NULL, 1835083264, 0.0018, '2013-10-22', NULL, 'The investment seeks long-term capital growth and current income. The fund is a "fund of funds." It seeks to achieve its investment objectives by primarily investing in other funds. It invests mainly in funds managed by Amundi Pioneer or one of its affiliates. The fund may also invest in securities of unaffiliated mutual funds or exchange-traded funds (ETFs) when the desired economic exposure to a particular asset category or investment strategy is not available through a Pioneer fund. The fund may also invest directly in securities.', 0.0095, NULL, 90293, 74960, 67.732, 65.703, 0.9989, 0, 4.08, 21.09, 36.43, 3.34, NULL, NULL, '{"Cap_Size": "Medium", "Quote_Mode": "ETF", "Currency_Base": "US_DOLLAR", "GeoZone_Class": "UNITED_STATES", "Strategy_Type": "Growth"}', '{"Net_Worth": 1835083264, "Yield_Rate": 0.0018, "Expense_Net": 0.0095, "Benchmark_Exp": null, "Turnover_Ratio": null}', '{"volume_metrics": {"Vol_3M": 90293, "Vol_Recent": 74960}, "moving_averages": {"MA_50": 67.732, "MA_200": 65.703}}', '{"asset_allocation": {"Bond_Weight": 0, "Equity_Weight": 0.9989}, "bond_characteristics": {"Avg_Maturity": null, "Duration_Yrs": null}}', '{"valuation_metrics": {"PB_Ratio": 4.08, "PE_Ratio": 36.43, "PS_Ratio": 3.34, "PCF_Ratio": 21.09}}');
INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (1571, 'RODM', 'ETF', 'US', 'BMO Mid Cap Value Fund Class A', 'BMO Mid-Cap Value Fund Class A', 'US$', 'Value', 'Large', 'BMO Funds', 'PCX', 'Foreign Large Blend', 1957379968, 0.0323, '2015-02-25', 0.57, 'The investment seeks to provide capital appreciation. The fund invests at least 80% of its assets in value-oriented common stocks of medium-sized U.S. companies similar in size, at the time of purchase, to those within the Russell Midcap© Value Index. The Adviser selects stocks using a unique, value-oriented approach focusing on high quality companies with long-term capital appreciation potential that are available at reasonable prices, which combines the use of proprietary analytical tools and the qualitative judgments of the investment team.', 0.0029, 0.0037, 230816, 172200, 30.507, 30.693, NULL, NULL, 1.57, 7.65, 15.56, 0.91, NULL, NULL, '{"Cap_Size": "Large", "Quote_Mode": "ETF", "Currency_Base": "US$", "GeoZone_Class": "US", "Strategy_Type": "Value"}', '{"Net_Worth": 1957379968, "Yield_Rate": 0.0323, "Expense_Net": 0.0029, "Benchmark_Exp": 0.0037, "Turnover_Ratio": 0.57}', '{"volume_metrics": {"Vol_3M": 230816, "Vol_Recent": 172200}, "moving_averages": {"MA_50": 30.507, "MA_200": 30.693}}', '{"asset_allocation": {"Bond_Weight": null, "Equity_Weight": null}, "bond_characteristics": {"Avg_Maturity": null, "Duration_Yrs": null}}', '{"valuation_metrics": {"PB_Ratio": 1.57, "PE_Ratio": 15.56, "PS_Ratio": 0.91, "PCF_Ratio": 7.65}}');
INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (1598, 'RYH', 'ETF', 'us', 'BBH Limited Duration Fund Class', 'BBH Limited Duration Fund Class Institutional', 'USD', 'Blend', 'Large', 'BBH', 'PCX', 'Health', 860428416, 0.0043, '2006-11-01', NULL, 'The investment seeks maximum total return, consistent with preservation of capital and prudent investment management. The fund seeks to achieve its investment objective by investing in a well-diversified portfolio of durable, performing fixed income instruments. These investments will be primarily focused in asset-backed securities, notes and bonds issued by domestic and foreign corporations and financial institutions and U.S. government, government agencies and government guaranteed issuers.', 0.004, 0.0049, 12241, 5960, 301.902, 292.319, 0.9998, 0, 4.13, 14.44, 22, 1.18, NULL, NULL, '{"Cap_Size": "Large", "Quote_Mode": "ETF", "Currency_Base": "USD", "GeoZone_Class": "us", "Strategy_Type": "Blend"}', '{"Net_Worth": 860428416, "Yield_Rate": 0.0043, "Expense_Net": 0.004, "Benchmark_Exp": 0.0049, "Turnover_Ratio": null}', '{"volume_metrics": {"Vol_3M": 12241, "Vol_Recent": 5960}, "moving_averages": {"MA_50": 301.902, "MA_200": 292.319}}', '{"asset_allocation": {"Bond_Weight": 0, "Equity_Weight": 0.9998}, "bond_characteristics": {"Avg_Maturity": null, "Duration_Yrs": null}}', '{"valuation_metrics": {"PB_Ratio": 4.13, "PE_Ratio": 22, "PS_Ratio": 1.18, "PCF_Ratio": 14.44}}');
INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (1572, 'ROKT', 'ETF', 'USA', 'BlackRock 40/60 Target Allocati', 'BlackRock 40/60 Target Allocation Fund Investor A Shares', 'AmericanDollar', 'Blend', 'Medium', 'BlackRock', 'PCX', 'Industrials', 22509124, 0.0172, '2018-10-19', 0.39, 'The investment seeks a balance between long term capital appreciation and high current income, with an emphasis on income. The fund, which is a fund of funds, normally obtains exposure to equity securities in an amount equal to 40% of its assets and exposure to fixed-income securities in an amount equal to 60% of its assets. Normally, the advisor intends to invest primarily in affiliated open-end funds and affiliated ETFs. The fund may, when consistent with its investment objective, buy or sell options or futures, or enter into total return swaps and foreign currency transactions (collectively, commonly known as derivatives).', 0.0045, 0.0046, 2893, 3970, 40.583, 40.853, 0.9985, 0, 3.42, 14, 27.26, 1.88, NULL, NULL, '{"Cap_Size": "Medium", "Quote_Mode": "ETF", "Currency_Base": "AmericanDollar", "GeoZone_Class": "USA", "Strategy_Type": "Blend"}', '{"Net_Worth": 22509124, "Yield_Rate": 0.0172, "Expense_Net": 0.0045, "Benchmark_Exp": 0.0046, "Turnover_Ratio": 0.39}', '{"volume_metrics": {"Vol_3M": 2893, "Vol_Recent": 3970}, "moving_averages": {"MA_50": 40.583, "MA_200": 40.853}}', '{"asset_allocation": {"Bond_Weight": 0, "Equity_Weight": 0.9985}, "bond_characteristics": {"Avg_Maturity": null, "Duration_Yrs": null}}', '{"valuation_metrics": {"PB_Ratio": 3.42, "PE_Ratio": 27.26, "PS_Ratio": 1.88, "PCF_Ratio": 14}}');
INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (1573, 'ROM', 'ETF', 'U.S.', 'Brown Advisory Emerging Markets', 'Brown Advisory Emerging Markets Select Fund Advisor Shares', 'usd', 'Growth', 'Large', 'Brown Advisory Funds', 'PCX', 'Trading--Leveraged Equity', 899778048, NULL, '2007-01-30', 0.31, 'The investment seeks total return by investing principally in equity securities issued by companies established or operating in emerging markets. The fund invests at least 80% of the value of its net assets (plus any borrowings for investment purposes) in equity securities issued by companies that are established or operating in emerging market countries. These will consist of companies in emerging market countries in Latin America, Asia, Eastern Europe, Africa, and the Middle East. It may invest up to 20% of its net assets in securities of companies that are established or operating in countries that are considered to be outside of emerging markets.', 0.0095, 0.009, 75090, 85970, 115.211, 97.245, NULL, NULL, NULL, NULL, NULL, 6.53, NULL, NULL, '{"Cap_Size": "Large", "Quote_Mode": "ETF", "Currency_Base": "usd", "GeoZone_Class": "U.S.", "Strategy_Type": "Growth"}', '{"Net_Worth": 899778048, "Yield_Rate": null, "Expense_Net": 0.0095, "Benchmark_Exp": 0.009, "Turnover_Ratio": 0.31}', '{"volume_metrics": {"Vol_3M": 75090, "Vol_Recent": 85970}, "moving_averages": {"MA_50": 115.211, "MA_200": 97.245}}', '{"asset_allocation": {"Bond_Weight": null, "Equity_Weight": null}, "bond_characteristics": {"Avg_Maturity": null, "Duration_Yrs": null}}', '{"valuation_metrics": {"PB_Ratio": null, "PE_Ratio": null, "PS_Ratio": 6.53, "PCF_Ratio": null}}');
INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (1574, 'ROMO', 'ETF', 'UNITED_STATES', 'Baron Asset Fund', 'Baron Asset Fund Retail Class', 'USD', 'Blend', 'Large', 'Baron Capital Group, Inc.', 'BTS', 'Allocation--70% to 85% Equity', 44372292, 0.0087, '2019-11-01', NULL, 'The investment seeks capital appreciation through long-term investments primarily in securities of mid-sized companies with undervalued assets or favorable growth prospects. The fund invests for the long term primarily in equity securities in the form of common stock of U.S. mid-sized growth companies. BAMCO, Inc. ("BAMCO" or the "Adviser") defines mid-sized companies as those, at the time of purchase, with market capitalizations above $2.5 billion or the smallest market cap stock in the Russell Midcap Growth Index at reconstitution, whichever is larger, and below the largest market cap stock in the Russell Midcap Growth Index at reconstitution.', 0.0085, 0.0052, 3146, 3230, 29.054, 27.896, 0.995, 0.0012, 3.07, 14.78, 24.31, 2.28, 3.74, 3.55, '{"Cap_Size": "Large", "Quote_Mode": "ETF", "Currency_Base": "USD", "GeoZone_Class": "UNITED_STATES", "Strategy_Type": "Blend"}', '{"Net_Worth": 44372292, "Yield_Rate": 0.0087, "Expense_Net": 0.0085, "Benchmark_Exp": 0.0052, "Turnover_Ratio": null}', '{"volume_metrics": {"Vol_3M": 3146, "Vol_Recent": 3230}, "moving_averages": {"MA_50": 29.054, "MA_200": 27.896}}', '{"asset_allocation": {"Bond_Weight": 0.0012, "Equity_Weight": 0.995}, "bond_characteristics": {"Avg_Maturity": 3.74, "Duration_Yrs": 3.55}}', '{"valuation_metrics": {"PB_Ratio": 3.07, "PE_Ratio": 24.31, "PS_Ratio": 2.28, "PCF_Ratio": 14.78}}');
INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (1575, 'ROOF', 'ETF', 'U.S.', 'iShares Developed Real Estate I', 'iShares Developed Real Estate Index Fund Investor A Shares', 'US_DOLLAR', 'Value', 'Small', 'BlackRock', 'PCX', 'Real Estate', 55924336, 0.0311, '2011-06-14', NULL, 'The investment seeks to track the investment results of an index composed of real estate equities in developed markets. The fund seeks to track the investment results of the FTSE EPRA/NAREIT Developed Index, which measures the stock performance of companies engaged in the ownership, disposal and development of income-producing real estate in developed countries as defined by FTSE EPRA/NAREIT. It generally invests at least 90% of its assets, plus the amount of any borrowing for investment purposes, in securities of the underlying index and in depositary receipts representing securities of the underlying index.', 0.007, 0.0037, 8090, 8490, 26.67, 25.767, 1, 0, 1.38, 11.81, 12.39, 2.76, NULL, NULL, '{"Cap_Size": "Small", "Quote_Mode": "ETF", "Currency_Base": "US_DOLLAR", "GeoZone_Class": "U.S.", "Strategy_Type": "Value"}', '{"Net_Worth": 55924336, "Yield_Rate": 0.0311, "Expense_Net": 0.007, "Benchmark_Exp": 0.0037, "Turnover_Ratio": null}', '{"volume_metrics": {"Vol_3M": 8090, "Vol_Recent": 8490}, "moving_averages": {"MA_50": 26.67, "MA_200": 25.767}}', '{"asset_allocation": {"Bond_Weight": 0, "Equity_Weight": 1}, "bond_characteristics": {"Avg_Maturity": null, "Duration_Yrs": null}}', '{"valuation_metrics": {"PB_Ratio": 1.38, "PE_Ratio": 12.39, "PS_Ratio": 2.76, "PCF_Ratio": 11.81}}');
INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (1576, 'RORO', 'ETF', 'US', 'BlackRock Real Estate Securitie', 'BlackRock Real Estate Securities Fund Investor A Shares', 'US Dollar', NULL, NULL, 'BlackRock', 'PCX', 'Large Growth', 30235936, NULL, '2020-11-17', NULL, 'The investment seeks total return comprised of long-term growth of capital and dividend income. The fund normally invests at least 80% of its net assets plus any borrowings for investment purposes (measured at the time of purchase) in a portfolio of equity investments in issuers that are primarily engaged in or related to the real estate industry inside the United States. It may invest up to 20% of its net assets plus any borrowings for investment purposes in a portfolio of equity investments in issuers that are primarily engaged in or related to the real estate industry outside the United States and fixed-income investments. The fund is non-diversified.', 0.0113, 0.0039, 17016, 31670, 24.076, 23.547, 0, 0.9982, NULL, NULL, NULL, NULL, 25.68, 18.51, '{"Cap_Size": null, "Quote_Mode": "ETF", "Currency_Base": "US Dollar", "GeoZone_Class": "US", "Strategy_Type": null}', '{"Net_Worth": 30235936, "Yield_Rate": null, "Expense_Net": 0.0113, "Benchmark_Exp": 0.0039, "Turnover_Ratio": null}', '{"volume_metrics": {"Vol_3M": 17016, "Vol_Recent": 31670}, "moving_averages": {"MA_50": 24.076, "MA_200": 23.547}}', '{"asset_allocation": {"Bond_Weight": 0.9982, "Equity_Weight": 0}, "bond_characteristics": {"Avg_Maturity": 25.68, "Duration_Yrs": 18.51}}', '{"valuation_metrics": {"PB_Ratio": null, "PE_Ratio": null, "PS_Ratio": null, "PCF_Ratio": null}}');
INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (1607, 'SBUG', 'ETF', 'U.S.A.', 'Sterling Capital Intermediate U', 'Sterling Capital Intermediate U.S. Government Fund Institutional Shares', 'Usd', NULL, NULL, 'Sterling Capital Funds', 'PCX', NULL, 15302790, NULL, '2019-10-07', NULL, 'The investment seeks current income consistent with the preservation of capital. The fund normally invests at least 80% of its net assets plus borrowings for investment purposes in bonds issued or guaranteed by the U.S. government or its agencies and instrumentalities ("U.S. government securities"). It invests, under normal market conditions, in U.S. government securities, some of which may be subject to repurchase agreements, or in "high grade" mortgage-backed securities, including collateralized mortgage obligations. The fund will maintain an average duration between 2.5 and 7 years.', NULL, NULL, 167, 100, 32.429, 34.76, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '{"Cap_Size": null, "Quote_Mode": "ETF", "Currency_Base": "Usd", "GeoZone_Class": "U.S.A.", "Strategy_Type": null}', '{"Net_Worth": 15302790, "Yield_Rate": null, "Expense_Net": null, "Benchmark_Exp": null, "Turnover_Ratio": null}', '{"volume_metrics": {"Vol_3M": 167, "Vol_Recent": 100}, "moving_averages": {"MA_50": 32.429, "MA_200": 34.76}}', '{"asset_allocation": {"Bond_Weight": null, "Equity_Weight": null}, "bond_characteristics": {"Avg_Maturity": null, "Duration_Yrs": null}}', '{"valuation_metrics": {"PB_Ratio": null, "PE_Ratio": null, "PS_Ratio": null, "PCF_Ratio": null}}');
INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (1577, 'ROSC', 'ETF', 'usa', 'Baron Asset Fund Inst Shs', 'Baron Asset Fund Institutional Class', 'Dollar', 'Value', 'Small', 'Baron Capital Group, Inc.', 'PCX', 'Small Value', 25563868, 0.0131, '2015-03-23', 1.51, 'The investment seeks capital appreciation through long-term investments primarily in securities of mid-sized companies with undervalued assets or favorable growth prospects. The fund invests for the long term primarily in equity securities in the form of common stock of U.S. mid-sized growth companies. BAMCO, Inc. ("BAMCO" or the "Adviser") defines mid-sized companies as those, at the time of purchase, with market capitalizations above $2.5 billion or the smallest market cap stock in the Russell Midcap Growth Index at reconstitution, whichever is larger, and below the largest market cap stock in the Russell Midcap Growth Index at reconstitution.', 0.0034, 0.0035, 5458, 23670, 40.173, 38.91, NULL, NULL, 2.12, 8.29, 13.25, 0.79, NULL, NULL, '{"Cap_Size": "Small", "Quote_Mode": "ETF", "Currency_Base": "Dollar", "GeoZone_Class": "usa", "Strategy_Type": "Value"}', '{"Net_Worth": 25563868, "Yield_Rate": 0.0131, "Expense_Net": 0.0034, "Benchmark_Exp": 0.0035, "Turnover_Ratio": 1.51}', '{"volume_metrics": {"Vol_3M": 5458, "Vol_Recent": 23670}, "moving_averages": {"MA_50": 40.173, "MA_200": 38.91}}', '{"asset_allocation": {"Bond_Weight": null, "Equity_Weight": null}, "bond_characteristics": {"Avg_Maturity": null, "Duration_Yrs": null}}', '{"valuation_metrics": {"PB_Ratio": 2.12, "PE_Ratio": 13.25, "PS_Ratio": 0.79, "PCF_Ratio": 8.29}}');
INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (1578, 'ROUS', 'ETF', 'UNITED_STATES', 'Beacon Accelerated Return Strat', 'Beacon Accelerated Return Strategy Fund Institutional Class', 'US Dollar', 'Blend', 'Large', 'Beacon Investment Advisory', 'PCX', 'Large Value', 392544352, 0.0165, '2015-02-25', 0.71, 'The investment seeks to deliver capital appreciation and generate positive alpha. The fund seeks to outperform U.S. equity markets in modestly rising market environments, to capture most of the equity returns in strong bull markets, and to generate returns that approximate the U.S. equity markets in falling markets, gross of fees. It seeks to capture returns through a systematic investment process of obtaining exposure to the U.S. equity markets primarily through the options markets. It is non-diversified.', 0.0019, 0.0034, 29250, 14710, 41.737, 40.166, 0.9926, 0, 4.06, 14.05, 21.92, 1.81, NULL, NULL, '{"Cap_Size": "Large", "Quote_Mode": "ETF", "Currency_Base": "US Dollar", "GeoZone_Class": "UNITED_STATES", "Strategy_Type": "Blend"}', '{"Net_Worth": 392544352, "Yield_Rate": 0.0165, "Expense_Net": 0.0019, "Benchmark_Exp": 0.0034, "Turnover_Ratio": 0.71}', '{"volume_metrics": {"Vol_3M": 29250, "Vol_Recent": 14710}, "moving_averages": {"MA_50": 41.737, "MA_200": 40.166}}', '{"asset_allocation": {"Bond_Weight": 0, "Equity_Weight": 0.9926}, "bond_characteristics": {"Avg_Maturity": null, "Duration_Yrs": null}}', '{"valuation_metrics": {"PB_Ratio": 4.06, "PE_Ratio": 21.92, "PS_Ratio": 1.81, "PCF_Ratio": 14.05}}');
INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (1588, 'RWK', 'ETF', 'USA', 'BMO TCH Core Plus Bond Fund Cla', 'BMO Core Plus Bond Fund Class A', 'usd', 'Value', 'Small', 'BMO Funds', 'PCX', 'Mid-Cap Value', 409437120, 0.0072, '2008-02-20', 0.33, 'The investment seeks to maximize total return consistent with current income. The fund invests at least 80% of its assets in bonds. The investments include corporate, asset-backed, mortgage-backed and U.S. government securities. Although the fund will invest primarily in securities with a minimum rating in the lowest investment grade category at the time of purchase, it may invest up to 20% of its assets in debt securities that are below investment grade, also known as high yield securities or "junk bonds."', 0.0039, 0.0043, 16806, 13860, 91.997, 89.043, 1, 0, 2.31, 8.28, 17.5, 0.71, NULL, NULL, '{"Cap_Size": "Small", "Quote_Mode": "ETF", "Currency_Base": "usd", "GeoZone_Class": "USA", "Strategy_Type": "Value"}', '{"Net_Worth": 409437120, "Yield_Rate": 0.0072, "Expense_Net": 0.0039, "Benchmark_Exp": 0.0043, "Turnover_Ratio": 0.33}', '{"volume_metrics": {"Vol_3M": 16806, "Vol_Recent": 13860}, "moving_averages": {"MA_50": 91.997, "MA_200": 89.043}}', '{"asset_allocation": {"Bond_Weight": 0, "Equity_Weight": 1}, "bond_characteristics": {"Avg_Maturity": null, "Duration_Yrs": null}}', '{"valuation_metrics": {"PB_Ratio": 2.31, "PE_Ratio": 17.5, "PS_Ratio": 0.71, "PCF_Ratio": 8.28}}');
INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (1579, 'RPAR', 'ETF', 'U.S.A.', 'Baron Asset Fund R6 Shares', 'Baron Asset Fund Class R6', 'Dollar', 'Blend', 'Large', 'Baron Capital Group, Inc.', 'PCX', 'Allocation--30% to 50% Equity', 1318786944, 0.0095, '2019-12-12', NULL, 'The investment seeks capital appreciation through long-term investments primarily in securities of mid-sized companies with undervalued assets or favorable growth prospects. The fund invests for the long term primarily in equity securities in the form of common stock of U.S. mid-sized growth companies. BAMCO, Inc. ("BAMCO" or the "Adviser") defines mid-sized companies as those, at the time of purchase, with market capitalizations above $2.5 billion or the smallest market cap stock in the Russell Midcap Growth Index at reconstitution, whichever is larger, and below the largest market cap stock in the Russell Midcap Growth Index at reconstitution.', 0.0051, 0.0037, 148038, 121490, 24.98, 24.285, NULL, NULL, 2.13, 10.95, 22.85, 1.64, NULL, NULL, '{"Cap_Size": "Large", "Quote_Mode": "ETF", "Currency_Base": "Dollar", "GeoZone_Class": "U.S.A.", "Strategy_Type": "Blend"}', '{"Net_Worth": 1318786944, "Yield_Rate": 0.0095, "Expense_Net": 0.0051, "Benchmark_Exp": 0.0037, "Turnover_Ratio": null}', '{"volume_metrics": {"Vol_3M": 148038, "Vol_Recent": 121490}, "moving_averages": {"MA_50": 24.98, "MA_200": 24.285}}', '{"asset_allocation": {"Bond_Weight": null, "Equity_Weight": null}, "bond_characteristics": {"Avg_Maturity": null, "Duration_Yrs": null}}', '{"valuation_metrics": {"PB_Ratio": 2.13, "PE_Ratio": 22.85, "PS_Ratio": 1.64, "PCF_Ratio": 10.95}}');
INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (1580, 'RSX', 'ETF', 'us', 'Brown Advisory Small Cap Growth', 'Brown Advisory Small-Cap Growth Fund Advisor Shares', 'DOLLAR', 'Value', 'Large', 'Brown Advisory Funds', 'BTS', 'Miscellaneous Region', 1912220288, 0.0275, '2007-04-24', 0.25, 'The investment seeks to achieve long-term capital appreciation by primarily investing in equity securities. Under normal conditions, the Adviser seeks to achieve the fund''s investment objective by investing at least 80% of the value of its net assets (plus any borrowings for investment purposes) in equity securities of small domestic companies. The fund invests primarily in companies the Adviser believes have above average growth prospects. Equity securities include domestic common and preferred stock, convertible debt securities, American Depositary Receipts ("ADRs"), real estate investment trusts ("REITs") and exchange traded funds ("ETFs").', 0.0061, 0.0053, 4251396, 6.97042e+06, 31.184, 28.614, 0.9995, 0, 1.35, 5.56, 10.63, 1.33, NULL, NULL, '{"Cap_Size": "Large", "Quote_Mode": "ETF", "Currency_Base": "DOLLAR", "GeoZone_Class": "us", "Strategy_Type": "Value"}', '{"Net_Worth": 1912220288, "Yield_Rate": 0.0275, "Expense_Net": 0.0061, "Benchmark_Exp": 0.0053, "Turnover_Ratio": 0.25}', '{"volume_metrics": {"Vol_3M": 4251396, "Vol_Recent": 6970420}, "moving_averages": {"MA_50": 31.184, "MA_200": 28.614}}', '{"asset_allocation": {"Bond_Weight": 0, "Equity_Weight": 0.9995}, "bond_characteristics": {"Avg_Maturity": null, "Duration_Yrs": null}}', '{"valuation_metrics": {"PB_Ratio": 1.35, "PE_Ratio": 10.63, "PS_Ratio": 1.33, "PCF_Ratio": 5.56}}');
INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (1581, 'RSXJ', 'ETF', 'United States', 'Brown Advisory Sustainable Bond', 'Brown Advisory Sustainable Bond Fund Investor Shares', 'US Dollar', 'Value', 'Small', 'Brown Advisory Funds', 'BTS', 'Miscellaneous Region', 30612008, 0.0431, '2011-04-13', 0.47, 'The investment seeks to provide a competitive total return consistent with preservation of principal while giving special consideration to certain environmental, social and governance ("ESG") criteria. The fund''s investment objective by investing at least 80% of the value of its net assets (plus any borrowings for investment purposes) in either fixed income securities of issuers that satisfy the fund''s ESG criteria or in securities where the use of the proceeds satisfy the fund''s ESG criteria. The fund may invest up to 20% of its assets in high-yield securities ("junk bonds" ).', 0.0075, 0.0053, 6676, 4440, 38.862, 37.54, 0.9989, 0, 1.21, 4.61, 10.68, 0.69, NULL, NULL, '{"Cap_Size": "Small", "Quote_Mode": "ETF", "Currency_Base": "US Dollar", "GeoZone_Class": "United States", "Strategy_Type": "Value"}', '{"Net_Worth": 30612008, "Yield_Rate": 0.0431, "Expense_Net": 0.0075, "Benchmark_Exp": 0.0053, "Turnover_Ratio": 0.47}', '{"volume_metrics": {"Vol_3M": 6676, "Vol_Recent": 4440}, "moving_averages": {"MA_50": 38.862, "MA_200": 37.54}}', '{"asset_allocation": {"Bond_Weight": 0, "Equity_Weight": 0.9989}, "bond_characteristics": {"Avg_Maturity": null, "Duration_Yrs": null}}', '{"valuation_metrics": {"PB_Ratio": 1.21, "PE_Ratio": 10.68, "PS_Ratio": 0.69, "PCF_Ratio": 4.61}}');
INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (1582, 'RTAI', 'ETF', 'U.S.', 'Sterling Capital South Carolin', 'Sterling Capital South Carolina Intermediate Tax Free Fund Class A', 'DOLLAR', NULL, NULL, 'Sterling Capital Funds', 'BTS', 'Muni National Interm', 12721942, NULL, '2020-10-20', NULL, 'The investment seeks current income exempt from federal and South Carolina income taxes consistent with preservation of capital. The fund normally invests at least 80% of its net assets in investments the income from which is exempt from federal income tax, alternative minimum tax, and South Carolina personal income tax. It invests primarily in municipal securities of the State of South Carolina and its political subdivisions that provide income exempt from both federal personal income tax and South Carolina personal income tax. The fund''s dollar-weighted average maturity is expected to be more than 3 years but less than 10 years. It is non-diversified.', 0.0191, 0.0029, 3822, 1610, 27.925, 27.837, NULL, NULL, NULL, NULL, NULL, NULL, 10.75, 7.15, '{"Cap_Size": null, "Quote_Mode": "ETF", "Currency_Base": "DOLLAR", "GeoZone_Class": "U.S.", "Strategy_Type": null}', '{"Net_Worth": 12721942, "Yield_Rate": null, "Expense_Net": 0.0191, "Benchmark_Exp": 0.0029, "Turnover_Ratio": null}', '{"volume_metrics": {"Vol_3M": 3822, "Vol_Recent": 1610}, "moving_averages": {"MA_50": 27.925, "MA_200": 27.837}}', '{"asset_allocation": {"Bond_Weight": null, "Equity_Weight": null}, "bond_characteristics": {"Avg_Maturity": 10.75, "Duration_Yrs": 7.15}}', '{"valuation_metrics": {"PB_Ratio": null, "PE_Ratio": null, "PS_Ratio": null, "PCF_Ratio": null}}');
INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (1584, 'RUSL', 'ETF', 'us', 'BlackRock Strategic Income Oppo', 'BlackRock Strategic Income Opportunities Portfolio Investor A Shares', 'USD', 'Value', 'Large', 'BlackRock', 'PCX', 'Trading--Leveraged Equity', 65718376, 0.0119, '2011-05-25', 2.07, 'The investment seeks total return as is consistent with preservation of capital. The fund normally invests in a combination of fixed income securities, including, but not limited to: high yield securities, international securities, emerging markets debt and mortgages. It may invest significantly in non-investment grade bonds (high yield or junk bonds). The fund may also invest significantly in non-dollar denominated bonds and bonds of emerging market issuers. It may invest up to 15% of its net assets in collateralized debt obligations, of which 10% (as a percentage of the fund''s net assets) may be collateralized in loan obligations.', 0.0126, 0.009, 48792, 73860, 33.805, 28.982, NULL, NULL, 1.35, 5.56, 10.63, 1.33, NULL, NULL, '{"Cap_Size": "Large", "Quote_Mode": "ETF", "Currency_Base": "USD", "GeoZone_Class": "us", "Strategy_Type": "Value"}', '{"Net_Worth": 65718376, "Yield_Rate": 0.0119, "Expense_Net": 0.0126, "Benchmark_Exp": 0.009, "Turnover_Ratio": 2.07}', '{"volume_metrics": {"Vol_3M": 48792, "Vol_Recent": 73860}, "moving_averages": {"MA_50": 33.805, "MA_200": 28.982}}', '{"asset_allocation": {"Bond_Weight": null, "Equity_Weight": null}, "bond_characteristics": {"Avg_Maturity": null, "Duration_Yrs": null}}', '{"valuation_metrics": {"PB_Ratio": 1.35, "PE_Ratio": 10.63, "PS_Ratio": 1.33, "PCF_Ratio": 5.56}}');
INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (1585, 'RVNU', 'ETF', 'United States', 'iShares Total U.S. Stock Market', 'iShares Total U.S. Stock Market Index Fund Investor A Shares', 'USD', NULL, NULL, 'BlackRock', 'PCX', 'Muni National Long', 139936352, 0.025, '2013-06-04', 0.12, 'The investment seeks to track the investment results of a broad-based index composed of U.S. equities. The fund seeks to track the investment results of the Russell 3000© Index, which measures the performance of the broad U.S. equity market. The underlying index is a float-adjusted capitalization-weighted index of the largest public issuers domiciled in the United States and its territories. The fund generally invests at least 90% of its assets, plus the amount of any borrowing for investment purposes, in securities of the underlying index.', 0.0015, 0.0026, 17308, 13800, 29.073, 29.254, 0, 1, NULL, NULL, NULL, NULL, 7.48, 9.86, '{"Cap_Size": null, "Quote_Mode": "ETF", "Currency_Base": "USD", "GeoZone_Class": "United States", "Strategy_Type": null}', '{"Net_Worth": 139936352, "Yield_Rate": 0.025, "Expense_Net": 0.0015, "Benchmark_Exp": 0.0026, "Turnover_Ratio": 0.12}', '{"volume_metrics": {"Vol_3M": 17308, "Vol_Recent": 13800}, "moving_averages": {"MA_50": 29.073, "MA_200": 29.254}}', '{"asset_allocation": {"Bond_Weight": 1, "Equity_Weight": 0}, "bond_characteristics": {"Avg_Maturity": 7.48, "Duration_Yrs": 9.86}}', '{"valuation_metrics": {"PB_Ratio": null, "PE_Ratio": null, "PS_Ratio": null, "PCF_Ratio": null}}');
INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (1586, 'RWGV', 'ETF', 'UNITED_STATES', 'BlackRock Short Obligations Fun', 'BlackRock Short Obligations Fund Investor A Shares', 'US$', 'Growth', 'Large', 'BlackRock', 'PCX', 'Large Growth', 17307732, 0.0014, '2019-01-16', 0.12, 'The investment seeks current income consistent with preservation of capital. The fund will invest in U.S. dollar-denominated investment grade and short-term fixed and floating rate debt securities maturing in three years or less (with certain exceptions) and will maintain a dollar-weighted average maturity of 180 days or less and a dollar-weighted average life of 365 days or less. It invests a significant portion of its assets in securities issued by financial services companies, including banks, broker-dealers and insurance companies, and repurchase agreements secured by such obligations.', 0.0063, 0.0039, 4282, 10380, 126.757, 115.184, NULL, NULL, 13.05, 23.91, 36.46, 4.79, NULL, NULL, '{"Cap_Size": "Large", "Quote_Mode": "ETF", "Currency_Base": "US$", "GeoZone_Class": "UNITED_STATES", "Strategy_Type": "Growth"}', '{"Net_Worth": 17307732, "Yield_Rate": 0.0014, "Expense_Net": 0.0063, "Benchmark_Exp": 0.0039, "Turnover_Ratio": 0.12}', '{"volume_metrics": {"Vol_3M": 4282, "Vol_Recent": 10380}, "moving_averages": {"MA_50": 126.757, "MA_200": 115.184}}', '{"asset_allocation": {"Bond_Weight": null, "Equity_Weight": null}, "bond_characteristics": {"Avg_Maturity": null, "Duration_Yrs": null}}', '{"valuation_metrics": {"PB_Ratio": 13.05, "PE_Ratio": 36.46, "PS_Ratio": 4.79, "PCF_Ratio": 23.91}}');
INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (1587, 'RWJ', 'ETF', 'USA', 'BlackRock Allocation Target Sha', 'BlackRock Allocation Target Shares Series A Portfolio', 'DOLLAR', 'Value', 'Small', 'BlackRock', 'PCX', 'Small Value', 711665600, 0.0047, '2008-02-19', 0.49, 'The investment seeks a high level of current income consistent with capital preservation. The fund will principally invest in the following securities: asset-backed securities; commercial and residential mortgage-backed securities issued or guaranteed by the U.S. government, various agencies of the U.S. government or various instrumentalities that have been established or sponsored by the U.S. government; commercial and residential mortgage-backed securities issued by banks and other financial institutions; CMOs; loans backed by commercial or residential real estate; derivatives; and repurchase agreements and reverse repurchase agreements.', 0.0039, 0.0035, 41052, 40440, 122.681, 117.832, 1, 0, 1.69, 6.2, 12.43, 0.39, NULL, NULL, '{"Cap_Size": "Small", "Quote_Mode": "ETF", "Currency_Base": "DOLLAR", "GeoZone_Class": "USA", "Strategy_Type": "Value"}', '{"Net_Worth": 711665600, "Yield_Rate": 0.0047, "Expense_Net": 0.0039, "Benchmark_Exp": 0.0035, "Turnover_Ratio": 0.49}', '{"volume_metrics": {"Vol_3M": 41052, "Vol_Recent": 40440}, "moving_averages": {"MA_50": 122.681, "MA_200": 117.832}}', '{"asset_allocation": {"Bond_Weight": 0, "Equity_Weight": 1}, "bond_characteristics": {"Avg_Maturity": null, "Duration_Yrs": null}}', '{"valuation_metrics": {"PB_Ratio": 1.69, "PE_Ratio": 12.43, "PS_Ratio": 0.39, "PCF_Ratio": 6.2}}');
INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (1590, 'RWM', 'ETF', 'U.S.', 'BMO TCH Corp Income Fund Class ', 'BMO Corporate Income Fund Class A', 'US_DOLLAR', NULL, NULL, 'BMO Funds', 'PCX', 'Trading--Inverse Equity', 265292640, NULL, '2007-01-23', NULL, 'The investment seeks to maximize total return consistent with current income. The fund invests at least 80% of its assets in corporate debt securities, including convertible debt securities. Although the fund will invest primarily in U.S. dollar denominated securities with a minimum rating in the lowest investment grade category at the time of purchase, it may invest up to 20% of its assets in debt securities that are below investment grade, also known as high yield securities or "junk bonds," and non-U.S. dollar denominated foreign debt securities.', 0.0095, 0.0092, 1146892, 1.55991e+06, 20.698, 21.4, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '{"Cap_Size": null, "Quote_Mode": "ETF", "Currency_Base": "US_DOLLAR", "GeoZone_Class": "U.S.", "Strategy_Type": null}', '{"Net_Worth": 265292640, "Yield_Rate": null, "Expense_Net": 0.0095, "Benchmark_Exp": 0.0092, "Turnover_Ratio": null}', '{"volume_metrics": {"Vol_3M": 1146892, "Vol_Recent": 1559910}, "moving_averages": {"MA_50": 20.698, "MA_200": 21.4}}', '{"asset_allocation": {"Bond_Weight": null, "Equity_Weight": null}, "bond_characteristics": {"Avg_Maturity": null, "Duration_Yrs": null}}', '{"valuation_metrics": {"PB_Ratio": null, "PE_Ratio": null, "PS_Ratio": null, "PCF_Ratio": null}}');
INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (1591, 'RWO', 'ETF', 'US', 'BlackRock Allocation Target Sh', 'BlackRock Allocation Target Shares Series P Portfolio', 'usd', 'Blend', 'Medium', 'BlackRock', 'PCX', 'Global Real Estate', 1689409920, 0.0269, '2008-05-07', 0.18, 'The investment seeks to provide a duration that is the inverse of its benchmark. The fund will seek to pursue its investment objective primarily by engaging in short sales of U.S. Treasury securities and by investing in derivative instruments that provide returns that are inverse to those available by investing directly in U.S. Treasury securities. Derivative instruments that the fund may invest in include, but are not limited to, futures (including U.S. Treasury futures), options, forward contracts and/or swaps, including interest rate swaps, swaptions and total return swaps.', 0.005, 0.0053, 122868, 108850, 53.774, 51.743, 0.9954, 0, 1.69, 19.76, 27.71, 8.76, NULL, NULL, '{"Cap_Size": "Medium", "Quote_Mode": "ETF", "Currency_Base": "usd", "GeoZone_Class": "US", "Strategy_Type": "Blend"}', '{"Net_Worth": 1689409920, "Yield_Rate": 0.0269, "Expense_Net": 0.005, "Benchmark_Exp": 0.0053, "Turnover_Ratio": 0.18}', '{"volume_metrics": {"Vol_3M": 122868, "Vol_Recent": 108850}, "moving_averages": {"MA_50": 53.774, "MA_200": 51.743}}', '{"asset_allocation": {"Bond_Weight": 0, "Equity_Weight": 0.9954}, "bond_characteristics": {"Avg_Maturity": null, "Duration_Yrs": null}}', '{"valuation_metrics": {"PB_Ratio": 1.69, "PE_Ratio": 27.71, "PS_Ratio": 8.76, "PCF_Ratio": 19.76}}');
INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (1592, 'RWVG', 'ETF', 'U.S.A.', NULL, 'BlackRock Allocation Target Shares Series V Portfolio', 'USD', 'Value', 'Large', 'BlackRock', 'PCX', 'Large Value', 37514560, 0.0099, '2019-01-16', NULL, 'The investment seeks as high a level of income exempt from federal income tax consistent with preservation of capital while seeking to minimize price volatility. The fund will invest in a broad range of short-term obligations issued by or on behalf of states, territories and possessions of the U.S., the District of Columbia, and their respective authorities, agencies, instrumentalities and political subdivision, in the opinion of counsel to the issuer of the obligation, is exempt from regular federal income tax. It invests in securities maturing in two years or less and will maintain a dollar-weighted average maturity of 120 days or less.', 0.0065, 0.0034, 6127, 2150, 58.091, 57.934, NULL, NULL, 2.55, 13.28, 19.64, 2.03, NULL, NULL, '{"Cap_Size": "Large", "Quote_Mode": "ETF", "Currency_Base": "USD", "GeoZone_Class": "U.S.A.", "Strategy_Type": "Value"}', '{"Net_Worth": 37514560, "Yield_Rate": 0.0099, "Expense_Net": 0.0065, "Benchmark_Exp": 0.0034, "Turnover_Ratio": null}', '{"volume_metrics": {"Vol_3M": 6127, "Vol_Recent": 2150}, "moving_averages": {"MA_50": 58.091, "MA_200": 57.934}}', '{"asset_allocation": {"Bond_Weight": null, "Equity_Weight": null}, "bond_characteristics": {"Avg_Maturity": null, "Duration_Yrs": null}}', '{"valuation_metrics": {"PB_Ratio": 2.55, "PE_Ratio": 19.64, "PS_Ratio": 2.03, "PCF_Ratio": 13.28}}');
INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (1593, 'RWX', 'ETF', 'UNITED_STATES', 'Brown Advisory Small-Cap Fundam', 'Brown Advisory Small-Cap Fundamental Value Fund Advisor Shares', 'Dollar', 'Blend', 'Medium', 'Brown Advisory Funds', 'PCX', 'Global Real Estate', 923759872, 0.0256, '2006-12-15', 0.14, 'The investment seeks to achieve long-term capital appreciation. The fund normally invests at least 80% of the value of its net assets (plus borrowings for investment purposes) in equity securities of small capitalization companies. Equity securities include common stock, preferred stock, equity-equivalent securities such as convertible securities, stock futures contracts, equity options, other investment companies, ADRs, REITs and ETFs, and the Adviser may also invest in private placements in these types of securities. Small companies are companies whose market capitalizations are generally less than $6 billion at the time of purchase.', 0.0059, 0.0053, 139928, 156150, 36.247, 36.544, 0.9913, 0, 1.09, 17.91, 17.16, 6.84, NULL, NULL, '{"Cap_Size": "Medium", "Quote_Mode": "ETF", "Currency_Base": "Dollar", "GeoZone_Class": "UNITED_STATES", "Strategy_Type": "Blend"}', '{"Net_Worth": 923759872, "Yield_Rate": 0.0256, "Expense_Net": 0.0059, "Benchmark_Exp": 0.0053, "Turnover_Ratio": 0.14}', '{"volume_metrics": {"Vol_3M": 139928, "Vol_Recent": 156150}, "moving_averages": {"MA_50": 36.247, "MA_200": 36.544}}', '{"asset_allocation": {"Bond_Weight": 0, "Equity_Weight": 0.9913}, "bond_characteristics": {"Avg_Maturity": null, "Duration_Yrs": null}}', '{"valuation_metrics": {"PB_Ratio": 1.09, "PE_Ratio": 17.16, "PS_Ratio": 6.84, "PCF_Ratio": 17.91}}');
INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (1594, 'RXD', 'ETF', 'USA', 'BMO Ultra Short Tax-Free Fund C', 'BMO Ultra Short Tax-Free Fund Class A', 'usd', NULL, NULL, 'BMO Funds', 'PCX', 'Trading--Inverse Equity', 1193497, NULL, '2007-01-30', NULL, 'The investment seeks to provide current income exempt from federal income tax consistent with preservation of capital. Under normal circumstances, the fund invests at least 80% of its assets in municipal securities, the income from which is exempt from federal income tax (including the federal alternative minimum tax (AMT)). It normally maintains an average dollar-weighted effective maturity of one year or less. Effective maturity takes into account the possibility that a bond may have prepayments or may be called by the issuer before its stated maturity date.', 0.0095, 0.0092, 19630, 59870, 13.607, 14.973, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '{"Cap_Size": null, "Quote_Mode": "ETF", "Currency_Base": "usd", "GeoZone_Class": "USA", "Strategy_Type": null}', '{"Net_Worth": 1193497, "Yield_Rate": null, "Expense_Net": 0.0095, "Benchmark_Exp": 0.0092, "Turnover_Ratio": null}', '{"volume_metrics": {"Vol_3M": 19630, "Vol_Recent": 59870}, "moving_averages": {"MA_50": 13.607, "MA_200": 14.973}}', '{"asset_allocation": {"Bond_Weight": null, "Equity_Weight": null}, "bond_characteristics": {"Avg_Maturity": null, "Duration_Yrs": null}}', '{"valuation_metrics": {"PB_Ratio": null, "PE_Ratio": null, "PS_Ratio": null, "PCF_Ratio": null}}');
