INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (1613, 'SCHD', 'ETF', 'us', 'Sterling Capital Behavioral Lar', 'Sterling Capital Behavioral Large Cap Value Equity Fund Institutional', 'DOLLAR', 'Value', 'Large', 'Sterling Capital Funds', 'PCX', 'Large Value', 26004670464, 0.0289, '2011-10-20', 0.43, 'The investment seeks maximum long-term total return, by investing primarily in equity securities of large companies. The fund normally invests at least 80% of its net assets plus borrowings for investment purposes in the equity securities of large companies. Large companies are defined as companies with market capitalizations within the range of those companies in the Standard & Poor''s 500© Index at the time of purchase.', 0.0006, 0.0034, 1831423, 2.26745e+06, 77.244, 75.627, 0.9996, 0, 4.05, 12.83, 19.24, 2.41, NULL, NULL, '{"Cap_Size": "Large", "Quote_Mode": "ETF", "Currency_Base": "DOLLAR", "GeoZone_Class": "us", "Strategy_Type": "Value"}', '{"Net_Worth": 26004670464, "Yield_Rate": 0.0289, "Expense_Net": 0.0006, "Benchmark_Exp": 0.0034, "Turnover_Ratio": 0.43}', '{"volume_metrics": {"Vol_3M": 1831423, "Vol_Recent": 2267450}, "moving_averages": {"MA_50": 77.244, "MA_200": 75.627}}', '{"asset_allocation": {"Bond_Weight": 0, "Equity_Weight": 0.9996}, "bond_characteristics": {"Avg_Maturity": null, "Duration_Yrs": null}}', '{"valuation_metrics": {"PB_Ratio": 4.05, "PE_Ratio": 19.24, "PS_Ratio": 2.41, "PCF_Ratio": 12.83}}');
