INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (1622, 'SCHO', 'ETF', 'USA', 'Sterling Capital Short Duration', 'Sterling Capital Short Duration Bond Fund Class C', 'USD', NULL, NULL, 'Sterling Capital Funds', 'PCX', 'Short Government', 9400687616, 0.008, '2010-08-05', 0.74, 'The investment seeks to provide current income and competitive total return. The fund normally invests at least 80% of its net assets plus borrowings for investment purposes in investment grade fixed income securities (bonds). It will invest in municipal securities, convertible securities, including convertible bonds and preferred stocks, and cash equivalents. The fund may invest up to 15% of its total assets in bonds that are below investment grade, which are commonly referred to as "high yield" or "junk" bonds, and non-dollar denominated foreign and emerging market securities. It will maintain an average duration between 1 and 3 years.', 0.0005, 0.0013, 833441, 855580, 51.05, 51.218, 0, 0.9992, NULL, NULL, NULL, NULL, 1.98, 1.95, '{"Cap_Size": null, "Quote_Mode": "ETF", "Currency_Base": "USD", "GeoZone_Class": "USA", "Strategy_Type": null}', '{"Net_Worth": 9400687616, "Yield_Rate": 0.008, "Expense_Net": 0.0005, "Benchmark_Exp": 0.0013, "Turnover_Ratio": 0.74}', '{"volume_metrics": {"Vol_3M": 833441, "Vol_Recent": 855580}, "moving_averages": {"MA_50": 51.05, "MA_200": 51.218}}', '{"asset_allocation": {"Bond_Weight": 0.9992, "Equity_Weight": 0}, "bond_characteristics": {"Avg_Maturity": 1.98, "Duration_Yrs": 1.95}}', '{"valuation_metrics": {"PB_Ratio": null, "PE_Ratio": null, "PS_Ratio": null, "PCF_Ratio": null}}');
INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (1623, 'SCHP', 'ETF', 'U.S.A.', 'Sterling Capital Short Duration', 'Sterling Capital Short Duration Bond Fund Class I', 'USD', NULL, NULL, 'Sterling Capital Funds', 'PCX', 'Inflation-Protected Bond', 18406871040, 0.0197, '2010-08-05', 0.23, 'The investment seeks to provide current income and competitive total return. The fund normally invests at least 80% of its net assets plus borrowings for investment purposes in investment grade fixed income securities (bonds). It will invest in municipal securities, convertible securities, including convertible bonds and preferred stocks, and cash equivalents. The fund may invest up to 15% of its total assets in bonds that are below investment grade, which are commonly referred to as "high yield" or "junk" bonds, and non-dollar denominated foreign and emerging market securities. It will maintain an average duration between 1 and 3 years.', 0.0005, 0.0016, 3249996, 3.90486e+06, 63.038, 62.476, 0, 1, NULL, NULL, NULL, NULL, 8.06, 7.56, '{"Cap_Size": null, "Quote_Mode": "ETF", "Currency_Base": "USD", "GeoZone_Class": "U.S.A.", "Strategy_Type": null}', '{"Net_Worth": 18406871040, "Yield_Rate": 0.0197, "Expense_Net": 0.0005, "Benchmark_Exp": 0.0016, "Turnover_Ratio": 0.23}', '{"volume_metrics": {"Vol_3M": 3249996, "Vol_Recent": 3904860}, "moving_averages": {"MA_50": 63.038, "MA_200": 62.476}}', '{"asset_allocation": {"Bond_Weight": 1, "Equity_Weight": 0}, "bond_characteristics": {"Avg_Maturity": 8.06, "Duration_Yrs": 7.56}}', '{"valuation_metrics": {"PB_Ratio": null, "PE_Ratio": nu