INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (1654, 'SGDM', 'ETF', 'usa', 'Brown Capital Management Mid Co', 'Brown Capital Management Mid Company Fund Institutional Shares', 'US$', 'Blend', 'Medium', 'Brown Capital Management', 'PCX', 'Equity Precious Metals', 240646528, 0.0033, '2014-07-14', NULL, 'The investment seeks long-term capital appreciation; current income is a secondary consideration in selecting portfolio investments. The fund invests at least 80% of its net assets (plus any borrowings for investment purposes) in a portfolio of equity securities of companies with total operating revenues of $500 million to $5 billion at the time of initial investment ("mid sized companies"). It typically invests in common stocks. The fund typically holds a portfolio of between 40 to 60 securities which the Advisor believes have the potential for growth.', 0.005, 0.0057, 25937, 23990, 27.236, 28.246, 0.9987, 0, 1.65, 7.24, 14.49, 2.8, NULL, NULL, '{"Cap_Size": "Medium", "Quote_Mode": "ETF", "Currency_Base": "US$", "GeoZone_Class": "usa", "Strategy_Type": "Blend"}', '{"Net_Worth": 240646528, "Yield_Rate": 0.0033, "Expense_Net": 0.005, "Benchmark_Exp": 0.0057, "Turnover_Ratio": null}', '{"volume_metrics": {"Vol_3M": 25937, "Vol_Recent": 23990}, "moving_averages": {"MA_50": 27.236, "MA_200": 28.246}}', '{"asset_allocation": {"Bond_Weight": 0, "Equity_Weight": 0.9987}, "bond_characteristics": {"Avg_Maturity": null, "Duration_Yrs": null}}', '{"valuation_metrics": {"PB_Ratio": 1.65, "PE_Ratio": 14.49, "PS_Ratio": 2.8, "PCF_Ratio": 7.24}}');
