INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (1669, 'SIJ', 'ETF', 'United States', 'Brown Capital Management Intern', 'Brown Capital Management International Small Company Fund Institutional Shares', 'US Dollar', NULL, NULL, 'Brown Capital Management', 'PCX', 'Trading--Inverse Equity', 1676788, NULL, '2007-01-30', NULL, 'The investment seeks long-term capital appreciation; current income is a secondary consideration in selecting portfolio investments. The fund invests at least 80% of its net assets (plus any borrowings for investment purposes) in the equity securities of non-U.S. based companies with total operating revenues of $500 million or less at the time of the initial investment, ("small companies"). The Advisor constructs the fund''s portfolio to generally be no more than 5% in cash. The Advisor believes a diversified portfolio of 40-65 securities and their research efforts may, collective, reduce portfolio risk.', 0.0095, 0.0092, 11600, 2760, 14.046, 14.83, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '{"Cap_Size": null, "Quote_Mode": "ETF", "Currency_Base": "US Dollar", "GeoZone_Class": "United States", "Strategy_Type": null}', '{"Net_Worth": 1676788, "Yield_Rate": null, "Expense_Net": 0.0095, "Benchmark_Exp": 0.0092, "Turnover_Ratio": null}', '{"volume_metrics": {"Vol_3M": 11600, "Vol_Recent": 2760}, "moving_averages": {"MA_50": 14.046, "MA_200": 14.83}}', '{"asset_allocation": {"Bond_Weight": null, "Equity_Weight": null}, "bond_characteristics": {"Avg_Maturity": null, "Duration_Yrs": null}}', '{"valuation_metrics": {"PB_Ratio": null, "PE_Ratio": null, "PS_Ratio": null, "PCF_Ratio": null}}');
