INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (1715, 'SPAB', 'ETF', 'United States', 'Federated Hermes Prudent Bear F', 'Federated Hermes Prudent Bear Fund Class A Shares', 'DOLLAR', NULL, NULL, 'Federated', 'PCX', 'Intermediate-Term Bond', 6158985216, 0.0229, '2007-05-23', 1.01, 'The investment seeks capital appreciation. The fund pursues its investment objective primarily through short positions in domestically traded equity securities and indices. It holds short-term liquid securities such as money market funds, U.S. Treasury securities, government agency securities or other equity securities for liquidity purposes and to cover its obligation to purchase securities subject to short sales in the future. The fund also seeks capital appreciation through long positions on equity securities which the fund''s adviser believes are undervalued.', 0.0003, 0.0023, 1288568, 1.25207e+06, 29.765, 29.905, NULL, NULL, NULL, NULL, NULL, NULL, 8.33, 6.62, '{"Cap_Size": null, "Quote_Mode": "ETF", "Currency_Base": "DOLLAR", "GeoZone_Class": "United States", "Strategy_Type": null}', '{"Net_Worth": 6158985216, "Yield_Rate": 0.0229, "Expense_Net": 0.0003, "Benchmark_Exp": 0.0023, "Turnover_Ratio": 1.01}', '{"volume_metrics": {"Vol_3M": 1288568, "Vol_Recent": 1252070}, "moving_averages": {"MA_50": 29.765, "MA_200": 29.905}}', '{"asset_allocation": {"Bond_Weight": null, "Equity_Weight": null}, "bond_characteristics": {"Avg_Maturity": 8.33, "Duration_Yrs": 6.62}}', '{"valuation_metrics": {"PB_Ratio": null, "PE_Ratio": null, "PS_Ratio": null, "PCF_Ratio": null}}');
INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (1716, 'SPAK', 'ETF', 'US', 'BlackRock Emerging Markets Flex', 'BlackRock Emerging Markets Flexible Dynamic Bond Portfolio Institutional Shares', 'AmericanDollar', NULL, NULL, 'BlackRock', 'PCX', NULL, 62984092, NULL, '2020-09-30', NULL, 'The investment seeks maximum long term total return. The fund invests primarily in a global portfolio of fixed income securities and derivatives of any maturity of issuers located in emerging markets that may be denominated in any currency (on a hedged or un-hedged basis). It will invest at least 80% of its assets in fixed income securities issued by governments, their political subdivisions (states, provinces and municipalities), agencies and companies tied economically to an emerging market. The fund is non-diversified.', 0.0045, NULL, 30341, 25670, 23.694, 24.954, 0.9986, 0, 3.58, NULL, NULL, NULL, NULL, NULL, '{"Cap_Size": null, "Quote_Mode": "ETF", "Currency_Base": "AmericanDollar", "GeoZone_Class": "US", "Strategy_Type": null}', '{"Net_Worth": 62984092, "Yield_Rate": null, "Expense_Net": 0.0045, "Benchmark_Exp": null, "Turnover_Ratio": null}', '{"volume_metrics": {"Vol_3M": 30341, "Vol_Recent": 25670}, "moving_averages": {"MA_50": 23.694, "MA_200": 24.954}}', '{"asset_allocation": {"Bond_Weight": 0, "Equity_Weight": 0.9986}, "bond_characteristics": {"Avg_Maturity": null, "Duration_Yrs": null}}', '{"valuation_metrics": {"PB_Ratio": 3.58, "PE_Ratio": null, "PS_Ratio": null, "PCF_Ratio": null}}');
INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (1717, 'SPBC', 'ETF', 'US', 'BlackRock Emerging Markets Allo', 'BlackRock Total Emerging Markets Fund Investor A', 'US$', NULL, NULL, 'BlackRock', 'NGM', 'Large Blend', 102553872, NULL, '2021-05-24', NULL, 'The investment seeks total return. The fund normally invests at least 80% of its net assets plus any borrowings for investment purposes in equity and debt instruments and related derivative instruments issued by, or tied economically to, companies or other issuers located in emerging markets. This is a non-fundamental policy of the fund and may be changed with 60 days'' prior notice to shareholders. It may invest in securities of companies of any market capitalization and may take both long and short positions in a variety of global instruments.', 0.005, 0.0036, 11214, 27650, 28.075, 26.78, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '{"Cap_Size": null, "Quote_Mode": "ETF", "Currency_Base": "US$", "GeoZone_Class": "US", "Strategy_Type": null}', '{"Net_Worth": 102553872, "Yield_Rate": null, "Expense_Net": 0.005, "Benchmark_Exp": 0.0036, "Turnover_Ratio": null}', '{"volume_metrics": {"Vol_3M": 11214, "Vol_Recent": 27650}, "moving_averages": {"MA_50": 28.075, "MA_200": 26.78}}', '{"asset_allocation": {"Bond_Weight": null, "Equity_Weight": null}, "bond_characteristics": {"Avg_Maturity": null, "Duration_Yrs": null}}', '{"valuation_metrics": {"PB_Ratio": null, "PE_Ratio": null, "PS_Ratio": null, "PCF_Ratio": null}}');
