INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (1735, 'SPLB', 'ETF', 'usa', 'William Blair Emerging Markets ', 'William Blair Emerging Markets Small Cap Growth Fund Class I', 'US_DOLLAR', NULL, NULL, 'William Blair', 'PCX', 'Long-Term Bond', 999402176, 0.0303, '2009-03-10', 0.22, 'The investment seeks long-term capital appreciation. Under normal market conditions, the fund invests at least 80% of its net assets (plus the amount of any borrowings for investment purposes) in equity securities of emerging market small capitalization ("small cap") companies. The fund invests primarily in a diversified portfolio of equity securities, including common stocks and other forms of equity investments (e.g., securities convertible into common stocks), issued by emerging market small cap companies, that the Adviser believes have above average growth, profitability and quality characteristics.', 0.0007, 0.0017, 2178973, 2.38068e+06, 31.622, 31.318, 0, 0.9957, NULL, NULL, NULL, NULL, 23.63, 15.33, '{"Cap_Size": null, "Quote_Mode": "ETF", "Currency_Base": "US_DOLLAR", "GeoZone_Class": "usa", "Strategy_Type": null}', '{"Net_Worth": 999402176, "Yield_Rate": 0.0303, "Expense_Net": 0.0007, "Benchmark_Exp": 0.0017, "Turnover_Ratio": 0.22}', '{"volume_metrics": {"Vol_3M": 2178973, "Vol_Recent": 2380680}, "moving_averages": {"MA_50": 31.622, "MA_200": 31.318}}', '{"asset_allocation": {"Bond_Weight": 0.9957, "Equity_Weight": 0}, "bond_characteristics": {"Avg_Maturity": 23.63, "Duration_Yrs": 15.33}}', '{"valuation_metrics": {"PB_Ratio": null, "PE_Ratio": null, "PS_Ratio": null, "PCF_Ratio": null}}');
