INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (1817, 'TECL', 'ETF', 'US', 'Brookfield Global Listed Infras', 'Brookfield Global Listed Infrastructure Fund Class A', 'Dollar', 'Growth', 'Large', 'Brookfield Investment Funds', 'PCX', 'Trading--Leveraged Equity', 2530157312, 0.0034, '2008-12-17', 3.76, 'The investment seeks total return through growth of capital and current income. The fund normally invests at least 80% of its net assets (plus the amount of any borrowing for investment purposes) in publicly traded equity securities of infrastructure companies listed on a domestic or foreign exchange, throughout the world, including the United States. It normally will maintain exposure to securities of infrastructure companies in the United States and in at least three countries outside the United States.', 0.0101, 0.009, 1377169, 1.96186e+06, 70.359, 56.958, NULL, NULL, 10.88, 22.02, 34.4, 6.58, NULL, NULL, '{"Cap_Size": "Large", "Quote_Mode": "ETF", "Currency_Base": "Dollar", "GeoZone_Class": "US", "Strategy_Type": "Growth"}', '{"Net_Worth": 2530157312, "Yield_Rate": 0.0034, "Expense_Net": 0.0101, "Benchmark_Exp": 0.009, "Turnover_Ratio": 3.76}', '{"volume_metrics": {"Vol_3M": 1377169, "Vol_Recent": 1961860}, "moving_averages": {"MA_50": 70.359, "MA_200": 56.958}}', '{"asset_allocation": {"Bond_Weight": null, "Equity_Weight": null}, "bond_characteristics": {"Avg_Maturity": null, "Duration_Yrs": null}}', '{"valuation_metrics": {"PB_Ratio": 10.88, "PE_Ratio": 34.4, "PS_Ratio": 6.58, "PCF_Ratio": 22.02}}');
INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (1818, 'TECS', 'ETF', 'UNITED_STATES', 'BMO Global Low Volatility Equit', 'BMO Global Low Volatility Equity Fund Class I', 'US Dollar', NULL, NULL, 'BMO Funds', 'PCX', 'Trading--Inverse Equity', 58659772, NULL, '2008-12-17', NULL, 'The investment seeks to provide capital appreciation. The fund invests at least 80% of its assets in equity securities of companies located in the countries included, at the time of purchase, in the MSCI All Country World Index, which includes 23 developed and 26 emerging market countries. It normally invests at least 40% of its net assets in securities located outside the United States and is diversified among at least three countries. The fund may invest in companies across all market capitalizations and may at times focus its investments in one or more sectors.', 0.011, 0.0092, 543785, 662580, 38.231, 53.151, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '{"Cap_Size": null, "Quote_Mode": "ETF", "Currency_Base": "US Dollar", "GeoZone_Class": "UNITED_STATES", "Strategy_Type": null}', '{"Net_Worth": 58659772, "Yield_Rate": null, "Expense_Net": 0.011, "Benchmark_Exp": 0.0092, "Turnover_Ratio": null}', '{"volume_metrics": {"Vol_3M": 543785, "Vol_Recent": 662580}, "moving_averages": {"MA_50": 38.231, "MA_200": 53.151}}', '{"asset_allocation": {"Bond_Weight": null, "Equity_Weight": null}, "bond_characteristics": {"Avg_Maturity": null, "Duration_Yrs": null}}', '{"valuation_metrics": {"PB_Ratio": null, "PE_Ratio": null, "PS_Ratio": null, "PCF_Ratio": null}}');
INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (1819, 'TEGS', 'ETF', 'UNITED_STATES', 'Boston Partners Global Long/Sho', 'Boston Partners Global Long/Short Fund Institutional Class', 'Usd', 'Growth', 'Medium', 'Boston Partners', 'BTS', 'Allocation--70% to 85% Equity', 16219594, NULL, '2020-05-07', NULL, 'The investment seeks long-term growth of capital. Under normal market conditions, the fund invests significantly (ordinarily at least 40% - unless market conditions are not deemed favorable by the Adviser, in which case the fund would invest at least 30%) in non-U.S. companies. It principally will be invested in issuers located in countries with developed securities markets, but may also invest in issuers located in emerging markets. The fund will allocate its assets among various regions and countries, including the United States (but in no less than three different countries). It is non-diversified.', 0.0115, 0.0052, 6285, 440, 29.452, 28.537, 1, 0, 5.33, 15.85, 32.65, 3.06, NULL, NULL, '{"Cap_Size": "Medium", "Quote_Mode": "ETF", "Currency_Base": "Usd", "GeoZone_Class": "UNITED_STATES", "Strategy_Type": "Growth"}', '{"Net_Worth": 16219594, "Yield_Rate": null, "Expense_Net": 0.0115, "Benchmark_Exp": 0.0052, "Turnover_Ratio": null}', '{"volume_metrics": {"Vol_3M": 6285, "Vol_Recent": 440}, "moving_averages": {"MA_50": 29.452, "MA_200": 28.537}}', '{"asset_allocation": {"Bond_Weight": 0, "Equity_Weight": 1}, "bond_characteristics": {"Avg_Maturity": null, "Duration_Yrs": null}}', '{"valuation_metrics": {"PB_Ratio": 5.33, "PE_Ratio": 32.65, "PS_Ratio": 3.06, "PCF_Ratio": 15.85}}');
INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (1820, 'TENG', 'ETF', 'America', 'Baron Global Advantage Fund R6 ', 'Baron Global Advantage Fund R6 Shares', 'Dollar', 'Blend', 'Large', 'Baron Capital Group, Inc.', 'PCX', 'Trading--Leveraged Equity', 5180955, NULL, '2021-06-10', NULL, 'The investment seeks capital appreciation. The fund is a diversified fund that, under normal circumstances, invests primarily in equity securities in the form of common stock of established and emerging markets companies located throughout the world, with capitalizations within the range of companies included in the MSCI ACWI Index Net USD. At all times, it will have investments in equity securities of companies in at least three countries outside of the U.S. Under normal conditions, at least 40% of the fund''s net assets will be invested in stocks of companies outside the U.S. (at least 30% if foreign market conditions are not favorable).', 0.0107, 0.009, 1551, 1520, 26.514, 25.979, NULL, NULL, 3.76, 12.22, 29.6, 2.68, NULL, NULL, '{"Cap_Size": "Large", "Quote_Mode": "ETF", "Currency_Base": "Dollar", "GeoZone_Class": "America", "Strategy_Type": "Blend"}', '{"Net_Worth": 5180955, "Yield_Rate": null, "Expense_Net": 0.0107, "Benchmark_Exp": 0.009, "Turnover_Ratio": null}', '{"volume_metrics": {"Vol_3M": 1551, "Vol_Recent": 1520}, "moving_averages": {"MA_50": 26.514, "MA_200": 25.979}}', '{"asset_allocation": {"Bond_Weight": null, "Equity_Weight": null}, "bond_characteristics": {"Avg_Maturity": null, "Duration_Yrs": null}}', '{"valuation_metrics": {"PB_Ratio": 3.76, "PE_Ratio": 29.6, "PS_Ratio": 2.68, "PCF_Ratio": 12.22}}');
INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (1821, 'TEQI', 'ETF', 'US', 'American Century Ginnie Mae Fd ', 'American Century Investments Ginnie Mae Fund C Class', 'US_DOLLAR', 'Value', 'Large', 'American Century Investments', 'PCX', NULL, 47755920, NULL, '2020-08-04', 0.09, 'The investment seeks high current income while maintaining liquidity and safety of principal by investing primarily in GNMA certificates. Under normal market conditions, the fund invests at least 80% of its net assets in securities issued by the Government National Mortgage Association (GNMA). GNMA certificates represent interests in pools of mortgage loans and in the cash flows from these loans. To generate additional income, the fund may purchase securities, including mortgage dollar rolls, in advance through when-issued and forward commitment transactions. It may commit up to 35% of its total assets to such transactions.', 0.0054, NULL, 8122, 14120, 35.544, 34.7, NULL, NULL, 2.04, 11.94, 22.64, 1.86, NULL, NULL, '{"Cap_Size": "Large", "Quote_Mode": "ETF", "Currency_Base": "US_DOLLAR", "GeoZone_Class": "US", "Strategy_Type": "Value"}', '{"Net_Worth": 47755920, "Yield_Rate": null, "Expense_Net": 0.0054, "Benchmark_Exp": null, "Turnover_Ratio": 0.09}', '{"volume_metrics": {"Vol_3M": 8122, "Vol_Recent": 14120}, "moving_averages": {"MA_50": 35.544, "MA_200": 34.7}}', '{"asset_allocation": {"Bond_Weight": null, "Equity_Weight": null}, "bond_characteristics": {"Avg_Maturity": null, "Duration_Yrs": null}}', '{"valuation_metrics": {"PB_Ratio": 2.04, "PE_Ratio": 22.64, "PS_Ratio": 1.86, "PCF_Ratio": 11.94}}');
INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (1822, 'TERM', 'ETF', 'USA', 'BlackRock GNMA Portfolio - Clas', 'BlackRock GNMA Portfolio Investor C Shares', 'USD', 'Value', 'Large', 'BlackRock', 'PCX', 'Large Value', 12065875, 0.0109, '2017-04-10', NULL, 'The investment seeks to maximize total return, consistent with income generation and prudent investment management. Under normal circumstances, the fund invests at least 80% of its assets in Government National Mortgage Association ("GNMA") securities. It invests primarily in securities issued by GNMA as well as other U.S. government securities. Securities purchased by the fund are rated in the highest rating category (AAA or Aaa) at the time of purchase by at least one major rating agency or are determined by the fund management team to be of similar quality.', 0.0067, 0.0034, 467, NULL, 21.995, 21.37, 0.9967, 0, 2.96, 12.41, 23.2, 1.98, NULL, NULL, '{"Cap_Size": "Large", "Quote_Mode": "ETF", "Currency_Base": "USD", "GeoZone_Class": "USA", "Strategy_Type": "Value"}', '{"Net_Worth": 12065875, "Yield_Rate": 0.0109, "Expense_Net": 0.0067, "Benchmark_Exp": 0.0034, "Turnover_Ratio": null}', '{"volume_metrics": {"Vol_3M": 467, "Vol_Recent": null}, "moving_averages": {"MA_50": 21.995, "MA_200": 21.37}}', '{"asset_allocation": {"Bond_Weight": 0, "Equity_Weight": 0.9967}, "bond_characteristics": {"Avg_Maturity": null, "Duration_Yrs": null}}', '{"valuation_metrics": {"PB_Ratio": 2.96, "PE_Ratio": 23.2, "PS_Ratio": 1.98, "PCF_Ratio": 12.41}}');
INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (1823, 'TFI', 'ETF', 'us', 'Baillie Gifford Developed EAFE ', 'Baillie Gifford Developed EAFE All Cap Fund Class 3', 'Dollar', NULL, NULL, 'Baillie Gifford Funds', 'PCX', 'Muni National Long', 3716455680, 0.0185, '2007-09-11', 0.15, 'The investment seeks capital appreciation. The fund invests at least 80% of its net assets (plus any borrowings for investment purposes) in common stocks and other equity securities of companies whose principal activities are in developed markets in Europe, Australasia and/or the Far East. It may invest in equity securities either directly or indirectly, such as through depositary receipts, and may invest in preferred stocks, convertible securities and warrants. The fund is not constrained with respect to market capitalization and may participate in initial public offerings and in securities offerings that are not registered in the U.S.', 0.0023, 0.0026, 668628, 582720, 51.525, 51.888, 0, 0.9963, NULL, NULL, NULL, NULL, 7.98, 6.2, '{"Cap_Size": null, "Quote_Mode": "ETF", "Currency_Base": "Dollar", "GeoZone_Class": "us", "Strategy_Type": null}', '{"Net_Worth": 3716455680, "Yield_Rate": 0.0185, "Expense_Net": 0.0023, "Benchmark_Exp": 0.0026, "Turnover_Ratio": 0.15}', '{"volume_metrics": {"Vol_3M": 668628, "Vol_Recent": 582720}, "moving_averages": {"MA_50": 51.525, "MA_200": 51.888}}', '{"asset_allocation": {"Bond_Weight": 0.9963, "Equity_Weight": 0}, "bond_characteristics": {"Avg_Maturity": 7.98, "Duration_Yrs": 6.2}}', '{"valuation_metrics": {"PB_Ratio": null, "PE_Ratio": null, "PS_Ratio": null, "PCF_Ratio": null}}');
