INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (1834, 'TIPZ', 'ETF', 'United States', 'Barrett Growth Fund', 'Barrett Growth Fund', 'Dollar', NULL, NULL, 'Barrett', 'PCX', 'Inflation-Protected Bond', 176260560, 0.0211, '2009-09-03', 0.1, 'The investment seeks to achieve long-term capital appreciation and to maximize after-tax returns. The fund invests primarily in a diversified portfolio of common stocks of large- and mid-cap U.S. companies, as well as global companies traded on a U.S. exchange, selected by the Adviser. It invests in common stocks of high-quality companies that Barrett believes have superior growth potential and stocks that can be purchased at reasonable prices. The fund may invest up to 25% of its net assets in foreign securities, and will normally make such investments through the purchase of American Depositary Receipts ("ADRs").', 0.002, 0.0016, 25312, 30040, 66.326, 65.655, 0, 0.9957, NULL, NULL, NULL, NULL, 8.83, 8.24, '{"Cap_Size": null, "Quote_Mode": "ETF", "Currency_Base": "Dollar", "GeoZone_Class": "United States", "Strategy_Type": null}', '{"Net_Worth": 176260560, "Yield_Rate": 0.0211, "Expense_Net": 0.002, "Benchmark_Exp": 0.0016, "Turnover_Ratio": 0.1}', '{"volume_metrics": {"Vol_3M": 25312, "Vol_Recent": 30040}, "moving_averages": {"MA_50": 66.326, "MA_200": 65.655}}', '{"asset_allocation": {"Bond_Weight": 0.9957, "Equity_Weight": 0}, "bond_characteristics": {"Avg_Maturity": 8.83, "Duration_Yrs": 8.24}}', '{"valuation_metrics": {"PB_Ratio": null, "PE_Ratio": null, "PS_Ratio": null, "PCF_Ratio": null}}');
