INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (1844, 'TOKE', 'ETF', 'US', 'Sterling Capital Intermediate ', 'Sterling Capital Intermediate U.S. Government Fund Class A', 'Usd', 'Blend', 'Small', 'Sterling Capital Funds', 'BTS', 'Miscellaneous Sector', 37123164, 0.0325, '2019-07-25', NULL, 'The investment seeks current income consistent with the preservation of capital. The fund normally invests at least 80% of its net assets plus borrowings for investment purposes in bonds issued or guaranteed by the U.S. government or its agencies and instrumentalities ("U.S. government securities"). It invests, under normal market conditions, in U.S. government securities, some of which may be subject to repurchase agreements, or in "high grade" mortgage-backed securities, including collateralized mortgage obligations. The fund will maintain an average duration between 2.5 and 7 years.', 0.0042, 0.0067, 16527, 16860, 13.794, 16.876, NULL, NULL, 2.71, NULL, NULL, 2.34, NULL, NULL, '{"Cap_Size": "Small", "Quote_Mode": "ETF", "Currency_Base": "Usd", "GeoZone_Class": "US", "Strategy_Type": "Blend"}', '{"Net_Worth": 37123164, "Yield_Rate": 0.0325, "Expense_Net": 0.0042, "Benchmark_Exp": 0.0067, "Turnover_Ratio": null}', '{"volume_metrics": {"Vol_3M": 16527, "Vol_Recent": 16860}, "moving_averages": {"MA_50": 13.794, "MA_200": 16.876}}', '{"asset_allocation": {"Bond_Weight": null, "Equity_Weight": null}, "bond_characteristics": {"Avg_Maturity": null, "Duration_Yrs": null}}', '{"valuation_metrics": {"PB_Ratio": 2.71, "PE_Ratio": null, "PS_Ratio": 2.34, "PCF_Ratio": null}}');
INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (1845, 'TOLZ', 'ETF', 'America', 'Baron Health Care Fund R6 Share', 'Baron Health Care Fund R6 Shares', 'AmericanDollar', 'Value', 'Large', 'Baron Capital Group, Inc.', 'PCX', 'Infrastructure', 122921752, 0.0347, '2014-03-25', NULL, 'The investment seeks capital appreciation. Under normal circumstances, the fund invests at least 80% of its net assets in equity securities in the form of common stock of companies engaged in the research, development, production, sale, delivery or distribution of products and services related to the health care industry. The Adviser uses various criteria to determine whether an issuer is engaged in activities related to the health care industry. It is non-diversified.', 0.0047, 0.0045, 17727, 22270, 46.505, 45.861, NULL, NULL, 2.32, 10.59, 22.93, 2.71, NULL, NULL, '{"Cap_Size": "Large", "Quote_Mode": "ETF", "Currency_Base": "AmericanDollar", "GeoZone_Class": "America", "Strategy_Type": "Value"}', '{"Net_Worth": 122921752, "Yield_Rate": 0.0347, "Expense_Net": 0.0047, "Benchmark_Exp": 0.0045, "Turnover_Ratio": null}', '{"volume_metrics": {"Vol_3M": 17727, "Vol_Recent": 22270}, "moving_averages": {"MA_50": 46.505, "MA_200": 45.861}}', '{"asset_allocation": {"Bond_Weight": null, "Equity_Weight": null}, "bond_characteristics": {"Avg_Maturity": null, "Duration_Yrs": null}}', '{"valuation_metrics": {"PB_Ratio": 2.32, "PE_Ratio": 22.93, "PS_Ratio": 2.71, "PCF_Ratio": 10.59}}');
INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (1846, 'TOTL', 'ETF', 'us', 'BlackRock High Equity Income Fu', 'BlackRock High Equity Income Fund Class K', 'usd', NULL, NULL, 'BlackRock', 'PCX', NULL, 3188717824, 0.0275, '2015-02-23', 0.25, 'The investment seeks high current income while maintaining prospects for capital appreciation. The fund will invest at least 80% of its net assets, plus the amount of any borrowings for investment purposes, in equity securities and equity-related instruments, including equity-linked notes. It may invest in securities of companies with any market capitalization, but will generally focus on large cap securities. The fund may invest up to 50% of its assets in equity-linked notes that provide exposure to equity securities and covered call options or other types of financial instruments.', 0.0055, NULL, 256833, 287540, 47.877, 48.281, NULL, NULL, NULL, NULL, NULL, NULL, 5.94, 4.32, '{"Cap_Size": null, "Quote_Mode": "ETF", "Currency_Base": "usd", "GeoZone_Class": "us", "Strategy_Type": null}', '{"Net_Worth": 3188717824, "Yield_Rate": 0.0275, "Expense_Net": 0.0055, "Benchmark_Exp": null, "Turnover_Ratio": 0.25}', '{"volume_metrics": {"Vol_3M": 256833, "Vol_Recent": 287540}, "moving_averages": {"MA_50": 47.877, "MA_200": 48.281}}', '{"asset_allocation": {"Bond_Weight": null, "Equity_Weight": null}, "bond_characteristics": {"Avg_Maturity": 5.94, "Duration_Yrs": 4.32}}', '{"valuation_metrics": {"PB_Ratio": null, "PE_Ratio": null, "PS_Ratio": null, "PCF_Ratio": null}}');
INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (1847, 'TPAY', 'ETF', 'America', 'Soundwatch Hedged Equity Fund -', 'Soundwatch Hedged Equity Fund Institutional Class', 'usd', 'Growth', 'Large', 'Soundwatch Capital', 'PCX', 'Technology', 13990530, 0.0022, '2019-01-31', NULL, 'The investment seeks to provide long-term capital appreciation. The fund invests at least 80% of its net assets, plus any borrowings for investment purposes, in a portfolio of equity securities and investments that have economic characteristics similar to equity securities. These equity securities and investments may include U.S. exchange-listed common stocks, equity index futures, and/or exchange-traded funds ("ETFs") that track the S&P 500 Index. For purposes of this 80% investment policy, the Adviser will consider the underlying holdings of any ETFs in which the fund invests.', 0.004, 0.0053, 1662, 2470, 43.548, 45.371, 0.9983, 0, 4.99, 24.83, 36.14, 5.72, NULL, NULL, '{"Cap_Size": "Large", "Quote_Mode": "ETF", "Currency_Base": "usd", "GeoZone_Class": "America", "Strategy_Type": "Growth"}', '{"Net_Worth": 13990530, "Yield_Rate": 0.0022, "Expense_Net": 0.004, "Benchmark_Exp": 0.0053, "Turnover_Ratio": null}', '{"volume_metrics": {"Vol_3M": 1662, "Vol_Recent": 2470}, "moving_averages": {"MA_50": 43.548, "MA_200": 45.371}}', '{"asset_allocation": {"Bond_Weight": 0, "Equity_Weight": 0.9983}, "bond_characteristics": {"Avg_Maturity": null, "Duration_Yrs": null}}', '{"valuation_metrics": {"PB_Ratio": 4.99, "PE_Ratio": 36.14, "PS_Ratio": 5.72, "PCF_Ratio": 24.83}}');
INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (1848, 'TPHD', 'ETF', 'United States', 'Bishop Street Hawaii Municipal ', 'Bishop Street Hawaii Municipal Bond Fund Class A', 'DOLLAR', 'Value', 'Medium', 'Bishop Street', 'PCX', 'Mid-Cap Value', 138675920, 0.0204, '2019-04-30', NULL, 'The investment seeks to provide high current income exempt from federal and Hawaii state income taxes. The fund invests at least 80% of its net assets (plus any borrowings for investment purposes) in investment grade municipal bonds, the interest from which is exempt from regular federal and Hawaii state income taxes. It may also invest in municipal bonds issued by other U.S. states, territories and possessions. There is no limit on the average maturity of the fund''s portfolio. The fund is non-diversified.', 0.0052, 0.0043, 22685, 8480, 30.725, 30.038, 0.9989, 0, 3.02, 12.98, 19.27, 1.69, NULL, NULL, '{"Cap_Size": "Medium", "Quote_Mode": "ETF", "Currency_Base": "DOLLAR", "GeoZone_Class": "United States", "Strategy_Type": "Value"}', '{"Net_Worth": 138675920, "Yield_Rate": 0.0204, "Expense_Net": 0.0052, "Benchmark_Exp": 0.0043, "Turnover_Ratio": null}', '{"volume_metrics": {"Vol_3M": 22685, "Vol_Recent": 8480}, "moving_averages": {"MA_50": 30.725, "MA_200": 30.038}}', '{"asset_allocation": {"Bond_Weight": 0, "Equity_Weight": 0.9989}, "bond_characteristics": {"Avg_Maturity": null, "Duration_Yrs": null}}', '{"valuation_metrics": {"PB_Ratio": 3.02, "PE_Ratio": 19.27, "PS_Ratio": 1.69, "PCF_Ratio": 12.98}}');
INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (1849, 'TPIF', 'ETF', 'America', 'BlackRock Health Sciences Oppor', 'BlackRock Health Sciences Opportunities Portfolio Class R', 'US$', 'Blend', 'Large', 'BlackRock', 'PCX', 'Foreign Large Blend', 88259024, 0.0225, '2019-12-02', 0.63, 'The investment seeks to provide long-term growth of capital. The fund invests at least 80% of its total assets in equity securities, primarily common stock, of companies in health sciences and related industries. The health sciences sector can include companies in health care equipment and supplies, health care providers and services, biotechnology, and pharmaceuticals. It will concentrate its investments (i.e., invest more than 25% of its assets) in health sciences or related industries, and may invest in companies located in non-U.S. countries.', 0.0062, 0.0037, 10716, 6060, 28.888, 28.969, 0.9963, 0, 1.77, 11.35, 19.23, 1.37, NULL, NULL, '{"Cap_Size": "Large", "Quote_Mode": "ETF", "Currency_Base": "US$", "GeoZone_Class": "America", "Strategy_Type": "Blend"}', '{"Net_Worth": 88259024, "Yield_Rate": 0.0225, "Expense_Net": 0.0062, "Benchmark_Exp": 0.0037, "Turnover_Ratio": 0.63}', '{"volume_metrics": {"Vol_3M": 10716, "Vol_Recent": 6060}, "moving_averages": {"MA_50": 28.888, "MA_200": 28.969}}', '{"asset_allocation": {"Bond_Weight": 0, "Equity_Weight": 0.9963}, "bond_characteristics": {"Avg_Maturity": null, "Duration_Yrs": null}}', '{"valuation_metrics": {"PB_Ratio": 1.77, "PE_Ratio": 19.23, "PS_Ratio": 1.37, "PCF_Ratio": 11.35}}');
