INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (1865, 'TUSA', 'ETF', 'US', 'Brown Advisory Global Leaders F', 'Brown Advisory Global Leaders Fund Investor Shares', 'DOLLAR', 'Value', 'Medium', 'Brown Advisory Funds', 'NGM', 'Mid-Cap Blend', 21593100, 0.0076, '2006-12-05', NULL, 'The investment seeks to achieve long-term capital appreciation by investing primarily in global equities. The fund aims to achieve its investment objective by investing at least 80% of the value of its net assets (plus any borrowings for investment purposes) in equity securities. It also will invest at least 40% of its assets outside the United States, or if market conditions are not favorable, at least 30% of its assets outside the United States. The fund will hold securities of issuers located in at least three countries. Its non-U.S. investments may include equity securities issued by companies that are established or operating in emerging market countries.', 0.007, 0.0047, 975, 970, 49.674, 47.919, 0.9988, 0, 2.4, 10.81, 16.64, 1.41, NULL, NULL, '{"Cap_Size": "Medium", "Quote_Mode": "ETF", "Currency_Base": "DOLLAR", "GeoZone_Class": "US", "Strategy_Type": "Value"}', '{"Net_Worth": 21593100, "Yield_Rate": 0.0076, "Expense_Net": 0.007, "Benchmark_Exp": 0.0047, "Turnover_Ratio": null}', '{"volume_metrics": {"Vol_3M": 975, "Vol_Recent": 970}, "moving_averages": {"MA_50": 49.674, "MA_200": 47.919}}', '{"asset_allocation": {"Bond_Weight": 0, "Equity_Weight": 0.9988}, "bond_characteristics": {"Avg_Maturity": null, "Duration_Yrs": null}}', '{"valuation_metrics": {"PB_Ratio": 2.4, "PE_Ratio": 16.64, "PS_Ratio": 1.41, "PCF_Ratio": 10.81}}');
INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (1866, 'TWIO', 'ETF', 'US', 'Brown Advisory Maryland Bond Fd', 'Brown Advisory Maryland Bond Fund Investor Shares', 'usd', 'Value', 'Medium', 'Brown Advisory Funds', 'PCX', NULL, 8844948, NULL, '2021-03-31', NULL, 'The investment seeks to provide a high level of current income exempt from both Federal and Maryland State income taxes without undue risk. The fund normally invests at least 80% of the value of its net assets (plus any borrowings for investment purposes) in Maryland bonds, including bonds issued on behalf of the State of Maryland, its local governments and public financing authorities. It may also invest in municipal securities issued by other states, U.S. territories, and possessions, U.S. government securities, general obligation securities and revenue securities, including private activity bonds. The fund is non-diversified.', 0.0085, NULL, 19074, 2370, 10.375, 10.313, NULL, NULL, 1.69, 10.09, 17.29, 1.29, NULL, NULL, '{"Cap_Size": "Medium", "Quote_Mode": "ETF", "Currency_Base": "usd", "GeoZone_Class": "US", "Strategy_Type": "Value"}', '{"Net_Worth": 8844948, "Yield_Rate": null, "Expense_Net": 0.0085, "Benchmark_Exp": null, "Turnover_Ratio": null}', '{"volume_metrics": {"Vol_3M": 19074, "Vol_Recent": 2370}, "moving_averages": {"MA_50": 10.375, "MA_200": 10.313}}', '{"asset_allocation": {"Bond_Weight": null, "Equity_Weight": null}, "bond_characteristics": {"Avg_Maturity": null, "Duration_Yrs": null}}', '{"valuation_metrics": {"PB_Ratio": 1.69, "PE_Ratio": 17.29, "PS_Ratio": 1.29, "PCF_Ratio": 10.09}}');
INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (1867, 'TWM', 'ETF', 'USA', 'BlackRock 80/20 Target Allocati', 'BlackRock 80/20 Target Allocation Fund Class Institutional', 'US_DOLLAR', NULL, NULL, 'BlackRock', 'PCX', 'Trading--Inverse Equity', 73111840, NULL, '2007-01-23', NULL, 'The investment seeks long term capital appreciation. The fund, which is a fund of funds, normally obtains exposure to equity securities in an amount equal to 80% of its assets and exposure to fixed-income securities in an amount equal to 20% of its assets. Under normal circumstances, the advisor intends to invest primarily in affiliated open-end funds and affiliated ETFs. The fund may, when consistent with its investment objective, buy or sell options or futures, or enter into total return swaps and foreign currency transactions (collectively, commonly known as derivatives).', 0.0095, 0.0092, 1989317, 3.0428e+06, 12.838, 13.847, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '{"Cap_Size": null, "Quote_Mode": "ETF", "Currency_Base": "US_DOLLAR", "GeoZone_Class": "USA", "Strategy_Type": null}', '{"Net_Worth": 73111840, "Yield_Rate": null, "Expense_Net": 0.0095, "Benchmark_Exp": 0.0092, "Turnover_Ratio": null}', '{"volume_metrics": {"Vol_3M": 1989317, "Vol_Recent": 3042800}, "moving_averages": {"MA_50": 12.838, "MA_200": 13.847}}', '{"asset_allocation": {"Bond_Weight": null, "Equity_Weight": null}, "bond_characteristics": {"Avg_Maturity": null, "Duration_Yrs": null}}', '{"valuation_metrics": {"PB_Ratio": null, "PE_Ratio": null, "PS_Ratio": null, "PCF_Ratio": null}}');
INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (1868, 'TYD', 'ETF', 'U.S.A.', 'Brown Advisory Emerging Markets', 'Brown Advisory Emerging Markets Select Fund Investor Shares', 'usd', NULL, NULL, 'Brown Advisory Funds', 'PCX', 'Trading--Leveraged Debt', 18540378, 0.1083, '2009-04-16', 0.76, 'The investment seeks total return by investing principally in equity securities issued by companies established or operating in emerging markets. The fund invests at least 80% of the value of its net assets (plus any borrowings for investment purposes) in equity securities issued by companies that are established or operating in emerging market countries. These will consist of companies in emerging market countries in Latin America, Asia, Eastern Europe, Africa, and the Middle East. It may invest up to 20% of its net assets in securities of companies that are established or operating in countries that are considered to be outside of emerging markets.', 0.0109, 0.0095, 15238, 18950, 52.142, 52.773, NULL, NULL, NULL, NULL, NULL, NULL, 8.48, 7.86, '{"Cap_Size": null, "Quote_Mode": "ETF", "Currency_Base": "usd", "GeoZone_Class": "U.S.A.", "Strategy_Type": null}', '{"Net_Worth": 18540378, "Yield_Rate": 0.1083, "Expense_Net": 0.0109, "Benchmark_Exp": 0.0095, "Turnover_Ratio": 0.76}', '{"volume_metrics": {"Vol_3M": 15238, "Vol_Recent": 18950}, "moving_averages": {"MA_50": 52.142, "MA_200": 52.773}}', '{"asset_allocation": {"Bond_Weight": null, "Equity_Weight": null}, "bond_characteristics": {"Avg_Maturity": 8.48, "Duration_Yrs": 7.86}}', '{"valuation_metrics": {"PB_Ratio": null, "PE_Ratio": null, "PS_Ratio": null, "PCF_Ratio": null}}');
INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (1869, 'TYO', 'ETF', 'US', 'Brown Advisory Small-Cap Growth', 'Brown Advisory Small-Cap Growth Fund Investor Shares', 'Usd', NULL, NULL, 'Brown Advisory Funds', 'PCX', 'Trading--Inverse Debt', 20911228, NULL, '2009-04-16', NULL, 'The investment seeks to achieve long-term capital appreciation by primarily investing in equity securities. Under normal conditions, the Adviser seeks to achieve the fund''s investment objective by investing at least 80% of the value of its net assets (plus any borrowings for investment purposes) in equity securities of small domestic companies. The fund invests primarily in companies the Adviser believes have above average growth prospects. Equity securities include domestic common and preferred stock, convertible debt securities, American Depositary Receipts ("ADRs"), real estate investment trusts ("REITs") and exchange traded funds ("ETFs").', 0.0107, 0.0088, 91638, 170010, 8.665, 8.742, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '{"Cap_Size": null, "Quote_Mode": "ETF", "Currency_Base": "Usd", "GeoZone_Class": "US", "Strategy_Type": null}', '{"Net_Worth": 20911228, "Yield_Rate": null, "Expense_Net": 0.0107, "Benchmark_Exp": 0.0088, "Turnover_Ratio": null}', '{"volume_metrics": {"Vol_3M": 91638, "Vol_Recent": 170010}, "moving_averages": {"MA_50": 8.665, "MA_200": 8.742}}', '{"asset_allocation": {"Bond_Weight": null, "Equity_Weight": null}, "bond_characteristics": {"Avg_Maturity": null, "Duration_Yrs": null}}', '{"valuation_metrics": {"PB_Ratio": null, "PE_Ratio": null, "PS_Ratio": null, "PCF_Ratio": null}}');
INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (1870, 'TZA', 'ETF', 'U.S.A.', 'Brown Advisory Total Return Fun', 'Brown Advisory Total Return Fund Investor Shares', 'USD', NULL, NULL, 'Brown Advisory Funds', 'PCX', 'Trading--Inverse Equity', 357509824, NULL, '2008-11-05', NULL, 'The investment seeks to provide a competitive total return consistent with preservation of principal. Normally, the Adviser seeks to achieve the fund''s investment objective by investing at least 80% of the value of its net assets in fixed income securities such as U.S. government securities, corporate fixed income securities, mortgage-backed and asset-backed securities. It invests in fixed income securities that primarily have a maturity that is between 0 and 30 years and are rated in the top four rating categories of a Nationally Recognized Statistical Rating Organization, or unrated and deemed to be of comparable quality by the Adviser.', 0.011, 0.0092, 11990739, 1.841369e+07, 27.004, 30.629, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '{"Cap_Size": null, "Quote_Mode": "ETF", "Currency_Base": "USD", "GeoZone_Class": "U.S.A.", "Strategy_Type": null}', '{"Net_Worth": 357509824, "Yield_Rate": null, "Expense_Net": 0.011, "Benchmark_Exp": 0.0092, "Turnover_Ratio": null}', '{"volume_metrics": {"Vol_3M": 11990739, "Vol_Recent": 18413690}, "moving_averages": {"MA_50": 27.004, "MA_200": 30.629}}', '{"asset_allocation": {"Bond_Weight": null, "Equity_Weight": null}, "bond_characteristics": {"Avg_Maturity": null, "Duration_Yrs": null}}', '{"valuation_metrics": {"PB_Ratio": null, "PE_Ratio": null, "PS_Ratio": null, "PCF_Ratio": null}}');
INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (1871, 'UAE', 'ETF', 'U.S.A.', 'Brown Advisory Small-Cap Fundam', 'Brown Advisory Small-Cap Fundamental Value Fund Investor Shares', 'US$', 'Value', 'Medium', 'Brown Advisory Funds', 'NGM', 'Miscellaneous Region', 20966724, 0.0367, '2014-04-29', 0.67, 'The investment seeks to achieve long-term capital appreciation. The fund normally invests at least 80% of the value of its net assets (plus borrowings for investment purposes) in equity securities of small capitalization companies. Equity securities include common stock, preferred stock, equity-equivalent securities such as convertible securities, stock futures contracts, equity options, other investment companies, ADRs, REITs and ETFs, and the Adviser may also invest in private placements in these types of securities. Small companies are companies whose market capitalizations are generally less than $6 billion at the time of purchase.', 0.0059, 0.0053, 16500, 43500, 15.418, 14.381, 0.9985, 0, 1.15, NULL, 14.62, 3.79, NULL, NULL, '{"Cap_Size": "Medium", "Quote_Mode": "ETF", "Currency_Base": "US$", "GeoZone_Class": "U.S.A.", "Strategy_Type": "Value"}', '{"Net_Worth": 20966724, "Yield_Rate": 0.0367, "Expense_Net": 0.0059, "Benchmark_Exp": 0.0053, "Turnover_Ratio": 0.67}', '{"volume_metrics": {"Vol_3M": 16500, "Vol_Recent": 43500}, "moving_averages": {"MA_50": 15.418, "MA_200": 14.381}}', '{"asset_allocation": {"Bond_Weight": 0, "Equity_Weight": 0.9985}, "bond_characteristics": {"Avg_Maturity": null, "Duration_Yrs": null}}', '{"valuation_metrics": {"PB_Ratio": 1.15, "P