INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (1893, 'UJB', 'ETF', 'U.S.', 'BlackRock GA Disciplined Volati', 'BlackRock GA Disciplined Volatility Equity Fund Institutional', 'US$', NULL, NULL, 'BlackRock', 'PCX', 'Trading--Leveraged Debt', 27205256, 0.0223, '2011-04-13', 0.12, 'The investment seeks to provide risk-adjusted total return. The fund will, under normal circumstances, invest at least 80% of its net assets (plus borrowings for investment purposes) in equity securities. It seeks to achieve its investment objective by investing in both equity and fixed-income securities, including money market securities and other short-term securities or instruments that the fund management team believes may offer attractive risk-adjusted returns. Equity securities include common stock, preferred stock, securities convertible into common stock, ADRs, or securities or other instruments whose price is linked to the value of common stock.', 0.0114, 0.0095, 22180, 29920, 77.613, 76.725, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '{"Cap_Size": null, "Quote_Mode": "ETF", "Currency_Base": "US$", "GeoZone_Class": "U.S.", "Strategy_Type": null}', '{"Net_Worth": 27205256, "Yield_Rate": 0.0223, "Expense_Net": 0.0114, "Benchmark_Exp": 0.0095, "Turnover_Ratio": 0.12}', '{"volume_metrics": {"Vol_3M": 22180, "Vol_Recent": 29920}, "moving_averages": {"MA_50": 77.613, "MA_200": 76.725}}', '{"asset_allocation": {"Bond_Weight": null, "Equity_Weight": null}, "bond_characteristics": {"Avg_Maturity": null, "Duration_Yrs": null}}', '{"valuation_metrics": {"PB_Ratio": null, "PE_Ratio": null, "PS_Ratio": null, "PCF_Ratio": null}}');
