INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (1903, 'UNOV', 'ETF', 'us', 'BlackRock U.S. Government Bond ', 'BlackRock U.S. Government Bond Portfolio Investor C Shares', 'DOLLAR', 'Blend', 'Large', 'BlackRock', 'BTS', NULL, 12392670, NULL, '2019-10-31', NULL, 'The investment seeks to maximize total return, consistent with income generation and prudent investment management. Under normal circumstances, the fund invests at least 80% of its assets in bonds that are issued or guaranteed by the U.S. government and its agencies. It invests primarily in the highest rated government and agency bonds and maintains an average portfolio duration that is within Â±20% of the Bloomberg Barclays U.S. government/Mortgage Index. The fund may also invest up to 5% of its assets in dollar-denominated investment grade securities that are rated below the highest rating category at the time of purchase.', 0.0079, NULL, 19362, 16500, 29.311, 29.063, 0.9999, 0, 4.42, 17.56, 26.46, 2.96, NULL, NULL, '{"Cap_Size": "Large", "Quote_Mode": "ETF", "Currency_Base": "DOLLAR", "GeoZone_Class": "us", "Strategy_Type": "Blend"}', '{"Net_Worth": 12392670, "Yield_Rate": null, "Expense_Net": 0.0079, "Benchmark_Exp": null, "Turnover_Ratio": null}', '{"volume_metrics": {"Vol_3M": 19362, "Vol_Recent": 16500}, "moving_averages": {"MA_50": 29.311, "MA_200": 29.063}}', '{"asset_allocation": {"Bond_Weight": 0, "Equity_Weight": 0.9999}, "bond_characteristics": {"Avg_Maturity": null, "Duration_Yrs": null}}', '{"valuation_metrics": {"PB_Ratio": 4.42, "PE_Ratio": 26.46, "PS_Ratio": 2.96, "PCF_Ratio": 17.56}}');
INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (1904, 'UOCT', 'ETF', 'U.S.A.', 'Baron International Growth Fund', 'Baron International Growth Fund Retail Shares', 'usd', 'Blend', 'Large', 'Baron Capital Group, Inc.', 'BTS', NULL, 65884692, NULL, '2018-09-28', NULL, 'The investment seeks capital appreciation. The fund is a diversified fund that invests for the long term primarily in equity securities in the form of common stock of non-U.S. growth companies. It seeks to diversify its investments among several developed countries and developing countries throughout the world, although the fund may only invest up to 35% of its net assets in developing countries. Developing countries include countries in the MSCI Emerging Markets (EM) Index, countries in the MSCI Frontier Markets (FM) Index and other countries determined by the Adviser to be developing countries based on classifications.', 0.008, NULL, 15395, 3320, 28.187, 27.698, 1, 0, 4.42, 17.56, 26.46, 2.96, NULL, NULL, '{"Cap_Size": "Large", "Quote_Mode": "ETF", "Currency_Base": "usd", "GeoZone_Class": "U.S.A.", "Strategy_Type": "Blend"}', '{"Net_Worth": 65884692, "Yield_Rate": null, "Expense_Net": 0.008, "Benchmark_Exp": null, "Turnover_Ratio": null}', '{"volume_metrics": {"Vol_3M": 15395, "Vol_Recent": 3320}, "moving_averages": {"MA_50": 28.187, "MA_200": 27.698}}', '{"asset_allocation": {"Bond_Weight": 0, "Equity_Weight": 1}, "bond_characteristics": {"Avg_Maturity": null, "Duration_Yrs": null}}', '{"valuation_metrics": {"PB_Ratio": 4.42, "PE_Ratio": 26.46, "PS_Ratio": 2.96, "PCF_Ratio": 17.56}}');
INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (1905, 'UPRO', 'ETF', 'us', 'Wm. Blair Funds International G', 'William Blair International Growth Fund Class I', 'usd', 'Blend', 'Large', 'William Blair', 'PCX', 'Trading--Leveraged Equity', 2496717824, 0.0005, '2009-06-23', 0.69, 'The investment seeks long-term capital appreciation. The fund normally invests at least 80% of its total assets in a diversified portfolio of equity securities, including common stocks and other forms of equity investments, issued by companies of all sizes domiciled outside the U.S. that the advisor believes have above-average growth, profitability and quality characteristics. Its investments are normally allocated among at least six different countries and no more than 50% of the fund''s equity holdings may be invested in securities of issuers in one country at any given time.', 0.0093, 0.009, 5753752, 7.66603e+06, 133.671, 114.978, NULL, NULL, NULL, NULL, NULL, 2.95, NULL, NULL, '{"Cap_Size": "Large", "Quote_Mode": "ETF", "Currency_Base": "usd", "GeoZone_Class": "us", "Strategy_Type": "Blend"}', '{"Net_Worth": 2496717824, "Yield_Rate": 0.0005, "Expense_Net": 0.0093, "Benchmark_Exp": 0.009, "Turnover_Ratio": 0.69}', '{"volume_metrics": {"Vol_3M": 5753752, "Vol_Recent": 7666030}, "moving_averages": {"MA_50": 133.671, "MA_200": 114.978}}', '{"asset_allocation": {"Bond_Weight": null, "Equity_Weight": null}, "bond_characteristics": {"Avg_Maturity": null, "Duration_Yrs": null}}', '{"valuation_metrics": {"PB_Ratio": null, "PE_Ratio": null, "PS_Ratio": 2.95, "PCF_Ratio": null}}');
