INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (1921, 'USLB', 'ETF', 'US', 'Baird Intermediate Bond Fd Inst', 'Baird Intermediate Bond Fund Class Institutional', 'US$', 'Blend', 'Medium', 'Baird', 'NGM', 'Mid-Cap Blend', 9819092, 0.0171, '2015-11-05', 0.33, 'The investment seeks an annual rate of total return, before fund expenses, greater than the annual rate of total return of the Bloomberg Barclays Intermediate U.S. Government/Credit Bond Index. The fund normally invests at least 80% of its net assets in the following types of U.S. dollar-denominated debt obligations: U.S. government and other public-sector agencies, asset-backed and mortgage-backed obligations of U.S. and foreign issuers and corporate debt of U.S. and foreign issuers.', 0.0035, 0.0047, 198, NULL, 40.741, 39.286, 1, 0, 3.72, 16.14, 24.17, 2.28, NULL, NULL, '{"Cap_Size": "Medium", "Quote_Mode": "ETF", "Currency_Base": "US$", "GeoZone_Class": "US", "Strategy_Type": "Blend"}', '{"Net_Worth": 9819092, "Yield_Rate": 0.0171, "Expense_Net": 0.0035, "Benchmark_Exp": 0.0047, "Turnover_Ratio": 0.33}', '{"volume_metrics": {"Vol_3M": 198, "Vol_Recent": null}, "moving_averages": {"MA_50": 40.741, "MA_200": 39.286}}', '{"asset_allocation": {"Bond_Weight": 0, "Equity_Weight": 1}, "bond_characteristics": {"Avg_Maturity": null, "Duration_Yrs": null}}', '{"valuation_metrics": {"PB_Ratio": 3.72, "PE_Ratio": 24.17, "PS_Ratio": 2.28, "PCF_Ratio": 16.14}}');
INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (1922, 'USMC', 'ETF', 'U.S.', 'BlackRock 40/60 Target Allocati', 'BlackRock 40/60 Target Allocation Fund Institutional', 'US_DOLLAR', 'Blend', 'Large', 'BlackRock', 'NGM', 'Large Blend', 1956080384, 0.014, '2017-10-11', 0.429, 'The investment seeks a balance between long term capital appreciation and high current income, with an emphasis on income. The fund, which is a fund of funds, normally obtains exposure to equity securities in an amount equal to 40% of its assets and exposure to fixed-income securities in an amount equal to 60% of its assets. Normally, the advisor intends to invest primarily in affiliated open-end funds and affiliated ETFs. The fund may, when consistent with its investment objective, buy or sell options or futures, or enter into total return swaps and foreign currency transactions (collectively, commonly known as derivatives).', 0.0012, 0.0036, 128219, 516970, 42.12, 39.846, 0.9979, 0, 4.7, 16.93, 25.7, 3.55, NULL, NULL, '{"Cap_Size": "Large", "Quote_Mode": "ETF", "Currency_Base": "US_DOLLAR", "GeoZone_Class": "U.S.", "Strategy_Type": "Blend"}', '{"Net_Worth": 1956080384, "Yield_Rate": 0.014, "Expense_Net": 0.0012, "Benchmark_Exp": 0.0036, "Turnover_Ratio": 0.429}', '{"volume_metrics": {"Vol_3M": 128219, "Vol_Recent": 516970}, "moving_averages": {"MA_50": 42.12, "MA_200": 39.846}}', '{"asset_allocation": {"Bond_Weight": 0, "Equity_Weight": 0.9979}, "bond_characteristics": {"Avg_Maturity": null, "Duration_Yrs": null}}', '{"valuation_metrics": {"PB_Ratio": 4.7, "PE_Ratio": 25.7, "PS_Ratio": 3.55, "PCF_Ratio": 16.93}}');
INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (1923, 'USMF', 'ETF', 'us', 'Baird Intermediate Bond Fd Inve', 'Baird Intermediate Bond Fund Class Investor', 'US_DOLLAR', 'Value', 'Medium', 'Baird', 'BTS', 'Mid-Cap Blend', 138485792, 0.0107, '2017-06-29', 1.47, 'The investment seeks an annual rate of total return, before fund expenses, greater than the annual rate of total return of the Bloomberg Barclays Intermediate U.S. Government/Credit Bond Index. The fund normally invests at least 80% of its net assets in the following types of U.S. dollar-denominated debt obligations: U.S. government and other public-sector agencies, asset-backed and mortgage-backed obligations of U.S. and foreign issuers and corporate debt of U.S. and foreign issuers.', 0.0028, 0.0047, 8553, 5760, 40.379, 39.439, 1, 0, 3.1, 10.25, 17.83, 1.42, NULL, NULL, '{"Cap_Size": "Medium", "Quote_Mode": "ETF", "Currency_Base": "US_DOLLAR", "GeoZone_Class": "us", "Strategy_Type": "Value"}', '{"Net_Worth": 138485792, "Yield_Rate": 0.0107, "Expense_Net": 0.0028, "Benchmark_Exp": 0.0047, "Turnover_Ratio": 1.47}', '{"volume_metrics": {"Vol_3M": 8553, "Vol_Recent": 5760}, "moving_averages": {"MA_50": 40.379, "MA_200": 39.439}}', '{"asset_allocation": {"Bond_Weight": 0, "Equity_Weight": 1}, "bond_characteristics": {"Avg_Maturity": null, "Duration_Yrs": null}}', '{"valuation_metrics": {"PB_Ratio": 3.1, "PE_Ratio": 17.83, "PS_Ratio": 1.42, "PCF_Ratio": 10.25}}');
INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (1924, 'USML', 'ETF', 'US', 'iShares Edge MSCI Min Vol USA I', 'iShares Edge MSCI Min Vol USA Index Fund Institutional Shares', 'Dollar', NULL, NULL, 'BlackRock', 'PCX', 'Trading--Leveraged Equity', 29944900, NULL, '2021-02-04', NULL, 'The investment seeks to track the investment results of the MSCI USA Minimum Volatility (USD) Index composed of U.S. equities that, in the aggregate, have lower volatility characteristics relative to the broader U.S. equity market. The fund generally invests at least 80% of its assets, plus the amount of any borrowing for investment purposes, in securities of the underlying index. The index measures the performance of equity securities that are in the top 85% by market capitalization of equity securities primarily traded on stock exchanges in the United States and that, in the aggregate, have lower volatility relative to the broader U.S. equity market.', 0.0095, 0.009, 277, 80, 32.245, 30.084, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '{"Cap_Size": null, "Quote_Mode": "ETF", "Currency_Base": "Dollar", "GeoZone_Class": "US", "Strategy_Type": null}', '{"Net_Worth": 29944900, "Yield_Rate": null, "Expense_Net": 0.0095, "Benchmark_Exp": 0.009, "Turnover_Ratio": null}', '{"volume_metrics": {"Vol_3M": 277, "Vol_Recent": 80}, "moving_averages": {"MA_50": 32.245, "MA_200": 30.084}}', '{"asset_allocation": {"Bond_Weight": null, "Equity_Weight": null}, "bond_characteristics": {"Avg_Maturity": null, "Duration_Yrs": null}}', '{"valuation_metrics": {"PB_Ratio": null, "PE_Ratio": null, "PS_Ratio": null, "PCF_Ratio": null}}');
INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (1925, 'USMV', 'ETF', 'United States', 'Brandes International Small Cap', 'Brandes International Small Cap Equity Fund Class C', 'US_DOLLAR', 'Blend', 'Large', 'Brandes', 'BTS', 'Large Blend', 27596214272, 0.015, '2011-10-18', 0.22, 'The investment seeks long term capital appreciation. The fund invests at least 80% of its net assets measured at the time of purchase in equity securities of small market capitalization companies located in at least three countries outside the United States. The fund manager considers a company to be a small capitalization company if it has a market capitalization of $5 billion or less at the time of purchase. The fund may invest up to 30% of its total assets, measured at the time of purchase, in securities of companies located in emerging markets (including frontier markets).', 0.0015, 0.0036, 4092950, 4.61575e+06, 76.456, 73.858, 0.9937, 0, 4.9, 16.74, 27.28, 2.76, NULL, NULL, '{"Cap_Size": "Large", "Quote_Mode": "ETF", "Currency_Base": "US_DOLLAR", "GeoZone_Class": "United States", "Strategy_Type": "Blend"}', '{"Net_Worth": 27596214272, "Yield_Rate": 0.015, "Expense_Net": 0.0015, "Benchmark_Exp": 0.0036, "Turnover_Ratio": 0.22}', '{"volume_metrics": {"Vol_3M": 4092950, "Vol_Recent": 4615750}, "moving_averages": {"MA_50": 76.456, "MA_200": 73.858}}', '{"asset_allocation": {"Bond_Weight": 0, "Equity_Weight": 0.9937}, "bond_characteristics": {"Avg_Maturity": null, "Duration_Yrs": null}}', '{"valuation_metrics": {"PB_Ratio": 4.9, "PE_Ratio": 27.28, "PS_Ratio": 2.76, "PCF_Ratio": 16.74}}');
INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (1926, 'USOI', 'ETF', 'U.S.A.', 'Baron International Growth Fund', 'Baron International Growth Fund Institutional Shares', 'USD', NULL, NULL, 'Baron Capital Group, Inc.', 'NGM', NULL, 130716208, 0.2127, '2017-04-25', NULL, 'The investment seeks capital appreciation. The fund is a diversified fund that invests for the long term primarily in equity securities in the form of common stock of non-U.S. growth companies. It seeks to diversify its investments among several developed countries and developing countries throughout the world, although the fund may only invest up to 35% of its net assets in developing countries. Developing countries include countries in the MSCI Emerging Markets (EM) Index, countries in the MSCI Frontier Markets (FM) Index and other countries determined by the Adviser to be developing countries based on classifications.', 0.0085, NULL, 680535, 1.31546e+06, 5.436, 5.136, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '{"Cap_Size": null, "Quote_Mode": "ETF", "Currency_Base": "USD", "GeoZone_Class": "U.S.A.", "Strategy_Type": null}', '{"Net_Worth": 130716208, "Yield_Rate": 0.2127, "Expense_Net": 0.0085, "Benchmark_Exp": null, "Turnover_Ratio": null}', '{"volume_metrics": {"Vol_3M": 680535, "Vol_Recent": 1315460}, "moving_averages": {"MA_50": 5.436, "MA_200": 5.136}}', '{"asset_allocation": {"Bond_Weight": null, "Equity_Weight": null}, "bond_characteristics": {"Avg_Maturity": null, "Duration_Yrs": null}}', '{"valuation_metrics": {"PB_Ratio": null, "PE_Ratio": null, "PS_Ratio": null, "PCF_Ratio": null}}');
