INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (1979, 'VNSE', 'ETF', 'America', 'Lord Abbett Multi-Asset Balance', 'Lord Abbett Multi-Asset Balanced Opportunity Fund Class R5', 'Dollar', 'Growth', 'Large', 'Lord Abbett', 'PCX', NULL, 6649680, NULL, '2020-09-16', 0.16, 'The investment seeks current income and capital growth. The fund is a "fund-of-funds" that invests in affiliated mutual funds (the "underlying funds") managed by Lord, Abbett & Co. LLC ("Lord Abbett"). Under normal conditions, through the underlying funds, it indirectly invests in U.S. equity securities, fixed income securities and select foreign (including emerging market) securities. The fund uses a "blend" strategy to gain investment exposure to both growth and value stocks, or to stocks with characteristics of both.', 0.0085, NULL, 18679, 840, 36.392, 33.186, NULL, NULL, 5.29, 18.2, 34.16, 3.05, NULL, NULL, '{"Cap_Size": "Large", "Quote_Mode": "ETF", "Currency_Base": "Dollar", "GeoZone_Class": "America", "Strategy_Type": "Growth"}', '{"Net_Worth": 6649680, "Yield_Rate": null, "Expense_Net": 0.0085, "Benchmark_Exp": null, "Turnover_Ratio": 0.16}', '{"volume_metrics": {"Vol_3M": 18679, "Vol_Recent": 840}, "moving_averages": {"MA_50": 36.392, "MA_200": 33.186}}', '{"asset_allocation": {"Bond_Weight": null, "Equity_Weight": null}, "bond_characteristics": {"Avg_Maturity": null, "Duration_Yrs": null}}', '{"valuation_metrics": {"PB_Ratio": 5.29, "PE_Ratio": 34.16, "PS_Ratio": 3.05, "PCF_Ratio": 18.2}}');
