INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (1940, 'UYM', 'ETF', 'U.S.', 'UBS U.S. Small Cap Growth Fund ', 'UBS U.S. Small Cap Growth Fund Class P', 'usd', 'Blend', 'Large', 'UBS Asset Management', 'PCX', 'Trading--Leveraged Equity', 82747816, 0.0044, '2007-01-30', 0.06, 'The investment seeks long-term capital appreciation. Under normal circumstances, the fund invests at least 80% of its net assets (plus borrowings for investment purposes, if any) in equity securities of U.S. small capitalization companies. Small capitalization companies are those companies within the range of the largest and smallest company in the Russell 2000 Index at the time of purchase. Investments in equity securities may include, but are not limited to, common stock and preferred stock; equity securities of real estate investment trusts ("REITs"); and exchange-traded funds ("ETFs"). The fund may invest up to 20% of its net assets in foreign securities.', 0.0095, 0.009, 10650, 6300, 98.42, 95.515, NULL, NULL, NULL, NULL, NULL, 2.56, NULL, NULL, '{"Cap_Size": "Large", "Quote_Mode": "ETF", "Currency_Base": "usd", "GeoZone_Class": "U.S.", "Strategy_Type": "Blend"}', '{"Net_Worth": 82747816, "Yield_Rate": 0.0044, "Expense_Net": 0.0095, "Benchmark_Exp": 0.009, "Turnover_Ratio": 0.06}', '{"volume_metrics": {"Vol_3M": 10650, "Vol_Recent": 6300}, "moving_averages": {"MA_50": 98.42, "MA_200": 95.515}}', '{"asset_allocation": {"Bond_Weight": null, "Equity_Weight": null}, "bond_characteristics": {"Avg_Maturity": null, "Duration_Yrs": null}}', '{"valuation_metrics": {"PB_Ratio": null, "PE_Ratio": null, "PS_Ratio": 2.56, "PCF_Ratio": null}}');
INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (1941, 'VABS', 'ETF', 'U.S.', 'BMO Pyrford Intl Stock Fund Cla', 'BMO Pyrford International Stock Fund Class R6', 'AmericanDollar', NULL, NULL, 'BMO Funds', 'PCX', 'Short-Term Bond', 7488143, NULL, '2021-02-09', NULL, 'The investment seeks to provide capital appreciation. The fund invests at least 80% of its assets in equity securities of companies located in a number of countries outside the United States. It invests primarily in companies that are located in the countries included, at the time of purchase, in the MSCI EAFE Index, which includes developed countries outside of North America. Although the fund may invest in companies across all market capitalizations, it invests primarily in companies that, at the time of purchase, have a minimum market capitalization of $2 billion.', 0.0039, 0.0026, 777, 80, 24.9, 24.98, NULL, NULL, NULL, NULL, NULL, NULL, 2.27, 1.67, '{"Cap_Size": null, "Quote_Mode": "ETF", "Currency_Base": "AmericanDollar", "GeoZone_Class": "U.S.", "Strategy_Type": null}', '{"Net_Worth": 7488143, "Yield_Rate": null, "Expense_Net": 0.0039, "Benchmark_Exp": 0.0026, "Turnover_Ratio": null}', '{"volume_metrics": {"Vol_3M": 777, "Vol_Recent": 80}, "moving_averages": {"MA_50": 24.9, "MA_200": 24.98}}', '{"asset_allocation": {"Bond_Weight": null, "Equity_Weight": null}, "bond_characteristics": {"Avg_Maturity": 2.27, "Duration_Yrs": 1.67}}', '{"valuation_metrics": {"PB_Ratio": null, "PE_Ratio": null, "PS_Ratio": null, "PCF_Ratio": null}}');
INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (1942, 'VALQ', 'ETF', 'United States', 'BlackRock International Dividen', 'BlackRock International Dividend Fund Institutional Shares', 'Usd', 'Value', 'Large', 'BlackRock', 'PCX', 'Large Value', 239609744, 0.0159, '2018-01-11', 1.78, 'The investment seeks long-term total return and current income. The fund normally invests at least 80% of its net assets plus the amount of any borrowings for investment purposes in dividend-paying equity securities issued by foreign companies of any market capitalization and derivatives that have similar economic characteristics. It may invest up to 20% of its net assets in global fixed-income securities, including corporate bonds, U.S. government debt securities, non-U.S. government and supranational debt securities, asset-backed securities, mortgage-backed securities, corporate loans, emerging market debt securities and non-investment grade debt securities.', 0.0029, 0.0034, 22958, 8730, 50.693, 49.711, 0.9962, 0, 3.21, 11.07, 20.02, 1.29, NULL, NULL, '{"Cap_Size": "Large", "Quote_Mode": "ETF", "Currency_Base": "Usd", "GeoZone_Class": "United States", "Strategy_Type": "Value"}', '{"Net_Worth": 239609744, "Yield_Rate": 0.0159, "Expense_Net": 0.0029, "Benchmark_Exp": 0.0034, "Turnover_Ratio": 1.78}', '{"volume_metrics": {"Vol_3M": 22958, "Vol_Recent": 8730}, "moving_averages": {"MA_50": 50.693, "MA_200": 49.711}}', '{"asset_allocation": {"Bond_Weight": 0, "Equity_Weight": 0.9962}, "bond_characteristics": {"Avg_Maturity": null, "Duration_Yrs": null}}', '{"valuation_metrics": {"PB_Ratio": 3.21, "PE_Ratio": 20.02, "PS_Ratio": 1.29, "PCF_Ratio": 11.07}}');
