INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (1947, 'VCIT', 'ETF', 'usa', 'Brown Advisory Tax-Exempt Susta', 'Brown Advisory Tax-Exempt Sustainable Bond Fund Investor Shares', 'US$', NULL, NULL, 'Brown Advisory Funds', 'NGM', 'Corporate Bond', 48390602752, 0.0233, '2009-11-19', 0.72, 'The investment seeks to provide a high level of current income exempt from Federal income tax by investing primarily in intermediate-term investment grade municipal bonds while giving special consideration to certain environmental, social, and governance criteria. Under normal circumstances, the fund will invest at least 80% of the value of its net assets in fixed income securities the interest of which is exempt from Federal income taxes, that do not subject shareholders to the federal alternative minimum tax, and that have either a bond issuer or a use of proceeds of the bond issuance that satisfies the fund''s ESG criteria. It is non-diversified.', 0.0005, 0.0017, 3521307, 4.93928e+06, 93.794, 94.363, NULL, NULL, NULL, NULL, NULL, NULL, 7.4, 6.53, '{"Cap_Size": null, "Quote_Mode": "ETF", "Currency_Base": "US$", "GeoZone_Class": "usa", "Strategy_Type": null}', '{"Net_Worth": 48390602752, "Yield_Rate": 0.0233, "Expense_Net": 0.0005, "Benchmark_Exp": 0.0017, "Turnover_Ratio": 0.72}', '{"volume_metrics": {"Vol_3M": 3521307, "Vol_Recent": 4939280}, "moving_averages": {"MA_50": 93.794, "MA_200": 94.363}}', '{"asset_allocation": {"Bond_Weight": null, "Equity_Weight": null}, "bond_characteristics": {"Avg_Maturity": 7.4, "Duration_Yrs": 6.53}}', '{"valuation_metrics": {"PB_Ratio": null, "PE_Ratio": null, "PS_Ratio": null, "PCF_Ratio": null}}');
INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (1948, 'VCLO', 'ETF', 'U.S.', 'iShares Total U.S. Stock Market', 'iShares Total U.S. Stock Market Index Fund Institutional Shares', 'DOLLAR', 'Growth', 'Large', 'BlackRock', 'PCX', 'Technology', 5349502, NULL, '2020-12-28', NULL, 'The investment seeks to track the investment results of a broad-based index composed of U.S. equities. The fund seeks to track the investment results of the Russell 3000© Index, which measures the performance of the broad U.S. equity market. The underlying index is a float-adjusted capitalization-weighted index of the largest public issuers domiciled in the United States and its territories. The fund generally invests at least 90% of its assets, plus the amount of any borrowing for investment purposes, in securities of the underlying index.', 0.0102, 0.0053, 34461, 39650, 17.822, 13.786, NULL, NULL, 15.89, 30.83, NULL, 9.34, NULL, NULL, '{"Cap_Size": "Large", "Quote_Mode": "ETF", "Currency_Base": "DOLLAR", "GeoZone_Class": "U.S.", "Strategy_Type": "Growth"}', '{"Net_Worth": 5349502, "Yield_Rate": null, "Expense_Net": 0.0102, "Benchmark_Exp": 0.0053, "Turnover_Ratio": null}', '{"volume_metrics": {"Vol_3M": 34461, "Vol_Recent": 39650}, "moving_averages": {"MA_50": 17.822, "MA_200": 13.786}}', '{"asset_allocation": {"Bond_Weight": null, "Equity_Weight": null}, "bond_characteristics": {"Avg_Maturity": null, "Duration_Yrs": null}}', '{"valuation_metrics": {"PB_Ratio": 15.89, "PE_Ratio": null, "PS_Ratio": 9.34, "PCF_Ratio": 30.83}}');
INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (1949, 'VCLT', 'ETF', 'America', 'Sterling Capital Intermediate U', 'Sterling Capital Intermediate U.S. Government Fund Class C', 'AmericanDollar', NULL, NULL, 'Sterling Capital Funds', 'NGM', 'Long-Term Bond', 6010107904, 0.0308, '2009-11-19', 0.62, 'The investment seeks current income consistent with the preservation of capital. The fund normally invests at least 80% of its net assets plus borrowings for investment purposes in bonds issued or guaranteed by the U.S. government or its agencies and instrumentalities ("U.S. government securities"). It invests, under normal market conditions, in U.S. government securities, some of which may be subject to repurchase agreements, or in "high grade" mortgage-backed securities, including collateralized mortgage obligations. The fund will maintain an average duration between 2.5 and 7 years.', 0.0005, 0.0017, 814680, 941230, 106.37, 105.286, 0, 0.9975, NULL, NULL, NULL, NULL, 23.3, 14.87, '{"Cap_Size": null, "Quote_Mode": "ETF", "Currency_Base": "AmericanDollar", "GeoZone_Class": "America", "Strategy_Type": null}', '{"Net_Worth": 6010107904, "Yield_Rate": 0.0308, "Expense_Net": 0.0005, "Benchmark_Exp": 0.0017, "Turnover_Ratio": 0.62}', '{"volume_metrics": {"Vol_3M": 814680, "Vol_Recent": 941230}, "moving_averages": {"MA_50": 106.37, "MA_200": 105.286}}', '{"asset_allocation": {"Bond_Weight": 0.9975, "Equity_Weight": 0}, "bond_characteristics": {"Avg_Maturity": 23.3, "Duration_Yrs": 14.87}}', '{"valuation_metrics": {"PB_Ratio": null, "PE_Ratio": null, "PS_Ratio": null, "PCF_Ratio": null}}');
INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (1950, 'VCSH', 'ETF', 'U.S.', 'Invenomic Fund Institutional Cl', 'Invenomic Fund Institutional Class shares', 'US_DOLLAR', NULL, NULL, 'Invenomic', 'NGM', 'Short-Term Bond', 47880630272, 0.0189, '2009-11-19', 0.56, 'The investment seeks long term capital appreciation. The fund invests primarily in both long and short positions in equity securities principally traded in United States markets. Under normal market conditions, the Sub-Adviser seeks to be fully invested in the long portfolio (greater than 80%), while allowing the size of the short portfolio to fluctuate based on the market opportunity. The fund may invest in equity securities of any type and across all market capitalizations. It may invest in securities of companies operating less than three years ("unseasoned issuers") and in initial public offerings of securities ("IPO").', 0.0005, 0.0026, 3448888, 4.69354e+06, 81.91, 82.458, NULL, NULL, NULL, NULL, NULL, NULL, 3, 2.81, '{"Cap_Size": null, "Quote_Mode": "ETF", "Currency_Base": "US_DOLLAR", "GeoZone_Class": "U.S.", "Strategy_Type": null}', '{"Net_Worth": 47880630272, "Yield_Rate": 0.0189, "Expense_Net": 0.0005, "Benchmark_Exp": 0.0026, "Turnover_Ratio": 0.56}', '{"volume_metrics": {"Vol_3M": 3448888, "Vol_Recent": 4693540}, "moving_averages": {"MA_50": 81.91, "MA_200": 82.458}}', '{"asset_allocation": {"Bond_Weight": null, "Equity_Weight": null}, "bond_characteristics": {"Avg_Maturity": 3, "Duration_Yrs": 2.81}}', '{"valuation_metrics": {"PB_Ratio": null, "PE_Ratio": null, "PS_Ratio": null, "PCF_Ratio": null}}');
