INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (1962, 'VGLT', 'ETF', 'America', 'iShares Edge MSCI Min Vol EAFE ', 'iShares Edge MSCI Min Vol EAFE Index Fund Class K', 'Usd', NULL, NULL, 'BlackRock', 'NGM', 'Long Government', 6284686848, 0.0187, '2009-11-19', 0.29, 'The investment seeks to track the investment results of the MSCI EAFE Minimum Volatility (USD) Index composed of developed market equities that, in the aggregate, have lower volatility characteristics relative to the broader developed equity markets, excluding the United States and Canada. The fund generally invests at least 80% of its assets, plus the amount of any borrowing for investment purposes, in securities of the underlying index and in investments that have economic characteristics that are substantially similar to the component securities of the underlying index (i.e., depositary receipts representing securities of the underlying index).', 0.0005, 0.0014, 2325076, 2.94702e+06, 88.617, 87.347, 0, 1, NULL, NULL, NULL, NULL, 24.2, 17.96, '{"Cap_Size": null, "Quote_Mode": "ETF", "Currency_Base": "Usd", "GeoZone_Class": "America", "Strategy_Type": null}', '{"Net_Worth": 6284686848, "Yield_Rate": 0.0187, "Expense_Net": 0.0005, "Benchmark_Exp": 0.0014, "Turnover_Ratio": 0.29}', '{"volume_metrics": {"Vol_3M": 2325076, "Vol_Recent": 2947020}, "moving_averages": {"MA_50": 88.617, "MA_200": 87.347}}', '{"asset_allocation": {"Bond_Weight": 1, "Equity_Weight": 0}, "bond_characteristics": {"Avg_Maturity": 24.2, "Duration_Yrs": 17.96}}', '{"valuation_metrics": {"PB_Ratio": null, "PE_Ratio": null, "PS_Ratio": null, "PCF_Ratio": null}}');
INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (1963, 'VGSH', 'ETF', 'America', 'Baillie Gifford EAFE Plus All C', 'Baillie Gifford EAFE Plus All Cap Fund Class K', 'AmericanDollar', NULL, NULL, 'Baillie Gifford Funds', 'NGM', 'Short Government', 16383806464, 0.0064, '2009-11-19', 0.67, 'The investment seeks capital appreciation. Under normal circumstances, the fund invests at least 85% of its net assets (plus any borrowings for investment purposes) in common stocks and other equity securities of companies whose principal activities are in Europe, Australasia and/or the Far East. It may invest in equity securities either directly or indirectly, such as through depositary receipts, and may invest in preferred stocks, convertible securities and warrants. The fund is not constrained with respect to market capitalization and may participate in initial public offerings ("IPOs") and in securities offerings that are not registered in the U.S.', 0.0005, 0.0013, 1395423, 1.71664e+06, 61.246, 61.439, 0, 0.9998, NULL, NULL, NULL, NULL, 2, 1.97, '{"Cap_Size": null, "Quote_Mode": "ETF", "Currency_Base": "AmericanDollar", "GeoZone_Class": "America", "Strategy_Type": null}', '{"Net_Worth": 16383806464, "Yield_Rate": 0.0064, "Expense_Net": 0.0005, "Benchmark_Exp": 0.0013, "Turnover_Ratio": 0.67}', '{"volume_metrics": {"Vol_3M": 1395423, "Vol_Recent": 1716640}, "moving_averages": {"MA_50": 61.246, "MA_200": 61.439}}', '{"asset_allocation": {"Bond_Weight": 0.9998, "Equity_Weight": 0}, "bond_characteristics": {"Avg_Maturity": 2, "Duration_Yrs": 1.97}}', '{"valuation_metrics": {"PB_Ratio": null, "PE_Ratio": null, "PS_Ratio": null, "PCF_Ratio": null}}');
INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (1964, 'VICE', 'ETF', 'us', 'BlackRock 60/40 Target Allocati', 'BlackRock 60/40 Target Allocation Fund Class K', 'Usd', 'Growth', 'Small', 'BlackRock', 'PCX', 'Miscellaneous Sector', 13888711, 0.0102, '2017-12-11', NULL, 'The investment seeks long term capital appreciation, and current income is also a consideration. The fund, which is a fund of funds, normally obtains exposure to equity securities in an amount equal to 60% of its assets and exposure to fixed-income securities in an amount equal to 40% of its assets. Normally, the advisor intends to invest primarily in affiliated open-end funds and affiliated ETFs. The fund may, when consistent with its investment objective, buy or sell options or futures, or enter into total return swaps and foreign currency transactions (collectively, commonly known as derivatives).', 0.0099, 0.0067, 1238, 730, 32.948, 33.952, 0.9981, 0, 3.84, 12.86, 21.55, 2.43, NULL, NULL, '{"Cap_Size": "Small", "Quote_Mode": "ETF", "Currency_Base": "Usd", "GeoZone_Class": "us", "Strategy_Type": "Growth"}', '{"Net_Worth": 13888711, "Yield_Rate": 0.0102, "Expense_Net": 0.0099, "Benchmark_Exp": 0.0067, "Turnover_Ratio": null}', '{"volume_metrics": {"Vol_3M": 1238, "Vol_Recent": 730}, "moving_averages": {"MA_50": 32.948, "MA_200": 33.952}}', '{"asset_allocation": {"Bond_Weight": 0, "Equity_Weight": 0.9981}, "bond_characteristics": {"Avg_Maturity": null, "Duration_Yrs": null}}', '{"valuation_metrics": {"PB_Ratio": 3.84, "PE_Ratio": 21.55, "PS_Ratio": 2.43, "PCF_Ratio": 12.86}}');
INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (1965, 'VIDI', 'ETF', 'U.S.A.', 'iShares Short-Term TIPS Bond In', 'iShares Short-Term TIPS Bond Index Fund Class K', 'Dollar', 'Value', 'Large', 'BlackRock', 'PCX', NULL, 524412192, 0.0224, '2013-10-29', 0.79, 'The investment seeks to track the investment results of an index composed of U.S. 0-5 Year Treasury Inflation-Protected Securities ("TIPS"). The fund seeks to track the investment results of the Bloomberg Barclays U.S. Treasury Inflation-Protected Securities 0-5 Years Index (Series-L) (the "underlying index"), which measures the performance of inflation-protected public obligations of the U.S. Treasury that have a remaining maturity of less than five years. It generally invests at least 90% of its assets, plus the amount of any borrowing for investment purposes, in securities of the underlying index.', 0.0059, NULL, 30675, 32730, 26.946, 27.566, NULL, NULL, 1.23, 5.48, 14.04, 0.66, NULL, NULL, '{"Cap_Size": "Large", "Quote_Mode": "ETF", "Currency_Base": "Dollar", "GeoZone_Class": "U.S.A.", "Strategy_Type": "Value"}', '{"Net_Worth": 524412192, "Yield_Rate": 0.0224, "Expense_Net": 0.0059, "Benchmark_Exp": null, "Turnover_Ratio": 0.79}', '{"volume_metrics": {"Vol_3M": 30675, "Vol_Recent": 32730}, "moving_averages": {"MA_50": 26.946, "MA_200": 27.566}}', '{"asset_allocation": {"Bond_Weight": null, "Equity_Weight": null}, "bond_characteristics": {"Avg_Maturity": null, "Duration_Yrs": null}}', '{"valuation_metrics": {"PB_Ratio": 1.23, "PE_Ratio": 14.04, "PS_Ratio": 0.66, "PCF_Ratio": 5.48}}');
INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (1967, 'VIOO', 'ETF', 'US', 'BlackRock Multi-Asset Income Po', 'BlackRock Multi-Asset Income Portfolio Class K', 'Usd', 'Blend', 'Small', 'BlackRock', 'PCX', 'Small Blend', 3551424512, 0.0088, '2010-09-07', 0.15, 'The investment seeks to maximize current income with consideration for capital appreciation. The fund may invest up to 60% of its assets in equity securities and up to 100% of its assets in fixed income securities. In addition, it may invest in structured notes that provide exposure to covered call options or other types of financial instruments. The fund may also invest up to 15% of its assets in collateralized debt obligations ("CDOs"), including collateralized loan obligations ("CLOs").', 0.001, 0.004, 38844, 48480, 210.448, 204.452, 0.9999, 0, 2.2, 10.36, 17.53, 1.24, NULL, NULL, '{"Cap_Size": "Small", "Quote_Mode": "ETF", "Currency_Base": "Usd", "GeoZone_Class": "US", "Strategy_Type": "Blend"}', '{"Net_Worth": 3551424512, "Yield_Rate": 0.0088, "Expense_Net": 0.001, "Benchmark_Exp": 0.004, "Turnover_Ratio": 0.15}', '{"volume_metrics": {"Vol_3M": 38844, "Vol_Recent": 48480}, "moving_averages": {"MA_50": 210.448, "MA_200": 204.452}}', '{"asset_allocation": {"Bond_Weight": 0, "Equity_Weight": 0.9999}, "bond_characteristics": {"Avg_Maturity": null, "Duration_Yrs": null}}', '{"valuation_metrics": {"PB_Ratio": 2.2, "PE_Ratio": 17.53, "PS_Ratio": 1.24, "PCF_Ratio": 10.36}}');
