INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (1982, 'VOO', 'ETF', 'United States', 'BlackRock Low Duration Bond Por', 'BlackRock Low Duration Bond Portfolio Investor A Shares', 'usd', 'Blend', 'Large', 'BlackRock', 'PCX', 'Large Blend', 753409982464, 0.0134, '2010-09-07', 0.04, 'The investment seeks to maximize total return, consistent with income generation and prudent investment management. The fund invests primarily in investment grade bonds and maintains an average portfolio duration that is between 0 and 3 years. It normally invests at least 80% of its assets in debt securities. The fund may invest up to 20% of its assets in non-investment grade bonds (commonly called "high yield" or "junk bonds"). It may also invest up to 35% of its assets in assets of foreign issuers, of which 10% (as a percentage of the fund''s assets) may be invested in emerging markets issuers.', 0.0003, 0.0036, 5023950, 7.27618e+06, 416.845, 395.053, 0.9996, 0, 4.42, 17.57, 26.46, 2.96, NULL, NULL, '{"Cap_Size": "Large", "Quote_Mode": "ETF", "Currency_Base": "usd", "GeoZone_Class": "United States", "Strategy_Type": "Blend"}', '{"Net_Worth": 753409982464, "Yield_Rate": 0.0134, "Expense_Net": 0.0003, "Benchmark_Exp": 0.0036, "Turnover_Ratio": 0.04}', '{"volume_metrics": {"Vol_3M": 5023950, "Vol_Recent": 7276180}, "moving_averages": {"MA_50": 416.845, "MA_200": 395.053}}', '{"asset_allocation": {"Bond_Weight": 0, "Equity_Weight": 0.9996}, "bond_characteristics": {"Avg_Maturity": null, "Duration_Yrs": null}}', '{"valuation_metrics": {"PB_Ratio": 4.42, "PE_Ratio": 26.46, "PS_Ratio": 2.96, "PCF_Ratio": 17.57}}');
