INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (1988, 'VPOP', 'ETF', 'USA', 'Meeder Balanced Fund - Adviser ', 'Meeder Balanced Fund Adviser Class', 'Usd', 'Growth', 'Large', 'Meeder Funds', 'PCX', 'Communications', 1239051, NULL, '2020-12-28', NULL, 'The investment seeks to provide income and long-term capital appreciation. The fund invests primarily in common and preferred stocks, as well as fixed income securities. It may also invest in investment companies ("underlying funds"), which include domestic and foreign mutual funds, as well as in exchange traded funds ("ETFs"), closed-end funds and unit investment trusts. The fund will have a minimum of 30% and a maximum of 70% of its net assets invested in equity securities or underlying funds investing in equity securities.', 0.0103, 0.0035, 7282, 3860, 12.377, 12.016, NULL, NULL, 10.02, 26.88, NULL, 5.02, NULL, NULL, '{"Cap_Size": "Large", "Quote_Mode": "ETF", "Currency_Base": "Usd", "GeoZone_Class": "USA", "Strategy_Type": "Growth"}', '{"Net_Worth": 1239051, "Yield_Rate": null, "Expense_Net": 0.0103, "Benchmark_Exp": 0.0035, "Turnover_Ratio": null}', '{"volume_metrics": {"Vol_3M": 7282, "Vol_Recent": 3860}, "moving_averages": {"MA_50": 12.377, "MA_200": 12.016}}', '{"asset_allocation": {"Bond_Weight": null, "Equity_Weight": null}, "bond_characteristics": {"Avg_Maturity": null, "Duration_Yrs": null}}', '{"valuation_metrics": {"PB_Ratio": 10.02, "PE_Ratio": null, "PS_Ratio": 5.02, "PCF_Ratio": 26.88}}');
