INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (1996, 'VSPY', 'ETF', 'America', 'Bull ProFund Investor Class', 'ProFunds Bull Fund Investor Class', 'US Dollar', NULL, NULL, 'ProFunds', 'PCX', 'Allocation--50% to 70% Equity', NULL, NULL, '2021-07-20', NULL, 'The investment seeks investment results, before fees and expenses, that correspond to the performance of the S&P 500© Index. The fund invests in financial instruments that the Advisor believes, in combination, should track the performance of the index. The index is a measure of large-cap U.S. stock market performance. It is a float-adjusted, market capitalization-weighted index of 500 U.S. operating companies and real estate investment trusts selected through a process that factors in criteria such as liquidity, price, market capitalization and financial viability. The fund is non-diversified.', 0.011, 0.0072, 10725, 2300, 9.994, 10.013, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '{"Cap_Size": null, "Quote_Mode": "ETF", "Currency_Base": "US Dollar", "GeoZone_Class": "America", "Strategy_Type": null}', '{"Net_Worth": null, "Yield_Rate": null, "Expense_Net": 0.011, "Benchmark_Exp": 0.0072, "Turnover_Ratio": null}', '{"volume_metrics": {"Vol_3M": 10725, "Vol_Recent": 2300}, "moving_averages": {"MA_50": 9.994, "MA_200": 10.013}}', '{"asset_allocation": {"Bond_Weight": null, "Equity_Weight": null}, "bond_characteristics": {"Avg_Maturity": null, "Duration_Yrs": null}}', '{"valuation_metrics": {"PB_Ratio": null, "PE_Ratio": null, "PS_Ratio": null, "PCF_Ratio": null}}');
