INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (2018, 'WBIT', 'ETF', 'U.S.', 'BMO Moderate Allocation Fund - ', 'BMO Moderate Allocation Fund Class I', 'USD', 'Value', 'Large', 'BMO Funds', 'PCX', 'Tactical Allocation', 29053278, 0.0286, '2019-05-28', 13.93, 'The investment seeks to provide total investment return from income and appreciation. The fund normally targets an allocation of approximately 60% of its total assets in funds that invest principally in fixed income securities and 40% of its total assets in funds that invest principally in equity securities. Under normal market conditions it allocates its assets among the underlying funds based on asset allocation target ranges of 50-70% of its total assets in funds that invest principally in fixed income securities and 30-50% of its total assets in funds that invest principally in equity securities.', 0.0089, 0.0112, 2048, 1730, 20.946, 20.486, NULL, NULL, 7.63, NULL, 59.99, 2.06, 5.74, 4.43, '{"Cap_Size": "Large", "Quote_Mode": "ETF", "Currency_Base": "USD", "GeoZone_Class": "U.S.", "Strategy_Type": "Value"}', '{"Net_Worth": 29053278, "Yield_Rate": 0.0286, "Expense_Net": 0.0089, "Benchmark_Exp": 0.0112, "Turnover_Ratio": 13.93}', '{"volume_metrics": {"Vol_3M": 2048, "Vol_Recent": 1730}, "moving_averages": {"MA_50": 20.946, "MA_200": 20.486}}', '{"asset_allocation": {"Bond_Weight": null, "Equity_Weight": null}, "bond_characteristics": {"Avg_Maturity": 5.74, "Duration_Yrs": 4.43}}', '{"valuation_metrics": {"PB_Ratio": 7.63, "PE_Ratio": 59.99, "PS_Ratio": 2.06, "PCF_Ratio": null}}');
INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (2019, 'WBIY', 'ETF', 'USA', 'Baird Quality Intermediate Muni', 'Baird Quality Intermediate Municipal Bond Fund Class Institutional', 'US Dollar', 'Value', 'Medium', 'Baird', 'PCX', 'Mid-Cap Value', 64457092, 0.0394, '2016-12-19', 1.96, 'The investment seeks current income that is substantially exempt from federal income tax; total return with relatively low volatility of principal is a secondary objective. The fund normally invests at least 80% of its net assets in municipal bonds and debentures, the interest from which is exempt from federal income tax. It invests in a broadly diversified portfolio of municipal obligations issued by governmental authorities throughout the U.S. and its territories. The fund may invest in all types of municipal obligations, including pre-refunded bonds, general obligation bonds, revenue bonds, municipal lease participations and tax-exempt commercial paper.', 0.007, 0.0043, 3746, 3860, 27.426, 27.365, 0.9952, 0, 2, 8.47, 16.24, 1.32, NULL, NULL, '{"Cap_Size": "Medium", "Quote_Mode": "ETF", "Currency_Base": "US Dollar", "GeoZone_Class": "USA", "Strategy_Type": "Value"}', '{"Net_Worth": 64457092, "Yield_Rate": 0.0394, "Expense_Net": 0.007, "Benchmark_Exp": 0.0043, "Turnover_Ratio": 1.96}', '{"volume_metrics": {"Vol_3M": 3746, "Vol_Recent": 3860}, "moving_averages": {"MA_50": 27.426, "MA_200": 27.365}}', '{"asset_allocation": {"Bond_Weight": 0, "Equity_Weight": 0.9952}, "bond_characteristics": {"Avg_Maturity": null, "Duration_Yrs": null}}', '{"valuation_metrics": {"PB_Ratio": 2, "PE_Ratio": 16.24, "PS_Ratio": 1.32, "PCF_Ratio": 8.47}}');
