INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (2166, 'IBCE', 'ETF', 'USA', 'American Beacon Bridgeway Large', 'American Beacon Bridgeway Large Cap Growth Fund R5 Class', 'Dollar', NULL, NULL, 'American Beacon', 'PCX', NULL, 31000084, 0.0223, '2013-04-17', 0.09, 'The investment seeks long-term total return on capital, primarily through capital appreciation. The fund invests in a diversified portfolio of large capitalization companies that are listed on the New York Stock Exchange, NYSE American, or NASDAQ. It normally invests at least 80% of its net assets (plus borrowings for investment purposes) in stocks from among those in the large-cap growth category at the time of purchase.', 0.001, NULL, 1193, 1500, 24.639, 24.773, NULL, NULL, NULL, NULL, NULL, NULL, 1.15, 1.13, '{"Cap_Size": null, "Quote_Mode": "ETF", "Currency_Base": "Dollar", "GeoZone_Class": "USA", "Strategy_Type": null}', '{"Net_Worth": 31000084, "Yield_Rate": 0.0223, "Expense_Net": 0.001, "Benchmark_Exp": null, "Turnover_Ratio": 0.09}', '{"volume_metrics": {"Vol_3M": 1193, "Vol_Recent": 1500}, "moving_averages": {"MA_50": 24.639, "MA_200": 24.773}}', '{"asset_allocation": {"Bond_Weight": null, "Equity_Weight": null}, "bond_characteristics": {"Avg_Maturity": 1.15, "Duration_Yrs": 1.13}}', '{"valuation_metrics": {"PB_Ratio": null, "PE_Ratio": null, "PS_Ratio": null, "PCF_Ratio": null}}');
INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (2054, 'XDSQ', 'ETF', 'America', 'Baird Municipal Bond Fund Insti', 'Baird Municipal Bond Fund Institutional', 'Dollar', 'Blend', 'Large', 'Baird', 'BTS', 'Large Blend', 10805522, NULL, '2021-03-31', NULL, 'The investment seeks a high level of current income that is exempt from federal income tax and is consistent with the preservation of capital. The fund normally invests at least 80% of its net assets in municipal bonds and debentures, the income from which is exempt from federal income tax (including the federal alternative minimum tax (AMT)). It invests in a broadly diversified portfolio of federally tax-exempt municipal obligations issued by governmental authorities throughout the U.S. and its territories.', 0.0079, 0.0036, 4764, 1900, 28.096, 27.39, 0.9964, 0, 4.42, 17.56, 26.45, 2.96, NULL, NULL, '{"Cap_Size": "Large", "Quote_Mode": "ETF", "Currency_Base": "Dollar", "GeoZone_Class": "America", "Strategy_Type": "Blend"}', '{"Net_Worth": 10805522, "Yield_Rate": null, "Expense_Net": 0.0079, "Benchmark_Exp": 0.0036, "Turnover_Ratio": null}', '{"volume_metrics": {"Vol_3M": 4764, "Vol_Recent": 1900}, "moving_averages": {"MA_50": 28.096, "MA_200": 27.39}}', '{"asset_allocation": {"Bond_Weight": 0, "Equity_Weight": 0.9964}, "bond_characteristics": {"Avg_Maturity": null, "Duration_Yrs": null}}', '{"valuation_metrics": {"PB_Ratio": 4.42, "PE_Ratio": 26.45, "PS_Ratio": 2.96, "PCF_Ratio": 17.56}}');
