INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (2076, 'XSOE', 'ETF', 'U.S.A.', 'Sterling Capital North Carolina', 'Sterling Capital North Carolina Intermediate Tax-Free Fund Class A', 'Usd', 'Blend', 'Large', 'Sterling Capital Funds', 'PCX', 'Diversified Emerging Mkts', 5030211584, 0.0129, '2014-12-10', 0.34, 'The investment seeks current income exempt from federal and North Carolina income taxes consistent with preservation of capital. The fund normally invests at least 80% of its net assets in investments the income from which is exempt from federal income tax, alternative minimum tax, and North Carolina personal income tax. It invests primarily in municipal securities of the State of North Carolina and its political subdivisions, that provide income exempt from both federal personal income tax and North Carolina personal income tax. The fund''s dollar-weighted average maturity is expected to be more than 3 years but less than 10 years. It is non-diversified.', 0.0032, 0.0056, 845537, 816210, 37.926, 39.936, 0.999, 0, 2.64, 12.59, 20.21, 1.38, NULL, NULL, '{"Cap_Size": "Large", "Quote_Mode": "ETF", "Currency_Base": "Usd", "GeoZone_Class": "U.S.A.", "Strategy_Type": "Blend"}', '{"Net_Worth": 5030211584, "Yield_Rate": 0.0129, "Expense_Net": 0.0032, "Benchmark_Exp": 0.0056, "Turnover_Ratio": 0.34}', '{"volume_metrics": {"Vol_3M": 845537, "Vol_Recent": 816210}, "moving_averages": {"MA_50": 37.926, "MA_200": 39.936}}', '{"asset_allocation": {"Bond_Weight": 0, "Equity_Weight": 0.999}, "bond_characteristics": {"Avg_Maturity": null, "Duration_Yrs": null}}', '{"valuation_metrics": {"PB_Ratio": 2.64, "PE_Ratio": 20.21, "PS_Ratio": 1.38, "PCF_Ratio": 12.59}}');
INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (2077, 'XSVM', 'ETF', 'us', 'Meeder Total Return Bond Fund -', 'Meeder Tactical Income Fund Adviser Class', 'usd', 'Value', 'Small', 'Meeder Funds', 'PCX', 'Small Value', 359587552, 0.0075, '2005-03-03', 0.75, 'The investment seeks to provide long-term total return and income. The fund normally invests at least 80% of its net assets in fixed income securities, principally mutual and exchange traded funds that invest in domestic and foreign fixed income securities. It may invest in fixed income securities of any duration and may utilize derivative investments that provide exposure to fixed income securities. The fund may also invest up to 20% of its net assets in equity securities, including preferred stock, convertible securities, common stocks and real estate investment trusts ("REITs").', 0.0039, 0.0035, 114098, 164650, 53.352, 50.468, 0.9995, 0, 1.47, 5.07, 9.06, 0.38, NULL, NULL, '{"Cap_Size": "Small", "Quote_Mode": "ETF", "Currency_Base": "usd", "GeoZone_Class": "us", "Strategy_Type": "Value"}', '{"Net_Worth": 359587552, "Yield_Rate": 0.0075, "Expense_Net": 0.0039, "Benchmark_Exp": 0.0035, "Turnover_Ratio": 0.75}', '{"volume_metrics": {"Vol_3M": 114098, "Vol_Recent": 164650}, "moving_averages": {"MA_50": 53.352, "MA_200": 50.468}}', '{"asset_allocation": {"Bond_Weight": 0, "Equity_Weight": 0.9995}, "bond_characteristics": {"Avg_Maturity": null, "Duration_Yrs": null}}', '{"valuation_metrics": {"PB_Ratio": 1.47, "PE_Ratio": 9.06, "PS_Ratio": 0.38, "PCF_Ratio": 5.07}}');
