INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (2080, 'XTJL', 'ETF', 'usa', 'UBS International Sustainable E', 'UBS International Sustainable Equity Fund Class A', 'DOLLAR', NULL, NULL, 'UBS Asset Management', 'BTS', NULL, 25, NULL, '2021-06-30', NULL, 'The investment seeks to maximize total return, consisting of capital appreciation and current income by investing primarily in the equity securities of non-U.S. issuers. The fund invests at least 80% of its net assets (plus borrowings for investment purposes, if any) in equity securities. Under normal market conditions, the fund invests primarily (at least 65% of its total assets) in issuers organized or having their principal place of business outside the United States or doing a substantial amount of business outside the United States. Up to 35% of the fund''s assets may be invested in U.S. equity securities.', 0.0079, NULL, 1582, 380, 26.875, 26.564, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '{"Cap_Size": null, "Quote_Mode": "ETF", "Currency_Base": "DOLLAR", "GeoZone_Class": "usa", "Strategy_Type": null}', '{"Net_Worth": 25, "Yield_Rate": null, "Expense_Net": 0.0079, "Benchmark_Exp": null, "Turnover_Ratio": null}', '{"volume_metrics": {"Vol_3M": 1582, "Vol_Recent": 380}, "moving_averages": {"MA_50": 26.875, "MA_200": 26.564}}', '{"asset_allocation": {"Bond_Weight": null, "Equity_Weight": null}, "bond_characteristics": {"Avg_Maturity": null, "Duration_Yrs": null}}', '{"valuation_metrics": {"PB_Ratio": null, "PE_Ratio": null, "PS_Ratio": null, "PCF_Ratio": null}}');
INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (2081, 'XTL', 'ETF', 'UNITED_STATES', 'BlackRock National Municipal Fu', 'BlackRock National Municipal Fund K Share', 'US Dollar', 'Blend', 'Small', 'BlackRock', 'PCX', 'Communications', 84375232, 0.008, '2011-01-26', 0.44, 'The investment seeks to provide shareholders with as high a level of income exempt from Federal income taxes as is consistent with the investment policies of the fund. The fund seeks to achieve its objective by investing at least 80% of its assets in municipal bonds. Although the advisor intends to invest at least 65% of the fund''s net assets in municipal bonds rated investment grade or in unrated municipal bonds that fund management believes are of comparable quality, it is possible that in the future the fund could invest up to 100% of its assets in "junk bonds." It will primarily invest in municipal bonds that have a maturity of five years or longer.', 0.0035, 0.0035, 7084, 14850, 97.876, 97.93, 0.9976, 0, 2.17, 8.42, 27.88, 1.73, NULL, NULL, '{"Cap_Size": "Small", "Quote_Mode": "ETF", "Currency_Base": "US Dollar", "GeoZone_Class": "UNITED_STATES", "Strategy_Type": "Blend"}', '{"Net_Worth": 84375232, "Yield_Rate": 0.008, "Expense_Net": 0.0035, "Benchmark_Exp": 0.0035, "Turnover_Ratio": 0.44}', '{"volume_metrics": {"Vol_3M": 7084, "Vol_Recent": 14850}, "moving_averages": {"MA_50": 97.876, "MA_200": 97.93}}', '{"asset_allocation": {"Bond_Weight": 0, "Equity_Weight": 0.9976}, "bond_characteristics": {"Avg_Maturity": null, "Duration_Yrs": null}}', '{"valuation_metrics": {"PB_Ratio": 2.17, "PE_Ratio": 27.88, "PS_Ratio": 1.73, "PCF_Ratio": 8.42}}');
