INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (2084, 'XVV', 'ETF', 'United States', 'UBS International Sustainable E', 'UBS International Sustainable Equity Fund Class P', 'USD', 'Blend', 'Large', 'UBS Asset Management', 'BTS', 'Large Blend', 82662272, NULL, '2020-09-22', 0.06, 'The investment seeks to maximize total return, consisting of capital appreciation and current income by investing primarily in the equity securities of non-U.S. issuers. The fund invests at least 80% of its net assets (plus borrowings for investment purposes, if any) in equity securities. Under normal market conditions, the fund invests primarily (at least 65% of its total assets) in issuers organized or having their principal place of business outside the United States or doing a substantial amount of business outside the United States. Up to 35% of the fund''s assets may be invested in U.S. equity securities.', 0.0008, 0.0036, 90379, 186260, 34.953, 32.996, 0.9975, 0, 4.8, 18.2, 26.78, 3.08, NULL, NULL, '{"Cap_Size": "Large", "Quote_Mode": "ETF", "Currency_Base": "USD", "GeoZone_Class": "United States", "Strategy_Type": "Blend"}', '{"Net_Worth": 82662272, "Yield_Rate": null, "Expense_Net": 0.0008, "Benchmark_Exp": 0.0036, "Turnover_Ratio": 0.06}', '{"volume_metrics": {"Vol_3M": 90379, "Vol_Recent": 186260}, "moving_averages": {"MA_50": 34.953, "MA_200": 32.996}}', '{"asset_allocation": {"Bond_Weight": 0, "Equity_Weight": 0.9975}, "bond_characteristics": {"Avg_Maturity": null, "Duration_Yrs": null}}', '{"valuation_metrics": {"PB_Ratio": 4.8, "PE_Ratio": 26.78, "PS_Ratio": 3.08, "PCF_Ratio": 18.2}}');
INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (2266, 'MLPR', 'ETF', 'US', 'BlackRock Total Factor Fund - C', 'BlackRock Total Factor Fund Investor C Shares', 'Usd', NULL, NULL, 'BlackRock', 'PCX', NULL, 30671500, NULL, '2020-06-02', NULL, 'The investment seeks total return. The fund invests in a broad range of global asset classes, such as equity securities, fixed and floating rate debt instruments, derivatives, other investment companies, including exchange-traded funds ("ETFs"), real estate investment trusts ("REITs") and commodity-related instruments. It will normally invest in both U.S. and non-U.S. companies, including companies located in emerging markets and in securities denominated in both U.S. dollars and foreign currencies.', NULL, NULL, 747, 350, 34.018, 32.607, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '{"Cap_Size": null, "Quote_Mode": "ETF", "Currency_Base": "Usd", "GeoZone_Class": "US", "Strategy_Type": null}', '{"Net_Worth": 30671500, "Yield_Rate": null, "Expense_Net": null, "Benchmark_Exp": null, "Turnover_Ratio": null}', '{"volume_metrics": {"Vol_3M": 747, "Vol_Recent": 350}, "moving_averages": {"MA_50": 34.018, "MA_200": 32.607}}', '{"asset_allocation": {"Bond_Weight": null, "Equity_Weight": null}, "bond_characteristics": {"Avg_Maturity": null, "Duration_Yrs": null}}', '{"valuation_metrics": {"PB_Ratio": null, "PE_Ratio": null, "PS_Ratio": null, "PCF_Ratio": null}}');
INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (2085, 'XWEB', 'ETF', 'U.S.', 'Bogle Investment Management Sma', 'SGI Small Cap Growth Fund Institutional Class', 'US Dollar', 'Growth', 'Medium', 'Bogle', 'PCX', 'Technology', 61357340, 0.0035, '2016-06-27', 0.52, 'The investment seeks to provide long-term capital appreciation. The fund seeks to achieve its objective by investing under normal circumstances at least 80% of the net assets of the portfolio (including borrowings for investment purposes) in the stocks of U.S. companies with market capitalizations, at the time of purchase, that are within the trailing twelve-month range of the market capitalizations of those companies that are included in the Russell 2000© Index ("Small Cap Stocks"). As part of its investment strategy, the Adviser will continue to invest in Small Cap Stocks that the adviser believes will appreciate more than the index.', 0.0035, 0.0053, 2387, 1950, 168.323, 171.871, 0.9997, 0, 5.73, 19.03, 29.46, 2.39, NULL, NULL, '{"Cap_Size": "Medium", "Quote_Mode": "ETF", "Currency_Base": "US Dollar", "GeoZone_Class": "U.S.", "Strategy_Type": "Growth"}', '{"Net_Worth": 61357340, "Yield_Rate": 0.0035, "Expense_Net": 0.0035, "Benchmark_Exp": 0.0053, "Turnover_Ratio": 0.52}', '{"volume_metrics": {"Vol_3M": 2387, "Vol_Recent": 1950}, "moving_averages": {"MA_50": 168.323, "MA_200": 171.871}}', '{"asset_allocation": {"Bond_Weight": 0, "Equity_Weight": 0.9997}, "bond_characteristics": {"Avg_Maturity": null, "Duration_Yrs": null}}', '{"valuation_metrics": {"PB_Ratio": 5.73, "PE_Ratio": 29.46, "PS_Ratio": 2.39, "PCF_Ratio": 19.03}}');
