INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (2091, 'YDEC', 'ETF', 'United States', 'BNY Mellon Small Cap Value Fund', 'BNY Mellon Small Cap Value Fund Class C', 'US_DOLLAR', 'Blend', 'Large', 'BNY Mellon', 'BTS', NULL, 8174003, NULL, '2020-12-17', NULL, 'The investment seeks long-term growth of capital. The fund normally invests at least 80% of its net assets, plus any borrowings for investment purposes, in equity securities of small-cap U.S. companies. The adviser currently considers small-cap companies to be those with total market capitalizations that are equal to or less than the total market capitalization of the largest company included in the Russell 2000© Value Index, the fund''s benchmark index. The fund''s portfolio managers use fundamental research and qualitative analysis to select stocks among the portfolio candidates.', 0.009, NULL, 7188, 6890, 21.685, 21.438, NULL, NULL, 1.75, 10.23, 21.32, 1.43, NULL, NULL, '{"Cap_Size": "Large", "Quote_Mode": "ETF", "Currency_Base": "US_DOLLAR", "GeoZone_Class": "United States", "Strategy_Type": "Blend"}', '{"Net_Worth": 8174003, "Yield_Rate": null, "Expense_Net": 0.009, "Benchmark_Exp": null, "Turnover_Ratio": null}', '{"volume_metrics": {"Vol_3M": 7188, "Vol_Recent": 6890}, "moving_averages": {"MA_50": 21.685, "MA_200": 21.438}}', '{"asset_allocation": {"Bond_Weight": null, "Equity_Weight": null}, "bond_characteristics": {"Avg_Maturity": null, "Duration_Yrs": null}}', '{"valuation_metrics": {"PB_Ratio": 1.75, "PE_Ratio": 21.32, "PS_Ratio": 1.43, "PCF_Ratio": 10.23}}');
INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (2092, 'YINN', 'ETF', 'U.S.', 'Boston Trust Walden Small Cap F', 'Boston Trust Walden Small Cap Fund', 'US$', 'Blend', 'Large', 'Boston Trust Walden Funds', 'PCX', 'Trading--Leveraged Equity', 393963744, 0.0075, '2009-12-03', 2.64, 'The investment seeks long-term capital growth through an actively managed portfolio of stocks of small capitalization companies. The fund invests, under normal circumstances, at least 80% of its assets in a diversified portfolio of domestic equity securities of small cap companies. For these purposes, the Adviser defines small cap issuers as those with market capitalizations within the range encompassed by the Russell 2000© Index at the time of purchase.', 0.0136, 0.009, 4118622, 4.6098e+06, 10.923, 15.46, NULL, NULL, 1.44, 12.17, 11.84, 1.75, NULL, NULL, '{"Cap_Size": "Large", "Quote_Mode": "ETF", "Currency_Base": "US$", "GeoZone_Class": "U.S.", "Strategy_Type": "Blend"}', '{"Net_Worth": 393963744, "Yield_Rate": 0.0075, "Expense_Net": 0.0136, "Benchmark_Exp": 0.009, "Turnover_Ratio": 2.64}', '{"volume_metrics": {"Vol_3M": 4118622, "Vol_Recent": 4609800}, "moving_averages": {"MA_50": 10.923, "MA_200": 15.46}}', '{"asset_allocation": {"Bond_Weight": null, "Equity_Weight": null}, "bond_characteristics": {"Avg_Maturity": null, "Duration_Yrs": null}}', '{"valuation_metrics": {"PB_Ratio": 1.44, "PE_Ratio": 11.84, "PS_Ratio": 1.75, "PCF_Ratio": 12.17}}');
INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (2093, 'YJUN', 'ETF', 'USA', 'Bridgeway Omni Small Cap Value ', 'Bridgeway Omni Small-Cap Value Fund Class N', 'US_DOLLAR', NULL, NULL, 'Bridgeway', 'BTS', NULL, NULL, NULL, '2021-06-18', NULL, 'The investment seeks to provide long-term total return on capital, primarily through capital appreciation. The fund invests in a broad and diverse group of small-cap stocks that the Adviser determines to be value stocks. It invests 80% of its net assets (plus borrowings for investment purposes) in equity or equity-related securities ("common stocks") of small-cap companies at the time of purchase. The fund primarily invests in small-cap stocks that are listed on the New York Stock Exchange, the NYSE MKT and NASDAQ. It may invest up to 15% of its total assets in foreign securities.', 0.009, NULL, 6738, 2350, 20.191, 20.209, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '{"Cap_Size": null, "Quote_Mode": "ETF", "Currency_Base": "US_DOLLAR", "GeoZone_Class": "USA", "Strategy_Type": null}', '{"Net_Worth": null, "Yield_Rate": null, "Expense_Net": 0.009, "Benchmark_Exp": null, "Turnover_Ratio": null}', '{"volume_metrics": {"Vol_3M": 6738, "Vol_Recent": 2350}, "moving_averages": {"MA_50": 20.191, "MA_200": 20.209}}', '{"asset_allocation": {"Bond_Weight": null, "Equity_Weight": null}, "bond_characteristics": {"Avg_Maturity": null, "Duration_Yrs": null}}', '{"valuation_metrics": {"PB_Ratio": null, "PE_Ratio": null, "PS_Ratio": null, "PCF_Ratio": null}}');
INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (2094, 'YLD', 'ETF', 'US', 'BNY Mellon Small Cap Value Fund', 'BNY Mellon Small Cap Value Fund Class Y', 'DOLLAR', NULL, NULL, 'BNY Mellon', 'PCX', 'Allocation--15% to 30% Equity', 233244096, 0.0373, '2015-07-08', 0.195, 'The investment seeks long-term growth of capital. The fund normally invests at least 80% of its net assets, plus any borrowings for investment purposes, in equity securities of small-cap U.S. companies. The adviser currently considers small-cap companies to be those with total market capitalizations that are equal to or less than the total market capitalization of the largest company included in the Russell 2000© Value Index, the fund''s benchmark index. The fund''s portfolio managers use fundamental research and qualitative analysis to select stocks among the portfolio candidates.', 0.0049, 0.0094, 15743, 62870, 20.86, 20.726, NULL, NULL, NULL, NULL, NULL, NULL, 6.87, 3.34, '{"Cap_Size": null, "Quote_Mode": "ETF", "Currency_Base": "DOLLAR", "GeoZone_Class": "US", "Strategy_Type": null}', '{"Net_Worth": 233244096, "Yield_Rate": 0.0373, "Expense_Net": 0.0049, "Benchmark_Exp": 0.0094, "Turnover_Ratio": 0.195}', '{"volume_metrics": {"Vol_3M": 15743, "Vol_Recent": 62870}, "moving_averages": {"MA_50": 20.86, "MA_200": 20.726}}', '{"asset_allocation": {"Bond_Weight": null, "Equity_Weight": null}, "bond_characteristics": {"Avg_Maturity": 6.87, "Duration_Yrs": 3.34}}', '{"valuation_metrics": {"PB_Ratio": null, "PE_Ratio": null, "PS_Ratio": null, "PCF_Ratio": null}}');
