INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (2095, 'YLDE', 'ETF', 'US', 'Bridgeway Omni-Tax Managed Smal', 'Bridgeway Omni Tax-Managed Small-Cap Value Fund Class N', 'Usd', 'Blend', 'Large', 'Bridgeway', 'NGM', 'Large Blend', 19877710, 0.01, '2017-05-22', 0.1, 'The investment seeks to provide long-term total return on capital, primarily through capital appreciation. The fund invests in a broad and diverse group of small-cap stocks that the Adviser determines to be value stocks. It invests 80% of its net assets (plus borrowings for investment purposes) in equity or equity-related securities ("common stocks") of small-cap companies at the time of purchase. The fund primarily invests in small-cap stocks that are listed on the New York Stock Exchange, the NYSE MKT and NASDAQ. It may invest up to 15% of its total assets in foreign securities.', 0.006, 0.0036, 1175, 1020, 41.49, 39.966, NULL, NULL, 3.9, 17, 27.59, 3.42, NULL, NULL, '{"Cap_Size": "Large", "Quote_Mode": "ETF", "Currency_Base": "Usd", "GeoZone_Class": "US", "Strategy_Type": "Blend"}', '{"Net_Worth": 19877710, "Yield_Rate": 0.01, "Expense_Net": 0.006, "Benchmark_Exp": 0.0036, "Turnover_Ratio": 0.1}', '{"volume_metrics": {"Vol_3M": 1175, "Vol_Recent": 1020}, "moving_averages": {"MA_50": 41.49, "MA_200": 39.966}}', '{"asset_allocation": {"Bond_Weight": null, "Equity_Weight": null}, "bond_characteristics": {"Avg_Maturity": null, "Duration_Yrs": null}}', '{"valuation_metrics": {"PB_Ratio": 3.9, "PE_Ratio": 27.59, "PS_Ratio": 3.42, "PCF_Ratio": 17}}');
INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (2096, 'YMAR', 'ETF', 'America', 'Boyar Value Fund Inc (The)', 'Boyar Value Fund', 'Dollar', 'Blend', 'Large', 'Boyar Value Fund', 'BTS', NULL, 4201622, NULL, '2021-03-18', NULL, 'The investment seeks long-term capital appreciation. Under normal market conditions, the fund invests primarily in equity securities that are believed by the Adviser to be intrinsically undervalued including common stock, preferred stock or securities convertible into or exchangeable for common stock. Intrinsic value, as the Adviser defines it, is the estimated current worth that would accrue to the stockholders of a company, either through liquidation of corporate assets upon termination of operations, or through the sale or merger of the entire enterprise as a continuing business.', 0.009, NULL, 10958, 2760, 20.879, 20.81, NULL, NULL, 1.86, 10.73, 21.03, 1.56, NULL, NULL, '{"Cap_Size": "Large", "Quote_Mode": "ETF", "Currency_Base": "Dollar", "GeoZone_Class": "America", "Strategy_Type": "Blend"}', '{"Net_Worth": 4201622, "Yield_Rate": null, "Expense_Net": 0.009, "Benchmark_Exp": null, "Turnover_Ratio": null}', '{"volume_metrics": {"Vol_3M": 10958, "Vol_Recent": 2760}, "moving_averages": {"MA_50": 20.879, "MA_200": 20.81}}', '{"asset_allocation": {"Bond_Weight": null, "Equity_Weight": null}, "bond_characteristics": {"Avg_Maturity": null, "Duration_Yrs": null}}', '{"valuation_metrics": {"PB_Ratio": 1.86, "PE_Ratio": 21.03, "PS_Ratio": 1.56, "PCF_Ratio": 10.73}}');
INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (2097, 'YOLO', 'ETF', 'UNITED_STATES', 'Boston Partners All-Cap Value F', 'Boston Partners All Cap Value Fund Institutional Class', 'AmericanDollar', 'Growth', 'Small', 'Boston Partners', 'PCX', NULL, 378309952, 0.01, '2019-04-17', NULL, 'The investment seeks to provide long-term growth of capital primarily through investment in equity securities; current income is a secondary objective. The fund pursues its objective by investing, under normal circumstances, at least 80% of its net assets (including borrowings for investment purposes) in a diversified portfolio consisting primarily of equity securities, such as common stocks of issuers across the capitalization spectrum and identified by the Adviser as having value characteristics. It may also invest up to 20% of its total assets in non U.S. dollar-denominated securities.', 0.0075, NULL, 122859, 140580, 15.841, 19.524, NULL, NULL, 3.83, NULL, NULL, 4.62, NULL, NULL, '{"Cap_Size": "Small", "Quote_Mode": "ETF", "Currency_Base": "AmericanDollar", "GeoZone_Class": "UNITED_STATES", "Strategy_Type": "Growth"}', '{"Net_Worth": 378309952, "Yield_Rate": 0.01, "Expense_Net": 0.0075, "Benchmark_Exp": null, "Turnover_Ratio": null}', '{"volume_metrics": {"Vol_3M": 122859, "Vol_Recent": 140580}, "moving_averages": {"MA_50": 15.841, "MA_200": 19.524}}', '{"asset_allocation": {"Bond_Weight": null, "Equity_Weight": null}, "bond_characteristics": {"Avg_Maturity": null, "Duration_Yrs": null}}', '{"valuation_metrics": {"PB_Ratio": 3.83, "PE_Ratio": null, "PS_Ratio": 4.62, "PCF_Ratio": null}}');
