INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (2099, 'YXI', 'ETF', 'United States', 'Boston Partners Global Equity A', 'Boston Partners Global Equity Advantage Fund Institutional Class', 'US$', NULL, NULL, 'Boston Partners', 'PCX', 'Trading--Inverse Equity', 2808429, NULL, '2010-03-16', NULL, 'The investment seeks to provide long-term capital appreciation. The fund seeks to achieve its investment objective by investing, under normal circumstances, at least 80% of its net assets (including borrowings for investment purposes) in a non-diversified portfolio of equity and equity-related securities issued by U.S. and non-U.S. companies of any capitalization size. It may invest up to 15% of its net assets in illiquid securities, including securities that are illiquid by virtue of the absence of a readily available market or legal or contractual restrictions on resale. The fund is non-diversified.', 0.0095, 0.0092, 14046, 8010, 15.69, 14.885, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '{"Cap_Size": null, "Quote_Mode": "ETF", "Currency_Base": "US$", "GeoZone_Class": "United States", "Strategy_Type": null}', '{"Net_Worth": 2808429, "Yield_Rate": null, "Expense_Net": 0.0095, "Benchmark_Exp": 0.0092, "Turnover_Ratio": null}', '{"volume_metrics": {"Vol_3M": 14046, "Vol_Recent": 8010}, "moving_averages": {"MA_50": 15.69, "MA_200": 14.885}}', '{"asset_allocation": {"Bond_Weight": null, "Equity_Weight": null}, "bond_characteristics": {"Avg_Maturity": null, "Duration_Yrs": null}}', '{"valuation_metrics": {"PB_Ratio": null, "PE_Ratio": null, "PS_Ratio": null, "PCF_Ratio": null}}');
INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (2100, 'YYY', 'ETF', 'U.S.', 'Baillie Gifford Positive Change', 'Baillie Gifford Positive Change Equities Fund Class K', 'US Dollar', 'Value', 'Large', 'Baillie Gifford Funds', 'PCX', 'Tactical Allocation', 453015936, 0.0887, '2012-06-12', 0.43, 'The investment seeks capital appreciation with an emphasis on investing in businesses that deliver positive change by contributing towards a more sustainable and inclusive world. Under normal circumstances, the fund invests at least 80% of its net assets (plus any borrowings for investment purposes) in equity securities. It invests predominantly in securities issued by companies located in countries represented in the MSCI ACWI Index, cash and cash equivalents. The fund is non-diversified.', 0.0245, 0.0112, 200751, 209070, 16.965, 17.123, NULL, NULL, 2.44, 13.02, 19.91, 2.01, 6.69, 5.38, '{"Cap_Size": "Large", "Quote_Mode": "ETF", "Currency_Base": "US Dollar", "GeoZone_Class": "U.S.", "Strategy_Type": "Value"}', '{"Net_Worth": 453015936, "Yield_Rate": 0.0887, "Expense_Net": 0.0245, "Benchmark_Exp": 0.0112, "Turnover_Ratio": 0.43}', '{"volume_metrics": {"Vol_3M": 200751, "Vol_Recent": 209070}, "moving_averages": {"MA_50": 16.965, "MA_200": 17.123}}', '{"asset_allocation": {"Bond_Weight": null, "Equity_Weight": null}, "bond_characteristics": {"Avg_Maturity": 6.69, "Duration_Yrs": 5.38}}', '{"valuation_metrics": {"PB_Ratio": 2.44, "PE_Ratio": 19.91, "PS_Ratio": 2.01, "PCF_Ratio": 13.02}}');
INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (2101, 'ZHDG', 'ETF', 'USA', 'Boston Partners Emerging Market', 'Boston Partners Emerging Markets Fund Institutional Class', 'US Dollar', NULL, NULL, 'Boston Partners', 'PCX', 'Large Blend', NULL, NULL, '2021-07-06', NULL, 'The investment seeks long-term growth of capital. The fund will pursue its objective through a value oriented, research-driven strategy of investing in equity securities and financial instruments with equity like characteristics designed to provide exposure to emerging markets. The advisor intends, under normal circumstances, to invest at least 80% of the fund''s net assets (including borrowings for investment purposes) in the securities of emerging market issuers, related derivative instruments and other investments that are tied economically to emerging market countries.', 0.0102, 0.0036, 43304, 40010, 20.504, 20.356, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '{"Cap_Size": null, "Quote_Mode": "ETF", "Currency_Base": "US Dollar", "GeoZone_Class": "USA", "Strategy_Type": null}', '{"Net_Worth": null, "Yield_Rate": null, "Expense_Net": 0.0102, "Benchmark_Exp": 0.0036, "Turnover_Ratio": null}', '{"volume_metrics": {"Vol_3M": 43304, "Vol_Recent": 40010}, "moving_averages": {"MA_50": 20.504, "MA_200": 20.356}}', '{"asset_allocation": {"Bond_Weight": null, "Equity_Weight": null}, "bond_characteristics": {"Avg_Maturity": null, "Duration_Yrs": null}}', '{"valuation_metrics": {"PB_Ratio": null, "PE_Ratio": null, "PS_Ratio": null, "PCF_Ratio": null}}');
