INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (2143, 'EWUS', 'ETF', 'America', 'Baron Real Estate Fund R6 Share', 'Baron Real Estate Fund Class R6', 'DOLLAR', 'Blend', 'Medium', 'Baron Capital Group, Inc.', 'BTS', 'Miscellaneous Region', 124223080, 0.0136, '2012-01-25', 0.25, 'The investment seeks capital appreciation. The fund normally invests 80% of its net assets for the long term in equity securities in the form of common stock of U.S. and non-U.S. real estate and real estate-related companies of any market capitalization, and in companies which, in the opinion of the Adviser, own significant real estate assets at the time of investment ("real estate companies"). It will invest more than 25% of its net assets in the real estate industry.', 0.0059, 0.0053, 21274, 43530, 46.843, 47.603, NULL, NULL, 2.19, 10.37, 21.55, 1.51, NULL, NULL, '{"Cap_Size": "Medium", "Quote_Mode": "ETF", "Currency_Base": "DOLLAR", "GeoZone_Class": "America", "Strategy_Type": "Blend"}', '{"Net_Worth": 124223080, "Yield_Rate": 0.0136, "Expense_Net": 0.0059, "Benchmark_Exp": 0.0053, "Turnover_Ratio": 0.25}', '{"volume_metrics": {"Vol_3M": 21274, "Vol_Recent": 43530}, "moving_averages": {"MA_50": 46.843, "MA_200": 47.603}}', '{"asset_allocation": {"Bond_Weight": null, "Equity_Weight": null}, "bond_characteristics": {"Avg_Maturity": null, "Duration_Yrs": null}}', '{"valuation_metrics": {"PB_Ratio": 2.19, "PE_Ratio": 21.55, "PS_Ratio": 1.51, "PCF_Ratio": 10.37}}');
INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (2126, 'ECH', 'ETF', 'U.S.', 'BlackRock 80/20 Target Allocati', 'BlackRock 80/20 Target Allocation Fund Class R', 'usd', 'Value', 'Medium', 'BlackRock', 'BTS', 'Miscellaneous Region', 471004320, 0.0223, '2007-11-12', 0.51, 'The investment seeks long term capital appreciation. The fund, which is a fund of funds, normally obtains exposure to equity securities in an amount equal to 80% of its assets and exposure to fixed-income securities in an amount equal to 20% of its assets. Under normal circumstances, the advisor intends to invest primarily in affiliated open-end funds and affiliated ETFs. The fund may, when consistent with its investment objective, buy or sell options or futures, or enter into total return swaps and foreign currency transactions (collectively, commonly known as derivatives).', 0.0059, 0.0053, 607469, 874020, 25.566, 29.038, 0.998, 0, 1.22, 4.77, 16.27, 1.04, NULL, NULL, '{"Cap_Size": "Medium", "Quote_Mode": "ETF", "Currency_Base": "usd", "GeoZone_Class": "U.S.", "Strategy_Type": "Value"}', '{"Net_Worth": 471004320, "Yield_Rate": 0.0223, "Expense_Net": 0.0059, "Benchmark_Exp": 0.0053, "Turnover_Ratio": 0.51}', '{"volume_metrics": {"Vol_3M": 607469, "Vol_Recent": 874020}, "moving_averages": {"MA_50": 25.566, "MA_200": 29.038}}', '{"asset_allocation": {"Bond_Weight": 0, "Equity_Weight": 0.998}, "bond_characteristics": {"Avg_Maturity": null, "Duration_Yrs": null}}', '{"valuation_metrics": {"PB_Ratio": 1.22, "PE_Ratio": 16.27, "PS_Ratio": 1.04, "PCF_Ratio": 4.77}}');
INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (2127, 'ECNS', 'ETF', 'us', 'BlackRock Allocation Target Sha', 'BlackRock Allocation Target Shares Series S Portfolio', 'US_DOLLAR', 'Value', 'Medium', 'BlackRock', 'PCX', 'China Region', 104722672, 0.0299, '2010-09-28', 0.39, 'The investment seeks to maximize total return. The fund will principally invest in the following securities: commercial and residential mortgage-backed securities; obligations of non-U.S. governments and supra-national organizations, such as the World Bank, which are chartered to promote economic development; obligations of domestic and non-U.S. corporations; asset-backed securities; collateralized mortgage obligations; U.S. Treasury and agency securities; when-issued and delayed delivery securities; derivatives; cash equivalent investments; repurchase agreements and reverse repurchase agreements; and dollar rolls.', 0.0059, 0.0068, 16219, 8410, 51.061, 54.243, NULL, NULL, 1.12, 6.72, 9.95, 0.78, NULL, NULL, '{"Cap_Size": "Medium", "Quote_Mode": "ETF", "Currency_Base": "US_DOLLAR", "GeoZone_Class": "us", "Strategy_Type": "Value"}', '{"Net_Worth": 104722672, "Yield_Rate": 0.0299, "Expense_Net": 0.0059, "Benchmark_Exp": 0.0068, "Turnover_Ratio": 0.39}', '{"volume_metrics": {"Vol_3M": 16219, "Vol_Recent": 8410}, "moving_averages": {"MA_50": 51.061, "MA_200": 54.243}}', '{"asset_allocation": {"Bond_Weight": null, "Equity_Weight": null}, "bond_characteristics": {"Avg_Maturity": null, "Duration_Yrs": null}}', '{"valuation_metrics": {"PB_Ratio": 1.12, "PE_Ratio": 9.95, "PS_Ratio": 0.78, "PCF_Ratio