INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (2128, 'EDEN', 'ETF', 'UNITED_STATES', 'BlackRock Tactical Opportunitie', 'BlackRock Tactical Opportunities Fund Investor C Shares', 'AmericanDollar', 'Growth', 'Large', 'BlackRock', 'BTS', 'Miscellaneous Region', 156468048, 0.0078, '2012-01-25', 0.21, 'The investment seeks total return. The fund managers use an asset allocation strategy, investing varying percentages of its portfolio in three major categories: stocks, bonds and money market instruments. The fund has wide flexibility in the relative weightings given to each category. With respect to its equity investments, it may invest in individual equity securities to an unlimited extent. The fund may invest in common stock, preferred stock, securities convertible into common stock, non-convertible preferred stock and depositary receipts.', 0.0053, 0.0053, 17187, 25820, 110.647, 107.467, 0.992, 0, 4.16, 18.09, 26.93, 2.92, NULL, NULL, '{"Cap_Size": "Large", "Quote_Mode": "ETF", "Currency_Base": "AmericanDollar", "GeoZone_Class": "UNITED_STATES", "Strategy_Type": "Growth"}', '{"Net_Worth": 156468048, "Yield_Rate": 0.0078, "Expense_Net": 0.0053, "Benchmark_Exp": 0.0053, "Turnover_Ratio": 0.21}', '{"volume_metrics": {"Vol_3M": 17187, "Vol_Recent": 25820}, "moving_averages": {"MA_50": 110.647, "MA_200": 107.467}}', '{"asset_allocation": {"Bond_Weight": 0, "Equity_Weight": 0.992}, "bond_characteristics": {"Avg_Maturity": null, "Duration_Yrs": null}}', '{"valuation_metrics": {"PB_Ratio": 4.16, "PE_Ratio": 26.93, "PS_Ratio": 2.92, "PCF_Ratio": 18.09}}');
