INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (2141, 'EUSA', 'ETF', 'U.S.A.', 'BlackRock International Dividen', 'BlackRock International Dividend Fund Class K', 'DOLLAR', 'Blend', 'Medium', 'BlackRock', 'PCX', 'Large Blend', 447847776, 0.0111, '2010-05-05', 0.3, 'The investment seeks long-term total return and current income. The fund normally invests at least 80% of its net assets plus the amount of any borrowings for investment purposes in dividend-paying equity securities issued by foreign companies of any market capitalization and derivatives that have similar economic characteristics. It may invest up to 20% of its net assets in global fixed-income securities, including corporate bonds, U.S. government debt securities, non-U.S. government and supranational debt securities, asset-backed securities, mortgage-backed securities, corporate loans, emerging market debt securities and non-investment grade debt securities.', 0.0015, 0.0036, 19739, 23670, 87.624, 84.016, 0.998, 0, 3.5, 15.78, 23.67, 2.28, NULL, NULL, '{"Cap_Size": "Medium", "Quote_Mode": "ETF", "Currency_Base": "DOLLAR", "GeoZone_Class": "U.S.A.", "Strategy_Type": "Blend"}', '{"Net_Worth": 447847776, "Yield_Rate": 0.0111, "Expense_Net": 0.0015, "Benchmark_Exp": 0.0036, "Turnover_Ratio": 0.3}', '{"volume_metrics": {"Vol_3M": 19739, "Vol_Recent": 23670}, "moving_averages": {"MA_50": 87.624, "MA_200": 84.016}}', '{"asset_allocation": {"Bond_Weight": 0, "Equity_Weight": 0.998}, "bond_characteristics": {"Avg_Maturity": null, "Duration_Yrs": null}}', '{"valuation_metrics": {"PB_Ratio": 3.5, "PE_Ratio":