INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (2148, 'FILL', 'ETF', 'USA', 'BlackRock 60/40 Target Allocati', 'BlackRock 60/40 Target Allocation Fund Class R Shares', 'AmericanDollar', 'Value', 'Large', 'BlackRock', 'PCX', 'Equity Energy', 78977608, 0.0307, '2012-01-31', 0.12, 'The investment seeks long term capital appreciation, and current income is also a consideration. The fund, which is a fund of funds, normally obtains exposure to equity securities in an amount equal to 60% of its assets and exposure to fixed-income securities in an amount equal to 40% of its assets. Normally, the advisor intends to invest primarily in affiliated open-end funds and affiliated ETFs. The fund may, when consistent with its investment objective, buy or sell options or futures, or enter into total return swaps and foreign currency transactions (collectively, commonly known as derivatives).', 0.0039, 0.0048, 35404, 33400, 18.522, 16.803, 0.9931, 0, 1.39, 7.94, NULL, 1.36, NULL, NULL, '{"Cap_Size": "Large", "Quote_Mode": "ETF", "Currency_Base": "AmericanDollar", "GeoZone_Class": "USA", "Strategy_Type": "Value"}', '{"Net_Worth": 78977608, "Yield_Rate": 0.0307, "Expense_Net": 0.0039, "Benchmark_Exp": 0.0048, "Turnover_Ratio": 0.12}', '{"volume_metrics": {"Vol_3M": 35404, "Vol_Recent": 33400}, "moving_averages": {"MA_50": 18.522, "MA_200": 16.803}}', '{"asset_allocation": {"Bond_Weight": 0, "Equity_Weight": 0.9931}, "bond_characteristics": {"Avg_Maturity": null, "Duration_Yrs": null}}', '{"valuation_metrics": {"PB_Ratio": 1.39, "PE_Ratio": null, "PS_Ratio": 1.36, "PCF_Ratio": 7.94}}');
INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (2149, 'FM', 'ETF', 'U.S.A.', 'BlackRock High Yield Bond Portf', 'BlackRock High Yield Bond Portfolio Class K', 'US_DOLLAR', 'Value', 'Medium', 'BlackRock', 'PCX', 'Diversified Emerging Mkts', 467473088, 0.0207, '2012-09-12', 0.25, 'The investment seeks to maximize total return, consistent with income generation and prudent investment management. The fund invests primarily in non-investment grade bonds with maturities of ten years or less. It normally invests at least 80% of its assets in high yield bonds. The fund may invest up to 30% of its assets in non-dollar denominated bonds of issuers located outside of the United States. Its investment in non-dollar denominated bonds may be on a currency hedged or unhedged basis. The fund may also invest in convertible and preferred securities.', 0.0079, 0.0056, 101793, 105500, 35.162, 32.777, NULL, NULL, 1.83, 9.5, 15.45, 2.34, NULL, NULL, '{"Cap_Size": "Medium", "Quote_Mode": "ETF", "Currency_Base": "US_DOLLAR", "GeoZone_Class": "U.S.A.", "Strategy_Type": "Value"}', '{"Net_Worth": 467473088, "Yield_Rate": 0.0207, "Expense_Net": 0.0079, "Benchmark_Exp": 0.0056, "Turnover_Ratio": 0.25}', '{"volume_metrics": {"Vol_3M": 101793, "Vol_Recent": 105500}, "moving_averages": {"MA_50": 35.162, "MA_200": 32.777}}', '{"asset_allocation": {"Bond_Weight": null, "Equity_Weight": null}, "bond_characteristics": {"Avg_Maturity": null, "Duration_Yrs": null}}', '{"valuation_metrics": {"PB_Ratio": 1.83, "PE_Ratio": 15.45, "PS_Ratio": 2.34, "PCF_Ratio": 9.5}}');
INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (2150, 'FNGO', 'ETF', 'U.S.A.', 'BlackRock Retirement Income 203', 'BlackRock Retirement Income 2030 Fund Investor A', 'DOLLAR', 'Growth', 'Large', 'BlackRock', 'PCX', 'Trading--Leveraged Equity', 235521072, NULL, '2018-08-01', NULL, 'The investment seeks to maximize current income while decumulating the fund''s assets to a predefined target fund net asset value per share, as a percentage of the fund''s net asset value per share at inception, over the term of the fund. The fund invests substantially all of its assets in BlackRock Multi-Asset Income Portfolio, a series of BlackRock Funds II, which seeks to maximize current income with consideration for capital appreciation. Under normal circumstances, the fund, indirectly through its investment in MAI, may invest up to 60% of its assets in equity securities and up to 100% of its assets in fixed-income securities.', 0.0095, 0.009, 16834, 24210, 49.855, 44.452, 1, 0, 7.27, 26.6, 29.23, 0.45, NULL, NULL, '{"Cap_Size": "Large", "Quote_Mode": "ETF", "Currency_Base": "DOLLAR", "GeoZone_Class": "U.S.A.", "Strategy_Type": "Growth"}', '{"Net_Worth": 235521072, "Yield_Rate": null, "Expense_Net": 0.0095, "Benchmark_Exp": 0.009, "Turnover_Ratio": null}', '{"volume_metrics": {"Vol_3M": 16834, "Vol_Recent": 24210}, "moving_averages": {"MA_50": 49.855, "MA_200": 44.452}}', '{"asset_allocation": {"Bond_Weight": 0, "Equity_Weight": 1}, "bond_characteristics": {"Avg_Maturity": null, "Duration_Yrs": null}}', '{"valuation_metrics": {"PB_Ratio": 7.27, "PE_Ratio": 29.23, "PS_Ratio": 0.4