INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (2167, 'IBDD', 'ETF', 'U.S.', 'Bridgeway Blue Chip Fund', 'Bridgeway Blue Chip Fund', 'US$', NULL, NULL, 'Bridgeway', 'PCX', NULL, 73079032, 0.0228, '2013-07-09', 0.13, 'The investment seeks to provide a long-term total return on capital, primarily through capital appreciation, but also some income. The fund seeks to achieve its objective by investing in blue-chip stocks, while minimizing the distribution of capital gains and minimizing costs, and through some income that is almost exclusively derived from dividends paid by companies held in the fund''s portfolio. It normally invests at least 80% of its net assets in blue-chip stocks as determined at the time of purchase. The Adviser selects stocks within the blue-chip category using a statistical approach that primarily considers market capitalization.', 0.001, NULL, 6425, 2320, 26.887, 27.035, NULL, NULL, NULL, NULL, NULL, NULL, 1.17, 1.16, '{"Cap_Size": null, "Quote_Mode": "ETF", "Currency_Base": "US$", "GeoZone_Class": "U.S.", "Strategy_Type": null}', '{"Net_Worth": 73079032, "Yield_Rate": 0.0228, "Expense_Net": 0.001, "Benchmark_Exp": null, "Turnover_Ratio": 0.13}', '{"volume_metrics": {"Vol_3M": 6425, "Vol_Recent": 2320}, "moving_averages": {"MA_50": 26.887, "MA_200": 27.035}}', '{"asset_allocation": {"Bond_Weight": null, "Equity_Weight": null}, "bond_characteristics": {"Avg_Maturity": 1.17, "Duration_Yrs": 1.16}}', '{"valuation_metrics": {"PB_Ratio": null, "PE_Ratio": null, "PS_Ratio": null, "PCF_Ratio": null}}');
INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (2168, 'IBDM', 'ETF', 'usa', 'American Beacon Bridgeway Large', 'American Beacon Bridgeway Large Cap Value Fund R5 Class', 'US$', NULL, NULL, 'American Beacon', 'PCX', NULL, 1409990016, 0.0181, '2015-03-10', 0.11, 'The investment seeks to provide long-term total return on capital, primarily through capital appreciation and some income. The fund invests in a diversified portfolio of stocks of large capitalization companies that are listed on the New York Stock Exchange, NYSE American, or NASDAQ. Under normal market conditions, at least 80% of Fund net assets (plus borrowings for investment purposes) are invested in stocks from among those in the large-cap value category at the time of purchase.', 0.001, NULL, 260000, 289530, 24.724, 24.77, NULL, NULL, NULL, NULL, NULL, NULL, 0.23, 0.2, '{"Cap_Size": null, "Quote_Mode": "ETF", "Currency_Base": "US$", "GeoZone_Class": "usa", "Strategy_Type": null}', '{"Net_Worth": 1409990016, "Yield_Rate": 0.0181, "Expense_Net": 0.001, "Benchmark_Exp": null, "Turnover_Ratio": 0.11}', '{"volume_metrics": {"Vol_3M": 260000, "Vol_Recent": 289530}, "moving_averages": {"MA_50": 24.724, "MA_200": 24.77}}', '{"asset_allocation": {"Bond_Weight": null, "Equity_Weight": null}, "bond_characteristics": {"Avg_Maturity": 0.23, "Duration_Yrs": 0.2}}', '{"valuation_metrics": {"PB_Ratio": null, "PE_Ratio": null, "PS_Ratio": null, "PCF_Ratio": null}}');
INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (2169, 'IBDN', 'ETF', 'U.S.A.', 'iShares Russell Mid-Cap Index F', 'iShares Russell Mid-Cap Index Fund Investor A Shares', 'DOLLAR', NULL, NULL, 'BlackRock', 'PCX', NULL, 1566330624, 0.02, '2015-03-10', 0.16, 'The investment seeks to track the investment results of the Russell Midcap© Index (the "underlying index"), which measures the performance of the mid-capitalization sector of the U.S. equity market. The fund generally invests at least 90% of its assets, plus the amount of any borrowing for investment purposes, in securities of the underlying index. The underlying index is a float-adjusted, capitalization-weighted index of equity securities issued by approximately 800 of the smallest issuers in the Russell 1000© Index.', 0.001, NULL, 146728, 167810, 25.251, 25.361, NULL, NULL, NULL, NULL, NULL, NULL, 0.9, 0.89, '{"Cap_Size": null, "Quote_Mode": "ETF", "Currency_Base": "DOLLAR", "GeoZone_Class": "U.S.A.", "Strategy_Type": null}', '{"Net_Worth": 1566330624, "Yield_Rate": 0.02, "Expense_Net": 0.001, "Benchmark_Exp": null, "Turnover_Ratio": 0.16}', '{"volume_metrics": {"Vol_3M": 146728, "Vol_Recent": 167810}, "moving_averages": {"MA_50": 25.251, "MA_200": 25.361}}', '{"asset_allocation": {"Bond_Weight": null, "Equity_Weight": null}, "bond_characteristics": {"Avg_Maturity": 0.9, "Duration_Yrs": 0.89}}', '{"valuation_metrics": {"PB_Ratio": null, "PE_Ratio": null, "PS_Ratio": null, "PCF_Ratio": null}}');
