INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (2178, 'IBHA', 'ETF', 'US', 'Bear ProFund Investor Class', 'ProFunds Bear Fund Investor Class', 'Usd', NULL, NULL, 'ProFunds', 'BTS', 'High Yield Bond', 43502120, 0.0271, '2019-05-07', 0.5, 'The investment seeks daily investment results, before fees and expenses, that correspond to the inverse (-1x) of the daily performance of the S&P 500© Index. The fund invests in financial instruments that ProFund Advisors believes, in combination, should produce daily returns consistent with its investment objective. The index is a float-adjusted, market capitalization-weighted index of 500 U.S. operating companies and real estate investment trusts selected through a process that factors in criteria such as liquidity, price, market capitalization and financial viability. The fund is non-diversified.', 0.0035, 0.0047, 6036, 5380, 24.141, 24.167, NULL, NULL, NULL, NULL, NULL, NULL, 0.23, 0.2, '{"Cap_Size": null, "Quote_Mode": "ETF", "Currency_Base": "Usd", "GeoZone_Class": "US", "Strategy_Type": null}', '{"Net_Worth": 43502120, "Yield_Rate": 0.0271, "Expense_Net": 0.0035, "Benchmark_Exp": 0.0047, "Turnover_Ratio": 0.5}', '{"volume_metrics": {"Vol_3M": 6036, "Vol_Recent": 5380}, "moving_averages": {"MA_50": 24.141, "MA_200": 24.167}}', '{"asset_allocation": {"Bond_Weight": null, "Equity_Weight": null}, "bond_characteristics": {"Avg_Maturity": 0.23, "Duration_Yrs": 0.2}}', '{"valuation_metrics": {"PB_Ratio": null, "PE_Ratio": null, "PS_Ratio": null, "PCF_Ratio": null}}');
