INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (2237, 'ITA', 'ETF', 'U.S.', 'Bernzott U.S. Small Cap Value F', 'Bernzott U.S.all Cap Value Fund', 'USD', 'Value', 'Large', 'Bernzott Capital Advisors', 'BTS', 'Industrials', 2963257344, 0.0083, '2006-05-01', 0.49, 'The investment seeks long-term capital appreciation. Under normal circumstances, the fund will invest at least 80% of its net assets (including amounts borrowed for investment purposes) in common stock of small capitalization companies that are organized in the United States and the securities of which are principally traded on a major U.S. exchange. It will generally hold between 25 and 35 positions. In addition, the fund may invest in exchange-traded funds ("ETFs"), which are pooled investment vehicles that generally seek to track the performance of specific indices and are traded on exchanges.', 0.0042, 0.0046, 190158, 237080, 105.571, 105.794, 0.9986, 0, 3.2, 19.16, 25.63, 2.32, NULL, NULL, '{"Cap_Size": "Large", "Quote_Mode": "ETF", "Currency_Base": "USD", "GeoZone_Class": "U.S.", "Strategy_Type": "Value"}', '{"Net_Worth": 2963257344, "Yield_Rate": 0.0083, "Expense_Net": 0.0042, "Benchmark_Exp": 0.0046, "Turnover_Ratio": 0.49}', '{"volume_metrics": {"Vol_3M": 190158, "Vol_Recent": 237080}, "moving_averages": {"MA_50": 105.571, "MA_200": 105.794}}', '{"asset_allocation": {"Bond_Weight": 0, "Equity_Weight": 0.9986}, "bond_characteristics": {"Avg_Maturity": null, "Duration_Yrs": null}}', '{"valuation_metrics": {"PB_Ratio": 3.2, "PE_Ratio": 25.63, "PS_Ratio": 2.32, "PCF_Ratio": 19.16}}');
