INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (2247, 'IWL', 'ETF', 'UNITED_STATES', 'Bishop Street Hawaii Municipal ', 'Bishop Street Hawaii Municipal Bond Fund Class Institutional', 'US$', 'Blend', 'Large', 'Bishop Street', 'PCX', 'Large Blend', 950714944, 0.0117, '2009-09-22', 0.05, 'The investment seeks to provide high current income exempt from federal and Hawaii state income taxes. The fund invests at least 80% of its net assets (plus any borrowings for investment purposes) in investment grade municipal bonds, the interest from which is exempt from regular federal and Hawaii state income taxes. It may also invest in municipal bonds issued by other U.S. states, territories and possessions. There is no limit on the average maturity of the fund''s portfolio. The fund is non-diversified.', 0.0015, 0.0036, 64614, 74090, 108.875, 103.037, 0.9981, 0, 4.87, 18.21, 27, 3.34, NULL, NULL, '{"Cap_Size": "Large", "Quote_Mode": "ETF", "Currency_Base": "US$", "GeoZone_Class": "UNITED_STATES", "Strategy_Type": "Blend"}', '{"Net_Worth": 950714944, "Yield_Rate": 0.0117, "Expense_Net": 0.0015, "Benchmark_Exp": 0.0036, "Turnover_Ratio": 0.05}', '{"volume_metrics": {"Vol_3M": 64614, "Vol_Recent": 74090}, "moving_averages": {"MA_50": 108.875, "MA_200": 103.037}}', '{"asset_allocation": {"Bond_Weight": 0, "Equity_Weight": 0.9981}, "bond_characteristics": {"Avg_Maturity": null, "Duration_Yrs": null}}', '{"valuation_metrics": {"PB_Ratio": 4.87, "PE_Ratio": 27, "PS_Ratio": 3.34, "PCF_Ratio": 18.21}}');
INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (2249, 'IWN', 'ETF', 'US', 'BlackRock Strategic Income Oppo', 'BlackRock Strategic Income Opportunities Portfolio Investor C Shares', 'US_DOLLAR', 'Value', 'Small', 'BlackRock', 'PCX', 'Small Value', 16731935744, 0.0121, '2000-07-24', 0.28, 'The investment seeks total return as is consistent with preservation of capital. The fund normally invests in a combination of fixed income securities, including, but not limited to: high yield securities, international securities, emerging markets debt and mortgages. It may invest significantly in non-investment grade bonds (high yield or junk bonds). The fund may also invest significantly in non-dollar denominated bonds and bonds of emerging market issuers. It may invest up to 15% of its net assets in collateralized debt obligations, of which 10% (as a percentage of the fund''s net assets) may be collateralized in loan obligations.', 0.0024, 0.0035, 1495873, 1.82311e+06, 167.373, 163.483, 0.9974, 0, 1.62, 8.03, 13.83, 1.17, NULL, NULL, '{"Cap_Size": "Small", "Quote_Mode": "ETF", "Currency_Base": "US_DOLLAR", "GeoZone_Class": "US", "Strategy_Type": "Value"}', '{"Net_Worth": 16731935744, "Yield_Rate": 0.0121, "Expense_Net": 0.0024, "Benchmark_Exp": 0.0035, "Turnover_Ratio": 0.28}', '{"volume_metrics": {"Vol_3M": 1495873, "Vol_Recent": 1823110}, "moving_averages": {"MA_50": 167.373, "MA_200": 163.483}}', '{"asset_allocation": {"Bond_Weight": 0, "Equity_Weight": 0.9974}, "bond_characteristics": {"Avg_Maturity": null, "Duration_Yrs": null}}', '{"valuation_metrics": {"PB_Ratio": 1.62, "PE_Ratio": 13.83, "PS_Ratio": 1.17, "PCF_Ratio": 8.03}}');
INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (2250, 'IWO', 'ETF', 'America', NULL, 'BlackRock Sustainable High Yield Bond Fund Institutional', 'Usd', 'Growth', 'Small', 'BlackRock', 'PCX', 'Small Growth', 12403911680, 0.0032, '2000-07-24', 0.35, 'The investment seeks to maximize total return, consistent with income generation and prudent investment management, while seeking to maintain certain environmental, governance and social ("ESG") characteristics, climate risk exposure and climate opportunities relative to the fund''s benchmark. The fund invests primarily in non-investment grade bonds with maturities of ten years or less. It normally invests at least 80% of its net assets, plus the amount of any borrowings for investment purposes, in high yield bonds.', 0.0024, 0.0033, 478666, 816800, 305.381, 302.632, 0.9983, 0, 5.75, 14.81, 27.65, 2.17, NULL, NULL, '{"Cap_Size": "Small", "Quote_Mode": "ETF", "Currency_Base": "Usd", "GeoZone_Class": "America", "Strategy_Type": "Growth"}', '{"Net_Worth": 12403911680, "Yield_Rate": 0.0032, "Expense_Net": 0.0024, "Benchmark_Exp": 0.0033, "Turnover_Ratio": 0.35}', '{"volume_metrics": {"Vol_3M": 478666, "Vol_Recent": 816800}, "moving_averages": {"MA_50": 305.381, "MA_200": 302.632}}', '{"asset_allocation": {"Bond_Weight": 0, "Equity_Weight": 0.9983}, "bond_characteristics": {"Avg_Maturity": null, "Duration_Yrs": null}}', '{"valuation_metrics": {"PB_Ratio": 5.75, "PE_Ratio": 27.65, "PS_Ratio": 2.17, "PCF_Ratio": 14.81}}');
