INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (2255, 'JPXN', 'ETF', 'United States', NULL, 'BlackRock SMID-Cap Growth Equity Fund Institutional', 'US$', 'Blend', 'Large', 'BlackRock', 'PCX', 'Japan Stock', 86292920, 0.0149, '2001-10-23', 0.1, 'The investment seeks long-term capital appreciation. Under normal circumstances, the fund invests at least 80% of its net assets, plus the amount of any borrowings for investment purposes, in equity securities issued by U.S. small- and mid-capitalization companies which fund management believes have above-average earnings growth potential, and derivatives that have similar economic characteristics to such equity securities. It may, when consistent with the fund''s investment objective, buy or sell options or futures on a security or an index of securities (commonly known as derivatives).', 0.0048, 0.004, 3023, 1840, 73.405, 73.472, 0.9946, 0, 1.43, 9.42, 17.46, 1.08, NULL, NULL, '{"Cap_Size": "Large", "Quote_Mode": "ETF", "Currency_Base": "US$", "GeoZone_Class": "United States", "Strategy_Type": "Blend"}', '{"Net_Worth": 86292920, "Yield_Rate": 0.0149, "Expense_Net": 0.0048, "Benchmark_Exp": 0.004, "Turnover_Ratio": 0.1}', '{"volume_metrics": {"Vol_3M": 3023, "Vol_Recent": 1840}, "moving_averages": {"MA_50": 73.405, "MA_200": 73.472}}', '{"asset_allocation": {"Bond_Weight": 0, "Equity_Weight": 0.9946}, "bond_characteristics": {"Avg_Maturity": null, "Duration_Yrs": null}}', '{"valuation_metrics": {"PB_Ratio": 1.43, "PE_Ratio": 17.46, "PS_Ratio": 1.08, "PCF_Ratio": 9.42}}');
