INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (2260, 'LQDH', 'ETF', 'America', 'iShares S&P 500 Index Fund - Cl', 'iShares S&P 500 Index Fund Investor A Shares', 'Usd', NULL, NULL, 'BlackRock', 'PCX', 'Corporate Bond', 630685696, 0.0189, '2014-05-27', 0.07, 'The investment seeks to provide investment results that correspond to the total return performance of publicly-traded common stocks in the aggregate, as represented by the Standard & Poor''s 500© Index. The fund is a "feeder" fund that invests all of its assets in the Master Portfolio of MIP, which has the same investment objective and strategies as the fund. At least 90% of the value of the fund''s assets is invested in securities comprising the S&P 500 Index. The percentage of the fund''s assets invested in a given stock is approximately the same as the percentage such stock represents in the S&P 500 Index.', 0.0024, 0.0017, 44328, 40840, 96.126, 95.85, NULL, NULL, NULL, NULL, NULL, NULL, 14.4, 0.04, '{"Cap_Size": null, "Quote_Mode": "ETF", "Currency_Base": "Usd", "GeoZone_Class": "America", "Strategy_Type": null}', '{"Net_Worth": 630685696, "Yield_Rate": 0.0189, "Expense_Net": 0.0024, "Benchmark_Exp": 0.0017, "Turnover_Ratio": 0.07}', '{"volume_metrics": {"Vol_3M": 44328, "Vol_Recent": 40840}, "moving_averages": {"MA_50": 96.126, "MA_200": 95.85}}', '{"asset_allocation": {"Bond_Weight": null, "Equity_Weight": null}, "bond_characteristics": {"Avg_Maturity": 14.4, "Duration_Yrs": 0.04}}', '{"valuation_metrics": {"PB_Ratio": null, "PE_Ratio": null, "PS_Ratio": null, "PCF_Ratio": null}}');
