INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (2289, 'TOK', 'ETF', 'America', 'BMO Short Term Income Fund Clas', 'BMO Short-Term Income Fund Class A', 'US_DOLLAR', 'Blend', 'Large', 'BMO Funds', 'PCX', NULL, 185287072, 0.015, '2007-12-10', 0.04, 'The investment seeks to maximize total return consistent with current income. The fund invests at least 80% of its assets in fixed income securities. Fund investments include corporate, asset-backed, and mortgage-backed securities with a minimum rating in the lowest investment grade category (i.e., rated BBB by Standard & Poor''s or Baa by Moody''s Investors Service, or higher, or unrated and considered by the Adviser to be comparable in quality) at the time of purchase and bank instruments, repurchase agreements, and U.S. government securities.', 0.0025, NULL, 1998, 2630, 99.211, 94.994, 0.9957, 0, 3.37, 15.52, 24.85, 2.54, NULL, NULL, '{"Cap_Size": "Large", "Quote_Mode": "ETF", "Currency_Base": "US_DOLLAR", "GeoZone_Class": "America", "Strategy_Type": "Blend"}', '{"Net_Worth": 185287072, "Yield_Rate": 0.015, "Expense_Net": 0.0025, "Benchmark_Exp": null, "Turnover_Ratio": 0.04}', '{"volume_metrics": {"Vol_3M": 1998, "Vol_Recent": 2630}, "moving_averages": {"MA_50": 99.211, "MA_200": 94.994}}', '{"asset_allocation": {"Bond_Weight": 0, "Equity_Weight": 0.9957}, "bond_characteristics": {"Avg_Maturity": null, "Duration_Yrs": null}}', '{"valuation_metrics": {"PB_Ratio": 3.37, "PE_Ratio": 24.85, "PS_Ratio": 2.54, "PCF_Ratio": 15.52}}');
INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (2290, 'TVIXF', 'ETF', 'usa', 'Boston Trust Midcap Fund', 'Boston Trust Midcap Fund', 'US$', NULL, NULL, 'Boston Trust Walden Funds', 'PNK', 'Trading--Miscellaneous', 17675852, NULL, '2010-11-29', NULL, 'The investment seeks long-term capital growth through an actively managed portfolio of stocks of middle capitalization ("midcap") companies. The fund invests, under normal circumstances, at least 80% of its assets in a diversified portfolio of domestic equity securities of midcap companies. Equity securities include common stock and any rights to purchase common stock. For these purposes, the Adviser defines midcap companies as those with market capitalizations within the range encompassed by the Russell Midcap© Index at the time of purchase.', 0.0165, 0.0087, 5787, 9170, 4.058, 8.893, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '{"Cap_Size": null, "Quote_Mode": "ETF", "Currency_Base": "US$", "GeoZone_Class": "usa", "Strategy_Type": null}', '{"Net_Worth": 17675852, "Yield_Rate": null, "Expense_Net": 0.0165, "Benchmark_Exp": 0.0087, "Turnover_Ratio": null}', '{"volume_metrics": {"Vol_3M": 5787, "Vol_Recent": 9170}, "moving_averages": {"MA_50": 4.058, "MA_200": 8.893}}', '{"asset_allocation": {"Bond_Weight": null, "Equity_Weight": null}, "bond_characteristics": {"Avg_Maturity": null, "Duration_Yrs": null}}', '{"valuation_metrics": {"PB_Ratio": null, "PE_Ratio": null, "PS_Ratio": null, "PCF_Ratio": null}}');
INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (2291, 'UCIB', 'ETF', 'USA', 'Baird Short-Term Municipal Bond', 'Baird Short-Term Municipal Bond Fund Institutional Class', 'US_DOLLAR', NULL, NULL, 'Baird', 'PCX', 'Commodities Broad Basket', 54136600, NULL, '2015-10-09', NULL, 'The investment seeks current income that is exempt from federal income tax and is consistent with the preservation of capital. The fund normally invests at least 80% of its net assets in municipal bonds and debentures, the income from which is exempt from federal income tax (including the federal alternative minimum tax ("AMT")). It invests in a broadly diversified portfolio of federally tax-exempt municipal obligations issued by governmental authorities throughout the U.S. and its territories. The fund may invest in all types of municipal obligations, including pre-refunded bonds, general obligation bonds, revenue bonds, and municipal lease participations.', 0.0055, 0.0081, 1676, 1520, 20.663, 19.159, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '{"Cap_Size": null, "Quote_Mode": "ETF", "Currency_Base": "US_DOLLAR", "GeoZone_Class": "USA", "Strategy_Type": null}', '{"Net_Worth": 54136600, "Yield_Rate": null, "Expense_Net": 0.0055, "Benchmark_Exp": 0.0081, "Turnover_Ratio": null}', '{"volume_metrics": {"Vol_3M": 1676, "Vol_Recent": 1520}, "moving_averages": {"MA_50": 20.663, "MA_200": 19.159}}', '{"asset_allocation": {"Bond_Weight": null, "Equity_Weight": null}, "bond_characteristics": {"Avg_Maturity": null, "Duration_Yrs": null}}', '{"valuation_metrics": {"PB_Ratio": null, "PE_Ratio": null, "PS_Ratio": null, "PCF_Ratio": null}}');
