INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (2306, 'EPP', 'ETF', 'U.S.', 'Cboe Vest S&P 500 Buffer Strate', 'CBOE Vest S&P 500 Buffer Strategy Fund Class C Shares', 'US_DOLLAR', 'Blend', 'Large', 'CBOE Vest', 'PCX', 'Pacific/Asia ex-Japan Stk', 2446532096, 0.0229, '2001-10-25', 0.08, 'The investment seeks to track, before fees and expenses, the performance of the Cboe© S&P 500© Buffer Protect Index Balanced Series (the "SPRO Index"). The adviser attempts to meet its objective by constructing a portfolio of specially designed options that are similar to options that comprise the indices that underlie the SPRO Index. The SPRO Index is a balanced index that is a composite of the twelve (12) Cboe© S&P 500© Buffer Protect Index Monthly Series that correspond to each month of the year. The fund is non-diversified.', 0.0048, 0.0054, 344309, 668890, 50.066, 51.2, 0.997, 0, 1.92, 12.13, 22.83, 3.27, NULL, NULL, '{"Cap_Size": "Large", "Quote_Mode": "ETF", "Currency_Base": "US_DOLLAR", "GeoZone_Class": "U.S.", "Strategy_Type": "Blend"}', '{"Net_Worth": 2446532096, "Yield_Rate": 0.0229, "Expense_Net": 0.0048, "Benchmark_Exp": 0.0054, "Turnover_Ratio": 0.08}', '{"volume_metrics": {"Vol_3M": 344309, "Vol_Recent": 668890}, "moving_averages": {"MA_50": 50.066, "MA_200": 51.2}}', '{"asset_allocation": {"Bond_Weight": 0, "Equity_Weight": 0.997}, "bond_characteristics": {"Avg_Maturity": null, "Duration_Yrs": null}}', '{"valuation_metrics": {"PB_Ratio": 1.92, "PE_Ratio": 22.83, "PS_Ratio": 3.27, "PCF_Ratio": 12.13}}');
INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (2307, 'ERUS', 'ETF', 'U.S.A.', 'Buffalo Flexible Income Fund', 'Buffalo Flexible Income Fund', 'USD', 'Value', 'Large', 'Buffalo', 'PCX', 'Miscellaneous Region', 576631808, 0.0423, '2010-11-09', 0.3, 'The investment seeks to generate high current income and, as a secondary objective, the long-term growth of capital. The fund invests in both debt and equity securities. It is anticipated that the dollar-weighted average maturity of debt securities that the fund purchases will not exceed 15 years. With respect to its investments in equity securities, the fund may invest in companies in any sector and of any size of market capitalization. It may invest up to 20% of its net assets in sponsored or unsponsored ADRs and securities of foreign companies that are traded on U.S. stock exchanges and U.S. over-the-counter markets.', 0.0059, 0.0053, 177836, 166500, 49.112, 44.166, NULL, NULL, 1.18, 5.59, 10.87, 1.35, NULL, NULL, '{"Cap_Size": "Large", "Quote_Mode": "ETF", "Currency_Base": "USD", "GeoZone_Class": "U.S.A.", "Strategy_Type": "Value"}', '{"Net_Worth": 576631808, "Yield_Rate": 0.0423, "Expense_Net": 0.0059, "Benchmark_Exp": 0.0053, "Turnover_Ratio": 0.3}', '{"volume_metrics": {"Vol_3M": 177836, "Vol_Recent": 166500}, "moving_averages": {"MA_50": 49.112, "MA_200": 44.166}}', '{"asset_allocation": {"Bond_Weight": null, "Equity_Weight": null}, "bond_characteristics": {"Avg_Maturity": null, "Duration_Yrs": null}}', '{"valuation_metrics": {"PB_Ratio": 1.18, "PE_Ratio": 10.87, "PS_Ratio": 1.35, "PCF_Ratio": 5.59}}');
INSERT INTO public.funds (productnum, tickersym, quotemode, geozone, shortlabel, fulldescription, currencybase, strategytype, capsize, parentgroup, listingvenue, productclass, networth, yieldrate, launchdate, turnoverratio, strategynotes, expensenet, benchmarkexp, vol3m, volrecent, ma50, ma200, equityweight, bondweight, pb_ratio, pcf_ratio, pe_ratio, ps_ratio, avgmaturity, duration, fundclass, fundmetrics, tradingdata, allocweights, valuationratios) VALUES (2308, 'EWA', 'ETF', 'U.S.', 'Buffalo Dividend Focus Fund', 'Buffalo Dividend Focus Fund', 'usd', 'Blend', 'Large', 'Buffalo', 'PCX', 'Miscellaneous Region', 1527076992, 0.0224, '1996-03-12', 0.08, 'The investment seeks current income; long-term growth of capital is a secondary objective. The fund invests in dividend-paying equity securities, consisting of common stocks, preferred stocks, rights, warrants and convertible securities. During normal market conditions, at least 80% of the fund''s assets will be invested in dividend-paying equity securities. The fund may invest up to 20% of its net assets in sponsored or unsponsored ADRs and securities of foreign companies that are traded on U.S. stock exchanges.', 0.0051, 0.0053, 2399042, 2.98701e+06, 25.697, 25.865, 0.9976, 0, 2.45, 12.28, 23.59, 3.26, NULL, NULL, '{"Cap_Size": "Large", "Quote_Mode": "ETF", "Currency_Base": "usd", "GeoZone_Class": "U.S.", "Strategy_Type": "Blend"}', '{"Net_Worth": 1527076992, "Yield_Rate": 0.0224, "Expense_Net": 0.0051, "Benchmark_Exp": 0.0053, "Turnover_Ratio": 0.08}', '{"volume_metrics": {"Vol_3M": 2399042, "Vol_Recent": 2987010}, "moving_averages": {"MA_50": 25.697, "MA_200": 25.865}}', '{"asset_allocation": {"Bond_Weight": 0, "Equity_Weight": 0.9976}, "bond_characteristics": {"Avg_Maturity": null, "Duration_Yrs": null}}', '{"valuation_metrics": {"PB_Ratio": 2.45, "PE_Ratio": 23.59, "PS_Ratio": 3.26, "PCF_Ratio": 12.28}}');
